window.DL_QUESTIONS=[{"id":"env-tested","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"Where is eco-driving (<em>sparsam körning</em>) tested?","img":"","opts":["In both the theory test and the driving test","Only in the theory test","Only in the driving test","It is not tested"],"a":0,"ex":"Transportstyrelsen says eco-driving is a competence area for all categories, tested in <strong>both</strong> the theory test and the driving test – the examiner assesses whether your driving gives low fuel consumption.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/klimat-och-energi/sparsam-korning/\" target=\"_blank\" rel=\"noopener\" title=\"Eco-driving\">Transportstyrelsen – Sparsam körning</a>"],"signs":[]},{"id":"env-speed-fuel","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"How does fuel consumption change when you drive faster than about 70–75 km/h?","img":"","opts":["It rises by about 0.5–1.0 decilitre per 10 km for every 10 km/h faster","It does not change","It falls, because you reach your goal sooner","It rises only for diesel cars"],"a":0,"ex":"For every <strong>10 km/h</strong> above about 70–75 km/h, consumption rises by <strong>0.5–1.0 dl per Swedish mile</strong> (10 km). Air resistance grows quickly with speed.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/klimat-och-energi/sparsam-korning/\" target=\"_blank\" rel=\"noopener\" title=\"Eco-driving\">Transportstyrelsen – Sparsam körning</a>"],"signs":[]},{"id":"env-saving","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"According to Trafikverket, about how much fuel does eco-driving save on average?","img":"","opts":["About 7 %","About 50 %","About 1 %","Nothing"],"a":0,"ex":"Eco-driving saves on average about <strong>7 %</strong> of the fuel – typically 4–10 %, sometimes more.","src":["<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-gear","area":"environment","paths":["car-manual","motorcycle"],"lesson":"eco-driving","q":"Which gear technique saves fuel?","img":"","opts":["Change up early and drive in as high a gear as the engine pulls without struggling","Drive in a low gear with high revs","Change gear as late as possible","Drive in neutral downhill"],"a":0,"ex":"Trafikverket’s eco-driving steps include <strong>changing up early</strong> and driving in as <strong>high a gear as possible</strong>.","src":["<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-automatic","area":"environment","paths":["car-automatic"],"lesson":"eco-driving","q":"How do you drive an automatic car economically?","img":"","opts":["Press the accelerator gently so the gearbox changes up early, and release it early before you stop","Use kick-down often","Always use the lowest drive range","Drive with the left foot on the brake"],"a":0,"ex":"A gentle accelerator lets the gearbox <strong>change up early</strong>. Plan ahead, keep an even speed and use engine braking – Trafikverket’s eco-driving steps.","src":["<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-plan","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"The traffic light far ahead turns red. What is the most economical way to drive?","img":"","opts":["Release the accelerator early and let the vehicle roll in gear","Keep your speed and brake hard at the light","Speed up to get through","Change to neutral and coast"],"a":0,"ex":"Plan ahead to <strong>avoid stopping</strong>, and use <strong>engine braking</strong>: release the accelerator early. Energy you brake away is lost as heat.","src":["<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-idle","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"Many municipalities have local rules on idling. What does Karlskoga’s rule say about a stationary vehicle’s engine?","img":"","opts":["It may run outdoors for at most one minute – except in queues or to power other equipment","It may run as long as you are in the car","It may run to heat the car for 15 minutes","There are no rules on idling"],"a":0,"ex":"In Karlskoga a combustion engine in a stationary vehicle may run outdoors for <strong>at most one minute</strong>. The exceptions are traffic queues and powering other equipment – not heating or cooling the vehicle. Rules vary between municipalities.","src":["<a class=\"cite\" href=\"https://karlskoga.se/download/18.46c328f31945d6815f0dbc/1737124335270/lokalahalsoskyddsforeskrifter-karlskoga-kommun.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Local health protection regulations, Karlskoga municipality\">Karlskoga kommun – Lokala hälsoskyddsföreskrifter</a>"],"signs":[]},{"id":"env-heater-why","area":"environment","paths":["car-manual","car-automatic"],"lesson":"eco-driving","q":"Why use an engine heater (<em>motorvärmare</em>) in cold weather?","img":"","opts":["A warm engine uses less fuel and lets out less harmful exhaust than a cold one","It makes the car go faster","It is required by law below 0 °C","It charges the battery"],"a":0,"ex":"A <strong>warm engine uses less fuel</strong> than a cold one, and emissions of carbon dioxide and other harmful substances fall. The heat also reduces wear.","src":["<a class=\"cite\" href=\"https://osthammar.se/link/b3cc4643d8234954ba3f5c8986f20f54.aspx\" target=\"_blank\" rel=\"noopener\" title=\"Use your engine heater the right way\">Energimyndigheten – Använd motorvärmare rätt</a>"],"signs":[]},{"id":"env-heater-time","area":"environment","paths":["car-manual","car-automatic"],"lesson":"eco-driving","q":"It is around 0 °C. How long before you leave should the engine heater be switched on?","img":"","opts":["About 1 hour","All night","5 minutes","3 hours"],"a":0,"ex":"Energimyndigheten’s guide – around <strong>0 °C: 1 hour</strong>; colder than −15 °C: 1.5 hours; up to +10 °C: 30 minutes. All night costs more electricity than it saves.","src":["<a class=\"cite\" href=\"https://osthammar.se/link/b3cc4643d8234954ba3f5c8986f20f54.aspx\" target=\"_blank\" rel=\"noopener\" title=\"Use your engine heater the right way\">Energimyndigheten – Använd motorvärmare rätt</a>"],"signs":[]},{"id":"env-cabin-heater","area":"environment","paths":["car-manual","car-automatic"],"lesson":"eco-driving","q":"How much electricity does a cabin heater usually use compared with an engine heater?","img":"","opts":["About three times as much","The same","Half as much","Ten times less"],"a":0,"ex":"A cabin heater normally uses about <strong>three times</strong> as much electricity as an engine heater.","src":["<a class=\"cite\" href=\"https://osthammar.se/link/b3cc4643d8234954ba3f5c8986f20f54.aspx\" target=\"_blank\" rel=\"noopener\" title=\"Use your engine heater the right way\">Energimyndigheten – Använd motorvärmare rätt</a>"],"signs":[]},{"id":"env-tyre-check","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"How often does Trafikverket’s eco-driving advice say you should check the tyre pressure?","img":"","opts":["At least every other time you fill up","Once a year","Only at the annual inspection","Never – modern tyres keep their pressure"],"a":0,"ex":"Service the vehicle regularly and check the tyre pressure <strong>at least every other time you fill up</strong>.","src":["<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-roofbox","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"What should you do with an empty roof box after the holiday?","img":"","opts":["Take it off – it adds air resistance and fuel use","Keep it on all year","Fill it with heavy things","Open it while driving"],"a":0,"ex":"Removing the <strong>roof box and roof rack</strong> when you do not need them is one of the eco-driving steps – they add air resistance.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/klimat-och-energi/sparsam-korning/\" target=\"_blank\" rel=\"noopener\" title=\"Eco-driving\">Transportstyrelsen – Sparsam körning</a>","<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-short-trips","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"Why are many short trips with a car especially bad for fuel use and emissions?","img":"","opts":["The engine is cold for a large part of each trip","Short trips use no fuel","The tyres wear less","The car runs better when cold"],"a":0,"ex":"A <strong>cold engine</strong> uses more fuel and pollutes more – on short trips it is cold for much of the way. Combine errands, walk, cycle or take public transport when you can.","src":["<a class=\"cite\" href=\"https://osthammar.se/link/b3cc4643d8234954ba3f5c8986f20f54.aspx\" target=\"_blank\" rel=\"noopener\" title=\"Use your engine heater the right way\">Energimyndigheten – Använd motorvärmare rätt</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 4 kap. 2 §\">TSFS 2011:20 4 kap. 2 §</a>"],"signs":[]},{"id":"env-downhill","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"eco-driving","q":"What is one of Trafikverket’s eco-driving steps for hills?","img":"","opts":["Roll downhill and keep an even accelerator uphill","Accelerate hard uphill to keep the speed","Brake all the way downhill","Drive downhill in neutral"],"a":0,"ex":"Trafikverket’s steps: <strong>roll</strong> in descents and keep an <strong>even accelerator</strong> in ascents – accept that the speed drops a little uphill.","src":["<a class=\"cite\" href=\"https://www.energimyndigheten.se/contentassets/9174f17706a9415390df8476191aafc9/kom-langre-som-medveten-bilist.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Go further as an aware driver\">Energimyndigheten – Kom längre som medveten bilist</a>"],"signs":[]},{"id":"env-exhaust","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What does exhaust from vehicles contain, according to Transportstyrelsen?","img":"","opts":["Particles, nitrogen dioxide and organic substances that help form ground-level ozone","Only water vapour","Only carbon dioxide","Nothing harmful in modern cars"],"a":0,"ex":"Exhaust contains <strong>particles, nitrogen dioxide and organic substances</strong>, and contributes to <strong>ground-level ozone</strong>. Traffic also releases wear particles from brakes, tyres and the road surface.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/luftkvaliet-i-tatorter/\" target=\"_blank\" rel=\"noopener\" title=\"Air quality\">Transportstyrelsen – Luftkvalitet</a>"],"signs":[]},{"id":"env-wear","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"Where do <strong>wear particles</strong> from road traffic come from?","img":"","opts":["Brakes, tyres and the road surface","Only the exhaust pipe","Only diesel engines","The windscreen washer fluid"],"a":0,"ex":"Road traffic releases wear particles from <strong>brakes, tyres and the road surface</strong> – also from electric vehicles.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/luftkvaliet-i-tatorter/\" target=\"_blank\" rel=\"noopener\" title=\"Air quality\">Transportstyrelsen – Luftkvalitet</a>"],"signs":[]},{"id":"env-studs-particles","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"Why do some city streets ban studded tyres?","img":"","opts":["To reduce road wear and the particles (PM10) in the air","Because studded tyres are illegal in towns","To protect tram rails","Because studded tyres give too much grip"],"a":0,"ex":"Levels of inhalable particles (PM10) are high in some larger towns and can be lowered by reducing the <strong>wear between tyres and road</strong>. Municipalities can ban studded tyres on certain streets (sign C44).","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/luftkvaliet-i-tatorter/\" target=\"_blank\" rel=\"noopener\" title=\"Air quality\">Transportstyrelsen – Luftkvalitet</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K10P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 10 kap. 2 §\">TrF 10 kap. 2 §</a>"],"signs":[]},{"id":"env-noise-most","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"Which environmental problem from traffic affects the <strong>most people</strong> in Sweden?","img":"","opts":["Noise","Oil spills","Light pollution","Litter"],"a":0,"ex":"Noise is the environmental impact that affects the most people in Sweden – almost <strong>2 million</strong> are exposed to traffic noise above 55 dBA outside their homes.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/buller/\" target=\"_blank\" rel=\"noopener\" title=\"Noise\">Transportstyrelsen – Buller</a>"],"signs":[]},{"id":"env-noise-speed","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"At <strong>higher speeds</strong>, what makes most of the noise from a car?","img":"","opts":["The tyres on the road","The engine","The radio","The air conditioning"],"a":0,"ex":"At low speeds the <strong>engine</strong> dominates – there electric cars are much quieter. At higher speeds the noise from <strong>tyres on the road</strong> dominates.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/buller/\" target=\"_blank\" rel=\"noopener\" title=\"Noise\">Transportstyrelsen – Buller</a>"],"signs":[]},{"id":"env-climate","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What is the national target for greenhouse gas emissions from domestic transport in Sweden?","img":"","opts":["At least 70 % lower in 2030 than in 2010","Zero by 2025","10 % lower by 2050","No target"],"a":0,"ex":"Emissions from domestic transport (excluding domestic flights) shall fall by at least <strong>70 % by 2030</strong> compared with 2010. Road traffic causes most of these emissions.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/klimat-och-energi/\" target=\"_blank\" rel=\"noopener\" title=\"Climate and energy\">Transportstyrelsen – Klimat och energi</a>"],"signs":[]},{"id":"env-climate-factors","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"Which of these affects how large road traffic’s climate emissions are?","img":"","opts":["How much we drive, biofuels, energy efficiency and electrification","Only the colour of the cars","Only the number of traffic lights","Only the weather"],"a":0,"ex":"Emissions depend on the <strong>amount of traffic</strong>, the use of <strong>biofuels</strong>, the vehicles’ <strong>energy efficiency</strong> and how many are <strong>electric</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/klimat-och-energi/\" target=\"_blank\" rel=\"noopener\" title=\"Climate and energy\">Transportstyrelsen – Klimat och energi</a>"],"signs":[]},{"id":"env-euro","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What does Transportstyrelsen advise if you want to be sure you can drive everywhere in towns?","img":"","opts":["Choose a vehicle with the latest Euro class","Choose the biggest engine","Choose a diesel car","Choose an old car"],"a":0,"ex":"Because of environmental zones, Transportstyrelsen advises choosing a vehicle with the <strong>latest Euro class</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/miljozoner/\" target=\"_blank\" rel=\"noopener\" title=\"Environmental zones\">Transportstyrelsen – Miljözoner</a>"],"signs":[]},{"id":"env-zone-mc","area":"environment","paths":["motorcycle"],"lesson":"environment-and-vehicles","q":"Do the environmental zone rules cover motorcycles?","img":"","opts":["No – the classes apply to cars, buses and trucks","Yes – all motorcycles need Euro 5","Yes – motorcycles may never enter","Only electric motorcycles"],"a":0,"ex":"The environmental zone classes apply to heavy trucks and buses (class 1), cars, light trucks and light buses (class 2), and both groups (class 3) – <strong>not motorcycles</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P22\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 22 §\">TrF 4 kap. 22 §</a>"],"signs":[]},{"id":"env-mc-euro5","area":"environment","paths":["motorcycle"],"lesson":"environment-and-vehicles","q":"Which environmental requirement applies to new types of motorcycles from 1 January 2020?","img":"","opts":["Euro 5","Euro 3","No requirement","Electric drive only"],"a":0,"ex":"EU rules made the second stage of environmental requirements – <strong>Euro 5</strong> – mandatory for new types of motorcycles from <strong>1 January 2020</strong>, with on-board diagnostics monitoring the emission control system.","src":["<a class=\"cite\" href=\"https://oeil.europarl.europa.eu/oeil/en/document-summary?id=1257404\" target=\"_blank\" rel=\"noopener\" title=\"EU type-approval rules for motorcycles and mopeds\">EU Regulation 168/2013 (summary)</a>"],"signs":[]},{"id":"env-wash","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"Where should you wash your car?","img":"","opts":["At a car wash with water treatment, or a self-service hall with oil separators","On the street, where the rain washes it away","On the driveway, with lots of detergent","In a lake"],"a":0,"ex":"Dirty wash water from the street or driveway goes straight to <strong>streams, lakes or the sea</strong>. It contains oil, detergents and asphalt residues that harm plants and animals.","src":["<a class=\"cite\" href=\"https://media.helsingborg.se/uploads/networks/1/2019/04/mf-informerar-biltvatt.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Car washing (Helsingborg environmental office)\">Helsingborgs stad – Biltvätt</a>"],"signs":[]},{"id":"env-degreaser","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"You need a degreaser for the car. What should you choose?","img":"","opts":["One without aromatic substances","The strongest one available","Petrol","Any – they are all the same"],"a":0,"ex":"Degreasers can contain aromatic substances that are harmful to the environment and to people – choose an <strong>aromatic-free</strong> one, and eco-labelled car care products.","src":["<a class=\"cite\" href=\"https://media.helsingborg.se/uploads/networks/1/2019/04/mf-informerar-biltvatt.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Car washing (Helsingborg environmental office)\">Helsingborgs stad – Biltvätt</a>"],"signs":[]},{"id":"env-fuels","area":"environment","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"Which of these are alternative fuels for vehicles?","img":"","opts":["Electricity, biofuels, HVO, biogas and hydrogen","Only petrol and diesel","Only coal","Only electricity"],"a":0,"ex":"Transportstyrelsen names <strong>electricity, biofuels, HVO, hydrogen and biogas</strong> as alternative fuels. Always use a fuel your vehicle is made for.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/klimat-och-energi/\" target=\"_blank\" rel=\"noopener\" title=\"Climate and energy\">Transportstyrelsen – Klimat och energi</a>"],"signs":[]},{"id":"pf-limit","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"From what blood alcohol level is it drink-driving (<em>rattfylleri</em>)?","img":"","opts":["0.2 per mille","0.5 per mille","0.8 per mille","1.0 per mille"],"a":0,"ex":"Drink-driving starts at <strong>0.2 per mille</strong> in the blood or <strong>0.10 mg/l</strong> in the breath – during or after driving.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4 §\">Trafikbrottslagen 4 §</a>"],"signs":[]},{"id":"pf-gross","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"From what blood alcohol level is drink-driving normally judged as <strong>aggravated</strong> (<em>grovt rattfylleri</em>)?","img":"","opts":["1.0 per mille","0.5 per mille","0.2 per mille","2.0 per mille"],"a":0,"ex":"It is judged especially as aggravated with at least <strong>1.0 per mille</strong> in the blood (0.50 mg/l breath), when the driver is considerably affected, or when the driving was an obvious danger to traffic safety. Up to two years in prison.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4a\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4a §\">Trafikbrottslagen 4a §</a>"],"signs":[]},{"id":"pf-penalty","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"What is the penalty for drink-driving (not aggravated)?","img":"","opts":["Fines or prison for up to six months","Only a warning","Prison for at least two years","Only a fine"],"a":0,"ex":"Drink-driving gives <strong>fines or prison for up to six months</strong>. Aggravated drink-driving gives prison for up to two years.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4 §\">Trafikbrottslagen 4 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4a\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4a §\">Trafikbrottslagen 4a §</a>"],"signs":[]},{"id":"pf-after","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"Your breath test is taken an hour <strong>after</strong> you stopped driving and shows 0.12 mg/l. Does it count?","img":"","opts":["Yes – the level during or after the journey counts","No – only the level while driving counts","Only if you admit it","Only on motorways"],"a":0,"ex":"The law says the alcohol concentration <strong>during or after</strong> the journey counts. 0.12 mg/l is above the 0.10 mg/l breath limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4 §\">Trafikbrottslagen 4 §</a>"],"signs":[]},{"id":"pf-burn","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"On average, how fast does the body get rid of alcohol?","img":"","opts":["About 0.15 per mille an hour – and nothing speeds it up","About 1 per mille an hour","Faster if you drink coffee","Faster if you sleep"],"a":0,"ex":"The body gets rid of on average about <strong>0.15 per mille per hour</strong> – it varies between people. <strong>Only time</strong> helps.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/alkohol---sa-paverkar-den/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol – how it affects you\">Trafikverket – Alkohol, så påverkar den</a>"],"signs":[]},{"id":"pf-next-day","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"You drank a lot last night. This morning a breath test would show zero. Are you fit to drive?","img":"","opts":["Not necessarily – your ability can be clearly reduced the day after","Yes – zero means fit","Yes, after a strong coffee","Yes, if you slept 8 hours"],"a":0,"ex":"Trafikverket warns that your ability can be <strong>clearly reduced the day after</strong>, even when the alcohol level is zero – avoid driving then.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/alkohol---sa-paverkar-den/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol – how it affects you\">Trafikverket – Alkohol, så påverkar den</a>"],"signs":[]},{"id":"pf-effects","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"Which of these is an effect of alcohol on a driver?","img":"","opts":["Tunnel vision, longer reaction time and worse judgement of distance","Better night vision","Faster reactions","Less sensitivity to glare"],"a":0,"ex":"Alcohol gives <strong>tunnel vision</strong>, a <strong>longer reaction time</strong> even at low levels, worse <strong>coordination</strong>, worse judgement of <strong>distances</strong>, and more sensitivity to <strong>glare</strong> in the dark.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/alkohol---sa-paverkar-den/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol – how it affects you\">Trafikverket – Alkohol, så påverkar den</a>"],"signs":[]},{"id":"pf-drugs","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"What is the limit for narcotics in the blood when driving?","img":"","opts":["Zero – any narcotic substance in the blood counts, unless taken as prescribed","The same as for alcohol, 0.2 per mille","There is no limit for drugs","Only cannabis is counted"],"a":0,"ex":"For narcotics there is <strong>zero tolerance</strong>: it is drug-driving if any narcotic substance remains in the blood – unless it was taken as prescribed by a doctor.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4 §\">Trafikbrottslagen 4 §</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/vad-sager-lagen-om-rattfylleri/\" target=\"_blank\" rel=\"noopener\" title=\"What does the law say about drink-driving?\">Trafikverket – Vad säger lagen om rattfylleri?</a>"],"signs":[]},{"id":"pf-medicine","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"Your doctor prescribed a strong painkiller that makes you drowsy. Who is responsible if you drive?","img":"","opts":["You – you can be convicted if you are so affected that you cannot drive safely","The doctor","The pharmacy","Nobody, since it is prescribed"],"a":0,"ex":"Even with a prescription, you can be convicted of drink-driving if you are so affected that you cannot drive safely. <strong>You</strong> are responsible for how a medicine affects you.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P4\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 4 §\">Trafikbrottslagen 4 §</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/alkohol---sa-paverkar-den/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol – how it affects you\">Trafikverket – Alkohol, så påverkar den</a>"],"signs":[]},{"id":"pf-breath-test","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"May the police stop you for a breath test even if you have done nothing wrong?","img":"","opts":["Yes – screening tests need no suspicion","No – only after an accident","Only at night","Only with a court order"],"a":0,"ex":"The police may carry out <strong>breath screening tests without any prior suspicion</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/vad-sager-lagen-om-rattfylleri/\" target=\"_blank\" rel=\"noopener\" title=\"What does the law say about drink-driving?\">Trafikverket – Vad säger lagen om rattfylleri?</a>"],"signs":[]},{"id":"pf-revoked","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"What usually happens to the licence after drink-driving?","img":"","opts":["It is revoked","Nothing","A warning only","It is renewed"],"a":0,"ex":"Drink-driving <strong>almost always</strong> leads to the licence being revoked.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/vad-sager-lagen-om-rattfylleri/\" target=\"_blank\" rel=\"noopener\" title=\"What does the law say about drink-driving?\">Trafikverket – Vad säger lagen om rattfylleri?</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P3\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 3 §\">KKL 5 kap. 3 §</a>"],"signs":[]},{"id":"pf-alcolock","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"After drink-driving with alcohol, what can you apply for instead of losing the licence?","img":"","opts":["A licence with an alcolock condition for one or two years","A shorter waiting period if you pay a fee","A licence valid only at night","Nothing – revocation is the only option"],"a":0,"ex":"You can apply for a licence with an <strong>alcolock condition</strong> – <strong>1 year</strong>, or <strong>2 years</strong> after aggravated or repeated drink-driving. You may then only drive vehicles with your own approved alcolock, and only in Sweden.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P20\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 20 §\">KKL 5 kap. 20 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P22\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 22 §\">KKL 5 kap. 22 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/alkolas-efter-rattfylleri/\" target=\"_blank\" rel=\"noopener\" title=\"Alcolock after drink-driving\">Transportstyrelsen – Alkolås efter rattfylleri</a>"],"signs":[]},{"id":"pf-alcolock-drugs","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"Can you get an alcolock licence after drug-driving?","img":"","opts":["No – only after drink-driving with alcohol","Yes, always","Yes, after one year","Yes, if you pay for it"],"a":0,"ex":"The alcolock alternative is only for drink-driving caused by <strong>alcohol</strong> – not if narcotics were in the blood, or if you use narcotics.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/alkolas-efter-rattfylleri/\" target=\"_blank\" rel=\"noopener\" title=\"Alcolock after drink-driving\">Transportstyrelsen – Alkolås efter rattfylleri</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P16\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 16 §\">KKL 5 kap. 16 §</a>"],"signs":[]},{"id":"pf-spirits","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"Which factors affect how high your alcohol level gets?","img":"","opts":["Sex, body weight, food, what you drank and over how long","Only the number of drinks","Only the time of day","Nothing – everyone gets the same level"],"a":0,"ex":"<strong>Sex, body weight, what and how much you have eaten</strong>, what you drank and <strong>over how long</strong> all affect the level. Spirits give a higher level than the same amount of alcohol in wine or beer.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/alkohol---sa-paverkar-den/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol – how it affects you\">Trafikverket – Alkohol, så påverkar den</a>"],"signs":[]},{"id":"pf-killed","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"alcohol-and-drugs","q":"About what share of people killed in Swedish road traffic in 2025 died in alcohol- or drug-related crashes?","img":"","opts":["About 17 %","About 1 %","About 50 %","About 90 %"],"a":0,"ex":"In 2025, <strong>35 people</strong> – <strong>17 %</strong> of everyone killed in road traffic – died in alcohol- or drug-related crashes.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol and drugs in road traffic\">Trafikverket – Alkohol och narkotika i vägtrafiken</a>"],"signs":[]},{"id":"pf-tired-rule","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"Does the law say anything about driving tired?","img":"","opts":["Yes – you may not drive if you cannot drive safely because of exhaustion","No – only alcohol is regulated","Only for truck drivers","Only at night"],"a":0,"ex":"A vehicle may not be driven by anyone who, because of illness, <strong>exhaustion</strong>, alcohol or other substances, cannot drive it safely.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 1 §\">TrF 3 kap. 1 §</a>"],"signs":[]},{"id":"pf-tired-share","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"According to VTI, how common is it for young drivers to fall asleep, or nearly, at the wheel?","img":"","opts":["About 30 % of drivers aged 20–24 report it during the past year","Almost never","About 1 %","All drivers have done it"],"a":0,"ex":"In surveys, about <strong>30 %</strong> of drivers aged <strong>20–24</strong> say they have fallen asleep or nearly fallen asleep while driving during the past year. Tiredness may contribute to about 10–40 % of all crashes.","src":["<a class=\"cite\" href=\"https://www.vti.se/forskning/trafikslag/vagtrafik/trotthet-hos-forare\" target=\"_blank\" rel=\"noopener\" title=\"Driver fatigue\">VTI – Trötthet hos förare</a>"],"signs":[]},{"id":"pf-tired-limits","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"VTI recommends avoiding driving if you have …","img":"","opts":["been awake 19 hours or more, or slept less than 5 hours","slept 7 hours","had a coffee","driven for 30 minutes"],"a":0,"ex":"VTI’s recommendation is to avoid driving after being <strong>awake 19 hours or more</strong>, or after <strong>less than 5 hours</strong> of sleep – and to avoid driving at about <strong>03–06</strong>, when the body clock is at its lowest.","src":["<a class=\"cite\" href=\"https://fudinfo.trafikverket.se/fudinfoexternwebb/Publikationer/Publikationer_001701_001800/Publikation_001723/Uttr%C3%B6ttning%20-%20VTI.PDF\" target=\"_blank\" rel=\"noopener\" title=\"Driving while exhausted – what does the law say?\">VTI – Uttröttning, vad säger lagen? (2013)</a>"],"signs":[]},{"id":"pf-tired-night","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"At what time of day is the body clock at its lowest, so that driving is most risky for tiredness?","img":"","opts":["Late at night, about 03:00–06:00","At noon","In the afternoon, 14:00–16:00","In the evening, 18:00–20:00"],"a":0,"ex":"VTI advises avoiding driving when the body clock is at its lowest – <strong>late at night between about 03 and 06</strong>.","src":["<a class=\"cite\" href=\"https://fudinfo.trafikverket.se/fudinfoexternwebb/Publikationer/Publikationer_001701_001800/Publikation_001723/Uttr%C3%B6ttning%20-%20VTI.PDF\" target=\"_blank\" rel=\"noopener\" title=\"Driving while exhausted – what does the law say?\">VTI – Uttröttning, vad säger lagen? (2013)</a>"],"signs":[]},{"id":"pf-tired-action","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"You notice you are yawning a lot and drifting in the lane. What should you do?","img":"","opts":["Stop as soon as you safely can and rest or sleep","Open the window and turn up the music","Speed up to get home sooner","Drink an energy drink and drive on"],"a":0,"ex":"VTI’s advice is to <strong>stop at once</strong> when you feel tired. Fresh air or music may help for a moment but do not remove the tiredness – rest and sleep do.","src":["<a class=\"cite\" href=\"https://fudinfo.trafikverket.se/fudinfoexternwebb/Publikationer/Publikationer_001701_001800/Publikation_001723/Uttr%C3%B6ttning%20-%20VTI.PDF\" target=\"_blank\" rel=\"noopener\" title=\"Driving while exhausted – what does the law say?\">VTI – Uttröttning, vad säger lagen? (2013)</a>"],"signs":[]},{"id":"pf-tired-groups","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"Which groups does VTI name as being at special risk of tiredness-related crashes?","img":"","opts":["Young drivers, professional drivers, shift workers and people with sleep disorders","Only older drivers","Only motorcyclists","Only drivers of electric cars"],"a":0,"ex":"Risk groups are <strong>young drivers, professional drivers, shift workers</strong> and drivers with <strong>sleep disorders</strong>.","src":["<a class=\"cite\" href=\"https://www.vti.se/forskning/trafikslag/vagtrafik/trotthet-hos-forare\" target=\"_blank\" rel=\"noopener\" title=\"Driver fatigue\">VTI – Trötthet hos förare</a>"],"signs":[]},{"id":"pf-tired-careless","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"You know you are very tired but drive anyway, and cause a crash. Can you be convicted?","img":"","opts":["Yes – driving while knowingly tired can lead to liability for careless driving","No – tiredness is never punished","Only if you were also drunk","Only professional drivers"],"a":0,"ex":"The preparatory works of the Traffic Offences Act describe driving while knowingly tired as a conscious risk that can lead to liability for <strong>careless driving</strong> (<em>vårdslöshet i trafik</em>).","src":["<a class=\"cite\" href=\"https://fudinfo.trafikverket.se/fudinfoexternwebb/Publikationer/Publikationer_001701_001800/Publikation_001723/Uttr%C3%B6ttning%20-%20VTI.PDF\" target=\"_blank\" rel=\"noopener\" title=\"Driving while exhausted – what does the law say?\">VTI – Uttröttning, vad säger lagen? (2013)</a>","<a class=\"cite\" href=\"https://lagen.nu/1951:649#P1\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 1 §\">Trafikbrottslagen 1 §</a>"],"signs":[]},{"id":"pf-tired-alcohol","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"How do alcohol and tiredness affect each other?","img":"","opts":["Alcohol dampens the body, so you do not notice the tiredness creeping in","Alcohol makes you more alert","They cancel each other out","They have nothing to do with each other"],"a":0,"ex":"Alcohol has a dampening effect – you <strong>do not notice</strong> that tiredness is creeping in.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/alkohol-och-narkotika-i-vagtrafiken/alkohol---sa-paverkar-den/\" target=\"_blank\" rel=\"noopener\" title=\"Alcohol – how it affects you\">Trafikverket – Alkohol, så påverkar den</a>"],"signs":[]},{"id":"pf-rumble","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"fatigue","q":"The rumble strips at the road edge wake you as you drift onto them. What should you do?","img":"","opts":["Stop at the next safe place and rest – it is a sign you are too tired","Continue – the strips will keep you awake","Drive in the middle of the road","Speed up"],"a":0,"ex":"Rumble strips are effective against run-off crashes, but if they wake you, you are <strong>too tired to drive</strong> – stop and rest.","src":["<a class=\"cite\" href=\"https://fudinfo.trafikverket.se/fudinfoexternwebb/Publikationer/Publikationer_001701_001800/Publikation_001723/Uttr%C3%B6ttning%20-%20VTI.PDF\" target=\"_blank\" rel=\"noopener\" title=\"Driving while exhausted – what does the law say?\">VTI – Uttröttning, vad säger lagen? (2013)</a>"],"signs":[]},{"id":"pf-vision-zero","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"What does <strong>Vision Zero</strong> (<em>Nollvisionen</em>) mean?","img":"","opts":["That no one should be killed or seriously injured in traffic","That no one should get a speeding fine","That cars should use zero fuel","That there should be zero traffic in cities"],"a":0,"ex":"Vision Zero means that <strong>no one should be killed or seriously injured</strong> in traffic. The Riksdag decided on it in <strong>1997</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/om-oss/vi-gor-sverige-narmare/nollvisionen-ar-var-ledstjarna/\" target=\"_blank\" rel=\"noopener\" title=\"Vision Zero is our guiding star\">Trafikverket – Nollvisionen</a>"],"signs":[]},{"id":"pf-men","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"In 2025, what share of the people killed in Swedish road traffic were men?","img":"","opts":["About 71 %","About 50 %","About 30 %","About 95 %"],"a":0,"ex":"Of the 203 people killed in 2025, <strong>144 – 71 %</strong> – were men.","src":["<a class=\"cite\" href=\"https://www.trafa.se/globalassets/statistik/vagtrafik/vagtrafikskador/2025/vagtrafikskador-2025.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Road traffic injuries 2025 – official statistics of Sweden\">Trafikanalys – Vägtrafikskador 2025</a>"],"signs":[]},{"id":"pf-young","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"Counted per inhabitant, which age groups have the highest risk of being killed in Swedish road traffic?","img":"","opts":["People 75 and older, and young adults aged 18–24","Children under 10","People aged 40–50","Everyone has the same risk"],"a":0,"ex":"Averaged over 2016–2025, the risk per inhabitant is highest for people <strong>75 and older</strong>, followed by <strong>young adults aged 18–24</strong>.","src":["<a class=\"cite\" href=\"https://www.trafa.se/globalassets/statistik/vagtrafik/vagtrafikskador/2025/vagtrafikskador-2025.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Road traffic injuries 2025 – official statistics of Sweden\">Trafikanalys – Vägtrafikskador 2025</a>"],"signs":[]},{"id":"pf-rural","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"Where did most people killed in road traffic in 2025 die?","img":"","opts":["Outside built-up areas – most often on 70 and 80 km/h roads","In towns on 30 km/h streets","On motorways","In car parks"],"a":0,"ex":"<strong>73 %</strong> died outside built-up areas, most often on roads with <strong>70 or 80 km/h</strong> limits.","src":["<a class=\"cite\" href=\"https://www.trafa.se/globalassets/statistik/vagtrafik/vagtrafikskador/2025/vagtrafikskador-2025.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Road traffic injuries 2025 – official statistics of Sweden\">Trafikanalys – Vägtrafikskador 2025</a>"],"signs":[]},{"id":"pf-group-pressure","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"Your friends in the car cheer you on to drive faster. What does the curriculum want you to be able to do?","img":"","opts":["Resist group pressure – you decide how you drive","Drive faster so they are happy","Let a friend drive instead, whatever their state","Turn up the music"],"a":0,"ex":"The curriculum asks how <strong>group pressure</strong> affects drivers, and that you can judge your ability to <strong>resist group pressure</strong> and impulsive actions.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 5 kap. 2 §\">TSFS 2011:20 5 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 5 kap. 3 §\">TSFS 2011:20 5 kap. 3 §</a>"],"signs":[]},{"id":"pf-thrill","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"What does the curriculum say about using the car for excitement?","img":"","opts":["You should know how to avoid using the vehicle to seek thrills","It is a good way to learn","It is fine outside towns","It is only a problem for motorcyclists"],"a":0,"ex":"The curriculum asks how to avoid using the vehicle as a means of <strong>seeking thrills</strong>, and how impulsive actions, adventure-seeking and play affect safety.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 5 kap. 2 §\">TSFS 2011:20 5 kap. 2 §</a>"],"signs":[]},{"id":"pf-overconfidence","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"Why does the curriculum stress a realistic picture of your own driving ability?","img":"","opts":["Over-estimating your ability leads to too small safety margins","To make driving lessons longer","Because confident drivers drive slowly","It is not mentioned in the curriculum"],"a":0,"ex":"The curriculum wants you to develop a <strong>realistic picture of your own ability</strong>, and the risk education covers the reasons for and consequences of <strong>over-estimating</strong> it.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 2 kap. 1 §\">TSFS 2011:20 2 kap. 1 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202012_40.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on risk education for category B — TSFS 2012:40 5 kap. 6 §\">TSFS 2012:40 5 kap. 6 §</a>"],"signs":[]},{"id":"pf-passenger-role","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"As a passenger, what does the risk education want you to think about?","img":"","opts":["How to avoid riding with a driver affected by alcohol or drugs","Nothing – passengers have no responsibility","How to help the driver go faster","How to use the phone for the driver"],"a":0,"ex":"The risk education asks what you can do to avoid that <strong>you or others</strong> drive or <strong>ride with</strong> a driver affected by alcohol or other drugs.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202012_40.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on risk education for category B — TSFS 2012:40 5 kap. 3 §\">TSFS 2012:40 5 kap. 3 §</a>"],"signs":[]},{"id":"pf-target-2030","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"attitudes-and-risk","q":"What is the target for the number of people killed in Swedish road traffic in 2030?","img":"","opts":["At most 133","At most 500","Zero","At most 250"],"a":0,"ex":"The target is at most <strong>133</strong> deaths in road traffic in <strong>2030</strong> – half the average of 2017–2019.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/om-oss/vi-gor-sverige-narmare/nollvisionen-ar-var-ledstjarna/\" target=\"_blank\" rel=\"noopener\" title=\"Vision Zero is our guiding star\">Trafikverket – Nollvisionen</a>"],"signs":[],"noExam":1},{"id":"pf-two-consequences","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"You are caught speeding by 35 km/h. Which two things can follow?","img":"","opts":["A fine and a decision on your licence from Transportstyrelsen","Only a fine","Only a licence decision","Only a letter of warning from the police"],"a":0,"ex":"A penalty (fine) and a <strong>licence decision</strong> (revocation or warning) are two separate consequences. Speeding 31–40 km/h over the limit normally means <strong>2 months</strong> without a licence.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 1 §\">KKL 5 kap. 1 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/aterkallat-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Revoked driving licence\">Transportstyrelsen – Återkallat körkort</a>"],"signs":[]},{"id":"pf-speed-31","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"What is the usual waiting period after speeding by 31–40 km/h over the limit?","img":"","opts":["2 months","1 week","1 year","No waiting period"],"a":0,"ex":"The most common revocation case is speeding by <strong>31–40 km/h</strong> – normally a <strong>2-month</strong> waiting period. More serious speeding gives a longer period.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/aterkallat-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Revoked driving licence\">Transportstyrelsen – Återkallat körkort</a>"],"signs":[]},{"id":"pf-speed-30-zone","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"Where the limit is 30 km/h, how much over the limit normally leads to a 2-month revocation?","img":"","opts":["21–30 km/h","5–10 km/h","41–50 km/h","Any amount"],"a":0,"ex":"Where the limit is <strong>30 km/h or lower</strong>, speeding by <strong>21–30 km/h</strong> normally gives a waiting period of two months.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/aterkallat-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Revoked driving licence\">Transportstyrelsen – Återkallat körkort</a>"],"signs":[]},{"id":"pf-red-light","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"What is the usual waiting period for driving against a red light?","img":"","opts":["2 months","1 day","2 years","Only a fine"],"a":0,"ex":"Driving against a <strong>red light</strong> normally gives a waiting period of <strong>2 months</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/aterkallat-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Revoked driving licence\">Transportstyrelsen – Återkallat körkort</a>"],"signs":[]},{"id":"pf-probation-revoked","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"Your licence is revoked for two months during your probation period. What must you do to get it back?","img":"","opts":["New learner’s permit, new risk education and pass both tests again","Just wait two months","Pay a fee","Pass only the driving test"],"a":0,"ex":"A revocation <strong>during probation</strong> – even a short one – means a new learner’s permit, a new risk education and <strong>both</strong> the theory and driving tests again. The new licence gets a new probation.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/nytt-korkort-efter-aterkallelse/\" target=\"_blank\" rel=\"noopener\" title=\"Getting a new licence after revocation (with and without probation)\">Transportstyrelsen – nytt körkort efter återkallelse</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P15\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 15 §\">KKL 5 kap. 15 §</a>"],"signs":[]},{"id":"pf-over-year","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"A driver not on probation gets a waiting period longer than one year. What is needed for a new licence?","img":"","opts":["A learner’s permit, the risk education again and both tests","Only a photo","Only the theory test","Nothing"],"a":0,"ex":"With a waiting period <strong>longer than one year</strong>, you need a learner’s permit, a new risk education and to pass the theory and driving tests again.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/nytt-korkort-efter-aterkallelse/\" target=\"_blank\" rel=\"noopener\" title=\"Getting a new licence after revocation (with and without probation)\">Transportstyrelsen – nytt körkort efter återkallelse</a>"],"signs":[]},{"id":"pf-48h","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"The police take your licence for speeding and let you drive for 48 hours. You drive on day three. What is that?","img":"","opts":["Unlawful driving","Allowed until Transportstyrelsen decides","A minor offence with no penalty","Allowed if you are on your way home"],"a":0,"ex":"After the <strong>48 hours</strong>, all driving is <strong>unlawful driving</strong> – even if Transportstyrelsen has not decided yet. The permission cannot be extended.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/om-polisen-tar-ditt-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"If the police take your licence\">Transportstyrelsen – Om polisen tar ditt körkort</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P7\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 7 §\">KKL 5 kap. 7 §</a>"],"signs":[]},{"id":"pf-warning","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"What does a <strong>warning</strong> (<em>varning</em>) on your licence mean?","img":"","opts":["You keep the licence, but it counts against you for 2 years (5 for drink-driving)","You lose the licence for one month","You must take a new test","Nothing at all"],"a":0,"ex":"A warning is a milder decision – you <strong>keep</strong> the licence. It counts against you for <strong>2 years</strong> (5 years for traffic sobriety offences), and new offences are likely to lead to revocation.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/varning-istallet-for-aterkallelse/\" target=\"_blank\" rel=\"noopener\" title=\"A warning instead of revocation\">Transportstyrelsen – Varning istället för återkallelse</a>"],"signs":[]},{"id":"pf-waiting-limits","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"What are the shortest and longest waiting periods after a revocation?","img":"","opts":["1 month and 3 years","1 week and 1 year","6 months and 10 years","There are no limits"],"a":0,"ex":"The waiting period is at least <strong>1 month</strong> and at most <strong>3 years</strong> – at least 1 year for a grave crime such as aggravated drink-driving.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P6\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 6 §\">KKL 5 kap. 6 §</a>"],"signs":[]},{"id":"pf-careless","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"What is the maximum penalty for <strong>gross</strong> careless driving (<em>grov vårdslöshet i trafik</em>)?","img":"","opts":["Prison for up to 2 years","A fine only","Prison for up to 10 years","A warning"],"a":0,"ex":"Gross negligence or obvious indifference to others’ lives or property when driving a motor vehicle gives <strong>prison for up to two years</strong>. Ordinary careless driving gives day-fines.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P1\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 1 §\">Trafikbrottslagen 1 §</a>"],"signs":[]},{"id":"pf-hit-run","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"What can leaving the scene of an accident you were involved in (<em>smitning</em>) lead to?","img":"","opts":["Fines or prison up to 6 months (1 year if grave) – and normally revocation for 2–6 months","Nothing if no one saw it","Only a parking fine","Only a warning"],"a":0,"ex":"Leaving the scene gives <strong>fines or prison up to six months</strong> (one year if grave), and the licence is normally revoked for <strong>2–6 months</strong> – even if you were not to blame.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P5\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 5 §\">Trafikbrottslagen 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/aterkallat-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Revoked driving licence\">Transportstyrelsen – Återkallat körkort</a>"],"signs":[]},{"id":"pf-unlawful","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"You drive while your licence is revoked. What is that?","img":"","opts":["Unlawful driving – fines, or up to 6 months in prison","Allowed in an emergency","Only a parking matter","Allowed during the day"],"a":0,"ex":"Driving without the right to drive is <strong>unlawful driving</strong> (<em>olovlig körning</em>). If the licence had been revoked, the penalty can be <strong>prison for up to six months</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P3\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 3 §\">Trafikbrottslagen 3 §</a>"],"signs":[]},{"id":"pf-repeated","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"You commit several minor offences within two years, for example small speeding offences and not wearing a seat belt. What can happen?","img":"","opts":["The licence can be revoked – normally for 2 months","Nothing – minor offences never affect the licence","Only fines, whatever happens","Your car is taken away"],"a":0,"ex":"<strong>Repeated</strong> offences within a two-year period can lead to revocation – normally a 2-month waiting period, or a warning if there is no earlier warning or revocation.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/aterkallat-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Revoked driving licence\">Transportstyrelsen – Återkallat körkort</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P3\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 3 §\">KKL 5 kap. 3 §</a>"],"signs":[]},{"id":"pf-confiscate","area":"personal","paths":["car-manual","car-automatic","motorcycle"],"lesson":"consequences","q":"Someone keeps driving without a licence with the same car. What can the court do?","img":"","opts":["Confiscate the car, if needed to prevent more crimes","Nothing","Only give a warning","Paint the car"],"a":0,"ex":"A vehicle used in a traffic crime can be <strong>confiscated</strong> if it is needed to prevent further crimes – especially after repeated unlawful driving or drink-driving.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P7\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 7 §\">Trafikbrottslagen 7 §</a>"],"signs":[]},{"id":"bd-care-special","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"Who does the law say you must show <strong>special consideration</strong> for?","img":"","opts":["Children, older people, school crossing patrols and people with a visible disability or illness","Only pedestrians at crossings","Drivers of emergency vehicles only","Cyclists on cycle tracks only"],"a":0,"ex":"The duty of care requires special consideration for <strong>children, older people, school crossing patrols</strong> and people who clearly have a <strong>disability or illness</strong> that hinders them in traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"bd-white-cane","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"A person with a <strong>white cane</strong> is about to cross the street. What does the cane tell you?","img":"","opts":["The person has impaired sight","The person is a school crossing patrol","The person has priority only at night","The person is deaf"],"a":0,"ex":"A white cane shows that the person has <strong>impaired sight</strong>. Show special consideration and be ready to stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"bd-fit","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"You are below the alcohol limit but feel clearly affected after one drink. May you drive?","img":"","opts":["No – nobody may drive who cannot drive safely, whatever the limit","Yes – you are below the limit","Yes, if you drive slowly","Yes, if a passenger has a licence"],"a":0,"ex":"A vehicle may not be driven by anyone who – because of illness, tiredness, alcohol or other substances, or any other reason – <strong>cannot drive safely</strong>. This applies whatever the limits say.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 1 §\">TrF 3 kap. 1 §</a>"],"signs":[]},{"id":"bd-distance","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"What does the law say about the distance to the vehicle in front?","img":"","opts":["It must be long enough to avoid running into it if it slows down or stops, and make overtaking easier for others","At least 3 seconds","At least 50 metres outside built-up areas","At least one car length per 10 km/h"],"a":0,"ex":"The law gives <strong>no number</strong>. The distance must be adapted so there is <strong>no risk of running into</strong> the vehicle in front if it slows down or stops, and so that others can <strong>overtake</strong> more easily. 3 seconds is only a rule of thumb.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 2 §\">TrF 3 kap. 2 §</a>"],"signs":[]},{"id":"bd-emergency","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"An ambulance with siren and blue lights comes up behind you. What does the law require?","img":"","opts":["Make way for it – and stop if necessary","Speed up to the speed limit","Stop at once wherever you are","Nothing, if you are on a main road"],"a":0,"ex":"A road user must <strong>make way</strong> for an emergency vehicle using its siren and blue lights, and <strong>stop if necessary</strong>. Usually you move as far right as you safely can and slow down.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 5 §\">TrF 2 kap. 5 §</a>"],"signs":[]},{"id":"bd-emergency-junction","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"You wait at a red light. A fire engine with siren and blue lights needs to get past you. What should you do?","img":"","opts":["Make room as well as you safely can without creating new danger – check the traffic around you","Drive straight out into the junction against red","Stay still – red always means stop","Turn off the engine"],"a":0,"ex":"You must make way and stop if necessary – but do what you <strong>safely</strong> can. A sudden move into a junction can cause a collision; the duty of care still applies.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 5 §\">TrF 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"bd-column","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"A funeral procession is passing through a junction. May you drive into a gap in it?","img":"","opts":["No","Yes, if you have green","Yes, if the gap is large","Yes, if you sound the horn"],"a":0,"ex":"You may not break into or obstruct a <strong>military column</strong>, a <strong>rescue service</strong> column, a <strong>group of children</strong> led by an adult, a <strong>funeral procession</strong> or another procession.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 6 §\">TrF 2 kap. 6 §</a>"],"signs":[]},{"id":"bd-signal-right","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"You indicate that you are going to change lanes. Does that give you the right to move over?","img":"","opts":["No – you must still make sure it can be done without danger or unnecessary obstruction","Yes – after three flashes","Yes, if you indicate in good time","Yes, on a motorway"],"a":0,"ex":"Signalling <strong>does not give you the right</strong> to go. You must still make sure the manoeuvre can be done without danger or unnecessary obstruction.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P66\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 66 §\">TrF 3 kap. 66 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P43\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 43 §\">TrF 3 kap. 43 §</a>"],"signs":[]},{"id":"bd-signal-when","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"When must you use the direction indicator?","img":"","opts":["When you start from the roadside, turn, turn around, change lanes or otherwise move sideways noticeably","Only when there are other vehicles around","Only when turning left","Only in built-up areas"],"a":0,"ex":"You must signal when you intend to <strong>start from the roadside, turn around, turn, change lanes</strong> or otherwise move sideways in a way that is not insignificant – in good time, clearly, and stop when the manoeuvre is done.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P65\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 65 §\">TrF 3 kap. 65 §</a>"],"signs":[]},{"id":"bd-horn","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"When may you use the horn?","img":"","opts":["When needed to prevent danger – and no longer than necessary","To greet friends","To tell a slow driver to hurry up","Whenever you overtake"],"a":0,"ex":"The horn – and a flash of the headlights – may only be used when needed to <strong>prevent danger</strong>, and not longer than necessary.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P64\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 64 §\">TrF 3 kap. 64 §</a>"],"signs":[]},{"id":"bd-object-road","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"Part of your load falls onto the road. What must you do?","img":"","opts":["Remove it at once – or, if you cannot, warn others until it is removed","Drive on and report it the next day","Nothing if it is small","Call a tow truck and drive on"],"a":0,"ex":"Whoever has caused something dangerous to be on the road must <strong>remove it immediately</strong>. If that is not possible, they must <strong>warn others</strong> – for example by marking it – until it has been removed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 10 §\">TrF 2 kap. 10 §</a>"],"signs":[]},{"id":"bd-sign-knocked","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"You accidentally knock over a road sign. What should you do?","img":"","opts":["Put it back, or tell the police or road authority at once","Leave it – it is the municipality’s job","Take it with you","Put it anywhere at the roadside"],"a":0,"ex":"You may never move or change a road sign or other traffic device. If you have knocked one over, put it back or tell the <strong>police or road authority</strong> at once.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 9 §\">TrF 2 kap. 9 §</a>"],"signs":[]},{"id":"bd-noise","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"Which of these is against the rules?","img":"","opts":["Letting the engine make more noise than necessary near homes","Driving at the speed limit at night","Using dipped beam in daylight","Stopping at a red light"],"a":0,"ex":"A motor vehicle may not make more <strong>noise</strong> or exhaust fumes than necessary, and you may not drive around needlessly near homes.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 7 §\">TrF 4 kap. 7 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 8 §\">TrF 4 kap. 8 §</a>"],"signs":[]},{"id":"bd-owner","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"basic-duties","q":"A friend borrows your car in January and it has summer tyres in winter conditions. Who can be responsible?","img":"","opts":["Also you, as the owner","Only your friend","Only the tyre shop","Nobody"],"a":0,"ex":"The <strong>owner</strong> is responsible for making sure the vehicle is not used in breach of certain rules – for example winter tyres when required, or overloading – even when someone else drives it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K1P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 1 kap. 5 §\">TrF 1 kap. 5 §</a>"],"signs":[],"noExam":1},{"id":"rp-keep-right","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"You drive on a road outside a built-up area with two lanes in your direction and a 100 km/h limit. Which lane should you normally use?","img":"","opts":["The right-hand lane","The left-hand lane","Either lane","The lane with less traffic"],"a":0,"ex":"The basic rule is to use the lane <strong>furthest to the right</strong> that is intended for your vehicle. The free choice of lane only applies on roads of <strong>70 km/h or lower</strong> with two marked lanes, or where lanes are signed for destinations.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 7 §\">TrF 3 kap. 7 §</a>"],"signs":[]},{"id":"rp-free-lane","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"In town, a street has a 50 km/h limit and two marked lanes in your direction. Which lane may you use?","img":"","opts":["The lane most suitable for your onward journey","Only the right-hand lane","Only the left-hand lane","Only the lane with the least traffic"],"a":0,"ex":"On roads with a limit of <strong>70 km/h or lower</strong> and at least two marked lanes in your direction, you may use the lane that is <strong>most suitable</strong> for your onward journey.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 7 §\">TrF 3 kap. 7 §</a>"],"signs":[]},{"id":"rp-weaving","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"On a 50 km/h street with two lanes in your direction, when may you change lanes?","img":"","opts":["Only to stop or park, to overtake, or to get into the right lane before a junction","Whenever the other lane moves faster","Never","Only in queues"],"a":0,"ex":"Where you may choose your lane freely, you may change lanes <strong>only</strong> to stop or park, to overtake, or to get into a suitable lane before turning.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 9 §\">TrF 3 kap. 9 §</a>"],"signs":[]},{"id":"rp-queue","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"There are dense queues in <strong>all</strong> lanes in your direction. Who may change lanes?","img":"","opts":["Only the driver in the right-hand lane – others only to stop, park or get into the right lane for a junction","Everyone, if they indicate","Only the driver in the left-hand lane","Nobody"],"a":0,"ex":"In dense queues in all lanes, only the driver in the <strong>rightmost</strong> lane may change lanes. Others may only do so to stop or park, or to get into a suitable lane before a junction.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 9 §\">TrF 3 kap. 9 §</a>"],"signs":[]},{"id":"rp-three-lanes","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"A two-way road has <strong>three lanes</strong> in total. Which lane may you not use?","img":"","opts":["The leftmost lane","The middle lane","The rightmost lane","You may use all three"],"a":0,"ex":"On a road with traffic in both directions and three lanes, you may not drive in the <strong>leftmost</strong> lane. With four or more lanes, you may not use the lanes left of the centre.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 8 §\">TrF 3 kap. 8 §</a>"],"signs":[]},{"id":"rp-solid-lanes","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"Two lanes in the same direction are separated by a <strong>solid</strong> line. May you change lanes?","img":"","opts":["No","Yes, if you indicate","Yes, if there is no traffic","Yes, to overtake"],"a":0,"ex":"If a <strong>solid line</strong> separates lanes in the same direction, you may not change lanes.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 9 §\">TrF 3 kap. 9 §</a>"],"signs":[]},{"id":"rp-reverse","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"When may you reverse?","img":"","opts":["Only when it can be done without danger or obstruction to others","Only in car parks","Never on public roads","Whenever you have your hazard lights on"],"a":0,"ex":"You may reverse or turn around only if it can be done <strong>without danger or obstruction</strong>. On motorways and expressways it is never allowed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P46\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 46 §\">TrF 3 kap. 46 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":[]},{"id":"rp-path","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-position","q":"May you drive a car on a footpath to reach a parking space?","img":"","opts":["No – you may only cross it","Yes, at walking pace","Yes, outside opening hours","Yes, if no one is walking there"],"a":0,"ex":"A path meant for certain traffic – such as a footpath or cycle track – may only be <strong>crossed</strong> by other traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 6 §\">TrF 3 kap. 6 §</a>"],"signs":[]},{"id":"sl-adapt","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"The limit is 90 km/h, but thick fog lets you see only 60 metres. How fast may you drive?","img":"","opts":["Only so fast that you can stop within the distance you can see","90 km/h – the limit applies","70 km/h – the base speed","80 km/h if you use fog lights"],"a":0,"ex":"Your speed must always be adapted to the conditions, and never so high that you <strong>cannot stop within the distance you can see</strong>. The limit is a maximum, not a target.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"sl-builtup","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What is the speed limit in a built-up area when no sign shows anything else?","img":"","opts":["50 km/h","30 km/h","40 km/h","60 km/h"],"a":0,"ex":"Within a built-up area the limit is <strong>50 km/h</strong>. The municipality can set 30 or 40 km/h with signs.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 17 §\">TrF 3 kap. 17 §</a>"],"signs":[]},{"id":"sl-base","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What is the <strong>base speed</strong> (<em>bashastighet</em>) outside built-up areas?","img":"","opts":["70 km/h","80 km/h","90 km/h","60 km/h"],"a":0,"ex":"Outside built-up areas the limit is <strong>70 km/h</strong> – the base speed – unless signs show something else.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 17 §\">TrF 3 kap. 17 §</a>"],"signs":[]},{"id":"sl-motorway","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What is the speed limit on a motorway when no sign shows anything else?","img":"","opts":["110 km/h","120 km/h","100 km/h","130 km/h"],"a":0,"ex":"On a motorway the limit is <strong>110 km/h</strong>. Trafikverket may set <strong>120 km/h</strong> with signs.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":[]},{"id":"sl-low-speed-situations","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"In which of these situations does the law specifically require a low enough speed?","img":"","opts":["When approaching a bus that has stopped to let passengers on or off","On a straight motorway in good weather","When overtaking","When driving downhill on a dry road"],"a":0,"ex":"The law lists situations needing low speed – among them approaching a <strong>tram, bus or school bus</strong> that has stopped for passengers, built-up areas, crossings, sharp bends, hill crests, dazzle, slippery roads, children and animals, road works and accidents.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>"],"signs":[]},{"id":"sl-splash","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"The road is full of puddles and slush, and pedestrians walk on the pavement. What must you do?","img":"","opts":["Slow down so you do not splash them","Keep the speed limit","Sound the horn as a warning","Drive in the middle of the road"],"a":0,"ex":"On <strong>dirty roads</strong> where others risk being splashed, the law requires a low enough speed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>"],"signs":[]},{"id":"sl-too-slow","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"Is it allowed to drive unnecessarily slowly or brake suddenly without reason?","img":"","opts":["No – not if it hinders others","Yes, always","Yes, below 30 km/h","Only on motorways"],"a":0,"ex":"You may not drive <strong>unnecessarily slowly</strong> or brake suddenly without good reason in a way that hinders others.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P16\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 16 §\">TrF 3 kap. 16 §</a>"],"signs":[]},{"id":"sl-trailer-braked","area":"rules","paths":["car-manual","car-automatic"],"lesson":"speed-limits","q":"You tow a trailer with a total weight of 1,200 kg that has an <strong>overrun brake</strong>, on a road with a 100 km/h limit. What is your maximum speed?","img":"","opts":["80 km/h","100 km/h","90 km/h","70 km/h"],"a":0,"ex":"A car with a braked trailer (for example with an overrun brake and rigid drawbar, at most 3.5 tonnes) may go at most <strong>80 km/h</strong> – even where the road limit is higher.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 20 §\">TrF 4 kap. 20 §</a>"],"signs":[]},{"id":"sl-towing-rope","area":"rules","paths":["car-manual","car-automatic"],"lesson":"speed-limits","q":"You tow a broken-down car with a tow rope. What is the maximum speed?","img":"","opts":["30 km/h","40 km/h","50 km/h","70 km/h"],"a":0,"ex":"Towing another vehicle with a rope or tow bar – and other cases not listed elsewhere – means at most <strong>30 km/h</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 20 §\">TrF 4 kap. 20 §</a>"],"signs":[]},{"id":"sl-mc-trailer","area":"rules","paths":["motorcycle"],"lesson":"speed-limits","q":"What is the maximum speed for a motorcycle with a trailer?","img":"","opts":["80 km/h","70 km/h","90 km/h","The road’s speed limit"],"a":0,"ex":"A <strong>motorcycle with a trailer</strong> may go at most <strong>80 km/h</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 20 §\">TrF 4 kap. 20 §</a>"],"signs":[]},{"id":"sl-mc-trailer-rules","area":"rules","paths":["motorcycle"],"lesson":"speed-limits","q":"Which trailer may a two-wheeled motorcycle tow?","img":"","opts":["One at most 125 cm wide, weighing at most half the motorcycle’s kerb weight – and never with passengers in it","Any light trailer up to 750 kg","Any trailer if the motorcycle has more than 50 kW","Motorcycles may never tow trailers"],"a":0,"ex":"A two-wheeled motorcycle may tow a trailer of at most <strong>125 cm</strong> width that weighs at most <strong>half the motorcycle’s kerb weight</strong>. Passengers may never ride in it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P15a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 15a §\">TrF 4 kap. 15a §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P15b\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 15b §\">TrF 4 kap. 15b §</a>"],"signs":[]},{"id":"sl-pedestrian-street","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What is the highest speed on a pedestrian street?","img":"","opts":["Walking pace","20 km/h","30 km/h","10 km/h"],"a":0,"ex":"On a pedestrian street and in a walking-speed area, vehicles may go at most <strong>walking pace</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1 §\">TrF 8 kap. 1 §</a>"],"signs":[]},{"id":"rw-right-hand","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"You come to a junction <strong>without signs or signals</strong>. A car approaches from your right. Who goes first?","img":"","opts":["The car from the right","You","Whoever is faster","Whoever is on the wider road"],"a":0,"ex":"When two vehicles’ paths cross, a driver must give way to the vehicle <strong>approaching from the right</strong> – the <strong>right-hand rule</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 18 §\">TrF 3 kap. 18 §</a>"],"signs":[]},{"id":"rw-right-hand-bike","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"At a junction without signs, a <strong>cyclist</strong> comes from your right on the carriageway. Who goes first?","img":"","opts":["The cyclist","You – cars have priority","Whoever arrives first","You, if you are turning right"],"a":0,"ex":"A bicycle is a vehicle too. In an unsigned junction, the <strong>right-hand rule</strong> applies to cyclists as well.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 18 §\">TrF 3 kap. 18 §</a>"],"signs":[]},{"id":"rw-from-left","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"At a junction without signs you have a car on your left. Its driver does not seem to slow down. What do you do?","img":"","opts":["Be ready to stop – having priority never means you may ignore the risk","Keep going – you have priority","Sound the horn and accelerate","Flash your headlights and keep going"],"a":0,"ex":"The car on your left must give way to you, but the <strong>duty of care</strong> still applies: if the other driver does not give way, you must do what you can to avoid a collision.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 18 §\">TrF 3 kap. 18 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"rw-car-park","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"You drive out of a car park onto a street. A car comes from your <strong>left</strong>. Who goes first?","img":"","opts":["The car on the street – you give way to everyone when leaving a car park","You – the car comes from the left","Whoever is faster","You, if you indicate"],"a":0,"ex":"When you come onto a road from a <strong>car park, property, petrol station</strong> or similar, you must give way to <strong>every vehicle</strong> whose path crosses yours – the right-hand rule does not apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>"],"signs":[]},{"id":"rw-across-pavement","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"You drive out of a driveway, across a pavement, onto the street. Who must you give way to?","img":"","opts":["Pedestrians on the pavement and all vehicles on the street","Only vehicles from the right","Only vehicles from the left","Nobody – the driveway is yours"],"a":0,"ex":"Driving out from a <strong>property</strong> across a footpath, you give way to <strong>pedestrians</strong> on it and to <strong>all vehicles</strong> on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P58\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 58 §\">TrF 3 kap. 58 §</a>"],"signs":[]},{"id":"rw-order","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"In which order do these decide who goes first at a junction?","img":"","opts":["Police officer → traffic lights → signs and markings → general rules","Signs → police officer → traffic lights → general rules","Traffic lights → police officer → general rules → signs","General rules → signs → traffic lights → police officer"],"a":0,"ex":"A <strong>police officer</strong> overrides everything; a working <strong>traffic light</strong> overrides give-way and stop signs; <strong>signs and markings</strong> override the <strong>general rules</strong> such as the right-hand rule.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P3\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 3 §\">TrF 2 kap. 3 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 2 §\">TrF 2 kap. 2 §</a>"],"signs":[]},{"id":"rw-turn-left","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"You turn left at a junction. An oncoming car is going straight on. Who goes first?","img":"","opts":["The oncoming car","You","Whoever indicates first","Whoever comes from the right"],"a":0,"ex":"A driver turning at a junction must make sure it can be done <strong>without obstructing oncoming traffic</strong> – so the oncoming car goes first.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P24\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 24 §\">TrF 3 kap. 24 §</a>"],"signs":[]},{"id":"rw-four-way","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"Four cars arrive at the same time at an unsigned crossroads, one from each direction. What happens?","img":"","opts":["Nobody can go by the right-hand rule alone – the drivers must agree carefully","The car going straight on goes first","The biggest vehicle goes first","The car from the north goes first"],"a":0,"ex":"Everyone has a car on their right, so the <strong>right-hand rule</strong> cannot decide. The drivers must <strong>agree</strong> – carefully, with eye contact and clear signals.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 18 §\">TrF 3 kap. 18 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"rw-tram","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"A tram approaches a junction where no sign gives the tram driver a duty to give way. What do you do?","img":"","opts":["Give the tram free way","The tram must give way to you if you come from the right","Sound the horn","Drive first if you are faster"],"a":0,"ex":"You must give <strong>free way</strong> to trains and trams – unless a road sign gives the tram driver a duty to give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 5 §\">TrF 2 kap. 5 §</a>"],"signs":[]},{"id":"rw-block-junction","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"The queue ahead continues through the junction. When may you drive into the junction?","img":"","opts":["When there is room for your whole vehicle on the other side","Whenever you have green","When the car in front starts moving","Never in a queue"],"a":0,"ex":"Drive so that you <strong>will not block</strong> crossing traffic if you have to stop. Wait before the junction until there is room on the other side.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 20 §\">TrF 3 kap. 20 §</a>"],"signs":[]},{"id":"rw-bus-stop-island","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"A bus has stopped at a stop <strong>without a traffic island</strong>, and passengers are getting off. You pass on its right side (for example a tram in the middle of the street). What must you do?","img":"","opts":["Stop and let the passengers get on and off","Drive past slowly","Sound the horn","Pass on the left instead"],"a":0,"ex":"When you pass a tram or bus stopped at a stop <strong>without a traffic island</strong>, on its right side, you must <strong>stop</strong> and let passengers get on and off.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P58\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 58 §\">TrF 3 kap. 58 §</a>"],"signs":[]},{"id":"rw-pedestrians-meet","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"You meet pedestrians walking on a narrow road without a footpath. What must you do?","img":"","opts":["Give them enough room and time to step aside","Sound the horn so they move","Keep your speed – they must move","Flash your lights"],"a":0,"ex":"When you <strong>meet or overtake</strong> pedestrians, you must give them enough <strong>room and time</strong> to step aside.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P58\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 58 §\">TrF 3 kap. 58 §</a>"],"signs":[]},{"id":"tl-left-lane","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"The road before a junction has two lanes in your direction. You will turn left. Which lane do you use?","img":"","opts":["The leftmost lane","The rightmost lane","Either lane","The lane with the shortest queue"],"a":0,"ex":"To turn <strong>left</strong>, place the vehicle in good time in the <strong>leftmost</strong> lane; to turn right, in the rightmost lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P25\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 25 §\">TrF 3 kap. 25 §</a>"],"signs":[]},{"id":"tl-right-turn-position","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"How do you position the car when you turn right at a junction?","img":"","opts":["As close to the right edge of the carriageway as is suitable","In the middle of the road","Close to the centre line","It does not matter"],"a":0,"ex":"When turning right, keep as close to the <strong>right edge</strong> as is suitable – then a cyclist cannot end up on your right.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P26\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 26 §\">TrF 3 kap. 26 §</a>"],"signs":[]},{"id":"tl-left-turn-position","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"On a two-way road, where should you be when you turn left?","img":"","opts":["As close to the centre of the carriageway as possible","Close to the right edge","In the oncoming lane","Anywhere, if you indicate"],"a":0,"ex":"When turning left on a two-way road, keep as close to the <strong>centre</strong> as possible – on a one-way road, close to the left edge – and end up on the right side of the road you turn into.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P26\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 26 §\">TrF 3 kap. 26 §</a>"],"signs":[]},{"id":"tl-look-back","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"Before you turn right, what does the law say you must pay special attention to?","img":"","opts":["The traffic behind you – for example cyclists on your right","The traffic signals only","The traffic on your left","Pedestrians on the other side of the road"],"a":0,"ex":"A driver may turn only without danger or unnecessary obstruction to others going the same way, and <strong>special attention</strong> must be paid to the <strong>traffic behind</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P26\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 26 §\">TrF 3 kap. 26 §</a>"],"signs":[]},{"id":"tl-cyclist-left","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"A cyclist is on your right before a junction. You will turn right. Which is true?","img":"","opts":["The cyclist may be going straight on – or even left – so check the mirror and blind spot","A cyclist on the right always turns right","The cyclist must give way to you","Cyclists must always wait behind cars"],"a":0,"ex":"Cyclists may keep to the <strong>right</strong> before a junction even when going <strong>left</strong> – they cross to the far side and turn there. Check your mirror and <strong>blind spot</strong> before turning right.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P28\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 28 §\">TrF 3 kap. 28 §</a>"],"signs":[]},{"id":"tl-two-left","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"You and an oncoming car both turn left at a junction. How do you pass each other?","img":"","opts":["Left side to left side – in front of each other – if it can be done safely","Right side to right side – behind each other","One must wait until the other has turned","It is forbidden for both to turn left at the same time"],"a":0,"ex":"Two vehicles from opposite directions that <strong>both turn left</strong> may pass each other on the <strong>left</strong>, in front of each other, if it can be done without danger or inconvenience.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P27\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 27 §\">TrF 3 kap. 27 §</a>"],"signs":[]},{"id":"tl-roundabout-in","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"Do you have to signal when you <strong>enter</strong> a roundabout?","img":"","opts":["No – there is only one direction to drive","Yes, always left","Yes, always right","Only in two-lane roundabouts"],"a":0,"ex":"Transportstyrelsen’s guide says there is <strong>no requirement to signal</strong> when you drive into a roundabout. You must signal <strong>right when you leave</strong> and when you change lanes in it.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/att-koera-i-cirkulationsplats-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Driving in a roundabout\">Transportstyrelsen – Att köra i cirkulationsplats</a>"],"signs":[]},{"id":"tl-roundabout-out","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What must you do when you leave a roundabout?","img":"","opts":["Signal right","Signal left","Sound the horn","Nothing"],"a":0,"ex":"When you leave a roundabout you <strong>must signal right</strong>. Plan so that you leave from the right-hand lane if you can.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/att-koera-i-cirkulationsplats-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Driving in a roundabout\">Transportstyrelsen – Att köra i cirkulationsplats</a>"],"signs":[]},{"id":"tl-roundabout-left-exit","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"You leave a two-lane roundabout from the <strong>left-hand lane</strong>. What must you watch out for?","img":"","opts":["Vehicles in the right-hand lane that may be going further round – you are changing lanes","Nothing – the left lane has priority","Pedestrians in the middle of the roundabout","Only traffic entering the roundabout"],"a":0,"ex":"Leaving from the left-hand lane means you <strong>cross</strong> the right-hand lane – a lane change. Take extra care with vehicles there, which may be going further round.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/att-koera-i-cirkulationsplats-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Driving in a roundabout\">Transportstyrelsen – Att köra i cirkulationsplats</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P43\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 43 §\">TrF 3 kap. 43 §</a>"],"signs":[]},{"id":"tl-acceleration-lane","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"How do you use an acceleration lane?","img":"","opts":["Match the speed of the traffic you are joining, and move out as soon as it is safe","Stop at the end and wait for a gap","Drive slowly to the end, then move out","Move out immediately, whatever the traffic"],"a":0,"ex":"On an acceleration lane, adapt your speed to the traffic in the lane you are entering, and leave the acceleration lane as soon as it can be done without danger or unnecessary obstruction.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P23\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 23 §\">TrF 3 kap. 23 §</a>"],"signs":[]},{"id":"mo-overtake-side","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"On which side do you normally overtake?","img":"","opts":["On the left","On the right","On either side","On the side with more room"],"a":0,"ex":"Overtaking is normally done on the <strong>left</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P31\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 31 §\">TrF 3 kap. 31 §</a>"],"signs":[]},{"id":"mo-overtake-right","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"The car in front has moved to the centre and signals left to turn. How do you pass it?","img":"","opts":["On the right","On the left","You must wait behind it","On the shoulder only"],"a":0,"ex":"You <strong>must</strong> overtake on the <strong>right</strong> when the vehicle in front turns left or clearly prepares to do so.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P31\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 31 §\">TrF 3 kap. 31 §</a>"],"signs":[]},{"id":"mo-conditions","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"Which of these stops you from overtaking?","img":"","opts":["The car behind you has already started to overtake you","The car in front drives at the speed limit","The road is dry","It is daytime"],"a":0,"ex":"You may not overtake if someone behind you has <strong>started to overtake you</strong>, if the driver in front has signalled to overtake or move left, or if the lane is not free far enough – and only if it can be done without danger.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P32\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 32 §\">TrF 3 kap. 32 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P36\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 36 §\">TrF 3 kap. 36 §</a>"],"signs":[]},{"id":"mo-junction","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"May you overtake a car just before an <strong>unsigned</strong> junction where the right-hand rule applies?","img":"","opts":["No","Yes, if no one is coming","Yes, at most 50 km/h","Yes, if you indicate"],"a":0,"ex":"Overtaking just before or in a junction is forbidden – except when overtaking on the right, when the junction has police or traffic lights, or when the drivers on the crossing road must give way or stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P39\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 39 §\">TrF 3 kap. 39 §</a>"],"signs":[]},{"id":"mo-junction-main","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"You are on a main road. Side roads have give-way signs. May you overtake before a junction (if it is otherwise safe)?","img":"","opts":["Yes – the drivers on the crossing road must give way","No – never before a junction","Only if the junction has traffic lights","Only motorcycles"],"a":0,"ex":"The ban on overtaking before junctions does not apply when signs show that drivers on the crossing road must <strong>give way or stop</strong>. It must still be safe.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P39\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 39 §\">TrF 3 kap. 39 §</a>"],"signs":[]},{"id":"mo-crest","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"May you overtake a car just before a hill crest where you cannot see oncoming traffic, on a road with one lane in each direction?","img":"","opts":["No","Yes, if you are quick","Yes, if you sound the horn","Yes, if the car is slow"],"a":0,"ex":"Overtaking is forbidden at a <strong>hill crest or bend with limited view</strong>, unless you have two lanes in your direction or can overtake without using the lane for oncoming traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P39\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 39 §\">TrF 3 kap. 39 §</a>"],"signs":[]},{"id":"mo-crest-bike","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"Before a hill crest with limited view you come up behind a cyclist. May you overtake if you can do it safely?","img":"","opts":["Yes – two-wheeled vehicles without a sidecar are excepted, but only when it is safe","No – never before a hill crest","Only if the cyclist signals","Only in built-up areas"],"a":0,"ex":"The overtaking bans at junctions, level crossings and places with limited view do not apply to <strong>two-wheeled vehicles without a sidecar</strong> – but overtaking must always be <strong>safe</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P39\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 39 §\">TrF 3 kap. 39 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P32\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 32 §\">TrF 3 kap. 32 §</a>"],"signs":[]},{"id":"mo-crossing","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"A car has stopped before an uncontrolled pedestrian crossing. What do you do?","img":"","opts":["Stop too – it may be stopping for a pedestrian you cannot see","Overtake it carefully","Sound the horn","Pass on the right"],"a":0,"ex":"You may not overtake just before or on an uncontrolled crossing. The car may have stopped for a pedestrian hidden from your view.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P40\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 40 §\">TrF 3 kap. 40 §</a>"],"signs":[]},{"id":"mo-being-overtaken","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"You notice a car behind is overtaking you. What must you do?","img":"","opts":["Keep as far right as possible and not speed up","Speed up so the overtake is shorter","Brake hard","Move to the left to block it"],"a":0,"ex":"When someone overtakes you, keep <strong>as far right as possible</strong> and do <strong>not increase your speed</strong> or make it harder in any other way.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P38\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 38 §\">TrF 3 kap. 38 §</a>"],"signs":[]},{"id":"mo-queue-not-overtaking","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"On a two-lane road with dense queues in both lanes, your lane moves faster. Is it overtaking when you pass cars in the other lane?","img":"","opts":["No","Yes – and it is forbidden","Yes – but allowed","Only if you pass on the right"],"a":0,"ex":"With <strong>dense queues in all lanes</strong>, passing vehicles in another lane is <strong>not</strong> counted as overtaking. Before a pedestrian crossing you must still go slowly enough to stop at once.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P41\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 41 §\">TrF 3 kap. 41 §</a>"],"signs":[]},{"id":"mo-back-right","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"After overtaking on a road with one lane in each direction, what do you do?","img":"","opts":["Move back to the right as soon as it is safe and convenient","Stay in the left lane until the next junction","Brake to let the overtaken car pass again","Signal left for 3 seconds"],"a":0,"ex":"After overtaking, return to the right as soon as it is safe and suitable, and keep a safe sideways distance while you pass.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P37\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 37 §\">TrF 3 kap. 37 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P33\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 33 §\">TrF 3 kap. 33 §</a>"],"signs":[]},{"id":"mo-slow-vehicle","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"You drive a slow vehicle on a narrow, winding road and a queue builds up behind you. What should you do?","img":"","opts":["Slow down and pull aside as soon as possible to let them pass","Keep going – they must wait","Speed up beyond the vehicle’s limits","Stop in the road"],"a":0,"ex":"Drivers of slow or wide vehicles on narrow or winding roads should <strong>slow down and pull aside</strong> as soon as possible to let others pass.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P38\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 38 §\">TrF 3 kap. 38 §</a>"],"signs":[]},{"id":"mo-cyclist-room","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"You want to overtake a cyclist, but oncoming traffic means you cannot leave a safe distance. What do you do?","img":"","opts":["Wait behind the cyclist","Overtake closely and quickly","Sound the horn so the cyclist moves","Flash your lights"],"a":0,"ex":"When overtaking you must leave a <strong>safe sideways distance</strong>. If you cannot, wait behind until you can.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P33\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 33 §\">TrF 3 kap. 33 §</a>"],"signs":[]},{"id":"pc-who-pedestrian","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"Who counts as a <strong>pedestrian</strong> under the rules?","img":"","opts":["A person walking beside and pushing a motorcycle","A person riding an e-scooter at 20 km/h","A person cycling slowly","A moped rider in a queue"],"a":0,"ex":"The rules for pedestrians also apply to people who <strong>walk beside and push</strong> a bicycle, moped or motorcycle, ski, skate, push a pram or wheelchair, and similar.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K1P4\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 1 kap. 4 §\">TrF 1 kap. 4 §</a>"],"signs":[]},{"id":"pc-escooter","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"Under Swedish law, what is a typical <strong>e-scooter</strong> (<em>elsparkcykel</em>) built for at most 20 km/h?","img":"","opts":["A cycle","A class I moped","A motor vehicle","A pedestrian aid"],"a":0,"ex":"Small electric one-person vehicles built for at most <strong>20 km/h</strong> with at most 250 W – most e-scooters – count as <strong>cycles</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>"],"signs":[]},{"id":"pc-ebike","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"An electrically assisted bicycle counts as a cycle if the motor …","img":"","opts":["only helps when you pedal, stops helping above 25 km/h and has at most 250 W","helps up to 45 km/h","has up to 1,000 W","can drive the bicycle without pedalling"],"a":0,"ex":"An e-bike is a <strong>cycle</strong> if the motor only helps when you pedal, gives <strong>no help above 25 km/h</strong>, and has at most <strong>250 watts</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>"],"signs":[]},{"id":"pc-cyclist-carriageway","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"A 16-year-old cyclist rides on the carriageway on a 50 km/h street even though there is a cycle track. Is that allowed?","img":"","opts":["Yes – cyclists aged 15 or more may use the carriageway with special care where the limit is 50 km/h or lower, if it suits their destination better","No – cyclists must always use the cycle track","Only at night","Only if they wear a helmet"],"a":0,"ex":"Bicycles normally use the cycle track, but a cyclist who is <strong>at least 15</strong> may use the carriageway instead, with special care, where the limit is <strong>50 km/h or lower</strong> and it suits the destination better.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 6 §\">TrF 3 kap. 6 §</a>"],"signs":[]},{"id":"pc-side-by-side","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"May cyclists ride side by side on the road?","img":"","opts":["Yes, when it causes no danger or inconvenience","Never","Only on cycle streets","Only children"],"a":0,"ex":"Cyclists ride one behind the other, but may ride <strong>side by side</strong> when it can be done without danger or inconvenience.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K6P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 6 kap. 1 §\">TrF 6 kap. 1 §</a>"],"signs":[]},{"id":"pc-helmet","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"Who must wear a helmet when cycling?","img":"","opts":["Cyclists under 15","Everyone","Cyclists over 65","Nobody – it is only recommended"],"a":0,"ex":"Cyclists <strong>under 15</strong> must wear a helmet.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K6P4a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 6 kap. 4a §\">TrF 6 kap. 4a §</a>"],"signs":[]},{"id":"pc-child-footpath","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"A 7-year-old cycles on the footpath where there is no cycle track. Is that allowed?","img":"","opts":["Yes – children up to and including the year they turn 8 may","No – never","Only with a parent","Only on Sundays"],"a":0,"ex":"Children up to and including the year they turn <strong>eight</strong> may cycle on the <strong>footpath</strong> if there is no cycle track.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P12a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 12a §\">TrF 3 kap. 12a §</a>"],"signs":[]},{"id":"pc-ped-left","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"Where there is no footpath or shoulder, on which side should pedestrians walk if possible?","img":"","opts":["On the left, facing the traffic","On the right, with the traffic","In the middle of the road","It does not matter"],"a":0,"ex":"Pedestrians who must use the carriageway should walk on the <strong>left</strong> side where possible, facing the oncoming traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K7P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 7 kap. 1 §\">TrF 7 kap. 1 §</a>"],"signs":[]},{"id":"pc-supervised-green","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"At a crossing with traffic lights, your light turns green while a pedestrian who started on green is still crossing. What do you do?","img":"","opts":["Let the pedestrian finish crossing","Drive on – you have green","Sound the horn","Drive around the pedestrian"],"a":0,"ex":"At a supervised crossing, obey the signals and give pedestrians who stepped out correctly <strong>time to cross</strong> – even if you have green.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P60\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 60 §\">TrF 3 kap. 60 §</a>"],"signs":[]},{"id":"pc-door","area":"rules","paths":["car-manual","car-automatic"],"lesson":"pedestrians-and-cyclists","q":"You have parked by the kerb on a street with cyclists. What should you do before opening the driver’s door?","img":"","opts":["Look in the mirror and over your shoulder – the door may not be opened in a way that causes danger","Open quickly to save time","Sound the horn first","Nothing – cyclists must keep their distance"],"a":0,"ex":"Doors may not be opened in a way that causes <strong>danger</strong>. Check the mirror and look over your shoulder – a cyclist may be right beside you.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P50\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 50 §\">TrF 3 kap. 50 §</a>"],"signs":[]},{"id":"pc-cyclist-from-track","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"A cyclist comes off a cycle track onto the road in front of you. Who should give way?","img":"","opts":["The cyclist","You","Whoever is on the right","Nobody"],"a":0,"ex":"A road user coming onto a road from a <strong>cycle track</strong> must give way. But always be ready – you must still avoid a collision.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"lc-barrier-up","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"A train has passed, and the barriers are <strong>going up</strong> but the lights still flash. May you drive onto the crossing?","img":"","opts":["No – wait until the barriers are fully up and the lights have stopped","Yes, as soon as the train has passed","Yes, if no other train is visible","Yes, slowly"],"a":0,"ex":"You may not drive in while a barrier is going down, is down <strong>or is going up</strong>, or while the lights flash or the bell rings. Another train may come.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 7 §\">TrF 2 kap. 7 §</a>"],"signs":[]},{"id":"lc-room","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"A queue stands just beyond a level crossing. When may you drive over?","img":"","opts":["Only when there is room for your whole vehicle on the other side","When the lights are not flashing","When the barriers are up","When the car in front starts"],"a":0,"ex":"You may not enter a level crossing if there is a risk you will <strong>have to stop</strong> on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 7 §\">TrF 2 kap. 7 §</a>"],"signs":[]},{"id":"lc-warning-late","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"The lights start flashing just as you reach the crossing. What does Trafikverket advise?","img":"","opts":["Stop before the barriers if you can – if you cannot, drive on. Never stop on the track","Always brake hard","Reverse at once","Stop on the crossing and wait"],"a":0,"ex":"Trafikverket: <strong>stop before the barriers if you can; if you cannot, drive on. Never stop on the track.</strong>","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-vid-jarnvag/sakerhet-vid-plankorsningar/\" target=\"_blank\" rel=\"noopener\" title=\"Safety at level crossings\">Trafikverket – Säkerhet vid plankorsningar</a>"],"signs":[]},{"id":"lc-white-light","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"Below the red lights of this level-crossing signal a <strong>white</strong> light flashes. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"Y1\" alt=\"Y1 Level crossing light signal\" width=\"64\" height=\"64\"></div>","opts":["It makes the crossing easier to notice – it is not a signal to drive","You may drive on","A train is coming in 10 seconds","The signal is broken"],"a":0,"ex":"The white flashing light below the red lights is there to make the crossing <strong>easier to notice</strong>. Red flashing lights mean <strong>stop</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K6P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 6 kap. 6 §\">VMF 6 kap. 6 §</a>"],"signs":["Y1"]},{"id":"lc-overtake","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"May you overtake a car just before a level crossing <strong>without barriers</strong>?","img":"","opts":["No","Yes, if no train is coming","Yes, at most 50 km/h","Yes, on the right"],"a":0,"ex":"Overtaking just before or on a level crossing is forbidden – unless it has <strong>barriers</strong> or is controlled by traffic lights like a road junction. (Two-wheeled vehicles without a sidecar may still be overtaken if it is safe.)","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P39\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 39 §\">TrF 3 kap. 39 §</a>"],"signs":[]},{"id":"lc-parking","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"How close to a level crossing may you park?","img":"","opts":["Not within 30 metres before or after it","Not within 10 metres before it","Not on it – otherwise anywhere","Not within 100 metres"],"a":0,"ex":"Parking is forbidden within <strong>30 metres</strong> of a level crossing – before and after it. Stopping or parking on the crossing is always forbidden.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P55\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 55 §\">TrF 3 kap. 55 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P47\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 47 §\">TrF 3 kap. 47 §</a>"],"signs":[]},{"id":"lc-stuck","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"Your car stops on a level crossing and will not start. What do you do first?","img":"","opts":["Get everyone out and away from the tracks, then call 112","Try to restart the engine again and again","Put out the warning triangle on the track","Stay in the car with the hazard lights on"],"a":0,"ex":"Get everyone out and <strong>well away</strong> from the tracks at once, and call <strong>112</strong>. The crossing’s ID number is on the back of the St Andrew’s cross. Only try to move the car if there is clearly time.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P57\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 57 §\">TrF 3 kap. 57 §</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-vid-jarnvag/sakerhet-vid-plankorsningar/\" target=\"_blank\" rel=\"noopener\" title=\"Safety at level crossings\">Trafikverket – Säkerhet vid plankorsningar</a>"],"signs":[]},{"id":"lc-trapped","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"You are trapped on a level crossing between closed barriers. What may the text on the back of the barrier tell you?","img":"","opts":["Kör genom bommen – drive through the barrier","Vänta – wait","Backa – reverse","Ring – call"],"a":0,"ex":"The back of a barrier may say <em>Kör genom bommen</em> – <strong>drive through the barrier</strong>. The barrier is built to give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K6P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 6 kap. 8 §\">VMF 6 kap. 8 §</a>"],"signs":[]},{"id":"lc-stop-look-listen","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"Why does Trafikverket tell you to always stop, look and listen at level crossings?","img":"","opts":["Trains are quiet and fast, have a long braking distance and cannot swerve","Trains always sound their horn, so you only need to listen","Level crossings are always guarded","Trains must give way to cars"],"a":0,"ex":"Trains are <strong>quiet, fast</strong>, have a <strong>long braking distance</strong> and <strong>cannot swerve or stop suddenly</strong>. They in principle always have priority.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-vid-jarnvag/sakerhet-vid-plankorsningar/\" target=\"_blank\" rel=\"noopener\" title=\"Safety at level crossings\">Trafikverket – Säkerhet vid plankorsningar</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 5 §\">TrF 2 kap. 5 §</a>"],"signs":[]},{"id":"mw-difference","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What is the main difference between a motorway and an expressway?","img":"","opts":["A motorway has separate carriageways for each direction; an expressway can have oncoming traffic on the same carriageway","An expressway has a 120 km/h limit","Motorcycles may only use expressways","Expressways have level junctions"],"a":0,"ex":"Both have no level junctions and slip roads only. A <strong>motorway</strong> has <strong>two separate carriageways</strong>; an <strong>expressway</strong> can have traffic in both directions on the <strong>same carriageway</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K10P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 10 kap. 7 §\">TrF 10 kap. 7 §</a>"],"signs":[]},{"id":"mw-who","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"Which of these may <strong>not</strong> be driven on a motorway?","img":"","opts":["A class I moped","A motorcycle","A car with a braked trailer","A bus"],"a":0,"ex":"Only motor vehicles built for and allowed to go <strong>at least 40 km/h</strong> may use a motorway – and <strong>class I mopeds</strong> are expressly banned.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":[]},{"id":"mw-expressway-limit","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"You drive on an expressway (<em>motortrafikled</em>) and have seen no speed limit sign. What is the limit?","img":"","opts":["70 km/h – the base speed","110 km/h","90 km/h","100 km/h"],"a":0,"ex":"An expressway has <strong>no limit of its own</strong>. Without signs, the base speed of <strong>70 km/h</strong> applies. (The 110 km/h rule is only for motorways.)","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 17 §\">TrF 3 kap. 17 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":[]},{"id":"mw-missed-exit","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"You miss your exit on the motorway. What do you do?","img":"","opts":["Drive on to the next exit","Stop on the shoulder and reverse","Turn around at the next gap in the central reserve","Stop and ask for help"],"a":0,"ex":"On a motorway you may <strong>never reverse or turn around</strong>, and never drive on the central reserve. Drive on to the next exit.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":[]},{"id":"mw-stop","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"Where may you stop on a motorway or expressway (when your vehicle works)?","img":"","opts":["Only at places signed as parking or rest areas","On the shoulder for at most 5 minutes","Anywhere with hazard lights on","At slip roads"],"a":0,"ex":"Vehicles may not be stopped or parked except at places <strong>signed as parking places or rest areas</strong>. This applies on expressways and slip roads too.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 2 §\">TrF 9 kap. 2 §</a>"],"signs":[]},{"id":"mw-joining","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"You join a motorway from a slip road <strong>without</strong> an acceleration lane. Who gives way?","img":"","opts":["You – to the traffic on the motorway","The traffic on the motorway – to you","Whoever is on the right","Nobody"],"a":0,"ex":"A driver coming onto a motorway, expressway or main road where there is <strong>no acceleration lane</strong> must give way to the traffic on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>"],"signs":[]},{"id":"mw-helping-join","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"You drive in the right-hand lane of a motorway. A car on the acceleration lane is about to join. What does the law ask of you?","img":"","opts":["Adjust your speed to make it easier for it to join","Keep your speed – you have priority","Sound the horn","Brake to a stop"],"a":0,"ex":"A driver who sees that someone wants to move into their lane must <strong>adjust the speed</strong> to make it easier. If it is safe, moving to the left lane also helps.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P43\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 43 §\">TrF 3 kap. 43 §</a>"],"signs":[]},{"id":"mw-leaving","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"Where should you slow down when leaving a motorway?","img":"","opts":["In the deceleration lane","In the right-hand lane before the exit","In the left-hand lane","On the shoulder"],"a":0,"ex":"Move into the right-hand lane in good time, then into the <strong>deceleration lane</strong> as soon as possible – and slow down there, not on the motorway.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P23\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 23 §\">TrF 3 kap. 23 §</a>"],"signs":[]},{"id":"mw-breakdown-triangle","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"Your car breaks down on the shoulder of a 110 km/h motorway. Must you put out a warning triangle?","img":"","opts":["Yes – the limit is above 50 km/h and the car stands where stopping is not allowed","No – hazard lights are enough on motorways","Only at night","Only if the car stands in a lane"],"a":0,"ex":"Where the limit is <strong>above 50 km/h</strong> and the vehicle stands on the carriageway or shoulder where stopping is not allowed, a <strong>warning triangle</strong> must be put out. Get everyone out on the side away from traffic, behind the barrier if there is one.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P57\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 57 §\">TrF 3 kap. 57 §</a>"],"signs":[]},{"id":"mw-towing","area":"rules","paths":["car-manual","car-automatic"],"lesson":"motorways","q":"May you tow a broken-down car on a tow rope along a motorway?","img":"","opts":["No – a towed car may go at most 30 km/h, and only vehicles allowed at least 40 km/h may use motorways","Yes, at most 30 km/h on the shoulder","Yes, if the rope is marked","Yes, in the right-hand lane"],"a":0,"ex":"A car on a tow rope or bar may go at most <strong>30 km/h</strong>, but only vehicles allowed to go <strong>at least 40 km/h</strong> may be driven on motorways and expressways.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 20 §\">TrF 4 kap. 20 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":[]},{"id":"sp-waiting","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"You wait in the car with the engine running while a friend runs into a shop. Is that stopping or parking?","img":"","opts":["Parking","Stopping","Neither","Stopping, if it is shorter than 5 minutes"],"a":0,"ex":"Stopping means standing still to let people in or out or to load or unload. <strong>Everything else</strong> – also waiting in the car with the engine running – is <strong>parking</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:651#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Ordinance (2001:651) — Vägtrafikdefinitionsförordningen 2 §\">Vägtrafikdefinitionsförordningen 2 §</a>"],"signs":[]},{"id":"sp-queue","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"You stand still in a queue at a red light. Is that stopping or parking?","img":"","opts":["Neither – it is caused by the traffic","Stopping","Parking","Both"],"a":0,"ex":"Standing still because of the <strong>traffic</strong> – a queue or a red light – or to avoid danger is neither stopping nor parking.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:651#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Ordinance (2001:651) — Vägtrafikdefinitionsförordningen 2 §\">Vägtrafikdefinitionsförordningen 2 §</a>"],"signs":[]},{"id":"sp-junction-10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"How close to the edge of a crossing road at a junction may you stop?","img":"","opts":["Not within 10 metres","Not within 5 metres","Not within 20 metres","Right at the junction is fine"],"a":0,"ex":"You may not stop or park <strong>in a junction</strong> or within <strong>10 metres</strong> of the nearest edge of a crossing carriageway.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"sp-cycle-track-10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"May you stop to let a passenger out 5 metres before a crossing cycle track?","img":"","opts":["No – not on it or within 10 metres before it","Yes – stopping is always allowed","Yes, if it is quick","Only on Sundays"],"a":0,"ex":"Stopping and parking is forbidden <strong>on, or within 10 metres before</strong>, a crossing cycle track or footpath – and the same before pedestrian crossings, cycle passages and cycle crossings.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"sp-crest","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"Where of these may you <strong>never</strong> stop?","img":"","opts":["Near a hill crest where the view is blocked","On a straight residential street","In a marked parking space","At a petrol station"],"a":0,"ex":"You may not stop or park on or near a <strong>hill crest</strong>, or in or near a <strong>bend</strong> where the view is blocked.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"sp-roundabout-tunnel","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"In which of these places is stopping always forbidden?","img":"","opts":["In a roundabout","On a one-way street","Next to a park","Outside a school, in a marked parking space"],"a":0,"ex":"You may never stop or park in a <strong>roundabout</strong>, a tunnel or underpass, a cycle lane, a restricted (hatched) area or a bus lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"sp-side","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"On a two-way road, on which side may you stop or park?","img":"","opts":["The right-hand side in your direction","Either side","The left-hand side, facing the traffic","The side with the most space"],"a":0,"ex":"Vehicles may only be stopped or parked on the <strong>right</strong> side in the direction of travel – on a one-way road also on the left.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P52\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 52 §\">TrF 3 kap. 52 §</a>"],"signs":[]},{"id":"sp-main-road","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"Which is true on a main road (<em>huvudled</em>)?","img":"","opts":["You may stop briefly, but not park","You may park for up to 2 hours","You may neither stop nor park","You may park at night only"],"a":0,"ex":"Parking is forbidden on a <strong>main road</strong>. Stopping briefly – for example to let someone out – is allowed if nothing else forbids it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P55\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 55 §\">TrF 3 kap. 55 §</a>"],"signs":[]},{"id":"sp-driveway","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"May you park in front of the entrance to someone’s property?","img":"","opts":["No – not in front of it, or so that traffic to and from it is seriously hindered","Yes, for up to one hour","Yes, if you leave a phone number","Yes, outside working hours"],"a":0,"ex":"You may not park on a road <strong>in front of the entrance to a property</strong>, or so that vehicles going to or from it are seriously hindered.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P55\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 55 §\">TrF 3 kap. 55 §</a>"],"signs":[]},{"id":"sp-double","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"May you park on the carriageway beside a car that is already parked along the kerb?","img":"","opts":["No – unless the other vehicle is a two-wheeled bicycle, moped or motorcycle","Yes, for a short time","Yes, with hazard lights on","Yes, in a one-way street"],"a":0,"ex":"Parking beside another vehicle stopped or parked along the edge (double parking) is forbidden – unless it is a <strong>two-wheeled</strong> bicycle, moped or motorcycle without a sidecar.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P55\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 55 §\">TrF 3 kap. 55 §</a>"],"signs":[]},{"id":"sp-lawn","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"In a built-up area, may you park on a public lawn next to the road?","img":"","opts":["No","Yes, if all parking spaces are taken","Yes, at weekends","Yes, if the wheels are close to the kerb"],"a":0,"ex":"In a built-up area you may not stop or park on public ground that is <strong>not road</strong> – for example a lawn, a park or a ditch.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P48\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 48 §\">TrF 3 kap. 48 §</a>"],"signs":[]},{"id":"sp-footpath","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"Which vehicles may be parked on a footpath or cycle track?","img":"","opts":["Only two-wheeled bicycles and two-wheeled class II mopeds","All vehicles for up to 10 minutes","Motorcycles","Small cars"],"a":0,"ex":"On a <strong>footpath or cycle track</strong>, only two-wheeled bicycles and two-wheeled class II mopeds may stop or park.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P48\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 48 §\">TrF 3 kap. 48 §</a>"],"signs":[]},{"id":"sp-leave-car","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What must you do when you leave a parked car?","img":"","opts":["Make sure it cannot start rolling and that nobody else can use it","Leave the key in it so it can be moved","Turn on the hazard lights","Nothing in particular"],"a":0,"ex":"The driver must make sure the vehicle <strong>cannot start moving by itself</strong> (parking brake and gear or P), and take steps so that <strong>nobody can use it</strong> without permission – lock it and take the key.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P50\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 50 §\">TrF 3 kap. 50 §</a>"],"signs":[]},{"id":"sp-dark-lights","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"You park on an unlit country road in darkness, on the carriageway. Which lights must show?","img":"","opts":["Parking lights and rear lights","Main beam","Hazard lights only","No lights"],"a":0,"ex":"In darkness, a vehicle stopped or parked <strong>on a road</strong> must show <strong>parking lights and rear lights</strong> – unless the road is well lit or the vehicle stands outside the carriageway and shoulder.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P74\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 74 §\">TrF 3 kap. 74 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P75\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 75 §\">TrF 3 kap. 75 §</a>"],"signs":[]},{"id":"sp-breakdown","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"Your car breaks down in a place where parking is not allowed. What does the law say?","img":"","opts":["Have it moved to a suitable place as soon as possible","You may leave it there for 24 hours","You may leave it until the next weekday","Nothing – a broken-down car is exempt"],"a":0,"ex":"If an accident or engine failure leaves the vehicle where stopping or parking is not allowed, it must be moved to a suitable place <strong>as soon as possible</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P51\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 51 §\">TrF 3 kap. 51 §</a>"],"signs":[]},{"id":"sp-fine-owner","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"Who must pay a parking fine (<em>felparkeringsavgift</em>) on a public street?","img":"","opts":["The vehicle owner","The person who drove","The municipality","Nobody, if you appeal"],"a":0,"ex":"The <strong>vehicle owner</strong> is responsible for paying the parking fine – even if they want to appeal.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/trans-027-stanna-och-parkera-a5-webb_2024-01-01.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Stopping and parking\">Transportstyrelsen – Stanna och parkera</a>"],"signs":[],"noExam":1},{"id":"sp-ticket","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"Where must you place a parking ticket?","img":"","opts":["At the front of the vehicle, easy to read from outside","In the glove compartment","On the rear window","In your pocket"],"a":0,"ex":"A parking ticket must be put at the <strong>front</strong> of the vehicle (or on it if not possible) so it can easily be read from outside.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P49a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 49a §\">TrF 3 kap. 49a §</a>"],"signs":[]},{"id":"li-default","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"Which lights are the basic choice when you drive?","img":"","opts":["Dipped beam","Main beam","Parking lights","Rear fog light"],"a":0,"ex":"When driving on a road the prescribed lights must be on, and the basic choice is <strong>dipped beam</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P68\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 68 §\">TrF 3 kap. 68 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P69\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 69 §\">TrF 3 kap. 69 §</a>"],"signs":[]},{"id":"li-drl-dark","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"May you drive with only daytime running lights at dusk?","img":"","opts":["No – in darkness, dusk, dawn or bad weather you need dipped beam","Yes, always","Yes, in built-up areas","Yes, if the street lights are on"],"a":0,"ex":"Daytime running lights may only replace dipped beam <strong>in daylight</strong> with good visibility – not in <strong>darkness, dusk, dawn</strong> or when the weather makes dipped beam necessary.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P71\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 71 §\">TrF 3 kap. 71 §</a>"],"signs":[]},{"id":"li-drl-rear","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"Why can daytime running lights be dangerous in rain or fog?","img":"","opts":["On many cars they do not light the rear lamps, so the car is hard to see from behind","They dazzle oncoming drivers","They use too much electricity","They are not allowed on motorways"],"a":0,"ex":"On many cars the daytime running lights do <strong>not</strong> light the rear lamps. In rain, snow or fog the car can be almost invisible from behind – so switch to <strong>dipped beam</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P71\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 71 §\">TrF 3 kap. 71 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/vaelj-raett-fordonsbelysning-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Choose the right vehicle lighting\">Transportstyrelsen – Välj rätt fordonsbelysning</a>"],"signs":[]},{"id":"li-main-must","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"When <strong>must</strong> you use main beam?","img":"","opts":["When your field of vision with dipped beam is not enough to drive safely at your speed","Always outside built-up areas at night","Only on motorways","Never – main beam is optional"],"a":0,"ex":"Main beam <strong>must</strong> be used when the driver’s field of vision, given the speed, is otherwise not enough to drive safely.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P70\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 70 §\">TrF 3 kap. 70 §</a>"],"signs":[]},{"id":"li-main-not","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"In which situation may you <strong>not</strong> use main beam?","img":"","opts":["On a road that is adequately lit by street lights","On a dark country road with no other traffic","When there is a risk of animals","On a motorway at night with no traffic ahead"],"a":0,"ex":"Main beam may not be used on a <strong>well-lit</strong> stretch, when it can <strong>dazzle</strong> an oncoming driver, when meeting a train or ship along the road if dazzle is possible, or <strong>close behind</strong> another vehicle.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P70\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 70 §\">TrF 3 kap. 70 §</a>"],"signs":[]},{"id":"li-meeting","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"A car comes towards you on a dark road. When do you switch to dipped beam?","img":"","opts":["In good time, before its driver can be dazzled","When the cars are side by side","Only if the other driver flashes you","Never – you need to see"],"a":0,"ex":"Main beam may not be used at a distance where the oncoming driver can be <strong>dazzled</strong>. Dip in good time and look towards the right edge of the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P70\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 70 §\">TrF 3 kap. 70 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P67\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 67 §\">TrF 3 kap. 67 §</a>"],"signs":[]},{"id":"li-rear-fog","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"When may you use the <strong>rear fog light</strong>?","img":"","opts":["Only in fog, heavy precipitation or similarly poor visibility – and not so that it dazzles drivers behind","Whenever it is dark","Whenever it rains a little","When someone drives too close behind"],"a":0,"ex":"The rear fog light may only be used in <strong>fog, heavy precipitation or similarly poor visibility</strong>, and in a way that does not dazzle drivers behind you.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P72\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 72 §\">TrF 3 kap. 72 §</a>"],"signs":[]},{"id":"li-fog-front","area":"rules","paths":["car-manual","car-automatic"],"lesson":"vehicle-lights","q":"In thick fog, which lights may you use at the front of a car instead of dipped beam?","img":"","opts":["Front fog lights","Main beam and fog lights together","Daytime running lights","Parking lights"],"a":0,"ex":"In <strong>fog and heavy precipitation</strong> you may use <strong>front fog lights</strong> instead of dipped beam. On a car, dipped beam and front fog lights may not be used at the same time.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P71\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 71 §\">TrF 3 kap. 71 §</a>"],"signs":[]},{"id":"li-mc-together","area":"rules","paths":["motorcycle"],"lesson":"vehicle-lights","q":"Which lights may a motorcycle use <strong>together</strong> in daylight?","img":"","opts":["Dipped beam, daytime running lights and fog lights","Only dipped beam","Only daytime running lights","Main beam and rear fog light"],"a":0,"ex":"In daylight a motorcycle may use dipped beam, daytime running lights and fog lights <strong>at the same time</strong> – an exception that does not apply to cars.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P71\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 71 §\">TrF 3 kap. 71 §</a>"],"signs":[]},{"id":"li-white-back","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"Which colour of light may a vehicle show <strong>backwards</strong> while driving (not reversing)?","img":"","opts":["Not white – except when reversing or working","White","Blue","Any colour"],"a":0,"ex":"A vehicle may only show white or yellow light <strong>forwards</strong>, and <strong>no white light backwards</strong> except when reversing or working.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P76\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 76 §\">TrF 3 kap. 76 §</a>"],"signs":[]},{"id":"li-amber","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"A road maintenance vehicle ahead has <strong>amber flashing beacons</strong>. What should you do?","img":"","opts":["Slow down and be ready to stop","Overtake it quickly","Pull over and stop","Nothing special"],"a":0,"ex":"Amber warning beacons are used by vehicles such as road maintenance vehicles. <strong>Slow down and be ready to stop.</strong>","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/vaelj-raett-fordonsbelysning-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Choose the right vehicle lighting\">Transportstyrelsen – Välj rätt fordonsbelysning</a>"],"signs":[]},{"id":"li-hazard","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vehicle-lights","q":"When are the hazard warning lights meant to be used?","img":"","opts":["When your vehicle stands still after a breakdown or accident and temporarily obstructs traffic","When you park illegally for a short time","When you drive slowly in rain","When you thank another driver"],"a":0,"ex":"Hazard warning lights are for when your vehicle is <strong>standing still after a breakdown or accident</strong> and temporarily obstructs traffic.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/vaelj-raett-fordonsbelysning-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Choose the right vehicle lighting\">Transportstyrelsen – Välj rätt fordonsbelysning</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P76\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 76 §\">TrF 3 kap. 76 §</a>"],"signs":[]},{"id":"pl-belt","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"Who must use a seat belt in a car?","img":"","opts":["Everyone, if a seat with a belt is available","Only the driver","Only passengers in the front","Only on motorways"],"a":0,"ex":"Everyone travelling in a vehicle with seat belts must use a seat with a belt, if one is available, and <strong>use the belt</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10 §\">TrF 4 kap. 10 §</a>"],"signs":[]},{"id":"pl-belt-responsible","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"A 12-year-old passenger does not wear the seat belt. Who is responsible?","img":"","opts":["The driver","The child","The car owner","Nobody"],"a":0,"ex":"The <strong>driver</strong> must make sure that passengers <strong>under 15</strong> use a seat belt or child restraint. Passengers aged 15 or over are responsible themselves.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10c\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10c §\">TrF 4 kap. 10c §</a>"],"signs":[]},{"id":"pl-belt-exception","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"When do you <strong>not</strong> have to wear the seat belt?","img":"","opts":["When reversing","In built-up areas","On short trips","Below 30 km/h"],"a":0,"ex":"The belt does not have to be used when the vehicle is <strong>not moving</strong>, when <strong>reversing</strong>, or when driving inside a car park, petrol station or workshop area and similar.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10d\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10d §\">TrF 4 kap. 10d §</a>"],"signs":[]},{"id":"pl-135","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"Up to what height must a child use a child seat, booster seat or booster cushion?","img":"","opts":["Shorter than 135 cm","Shorter than 120 cm","Shorter than 150 cm","Until 7 years old"],"a":0,"ex":"Children <strong>shorter than 135 cm</strong> must use a child seat, booster cushion or other special child restraint.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10 §\">TrF 4 kap. 10 §</a>"],"signs":[]},{"id":"pl-airbag","area":"rules","paths":["car-manual","car-automatic"],"lesson":"passengers-and-loads","q":"Where must you <strong>never</strong> put a rear-facing baby seat?","img":"","opts":["On a seat with an active passenger airbag","In the back seat","Behind the driver","In the middle of the back seat"],"a":0,"ex":"Never put a child in a baby seat, child seat or booster on a seat with an <strong>active passenger airbag</strong> – it can be deadly.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/sa-skyddar-du-barnen---regler-och-tips/\" target=\"_blank\" rel=\"noopener\" title=\"How to protect children in the car – rules and tips\">Transportstyrelsen – Så skyddar du barnen</a>"],"signs":[]},{"id":"pl-rear-facing","area":"rules","paths":["car-manual","car-automatic"],"lesson":"passengers-and-loads","q":"Until about what age does Transportstyrelsen advise children to travel rear-facing?","img":"","opts":["About four years","About one year","About two years","About seven years"],"a":0,"ex":"Children are safest <strong>rear-facing</strong> until about <strong>four years</strong> old. Small children in forward-facing seats run five times the risk of being killed or seriously injured.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/sa-skyddar-du-barnen---regler-och-tips/\" target=\"_blank\" rel=\"noopener\" title=\"How to protect children in the car – rules and tips\">Transportstyrelsen – Så skyddar du barnen</a>"],"signs":[]},{"id":"pl-mc-passenger-age","area":"rules","paths":["motorcycle"],"lesson":"passengers-and-loads","q":"How old must you be to carry a passenger on a motorcycle?","img":"","opts":["18","16","20","24"],"a":0,"ex":"A passenger may only be carried if the rider is at least <strong>18</strong>, the motorcycle is built for a passenger, and at most one passenger is carried.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P6b\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 6b §\">TrF 4 kap. 6b §</a>"],"signs":[]},{"id":"pl-mc-helmet","area":"rules","paths":["motorcycle"],"lesson":"passengers-and-loads","q":"Who must wear a helmet on a motorcycle?","img":"","opts":["Everyone on it – with exceptions such as a passenger under seven using other suitable head protection","Only the rider","Only passengers under 15","Only outside built-up areas"],"a":0,"ex":"Everyone on a motorcycle or moped must wear a protective helmet. The rider must make sure passengers under 15 wear one.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 9 §\">TrF 4 kap. 9 §</a>"],"signs":[]},{"id":"pl-load-behind","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"A load sticks out <strong>more than 1 metre behind</strong> your car in darkness. How must it be marked?","img":"","opts":["With a red light and red reflectors","With a white light","With an orange flag only","It does not need marking"],"a":0,"ex":"A load sticking out more than 1 m behind must be marked; in darkness, dusk, dawn or bad weather with a <strong>red light and red reflectors</strong> at the back (white at the front).","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P82\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 82 §\">TrF 3 kap. 82 §</a>"],"signs":[]},{"id":"pl-load-secure","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"What does the law say about a load?","img":"","opts":["It may not be a danger, fall off, drag behind or make the vehicle harder to drive – secure and cover it if needed","It only needs to be secured on motorways","Only trucks must secure loads","It may stick out any distance if it is light"],"a":0,"ex":"A load may not be carried so that it can <strong>endanger people, damage property, drag behind or fall off</strong>, cause dust, make driving harder or cause noise. It must be <strong>secured</strong> and <strong>covered</strong> when needed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P80\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 80 §\">TrF 3 kap. 80 §</a>"],"signs":[]},{"id":"pl-load-view","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"Which of these is <strong>not</strong> allowed when you load your car?","img":"","opts":["The load hides the brake lights","The load is in the boot","The load is strapped down","The load is on a roof rack"],"a":0,"ex":"A load may not block your <strong>view</strong>, make the vehicle hard to manoeuvre, or hide <strong>indicators, brake lights, lamps or headlights</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P78\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 78 §\">TrF 3 kap. 78 §</a>"],"signs":[]},{"id":"pl-overweight","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"Five adults and heavy luggage are going in your car. What must you check?","img":"","opts":["That the car’s total weight in the registration certificate is not exceeded","Only the tyre tread","That the seats are comfortable","Nothing – passengers do not count"],"a":0,"ex":"The vehicle’s <strong>total weight</strong> may never be exceeded – people and luggage count. Check the registration certificate.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P4\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 4 §\">TrF 4 kap. 4 §</a>"],"signs":[]},{"id":"pl-moving","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"passengers-and-loads","q":"May a passenger get out while the car is still rolling slowly?","img":"","opts":["No","Yes, below 5 km/h","Yes, in a car park","Yes, if the door is on the pavement side"],"a":0,"ex":"Nobody may get on or off a <strong>moving</strong> vehicle.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P3\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 3 §\">TrF 3 kap. 3 §</a>"],"signs":[]},{"id":"tt-total-weight","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"Which weights decide whether your B licence covers a car and trailer?","img":"","opts":["The total weights in the registration certificates","What they actually weigh with the load right now","The kerb weights","The weight of the load only"],"a":0,"ex":"For the <strong>licence</strong>, what counts is the <strong>total weights</strong> in the registration certificates – an empty trailer with a high total weight counts with its total weight.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>"],"signs":[]},{"id":"tt-calc-no","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"Your car’s total weight is 2,400 kg. The trailer’s total weight is 1,300 kg. May you tow it with a plain B licence?","img":"","opts":["No – together 3,700 kg, so you need B96 or BE","Yes – the trailer is under 3,500 kg","Yes, if it is empty","Yes, at most 40 km/h"],"a":0,"ex":"The trailer is over 750 kg, so car + trailer total weights must be <strong>at most 3,500 kg</strong>. 2,400 + 1,300 = 3,700 kg → you need <strong>B96</strong> (up to 4,250 kg combined) or <strong>BE</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P7a\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 7a §\">KKL 2 kap. 7a §</a>"],"signs":[]},{"id":"tt-kerb","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"What is <strong>kerb weight</strong> (<em>tjänstevikt</em>)?","img":"","opts":["The vehicle ready to drive – fuel, oil, tools and, for a car, the driver","The heaviest the vehicle may weigh","The weight of the load","The weight on the rear axle"],"a":0,"ex":"Kerb weight is the vehicle <strong>ready to drive</strong>, with fuel, oil, water, tools and spare wheel – and for a car the <strong>driver</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>"],"signs":[]},{"id":"tt-maxload","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"A car has a total weight of 2,000 kg and a kerb weight of 1,550 kg. How much may you load (passengers and goods)?","img":"","opts":["450 kg","2,000 kg","1,550 kg","3,550 kg"],"a":0,"ex":"The <strong>maximum load</strong> is total weight minus kerb weight: 2,000 − 1,550 = <strong>450 kg</strong> (the driver is already in the kerb weight).","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/vikter/\" target=\"_blank\" rel=\"noopener\" title=\"Vehicle weights – kerb weight, total weight, gross weight and maximum load\">Transportstyrelsen – Vikter</a>","<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>"],"signs":[]},{"id":"tt-cert-fields","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"Where do you find the maximum weight of a <strong>braked</strong> trailer your car may tow?","img":"","opts":["Field O.1 in the registration certificate","Field O.2","On the tow bar","In the driving licence"],"a":0,"ex":"In the registration certificate, <strong>O.1</strong> is the maximum braked trailer weight, <strong>O.2</strong> unbraked, and <strong>F.3</strong> the maximum combined weight.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/regler-for-olika-fordonsslag/slap/vikter/\" target=\"_blank\" rel=\"noopener\" title=\"Weights to consider when towing a trailer\">Transportstyrelsen – Vikter när du drar en släpvagn</a>"],"signs":[],"noExam":1},{"id":"tt-rope-mark","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"You tow a car with a tow rope and there is more than 2 metres between the cars. What must you do?","img":"","opts":["Mark the rope clearly, for example with a flag","Nothing","Drive with the hazard lights on only","Use a rope at least 10 metres long"],"a":0,"ex":"If the distance between the towing and towed vehicle is more than <strong>2.0 m</strong>, the rope or bar must be <strong>clearly marked</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 5 §\">TrF 4 kap. 5 §</a>"],"signs":[]},{"id":"tt-unbraked-speed","area":"rules","paths":["car-manual","car-automatic"],"lesson":"towing-trailers","q":"Your car’s kerb weight is 1,600 kg. You tow an unbraked trailer with a total weight of 600 kg. What is the maximum speed?","img":"","opts":["80 km/h","40 km/h","30 km/h","90 km/h"],"a":0,"ex":"A trailer whose total weight is <strong>at most half the car’s kerb weight and at most 750 kg</strong> may be towed at <strong>80 km/h</strong> (600 ≤ 800 and ≤ 750).","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 20 §\">TrF 4 kap. 20 §</a>"],"signs":[]},{"id":"ph-hold","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"phones-and-distraction","q":"What does the law say about using a mobile phone while driving?","img":"","opts":["You may not hold it in your hand while using it, and any use must not affect your driving","It is allowed if you drive slowly","It is allowed at red lights with the phone in your hand","Only texting is forbidden"],"a":0,"ex":"A driver may <strong>never hold</strong> a phone or other communication device in the hand while using it, and may only use it hands-free if it <strong>does not affect the driving</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10e\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10e §\">TrF 4 kap. 10e §</a>"],"signs":[]},{"id":"ph-handsfree","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"phones-and-distraction","q":"Is talking on a hands-free phone while driving risk-free?","img":"","opts":["No – the conversation itself takes attention; end the call if it affects your driving","Yes – hands-free is completely safe","Yes, if the call is short","It is forbidden"],"a":0,"ex":"Hands-free is allowed but <strong>not required</strong>, and it does not remove the risk – the <strong>conversation itself</strong> takes your attention. End the call if it affects your driving.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/regler-for-mobilanvandning-och-kommunikationsutrustning/sluta-rattsurfa/fragor-och-svar-om-mobilanvandning-i-fordon/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers – using a mobile phone in a vehicle\">Transportstyrelsen – mobilanvändning i fordon</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10e\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10e §\">TrF 4 kap. 10e §</a>"],"signs":[]},{"id":"ph-metres","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"phones-and-distraction","q":"You look down at your phone for 2 seconds at 40 km/h. How far does the car travel without your control?","img":"","opts":["About 22 metres","About 5 metres","About 10 metres","About 50 metres"],"a":0,"ex":"At <strong>40 km/h</strong> you travel about 11 m per second, so <strong>2 seconds = 22 metres</strong> blind. At 90 km/h it is 50 m.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/regler-for-mobilanvandning-och-kommunikationsutrustning/sluta-rattsurfa/fragor-och-svar-om-mobilanvandning-i-fordon/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers – using a mobile phone in a vehicle\">Transportstyrelsen – mobilanvändning i fordon</a>"],"signs":[]},{"id":"ph-supervisor","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"phones-and-distraction","q":"During private practice, the supervisor holds a phone to read a message. Is that allowed?","img":"","opts":["No – the supervisor counts as the driver","Yes – the supervisor is not driving","Yes, if the learner drives slowly","Only in built-up areas"],"a":0,"ex":"The phone rule also applies to the <strong>supervisor</strong>, because the supervisor counts as the driver during practice.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/regler-for-mobilanvandning-och-kommunikationsutrustning/sluta-rattsurfa/fragor-och-svar-om-mobilanvandning-i-fordon/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers – using a mobile phone in a vehicle\">Transportstyrelsen – mobilanvändning i fordon</a>"],"signs":[]},{"id":"ph-navigator","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"phones-and-distraction","q":"What is the best way to use the phone as a navigator?","img":"","opts":["In a holder, with the route set before you leave","In your hand, typing the address while driving slowly","On your lap","Let it lie on the passenger seat"],"a":0,"ex":"Using the phone in a <strong>holder</strong> is not banned since you do not hold it – but set the route <strong>before</strong> you leave, and stop if you must change it.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/regler-for-mobilanvandning-och-kommunikationsutrustning/sluta-rattsurfa/fragor-och-svar-om-mobilanvandning-i-fordon/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers – using a mobile phone in a vehicle\">Transportstyrelsen – mobilanvändning i fordon</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10e\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10e §\">TrF 4 kap. 10e §</a>"],"signs":[]},{"id":"sa-walking-area-surface","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"In a walking-speed area, where can you expect pedestrians?","img":"","opts":["Anywhere – the whole surface is for them","Only on the pavement","Only at crossings","Nowhere – it is for cars"],"a":0,"ex":"A walking-speed area is designed so that pedestrians use the <strong>whole surface</strong> – expect people and children playing anywhere.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K10P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 10 kap. 8 §\">TrF 10 kap. 8 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1 §\">TrF 8 kap. 1 §</a>"],"signs":[]},{"id":"sa-pedestrian-delivery","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"When may you drive a car along a pedestrian street (not just across it)?","img":"","opts":["When needed for deliveries, or transport of goods, residents, hotel guests or sick or disabled people to an address there","Whenever you go slowly","At night","To find a parking space"],"a":0,"ex":"On a pedestrian street motor vehicles may only <strong>cross</strong> – except when needed for <strong>deliveries</strong> to shops, <strong>goods or residents</strong> to an address, <strong>hotel guests</strong>, or <strong>sick or disabled</strong> people.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1 §\">TrF 8 kap. 1 §</a>"],"signs":[]},{"id":"sa-cycle-street-enter","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"You turn onto a cycle street from another road. Who gives way?","img":"","opts":["You – to vehicles on the cycle street","The cyclists – to you","Whoever comes from the right","Nobody"],"a":0,"ex":"A driver who comes <strong>onto</strong> a cycle street from another road must <strong>give way</strong> to vehicles on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1a §\">TrF 8 kap. 1a §</a>"],"signs":[]},{"id":"sa-zone-class2","area":"rules","paths":["car-manual","car-automatic"],"lesson":"special-areas","q":"May you drive a <strong>diesel</strong> car that meets Euro 5 in an environmental zone of class 2?","img":"","opts":["No – diesel cars need Euro 6","Yes – Euro 5 is enough for all cars","Yes, outside rush hour","Only if it is a hybrid"],"a":0,"ex":"In class 2 zones, <strong>petrol</strong> vehicles need at least <strong>Euro 5</strong>, but <strong>diesel</strong> vehicles need <strong>Euro 6</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P22b\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 22b §\">TrF 4 kap. 22b §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/miljozoner/\" target=\"_blank\" rel=\"noopener\" title=\"Environmental zones\">Transportstyrelsen – Miljözoner</a>"],"signs":[]},{"id":"sa-zone-class3","area":"rules","paths":["car-manual","car-automatic"],"lesson":"special-areas","q":"Which cars may be driven in an environmental zone of <strong>class 3</strong>?","img":"","opts":["Mainly electric, fuel-cell and certain gas cars","All cars meeting Euro 6","All hybrids","Only taxis"],"a":0,"ex":"Class 3 is the strictest. For cars it allows mainly <strong>electric</strong>, <strong>hydrogen fuel-cell</strong> and certain <strong>gas</strong> vehicles.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P22d\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 22d §\">TrF 4 kap. 22d §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/miljozoner/\" target=\"_blank\" rel=\"noopener\" title=\"Environmental zones\">Transportstyrelsen – Miljözoner</a>"],"signs":[]},{"id":"sa-tunnel","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"May you stop in a road tunnel to look at the map?","img":"","opts":["No – stopping and parking are forbidden in tunnels","Yes, with hazard lights on","Yes, in the right-hand lane","Yes, if traffic is light"],"a":0,"ex":"You may not stop or park in a <strong>tunnel or underpass</strong>. Emergency lay-bys are only for breakdowns and emergencies.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"sa-car-park-rules","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"Do the traffic rules apply in a public car park or at a petrol station?","img":"","opts":["Yes – places generally used for motor traffic count as roads","No – they are private property","Only the speed limits apply","Only at night"],"a":0,"ex":"Every road, street, square or other place <strong>generally used for motor traffic</strong> counts as a road, so the normal rules apply in public car parks and at petrol stations.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:651#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Ordinance (2001:651) — Vägtrafikdefinitionsförordningen 2 §\">Vägtrafikdefinitionsförordningen 2 §</a>"],"signs":[]},{"id":"sd-total","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"What does the <strong>stopping distance</strong> consist of?","img":"","opts":["The distance you travel while reacting plus the braking distance","Only the braking distance","The distance to the vehicle in front","The distance shown on the speedometer"],"a":0,"ex":"The overall stopping distance is the <strong>reaction (thinking) distance</strong> – travelled before you even start braking – plus the <strong>braking distance</strong>. Never get closer to the vehicle in front than you can stop.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 126\">UK Highway Code rule 126</a>"],"signs":[]},{"id":"sd-double","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"You double your speed. What happens to the braking distance, roughly?","img":"","opts":["It becomes about four times longer","It doubles","It stays the same with ABS","It becomes three times longer"],"a":0,"ex":"The energy of a moving vehicle grows with the <strong>square</strong> of the speed, so double the speed gives about <strong>four times</strong> the braking distance – and much harder crash forces.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/om-oss/nyheter/lansnyheter/vastra-gotaland/2025/trafiksakerhetskonferens-2025---visste-du-att/\" target=\"_blank\" rel=\"noopener\" title=\"Road safety facts from Trafikverket's 2025 conference\">Trafikverket – Visste du att? (2025)</a>"],"signs":[]},{"id":"sd-reaction-90","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"You drive at 90 km/h and need one second to react. About how far do you travel before you start braking?","img":"","opts":["About 25 metres","About 9 metres","About 50 metres","About 90 metres"],"a":0,"ex":"Metres per second = km/h ÷ 3.6, so 90 km/h is about <strong>25 m per second</strong>. Transportstyrelsen uses the same calculation: two seconds at 40 km/h is 22 metres.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/regler-for-mobilanvandning-och-kommunikationsutrustning/sluta-rattsurfa/fragor-och-svar-om-mobilanvandning-i-fordon/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers – using a mobile phone in a vehicle\">Transportstyrelsen – mobilanvändning i fordon</a>"],"signs":[]},{"id":"sd-older","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"According to Trafikverket, how does the risk of injury for an unprotected road user over 65 change between 30 and 50 km/h?","img":"","opts":["It is three times higher at 50 km/h","It is about the same","It is 10 % higher at 50 km/h","It is lower at 50 km/h"],"a":0,"ex":"Trafikverket reports that the risk of injury for unprotected road users over 65 is <strong>three times higher at 50 km/h</strong> than at 30 km/h.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/om-oss/nyheter/lansnyheter/vastra-gotaland/2025/trafiksakerhetskonferens-2025---visste-du-att/\" target=\"_blank\" rel=\"noopener\" title=\"Road safety facts from Trafikverket's 2025 conference\">Trafikverket – Visste du att? (2025)</a>"],"signs":[]},{"id":"sd-car-front","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"Modern car fronts are designed to protect pedestrians. Up to about what impact speed does that help?","img":"","opts":["Below about 50 km/h","Up to 110 km/h","At all speeds","Only below 10 km/h"],"a":0,"ex":"Pedestrian-friendly car fronts only help at impact speeds <strong>below about 50 km/h</strong>. Above that, the forces are so great that the design hardly matters.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/om-oss/nyheter/lansnyheter/vastra-gotaland/2025/trafiksakerhetskonferens-2025---visste-du-att/\" target=\"_blank\" rel=\"noopener\" title=\"Road safety facts from Trafikverket's 2025 conference\">Trafikverket – Visste du att? (2025)</a>"],"signs":[]},{"id":"sd-gap-law","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"Does Swedish law set the following distance as a number of seconds or metres?","img":"","opts":["No – it must be long enough to avoid running into the vehicle in front if it slows down or stops","Yes – 3 seconds","Yes – 2 seconds","Yes – 50 metres outside built-up areas"],"a":0,"ex":"The law gives <strong>no number</strong>. The distance must be adapted so you do not run into the vehicle in front if it slows down or stops. Counting seconds is a practical rule of thumb.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 2 §\">TrF 3 kap. 2 §</a>"],"signs":[]},{"id":"sd-wet-gap","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"How should your following distance change on a wet road?","img":"","opts":["It should be at least doubled","It can stay the same","It can be shorter with ABS","Only trucks need more distance"],"a":0,"ex":"Make the gap <strong>at least double</strong> on wet roads – and up to <strong>ten times</strong> greater on icy roads.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 126\">UK Highway Code rule 126</a>"],"signs":[]},{"id":"sd-see","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-and-stopping-distance","q":"You drive at night with dipped beam. Your stopping distance is longer than the stretch your lights show. What does that mean?","img":"","opts":["You are driving too fast – you must be able to stop within the distance you can see","Nothing, if you keep the speed limit","You must switch on the fog lights","You should drive closer to the car in front to use its lights"],"a":0,"ex":"The speed may never be so high that you cannot <strong>stop within the distance you can see</strong>. Slow down, and use main beam when it is allowed and needed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P70\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 70 §\">TrF 3 kap. 70 §</a>"],"signs":[]},{"id":"spn-curriculum","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"seeing-and-planning","q":"Which of these does the curriculum require you to show when you drive?","img":"","opts":["Good scanning routines and sufficient safety margins","The ability to drive fast in bends","Knowledge of car prices","Driving without using the mirrors"],"a":0,"ex":"The curriculum requires <strong>good scanning routines</strong>, <strong>sufficient safety margins</strong>, identifying risks and foreseeing how situations can develop.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 3 kap. 2 §\">TSFS 2011:20 3 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 3 kap. 2 §\">TSFS 2011:19 3 kap. 2 §</a>"],"signs":[]},{"id":"spn-ball","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"seeing-and-planning","q":"A ball rolls out into the street from between parked cars. What should you expect?","img":"","opts":["That a child may run out after it – slow down and be ready to stop","Nothing – just drive around the ball","That the ball will stop by itself","That a dog is playing"],"a":0,"ex":"Read the clues: a ball means a <strong>child</strong> may follow. The law requires a low enough speed when you approach children, and care to avoid accidents.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"spn-bus","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"seeing-and-planning","q":"You approach a bus that has stopped to let passengers off. What does the law require?","img":"","opts":["A low enough speed – people may cross in front of or behind the bus","Overtaking it quickly","Sounding the horn","Nothing special"],"a":0,"ex":"The law requires a low enough speed when approaching a <strong>tram, bus or school bus</strong> that has stopped to let passengers on or off. People may step out in front of or behind it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>"],"signs":[]},{"id":"re-2plus1","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"roads-and-environments","q":"On a road with a central barrier that alternates between one and two lanes in your direction, where can you overtake?","img":"","opts":["Only where you have two lanes in your direction","Anywhere, if no one is coming","Only on the shoulder","Nowhere"],"a":0,"ex":"The barrier separates the directions, so you can only overtake where <strong>two lanes</strong> run in your direction – the lane you use must be free for a long enough distance. Do not start just before the two lanes end.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P36\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 36 §\">TrF 3 kap. 36 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P44\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 44 §\">TrF 3 kap. 44 §</a>"],"signs":[]},{"id":"re-roadworks","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"roads-and-environments","q":"What does the law demand when you drive past road works?","img":"","opts":["A low enough speed","Keeping the normal limit","Driving on the shoulder","Sounding the horn"],"a":0,"ex":"The law lists <strong>road works</strong> among the places where you must keep a low enough speed. Expect narrow lanes, gravel and people working.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>"],"signs":[]},{"id":"dw-reduced","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"Visibility is reduced by heavy snowfall. What does the law say about your speed?","img":"","opts":["It must be low enough for the circumstances","You may keep the speed limit","You must drive at most 30 km/h","You must stop and wait"],"a":0,"ex":"The law specifically demands a low enough speed when <strong>visibility is reduced</strong> by light or weather, and you must always be able to stop within the distance you can see.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"dw-dazzled","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"You are dazzled by a low sun or oncoming lights and can hardly see. What do you do?","img":"","opts":["Slow down – and stop if necessary","Keep your speed and steer straight","Speed up to get past quickly","Switch on the hazard lights and continue"],"a":0,"ex":"If you are dazzled, <strong>slow down and, if necessary, stop</strong>. Where there is a risk of dazzle, the law demands a low enough speed.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 237\">UK Highway Code rule 237</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>"],"signs":[]},{"id":"dw-rain-dry","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"It starts to rain after a long dry, warm spell. What should you expect?","img":"","opts":["The road may become slippery","Better grip than usual","No change","Shorter braking distances"],"a":0,"ex":"If it rains after a <strong>dry spell</strong>, the road may become <strong>slippery</strong>.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 237\">UK Highway Code rule 237</a>"],"signs":[]},{"id":"dw-fog","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"In fog, a car stays close behind you. What should you do?","img":"","opts":["Keep a speed at which you can stop within what you can see – do not speed up to get away","Speed up to get away from it","Brake hard to warn it","Switch off your rear lights"],"a":0,"ex":"In fog, be able to stop <strong>well within the distance you can see</strong>, keep a safe distance, and <strong>do not accelerate</strong> to get away from a vehicle that is too close behind you.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 235\">UK Highway Code rule 235</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"dw-fog-patches","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"The fog seems to be clearing. What should you keep in mind?","img":"","opts":["Fog often lies in patches – you can suddenly be in thick fog again","You can speed up to the limit at once","Fog never comes back on the same road","You can switch off all lights"],"a":0,"ex":"Fog can drift in patches. Even if it seems to be clearing, you can suddenly find yourself in <strong>thick fog</strong> again.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 234\">UK Highway Code rule 234</a>"],"signs":[]},{"id":"dw-wind","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"Where are strong side-wind gusts most likely to push a vehicle off course?","img":"","opts":["On open stretches, on bridges and at gaps in hedges or forest","In tunnels","In town centres between tall buildings only","On roads with many bends"],"a":0,"ex":"Strong gusts can blow a car, cyclist or motorcyclist off course on <strong>open stretches</strong>, on <strong>bridges</strong> and at <strong>gaps</strong> in hedges or forest. Sign A24 warns of places where side wind is common.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 232\">UK Highway Code rule 232</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":[]},{"id":"dw-spray","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"darkness-and-weather","q":"Why should you keep further back from the vehicle in front in heavy rain?","img":"","opts":["Rain and spray make it hard to see and be seen, and stopping distances are at least double","To save fuel","Because the law sets 100 m in rain","To avoid getting the car dirty"],"a":0,"ex":"In wet weather keep well back – <strong>spray</strong> makes it hard to see and be seen, and stopping distances are <strong>at least double</strong> those on dry roads.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 227\">UK Highway Code rule 227</a>"],"signs":[]},{"id":"wd-windows","area":"safety","paths":["car-manual","car-automatic"],"lesson":"winter-driving","q":"Your windscreen is covered in ice. What should you do before driving?","img":"","opts":["Clear all windows completely, and the lights and mirrors","Scrape a small peephole in front of the driver","Drive slowly until the heater melts the ice","Only clear the front side windows"],"a":0,"ex":"You must be able to see: clear snow and ice from <strong>all</strong> windows, make sure the <strong>mirrors</strong> are clear, and clean the <strong>lights</strong> and number plates.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 229\">UK Highway Code rule 229</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"wd-roof","area":"safety","paths":["car-manual","car-automatic"],"lesson":"winter-driving","q":"Why should you clear snow from the roof of the car before you drive?","img":"","opts":["It can fall off into the path of other road users, or slide over your windscreen when you brake","It makes the car heavier","It is only for looks","It damages the paint"],"a":0,"ex":"Remove all snow that might <strong>fall off into the path of other road users</strong> – it can also slide down over your windscreen when you brake.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 229\">UK Highway Code rule 229</a>"],"signs":[]},{"id":"wd-plough","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"winter-driving","q":"A snow plough is clearing the road ahead. When may you overtake it?","img":"","opts":["Only when the lane you will use has been cleared","Whenever there is no oncoming traffic","Never","When it signals with amber lights"],"a":0,"ex":"Snow ploughs may throw out snow on both sides. Do <strong>not overtake</strong> unless the lane you intend to use <strong>has been cleared</strong>. Their amber lights mean slow down and be ready to stop.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 230\">UK Highway Code rule 230</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/globalassets/global/publikationer-och-rapporter/vag/trafikant/produkter/vaelj-raett-fordonsbelysning-a5-webb.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Choose the right vehicle lighting\">Transportstyrelsen – Välj rätt fordonsbelysning</a>"],"signs":[]},{"id":"wd-avoid","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"winter-driving","q":"What does the curriculum say about travelling in risky conditions such as slippery roads and bad weather?","img":"","opts":["Avoid them when you can – plan your trip","They are good practice","Only professional drivers should avoid them","Nothing"],"a":0,"ex":"The curriculum wants you to plan your travel so that trips in risky conditions – <strong>dense traffic, slippery roads and bad weather</strong> – are avoided when possible.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_20.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for category B — TSFS 2011:20 4 kap. 1 §\">TSFS 2011:20 4 kap. 1 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 4 kap. 1 §\">TSFS 2011:19 4 kap. 1 §</a>"],"signs":[]},{"id":"wd-dipped","area":"safety","paths":["car-manual","car-automatic"],"lesson":"winter-driving","q":"It is snowing in the afternoon and getting dark. Which lights do you use?","img":"","opts":["Dipped beam","Daytime running lights","Only the rear fog light","Parking lights"],"a":0,"ex":"Daytime running lights may not replace dipped beam in dusk, darkness or when the weather makes dipped beam necessary.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P71\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 71 §\">TrF 3 kap. 71 §</a>"],"signs":[]},{"id":"wl-when","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"When are you most likely to meet wild animals on the road?","img":"","opts":["At dawn and dusk","At midday","Only at night in summer","Only in winter"],"a":0,"ex":"The animals are most active at <strong>dawn and dusk</strong> – at the same time as many people drive to and from work.","src":["<a class=\"cite\" href=\"https://polisen.se/aktuellt/nyheter/ost/2025/oktober/nu-okar-viltolyckorna/\" target=\"_blank\" rel=\"noopener\" title=\"50 people hit wild animals every day – make sure it is not you\">Polisen – Viltolyckor (2025)</a>","<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>"],"signs":[]},{"id":"wl-months","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"In which months do most wildlife crashes happen?","img":"","opts":["October and November","June and July","January and February","April and May"],"a":0,"ex":"The Police report that most wildlife crashes happen in <strong>October and November</strong>.","src":["<a class=\"cite\" href=\"https://polisen.se/aktuellt/nyheter/ost/2025/oktober/nu-okar-viltolyckorna/\" target=\"_blank\" rel=\"noopener\" title=\"50 people hit wild animals every day – make sure it is not you\">Polisen – Viltolyckor (2025)</a>"],"signs":[]},{"id":"wl-species","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"Which animal is involved in most reported wildlife crashes on Swedish roads?","img":"","opts":["Roe deer","Elk","Reindeer","Wild boar"],"a":0,"ex":"In 2025, <strong>69 %</strong> of the more than 70,000 reported wildlife crashes involved <strong>roe deer</strong>, followed by wild boar, fallow deer and elk.","src":["<a class=\"cite\" href=\"https://www.trafa.se/globalassets/statistik/vagtrafik/vagtrafikskador/2025/vagtrafikskador-2025.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Road traffic injuries 2025 – official statistics of Sweden\">Trafikanalys – Vägtrafikskador 2025</a>"],"signs":[]},{"id":"wl-prevent","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"What is the Police’s first piece of advice for avoiding wildlife crashes?","img":"","opts":["Lower your speed","Sound the horn in forests","Drive in the middle of the road","Use fog lights"],"a":0,"ex":"Lowering the speed gives you more time to react and a <strong>shorter braking distance</strong>. Also watch the ditch edges, take warning signs seriously and be extra alert at dawn and dusk.","src":["<a class=\"cite\" href=\"https://polisen.se/aktuellt/nyheter/ost/2025/oktober/nu-okar-viltolyckorna/\" target=\"_blank\" rel=\"noopener\" title=\"50 people hit wild animals every day – make sure it is not you\">Polisen – Viltolyckor (2025)</a>"],"signs":[]},{"id":"wl-roe-ran","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"You hit a roe deer. It gets up and runs into the forest, apparently unhurt. What must you do?","img":"","opts":["Mark the place and call 112 to notify the police","Nothing – it was not hurt","Follow it to check that it is fine","Report it to your insurance company only"],"a":0,"ex":"The duty to <strong>mark the place and notify the police</strong> applies <strong>even if the animal does not look injured</strong> or lies dead at the spot.","src":["<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>"],"signs":[]},{"id":"wl-mark-side","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"On which side of the road should you mark the place after a wildlife crash?","img":"","opts":["The side where the animal disappeared","The side where you stopped","Always the right side","Both sides"],"a":0,"ex":"Mark the place – with the special marking strip or something clearly visible like a plastic bag – on the side of the road where the animal <strong>disappeared</strong>.","src":["<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>","<a class=\"cite\" href=\"https://www.viltolycka.se/information/krock/\" target=\"_blank\" rel=\"noopener\" title=\"What to do if you collide with a wild animal\">Nationella viltolycksrådet – Om du kolliderar med vilt</a>"],"signs":[]},{"id":"wl-track","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"An injured elk disappears into the forest after a collision. What should you do?","img":"","opts":["Do not follow it – the police send a specially trained tracker","Follow it to end its suffering","Wait for it to come back","Drive away – it is the hunters’ job"],"a":0,"ex":"Do <strong>not</strong> follow or track an injured animal yourself. The police contact a specially trained tracker. Stay reachable by phone.","src":["<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>","<a class=\"cite\" href=\"https://www.viltolycka.se/information/krock/\" target=\"_blank\" rel=\"noopener\" title=\"What to do if you collide with a wild animal\">Nationella viltolycksrådet – Om du kolliderar med vilt</a>"],"signs":[]},{"id":"wl-reindeer","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"Must you notify the police if you hit a <strong>reindeer</strong>?","img":"","opts":["Yes – even though reindeer are not wild animals","No – reindeer are domestic animals","Only if it dies","Only in Norrbotten"],"a":0,"ex":"You must also notify the police if you have hit a <strong>reindeer</strong>, even though reindeer do not count as wild animals.","src":["<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>","<a class=\"cite\" href=\"https://www.viltolycka.se/fragor-svar/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers on wildlife collisions\">Nationella viltolycksrådet – Frågor och svar</a>"],"signs":[]},{"id":"wl-fox","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"Must you notify the police after hitting a <strong>fox or a hare</strong>?","img":"","opts":["No – they are not covered by the duty to report","Yes, always","Only in daylight","Only if the car is damaged"],"a":0,"ex":"The duty to report covers bear, wolf, wolverine, lynx, elk, deer, roe deer, otter, wild boar, mouflon and eagle (and reindeer). A <strong>hare, badger or fox</strong> does not have to be reported.","src":["<a class=\"cite\" href=\"https://www.viltolycka.se/fragor-svar/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers on wildlife collisions\">Nationella viltolycksrådet – Frågor och svar</a>","<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>"],"signs":[]},{"id":"wl-boar-strip","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"After a collision with a <strong>wild boar</strong>, where should you put the marking strip?","img":"","opts":["About 100 metres from the place – and tell the police","Right at the place","On the car","No marking is needed"],"a":0,"ex":"For <strong>wild boar, bear, wolf and lynx</strong>, put the marking strip about <strong>100 m</strong> from the place and inform the police that you have done so.","src":["<a class=\"cite\" href=\"https://www.viltolycka.se/information/krock/\" target=\"_blank\" rel=\"noopener\" title=\"What to do if you collide with a wild animal\">Nationella viltolycksrådet – Om du kolliderar med vilt</a>"],"signs":[]},{"id":"wl-not-report","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"What happens if you do not notify the police after hitting an elk?","img":"","opts":["It is an offence and can give a fine","Nothing","Only your insurance is affected","You lose your licence for a year"],"a":0,"ex":"Not notifying the police after a collision with these animals is an <strong>offence</strong> under the hunting regulations and can give <strong>day-fines</strong>. Insurance companies also usually require that it was reported via 112.","src":["<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>","<a class=\"cite\" href=\"https://www.viltolycka.se/fragor-svar/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers on wildlife collisions\">Nationella viltolycksrådet – Frågor och svar</a>"],"signs":[]},{"id":"wl-pass-site","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"You pass a place where a wildlife crash has just happened. What should you do?","img":"","opts":["Slow down – a tracker and dog may be working there, and an injured animal may be near","Speed up to get past quickly","Stop and take photos","Sound the horn to scare animals away"],"a":0,"ex":"Slow down and pass carefully – a <strong>tracker with a dog</strong> may be working on or beside the road, and an injured animal may be nearby.","src":["<a class=\"cite\" href=\"https://www.viltolycka.se/fragor-svar/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers on wildlife collisions\">Nationella viltolycksrådet – Frågor och svar</a>"],"signs":[]},{"id":"vr-mc-look","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vulnerable-road-users","q":"Why should you look twice for motorcycles before turning or pulling out at a junction?","img":"","opts":["They are hard to see, and their speed and distance are easily misjudged","Because they always have priority","Because they are slower than cars","Because they must give way to you"],"a":0,"ex":"Other road users often have difficulty seeing motorcyclists – and drivers may not see them at all, or misjudge their <strong>distance or speed</strong>, especially at <strong>junctions</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 3 kap. 2 §\">TSFS 2011:19 3 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 86\">UK Highway Code rule 86</a>"],"signs":[]},{"id":"vr-children","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vulnerable-road-users","q":"You approach children walking beside the road. What does the law require?","img":"","opts":["A speed low enough for the situation","Sounding the horn","Keeping the limit","Flashing the headlights"],"a":0,"ex":"The law requires a low enough speed when approaching <strong>children</strong> on or beside the road, and special consideration for them.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"vr-overtake-cyclist","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"vulnerable-road-users","q":"How much room should you leave when you overtake a cyclist?","img":"","opts":["A safe sideways distance – if you cannot, wait behind","At least 10 cm","The same as when overtaking a car","It does not matter if you are fast"],"a":0,"ex":"When overtaking, leave a <strong>safe sideways distance</strong>. Cyclists can wobble or swerve round potholes. If oncoming traffic prevents it, wait.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P33\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 33 §\">TrF 3 kap. 33 §</a>"],"signs":[]},{"id":"fa-stay","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"You are involved in a traffic accident, but it was not your fault. What does the law require?","img":"","opts":["Stay at the scene, help the injured as far as you can, and give your name and address if asked","You may leave, since it was not your fault","Only call your insurance company","Leave your phone number on the windscreen"],"a":0,"ex":"A road user involved in a traffic accident – <strong>with or without being at fault</strong> – must <strong>stay</strong>, help the injured as far as they can, and give name, address and information about the event if asked.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 8 §\">TrF 2 kap. 8 §</a>"],"signs":[]},{"id":"fa-property","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"You damage a parked car and nobody is there. What must you do?","img":"","opts":["Inform the owner or the police as soon as possible","Nothing if the damage is small","Wait until the next day","Drive away and send a letter later if you want"],"a":0,"ex":"If property is damaged and nobody is there to receive your details, inform the <strong>owner</strong> or the <strong>police</strong> as soon as possible.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 8 §\">TrF 2 kap. 8 §</a>"],"signs":[]},{"id":"fa-injury-police","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"Someone is injured in an accident you were involved in (not an insignificant injury). Who must be informed?","img":"","opts":["The police, as soon as possible","Only the injured person’s family","Only your insurance company","Nobody, if an ambulance came"],"a":0,"ex":"If someone has been <strong>injured</strong> – and the injury is not insignificant – the <strong>police</strong> must be informed as soon as possible.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 8 §\">TrF 2 kap. 8 §</a>"],"signs":[]},{"id":"fa-traces","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"Someone has been seriously injured in a crash. When may you move the vehicles?","img":"","opts":["Only if they are a danger to other traffic – and do not remove traces that can matter for the investigation","Always at once, to clear the road","Never, even if they block a motorway","Only after one hour"],"a":0,"ex":"Normally a vehicle that is a danger or obstruction should be moved at once – but if someone has been <strong>killed or seriously injured</strong>, move it only if it is a <strong>danger</strong> to other traffic, and do not remove <strong>traces</strong> that matter for the investigation.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 8 §\">TrF 2 kap. 8 §</a>"],"signs":[]},{"id":"fa-order","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"You arrive first at a crash on a country road. What is the right order?","img":"","opts":["Protect the scene, call 112, help the injured","Help the injured, then think about traffic","Call 112 and drive on","Take photos, then call 112"],"a":0,"ex":"<strong>Protect</strong> the scene (hazard lights, warning triangle, reflective vest), <strong>alert</strong> 112, then <strong>help</strong> the injured – starting with the most life-threatening. Make sure the scene is safe for you too.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P57\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 57 §\">TrF 3 kap. 57 §</a>","<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/hjart-lungraddning-hlr/\" target=\"_blank\" rel=\"noopener\" title=\"Cardiopulmonary resuscitation (CPR) for adults\">1177 – Hjärt-lungräddning</a>"],"signs":[]},{"id":"fa-cpr","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"How do you give chest compressions to an adult during CPR?","img":"","opts":["5–6 cm deep, 100–120 times a minute, 30 compressions then 2 breaths","1–2 cm deep, 60 times a minute","10 cm deep, 30 times a minute","15 compressions then 15 breaths"],"a":0,"ex":"Press in the <strong>middle of the chest</strong>, <strong>5–6 cm</strong> deep, <strong>100–120 times a minute</strong>: 30 compressions, then 2 rescue breaths, and continue 30:2.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/hjart-lungraddning-hlr/\" target=\"_blank\" rel=\"noopener\" title=\"Cardiopulmonary resuscitation (CPR) for adults\">1177 – Hjärt-lungräddning</a>"],"signs":[]},{"id":"fa-breathing","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"An unconscious person takes rare, gasping breaths. What does that mean?","img":"","opts":["It is not normal breathing – call 112 and start CPR","The person is breathing normally – recovery position","The person is sleeping","Wait and see if it gets better"],"a":0,"ex":"Rare, gasping breaths are <strong>not normal breathing</strong>. Call 112 and start <strong>CPR</strong>.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/hjart-lungraddning-hlr/\" target=\"_blank\" rel=\"noopener\" title=\"Cardiopulmonary resuscitation (CPR) for adults\">1177 – Hjärt-lungräddning</a>"],"signs":[]},{"id":"fa-recovery","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"A person is unconscious but breathes normally. What do you do?","img":"","opts":["Place them in the recovery position, keep them warm and watch their breathing","Start chest compressions","Sit them up","Give them water"],"a":0,"ex":"Put them in the <strong>recovery position</strong> (<em>stabilt sidoläge</em>) – on the side, so the tongue cannot block the airway – keep them warm and keep watching the breathing.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/chock/\" target=\"_blank\" rel=\"noopener\" title=\"Shock\">1177 – Chock</a>"],"signs":[]},{"id":"fa-bleeding","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"An injured person is bleeding heavily from the leg. What do you do?","img":"","opts":["Press hard directly on the wound and keep pressing until the ambulance staff take over","Raise the leg and wait","Wash the wound first","Give the person something to drink"],"a":0,"ex":"Press <strong>hard and directly</strong> on the wound – with a cloth or your bare hands – and keep pressing until the ambulance staff tell you to stop.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/stoppa-blodning/\" target=\"_blank\" rel=\"noopener\" title=\"Stopping bleeding\">1177 – Stoppa en blödning</a>"],"signs":[]},{"id":"fa-object","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"A piece of glass is stuck in a bleeding wound. What do you do?","img":"","opts":["Leave it and press around it","Pull it out at once","Push it in further","Pour water over it"],"a":0,"ex":"Do <strong>not remove</strong> objects stuck in a wound – press beside them.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/stoppa-blodning/\" target=\"_blank\" rel=\"noopener\" title=\"Stopping bleeding\">1177 – Stoppa en blödning</a>"],"signs":[]},{"id":"fa-shock","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"A conscious injured person is pale, cold, sweaty and has a fast weak pulse – signs of shock. What do you do?","img":"","opts":["Lay them on their back with the legs raised, keep them warm, do not leave them, give nothing to eat or drink","Give them something sweet to drink","Make them walk around","Sit them up and leave to get help"],"a":0,"ex":"For shock in a conscious person, lay them on their <strong>back with the legs raised</strong>, keep them <strong>warm</strong> and <strong>calm</strong>, do not leave them alone, and give <strong>nothing to eat or drink</strong>.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/chock/\" target=\"_blank\" rel=\"noopener\" title=\"Shock\">1177 – Chock</a>"],"signs":[]},{"id":"fa-aed","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"A defibrillator (<em>hjärtstartare</em>) is available during CPR. What do you do?","img":"","opts":["Use it as soon as possible – it gives spoken instructions and cannot harm the person","Only a doctor may use it","Use it only if CPR has failed for 30 minutes","Never use it outdoors"],"a":0,"ex":"Use a <strong>defibrillator</strong> as soon as one is available. It gives spoken instructions and cannot harm the person.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/hjart-lungraddning-hlr/\" target=\"_blank\" rel=\"noopener\" title=\"Cardiopulmonary resuscitation (CPR) for adults\">1177 – Hjärt-lungräddning</a>"],"signs":[]},{"id":"fa-helmet","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"An injured motorcyclist lies on the road wearing a helmet. Should you take it off?","img":"","opts":["Not unless it is essential, for example to keep the airway open","Yes, always, so the rider can breathe","Yes, to check for head injuries","Only if the rider asks"],"a":0,"ex":"Do <strong>not remove</strong> a motorcyclist’s helmet unless it is <strong>essential</strong> and you know how. Then keep the head and neck as still as possible.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/breakdowns-and-incidents-274-to-287\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – breakdowns and incidents — UK Highway Code rule 283\">UK Highway Code rule 283</a>"],"signs":[]},{"id":"fa-112","area":"safety","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"What number do you call for an ambulance, the police or the fire service in Sweden?","img":"","opts":["112","911","999","114 14"],"a":0,"ex":"Call <strong>112</strong>. Say what has happened, where, how many are injured, and if anyone is trapped. The 112 app can show your position.","src":["<a class=\"cite\" href=\"https://www.1177.se/olyckor--skador/akuta-rad---forsta-hjalpen/hjart-lungraddning-hlr/\" target=\"_blank\" rel=\"noopener\" title=\"Cardiopulmonary resuscitation (CPR) for adults\">1177 – Hjärt-lungräddning</a>","<a class=\"cite\" href=\"https://polisen.se/lagar-och-regler/trafik-och-fordon/viltolyckor/\" target=\"_blank\" rel=\"noopener\" title=\"Collisions with wild animals\">Polisen – Viltolyckor</a>"],"signs":[]},{"id":"mcs-bends","area":"safety","paths":["motorcycle"],"lesson":"mc-cornering","q":"According to Trafikverket’s analyses, where do motorcycle crashes most often happen?","img":"","opts":["In bends","In roundabouts","In car parks","At pedestrian crossings"],"a":0,"ex":"The most common <strong>place</strong> for motorcycle crashes is in <strong>bends</strong>. The most common type of fatal crash is the single-vehicle crash.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcs-single","area":"safety","paths":["motorcycle"],"lesson":"mc-cornering","q":"What is the most common type of crash in which motorcyclists are killed?","img":"","opts":["Single-vehicle crashes","Rear-end collisions","Crashes with pedestrians","Crashes in car parks"],"a":0,"ex":"The most common crash type for killed motorcyclists is the <strong>single-vehicle crash</strong>; the second most common is the <strong>junction crash</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcs-speed","area":"safety","paths":["motorcycle"],"lesson":"mc-cornering","q":"In fatal motorcycle crashes, how many riders were judged to have kept to the speed limit?","img":"","opts":["Only about three in ten","About nine in ten","All of them","About half"],"a":0,"ex":"Trafikverket’s analyses show that only <strong>three in ten</strong> riders were judged to have kept to the limit. Speeding can both cause the crash and make the injuries worse.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcs-headon","area":"safety","paths":["motorcycle"],"lesson":"mc-cornering","q":"In 8 of 10 fatal head-on crashes involving a motorcyclist, what happened?","img":"","opts":["The motorcycle crossed into the oncoming lane","A car crossed into the motorcycle’s lane","A truck overtook","An animal ran out"],"a":0,"ex":"In <strong>8 of 10</strong> fatal head-on crashes with motorcyclists, the <strong>motorcycle crossed into the oncoming lane</strong> – often in bends or when overtaking.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcs-junction","area":"safety","paths":["motorcycle"],"lesson":"mc-visibility-and-position","q":"What is the second most common type of fatal motorcycle crash?","img":"","opts":["The junction crash","The rear-end crash","Hitting a pedestrian","A crash in a tunnel"],"a":0,"ex":"After single-vehicle crashes, the <strong>junction crash</strong> is the second most common – often a car turning across or pulling out in front of the rider.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcs-mirrors","area":"safety","paths":["motorcycle"],"lesson":"mc-visibility-and-position","q":"In a traffic queue, where should you position your motorcycle?","img":"","opts":["So that the driver in front can see you in their mirrors","Directly behind the car, in the middle","In the blind spot beside the car","On the shoulder"],"a":0,"ex":"Position yourself so that drivers in front <strong>can see you in their mirrors</strong>, and watch for pedestrians crossing between vehicles and cars changing lanes.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 88\">UK Highway Code rule 88</a>"],"signs":[]},{"id":"mcs-headlight","area":"safety","paths":["motorcycle"],"lesson":"mc-visibility-and-position","q":"Must a motorcycle ride with its headlight on in daylight?","img":"","opts":["Yes – a motor vehicle with headlights must use them","No – only at night","Only outside built-up areas","Only in rain"],"a":0,"ex":"A motor vehicle that has headlights must use them when driving on a road – and dipped headlights make you more conspicuous.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P68\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 68 §\">TrF 3 kap. 68 §</a>","<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 86\">UK Highway Code rule 86</a>"],"signs":[]},{"id":"mcs-turbulence","area":"safety","paths":["motorcycle"],"lesson":"mc-road-surface","q":"What should you expect when you overtake a large truck on a motorcycle in strong wind?","img":"","opts":["Turbulence from the truck can push the motorcycle sideways","Better grip in the truck’s slipstream","Nothing special","The wind will stop completely"],"a":0,"ex":"Large vehicles create <strong>turbulence</strong> in windy weather, and motorcyclists are <strong>particularly affected</strong>.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 233\">UK Highway Code rule 233</a>"],"signs":[]},{"id":"mcs-diesel","area":"safety","paths":["motorcycle"],"lesson":"mc-road-surface","q":"Near a petrol station you see a shiny patch on the wet road where diesel may have been spilt. What do you do?","img":"","opts":["Treat it as very slippery – ride round it if you can, otherwise upright and as smoothly as possible","Brake hard on it to test the grip","Lean harder so you get past it quickly","Nothing – diesel does not affect grip"],"a":0,"ex":"Spilt <strong>diesel</strong> makes the surface <strong>very slippery</strong>, and shiny patches on a wet road are slippery too. Ride round it if you can – otherwise keep the motorcycle upright and brake, accelerate and steer as little and as smoothly as possible.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 227\">UK Highway Code rule 227</a>","<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Slippery surfaces\">SGI Motorcycle Handbook Slippery surfaces</a>","<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Rain\">SGI Motorcycle Handbook Rain</a>"],"signs":[]},{"id":"mcs-surface","area":"safety","paths":["motorcycle"],"lesson":"mc-road-surface","q":"Which road factor does Trafikverket name as important for motorcycle safety?","img":"","opts":["Even and predictable friction","Many speed bumps","Wide road markings","Dark asphalt"],"a":0,"ex":"Trafikverket lists <strong>even and predictable friction</strong> among the infrastructure measures for motorcycle safety – and works on maintenance requirements for <strong>loose gravel</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcs-curriculum-surface","area":"safety","paths":["motorcycle"],"lesson":"mc-road-surface","q":"What does the motorcycle curriculum say about road conditions?","img":"","opts":["You must explain how the road condition affects the motorcycle’s handling","Road conditions only matter for cars","Motorcycles are not affected by gravel","You may only ride on dry roads"],"a":0,"ex":"The curriculum requires you to explain <strong>how the road condition affects the motorcycle’s handling</strong>, and how different road conditions and environments affect riding and safety.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 2 kap. 2 §\">TSFS 2011:19 2 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 4 kap. 2 §\">TSFS 2011:19 4 kap. 2 §</a>"],"signs":[]},{"id":"sb-shape-warning","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"A sign is a <strong>triangle with the point up</strong>, yellow with a red border. What kind of sign is it?","img":"","opts":["A warning sign","A prohibitory sign","A mandatory sign","An information sign"],"a":0,"ex":"Warning signs (group A) are almost all yellow triangles with a red border and the point up. They warn of a danger ahead – they do not forbid anything by themselves.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P4\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 4 §\">VMF 2 kap. 4 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 1 §\">VMF 2 kap. 1 §</a>"],"signs":[]},{"id":"sb-shape-mandatory","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"A <strong>round blue</strong> sign with a white symbol is …","img":"","opts":["a mandatory sign – it tells you what you must do","a prohibitory sign – it tells you what you may not do","a warning sign","a recommendation you may ignore"],"a":0,"ex":"Mandatory signs (<em>påbudsmärken</em>, group D) are round and blue with white symbols. Prohibitory signs are round with a <strong>red</strong> edge.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 9 §\">VMF 2 kap. 9 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":[]},{"id":"sb-prohibition-end","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"Where does a prohibition shown by a prohibitory sign normally end?","img":"","opts":["At the next junction – unless an end sign or a panel shows something else","After exactly one kilometre","At the next built-up area","Only at an end sign"],"a":0,"ex":"A prohibitory sign applies from the sign <strong>to the next junction</strong>, or to an earlier end sign or a matching sign with a downward-arrow panel (T11). Some signs have their own rules, for example speed limits and no overtaking.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 7 §\">VMF 2 kap. 7 §</a>"],"signs":[]},{"id":"sb-exit-not-junction","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"You pass a “no stopping” sign and then the exit from a petrol station. Does the ban end at the exit?","img":"","opts":["No – exits from petrol stations, car parks and properties do not count as junctions","Yes – every road that joins ends the ban","Yes, but only on the left side of the road","Only if there is a give-way sign at the exit"],"a":0,"ex":"Exits from car parks, petrol stations, properties, small tracks and similar places are <strong>not</strong> junctions for this purpose, so the prohibition continues.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 7 §\">VMF 2 kap. 7 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>"],"signs":[]},{"id":"sb-speed-end","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"How long does this speed limit apply?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C31-5\" alt=\"C31 Speed limit\" width=\"64\" height=\"64\"></div>","opts":["Until a new speed limit, an end-of-temporary-limit sign, a pedestrian street or a walking-speed area","Until the next junction","For one kilometre","Until the next built-up area sign"],"a":0,"ex":"Unlike most prohibitory signs, <strong>C31 does not end at a junction</strong>. It applies until a different speed limit, <strong>C32</strong>, <strong>E7</strong> (pedestrian street) or <strong>E9</strong> (walking-speed area).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C31"]},{"id":"sb-overhead-lane","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"A prohibitory sign hangs <strong>over the left lane</strong> of a motorway. Who does it apply to?","img":"","opts":["Only the drivers in the left lane","All lanes","Only heavy trucks","Only the right lane"],"a":0,"ex":"Prohibitory and mandatory signs placed over the carriageway apply only to the <strong>lane they are placed over</strong>. A speed limit sign (C31) also covers the shoulder next to that lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P3\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 3 §\">VMF 2 kap. 3 §</a>"],"signs":[]},{"id":"sb-police-first","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"The traffic light shows red, but a police officer waves you on. What do you do?","img":"","opts":["Drive on – the police officer’s direction comes first","Wait for green","Drive on only if the junction is empty","Turn around"],"a":0,"ex":"A police officer’s directions apply <strong>before</strong> traffic signals, signs, markings and the traffic rules.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P3\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 3 §\">TrF 2 kap. 3 §</a>"],"signs":[]},{"id":"sb-light-before-sign","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"At a junction there is both a working traffic light (steady light) and a give-way sign. Which do you follow?","img":"","opts":["The traffic light","The give-way sign","The right-hand rule","Whichever is nearer"],"a":0,"ex":"A steady light in a traffic signal applies <strong>before</strong> a stop or give-way sign. The signs apply when the signal is switched off or only flashes yellow.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 2 §\">TrF 2 kap. 2 §</a>"],"signs":[]},{"id":"sb-light-off","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"The traffic lights at a junction only flash yellow. What applies?","img":"","opts":["The road signs and the general traffic rules – take special care","Everyone must stop","The main road always has priority","Treat it as green"],"a":0,"ex":"Flashing yellow means the signal is out of order or temporarily not working. Then the <strong>signs</strong> at the junction – and otherwise the general rules such as the right-hand rule – apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 2 §\">TrF 2 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 6 §\">VMF 3 kap. 6 §</a>"],"signs":[]},{"id":"sb-sign-before-rule","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"In a built-up area there is a 40 km/h sign. What is the speed limit?","img":"","opts":["40 km/h – the sign applies before the general rule","50 km/h – the general rule for built-up areas","30 km/h","60 km/h"],"a":0,"ex":"If a sign differs from a general traffic rule, the <strong>sign applies before the rule</strong>. The general limit of 50 km/h in built-up areas is replaced by the 40 km/h sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 2 §\">TrF 2 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 17 §\">TrF 3 kap. 17 §</a>"],"signs":[]},{"id":"sb-with-e5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"A prohibitory sign is put up <strong>together with the built-up area sign</strong> (E5). Where does the prohibition apply?","img":"","opts":["In the whole built-up area","Until the next junction","Only on the main road","For one kilometre"],"a":0,"ex":"A prohibitory sign placed together with <strong>E5</strong> applies in the <strong>whole built-up area</strong>, unless something else is shown for a certain road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 7 §\">VMF 2 kap. 7 §</a>"],"signs":[]},{"id":"sb-pushing-bike","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"Does a “no vehicles” sign apply to someone <strong>walking beside</strong> a bicycle?","img":"","opts":["No – they count as a pedestrian, unless a panel says otherwise","Yes, always","Only at night","Only for electric bicycles"],"a":0,"ex":"A person who walks with a bicycle or moped counts as a <strong>pedestrian</strong>, so a ban aimed at vehicles does not apply to them – unless a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 7 §\">VMF 2 kap. 7 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K1P4\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 1 kap. 4 §\">TrF 1 kap. 4 §</a>"],"signs":[]},{"id":"sb-panels-several","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signs-basics","q":"Under a sign there are <strong>two separate panels</strong>. How do you read them?","img":"","opts":["Each panel adds its own condition to the sign","Only the lower panel applies","Only the upper panel applies","The panels cancel each other out"],"a":0,"ex":"With several panels, each one applies as a <strong>separate addition</strong> to the sign. If <strong>one</strong> panel holds several instructions, they apply <strong>together</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 2 §\">VMF 2 kap. 2 §</a>"],"signs":[]},{"id":"ws-distance-50","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"On a road with a speed limit of 50 km/h, how far before the danger does a warning sign normally stand?","img":"","opts":["5–75 metres","150–250 metres","200–400 metres","Exactly 100 metres"],"a":0,"ex":"Where the limit is <strong>50 km/h or lower</strong>, warning signs stand <strong>5–75 m</strong> before the danger. At 60–70 km/h it is 50–200 m, at 80–90 km/h 150–250 m, and above 90 km/h 200–400 m.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 2 §\">TSFS 2019:74 2 kap. 2 §</a>"],"signs":[]},{"id":"ws-distance-90","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"On a road with a speed limit of 90 km/h, how far before the danger does a warning sign normally stand?","img":"","opts":["150–250 metres","5–75 metres","50–100 metres","500–1,000 metres"],"a":0,"ex":"At <strong>80 or 90 km/h</strong> a warning sign stands <strong>150–250 m</strong> before the danger. If it has to stand further away, a distance panel (T2) shows the distance.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 2 §\">TSFS 2019:74 2 kap. 2 §</a>"],"signs":[]},{"id":"ws-no-sign","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"On a road with the base speed of 70 km/h you see <strong>no warning sign</strong> before a bend. What can you conclude?","img":"","opts":["Nothing – warning signs are only used for dangers you cannot be expected to foresee","That the bend can be taken at 70 km/h","That there are no junctions or animals ahead","That the road is never icy"],"a":0,"ex":"On roads with the base speed, warning signs may only be used for things road users <strong>cannot be expected to foresee</strong>. Ordinary bends, visible junctions and winter ice are often not signed – you must always adapt your speed to what you see.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 1 §\">TSFS 2019:74 2 kap. 1 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"ws-a10-winter","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"In winter you drive a long stretch without seeing this sign. Can the road still be icy?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A10-1\" alt=\"A10 Slippery road\" width=\"64\" height=\"64\"></div>","opts":["Yes – the sign is used for snow or ice only if there are special reasons","No – the road authority must put it up wherever there is ice","Only if the temperature is below −10 °C","Only on bridges"],"a":0,"ex":"Sign <strong>A10 (slippery road)</strong> is used to warn of snow or ice <strong>only if there are special reasons</strong>. In winter you must judge the grip yourself.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A10"]},{"id":"ws-a3-percent","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"The sign shows 10 %. What does that mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A3-1\" alt=\"A3 Steep descent\" width=\"64\" height=\"64\"></div>","opts":["The road drops 10 metres for every 100 metres","The road drops 10 metres in total","The descent is 10 kilometres long","The speed limit drops by 10 %"],"a":0,"ex":"The percentage on the steep-descent and steep-ascent signs is the slope – <strong>10 %</strong> means 10 metres down (or up) per 100 metres. Downhill, use a lower gear so the engine helps to brake.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A3"]},{"id":"ws-a28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What applies at the junction this sign warns of?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A28-1\" alt=\"A28 Crossroads (right-hand rule)\" width=\"64\" height=\"64\"></div>","opts":["The right-hand rule – give way to vehicles from your right","You have priority","Everyone must stop","Traffic from the left has priority"],"a":0,"ex":"<strong>A28 (crossroads)</strong> warns of a junction where nobody has priority from signs, so the <strong>right-hand rule</strong> applies.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 18 §\">TrF 3 kap. 18 §</a>"],"signs":["A28"]},{"id":"ws-a29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign tell you?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A29-1\" alt=\"A29 Junction where side roads must give way\" width=\"64\" height=\"64\"></div>","opts":["Junction ahead where the side roads must give way – you are on the road with priority","Junction ahead where you must give way","A one-way street joins from the right","The road ahead is closed"],"a":0,"ex":"<strong>A29</strong> shows a junction where traffic on the side roads must give way or stop. The <strong>wide line</strong> in the symbol is your road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 12 §\">TSFS 2019:74 2 kap. 12 §</a>"],"signs":["A29"]},{"id":"ws-a38","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What do the red stripes on these boards count down to?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A38-1\" alt=\"A38 Distance to level crossing\" width=\"64\" height=\"64\"></div>","opts":["A level crossing – in thirds of the distance","A motorway exit – one stripe per 100 m","A school","A speed camera"],"a":0,"ex":"The distance markers (<strong>A38</strong>) count down to a <strong>level crossing</strong> in thirds: three stripes, then two, then one.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 17 §\">TSFS 2019:74 2 kap. 17 §</a>"],"signs":["A38"]},{"id":"ws-a39-place","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"Where does this sign stand?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A39-1\" alt=\"A39 St Andrew's cross (level crossing)\" width=\"64\" height=\"64\"></div>","opts":["Immediately before a railway or tramway crossing – normally at least 5 m before the nearest rail","150–250 m before the crossing","At the end of a railway crossing","At a railway station car park"],"a":0,"ex":"The <strong>St Andrew’s cross (A39)</strong> stands <strong>immediately before</strong> the crossing – normally at least five metres before the nearest rail. Where there is more than one track, another train can come as soon as one has passed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 20 §\">TSFS 2019:74 2 kap. 20 §</a>"],"signs":["A39"]},{"id":"ws-a41","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"When is this sign used?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A41\" alt=\"A41 Accident\" width=\"64\" height=\"64\"></div>","opts":["Only at a traffic accident that blocks part of the road, for as long as it does","At places where many accidents have happened in the past","At every motorway entry","At road works"],"a":0,"ex":"<strong>A41 (accident)</strong> is put up only at an accident that <strong>blocks part of the road</strong>, and only for as long as it does. The law requires a low enough speed past an accident.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 22 §\">TSFS 2019:74 2 kap. 22 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>"],"signs":["A41"]},{"id":"ws-children","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"You approach children playing beside the road. What does the law require?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A15-1\" alt=\"A15 Children\" width=\"64\" height=\"64\"></div>","opts":["A speed low enough for the situation, so you can stop if a child runs out","Sounding the horn as a warning","Keeping the speed limit – nothing more","Stopping and waiting until they are gone"],"a":0,"ex":"The law requires a <strong>low enough speed</strong> when you approach children on or beside the road. Sign <strong>A15</strong> tells you that children often cross or stay there.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 15 §\">TrF 3 kap. 15 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A15"]},{"id":"ws-a19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign mark?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A19-1\" alt=\"A19 Animals\" width=\"64\" height=\"64\"></div>","opts":["A place or stretch with a special risk of animals on or beside the road","A hunting area – do not stop","A zoo or wildlife park","A place where elk must be reported to the police"],"a":0,"ex":"<strong>A19</strong> marks a place or stretch where there is a <strong>special risk</strong> of animals on or by the road. The elk is the standard symbol.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 2 kap. 8 §\">TSFS 2019:74 2 kap. 8 §</a>"],"signs":["A19"]},{"id":"ps-giveway-meaning","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does the duty to give way (<em>väjningsplikt</em>) require of you?","img":"","opts":["Show it early by slowing down or stopping, and only drive on if you cause no danger or obstruction","Always stop completely","Sound the horn and drive on carefully","Drive on if you are faster than the others"],"a":0,"ex":"A driver who must give way must <strong>clearly show it in good time</strong> by slowing down or stopping, and may continue only if it causes <strong>no danger or obstruction</strong> – nobody should need to brake or swerve because of you.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 5 §\">TrF 3 kap. 5 §</a>"],"signs":[]},{"id":"ps-stop-empty","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You come to this sign and can see that the crossing road is completely empty. What must you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B2-1\" alt=\"B2 Stop\" width=\"64\" height=\"64\"></div>","opts":["Stop completely, then drive on","Slow down and drive on without stopping","Stop only if a vehicle is coming","Sound the horn and drive on"],"a":0,"ex":"<strong>Stop means stop</strong> – you must stop completely before entering the crossing road, even if it is empty, and then give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P19\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 19 §\">TrF 3 kap. 19 §</a>"],"signs":["B2"]},{"id":"ps-stop-where","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"Where must you stop at a stop sign that has <strong>no stop line</strong>?","img":"","opts":["Immediately before you enter the crossing road","At the sign","10 metres before the junction","In the middle of the crossing road"],"a":0,"ex":"Stop <strong>at the stop line</strong>. If there is none, stop <strong>immediately before entering</strong> the crossing road, route or track area.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P19\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 19 §\">TrF 3 kap. 19 §</a>"],"signs":[]},{"id":"ps-stop-view","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You have stopped at the stop line, but buildings hide the crossing road. What do you do?","img":"","opts":["Roll forward slowly until you can see, and give way","Drive straight out – you have already stopped","Reverse and choose another road","Wait until another car comes"],"a":0,"ex":"Make your stop <strong>at the stop line</strong>. If you cannot see from there, roll forward slowly and look again – then drive on only when it causes no danger or obstruction.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P19\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 19 §\">TrF 3 kap. 19 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 5 §\">TrF 3 kap. 5 §</a>"],"signs":[]},{"id":"ps-b1-t3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"A give-way sign has a panel with <strong>“STOPP 200 m”</strong>. What does it mean?","img":"","opts":["A stop sign comes in 200 metres","Give way within 200 metres","Stopping is forbidden for 200 metres","A police check is 200 metres ahead"],"a":0,"ex":"Panel <strong>T3 (distance to stop)</strong> is only used under the give-way sign B1. It warns that a <strong>stop sign</strong> comes after the distance shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ps-t13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"This panel is under a give-way sign. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T13-1\" alt=\"T13 All-way give way\" width=\"64\" height=\"64\"></div>","opts":["All drivers entering the junction must give way","Only you must give way","The junction is a roundabout","The main road continues to the right"],"a":0,"ex":"<strong>T13</strong> means <strong>all-way give way</strong> – everyone entering the junction must give way. Nobody has priority, so be extra careful and make yourself understood.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T13"]},{"id":"ps-main-road-park","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"May you park on this kind of road?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B4-1\" alt=\"B4 Main road\" width=\"64\" height=\"64\"></div>","opts":["No – parking on a main road is not allowed","Yes, anywhere","Yes, but only at night","Yes, if the hazard lights are on"],"a":0,"ex":"<strong>B4</strong> marks a main road (<em>huvudled</em>). You may <strong>not park</strong> on a main road. Stopping briefly, for example to let someone out, is allowed where nothing else forbids it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P55\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 55 §\">TrF 3 kap. 55 §</a>"],"signs":["B4"]},{"id":"ps-enter-main","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You drive from a side road onto a main road that has <strong>no acceleration lane</strong>. Who gives way?","img":"","opts":["You – to the vehicles on the main road","The vehicles on the main road – to you","Whoever comes from the right","Nobody – drive in at the same speed"],"a":0,"ex":"A driver who enters a main road, motorway or expressway where there is no acceleration lane must <strong>give way</strong> to vehicles on that road.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>"],"signs":[]},{"id":"ps-priority-care","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You are on a main road and a car pulls out in front of you from a side road. What must you do?","img":"","opts":["Do what you can to avoid a collision – priority does not mean you may ignore others","Keep your speed – you have priority","Sound the horn and keep going","Speed up to get past first"],"a":0,"ex":"Having priority never means you can ignore others. Every road user must take the care needed to <strong>avoid accidents</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 1 §\">TrF 2 kap. 1 §</a>"],"signs":[]},{"id":"ps-b6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You come to this sign before a narrow bridge. An oncoming car is on the bridge. What do you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B6-1\" alt=\"B6 Give way to oncoming traffic\" width=\"64\" height=\"64\"></div>","opts":["Wait until it has passed – you must give way to oncoming traffic","Drive on – the oncoming car must reverse","Flash your lights and drive on","Drive on if you are already close"],"a":0,"ex":"<strong>B6</strong> means <strong>give way to oncoming traffic</strong> on the narrow stretch: do not drive in if it would hinder vehicles coming towards you.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B6"]},{"id":"ps-obstacle-side","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"On a narrow road without signs, a parked car blocks <strong>your</strong> side, and a car is coming towards you. Who should stop?","img":"","opts":["You – the driver with the obstacle on their side","The oncoming driver","The one who is driving faster","The one who comes from the right"],"a":0,"ex":"The general rule is that the driver who has the <strong>obstacle on their side</strong> must stop if necessary to let the oncoming vehicle pass.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 30 §\">TrF 3 kap. 30 §</a>"],"signs":[]},{"id":"ps-crossing-uncontrolled","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"At an <strong>uncontrolled</strong> pedestrian crossing, who must you give way to?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B3-1\" alt=\"B3 Pedestrian crossing\" width=\"64\" height=\"64\"></div>","opts":["Pedestrians who are on the crossing or about to step onto it","Only pedestrians who are already in your half of the crossing","Nobody – pedestrians must wait for a gap","Only children and older people"],"a":0,"ex":"At an uncontrolled crossing a driver must <strong>give way</strong> to pedestrians who have stepped onto the crossing <strong>or are just about to</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P61\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 61 §\">TrF 3 kap. 61 §</a>"],"signs":["B3"]},{"id":"ps-crossing-controlled","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What makes a pedestrian crossing <strong>controlled</strong> (<em>bevakat</em>)?","img":"","opts":["Traffic lights or a police officer directing the traffic","A B3 sign on both sides","Street lighting","A school nearby"],"a":0,"ex":"A crossing is <strong>controlled</strong> when traffic there is directed by <strong>traffic lights or a police officer</strong>. Without them it is uncontrolled.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:651#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Ordinance (2001:651) — Vägtrafikdefinitionsförordningen 2 §\">Vägtrafikdefinitionsförordningen 2 §</a>"],"signs":[]},{"id":"ps-crossing-overtake","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"May you overtake just before an uncontrolled pedestrian crossing?","img":"","opts":["No","Yes, if no pedestrian is visible","Yes, if you sound the horn","Yes, at most 30 km/h"],"a":0,"ex":"Overtaking just before or on an <strong>uncontrolled</strong> crossing is forbidden – a vehicle you overtake may be hiding a pedestrian.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P40\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 40 §\">TrF 3 kap. 40 §</a>"],"signs":[]},{"id":"ps-crossing-park","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"How close to a pedestrian crossing may you stop or park?","img":"","opts":["Not on it, and not within 10 metres before it","Not within 5 metres after it","Anywhere, if the hazard lights are on","Not within 20 metres before it"],"a":0,"ex":"You may not stop or park <strong>on</strong> a pedestrian crossing or <strong>within 10 metres before</strong> it, so that pedestrians and drivers can see each other.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"ps-crossing-no-stop-on","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"The traffic ahead is queueing beyond a pedestrian crossing. What should you do?","img":"","opts":["Wait before the crossing so you do not have to stop on it","Drive onto the crossing and wait there","Use the hazard lights and stop on the crossing","Overtake the queue"],"a":0,"ex":"You must approach a pedestrian crossing so that you <strong>will not have to stop on it</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P62\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 62 §\">TrF 3 kap. 62 §</a>"],"signs":[]},{"id":"ps-cycle-crossing","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You come to a cycle crossing with this sign. A cyclist is about to ride onto it. What do you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B8-1\" alt=\"B8 Cycle crossing\" width=\"64\" height=\"64\"></div>","opts":["Give way to the cyclist","Drive on – cyclists must give way to cars","Sound the horn so the cyclist waits","Give way only if the cyclist is already on the crossing"],"a":0,"ex":"At a <strong>cycle crossing</strong> (B8 sign, square markings and a give-way line) drivers must <strong>give way</strong> to cyclists and class II moped riders who are on it or about to ride onto it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P61a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 61a §\">TrF 3 kap. 61a §</a>"],"signs":["B8"]},{"id":"ps-cycle-passage","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"You have just turned at a junction and reach an uncontrolled <strong>cycle passage</strong> (markings, no B8 sign, no traffic lights). A cyclist is about to ride onto it. What applies?","img":"","opts":["Drive slowly and let the cyclist go first","The cyclist must always wait for you","Sound the horn and drive on","Accelerate so you pass before the cyclist"],"a":0,"ex":"At a cycle passage cyclists must cross only when it is safe – but <strong>after turning</strong> at a junction, a driver must drive slowly and let cyclists who are on or about to ride onto the passage go first.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P61\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 61 §\">TrF 3 kap. 61 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K6P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 6 kap. 6 §\">TrF 6 kap. 6 §</a>"],"signs":[]},{"id":"pr-c1-where","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"Where do you typically see this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C1-1\" alt=\"C1 No entry\" width=\"64\" height=\"64\"></div>","opts":["At the far end of a one-way street, where traffic comes towards you","At the start of a motorway","At a pedestrian street – for all traffic","At a car park exit"],"a":0,"ex":"<strong>C1 (no entry)</strong> stops traffic going <strong>in</strong> from your side. You see it at the far end of a <strong>one-way street</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 4 kap. 3 §\">TSFS 2019:74 4 kap. 3 §</a>"],"signs":["C1"]},{"id":"pr-c1-c2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What is the difference between C1 (no entry) and C2 (no vehicles)?","img":"","opts":["C1 bans driving in from your side; C2 closes the road to vehicles in both directions","C1 is for cars only; C2 for all vehicles","C2 is temporary; C1 is permanent","There is no difference"],"a":0,"ex":"<strong>C1</strong> stops traffic going in from your side – traffic from the other side may come out. <strong>C2</strong> is a red ring that closes the road to vehicles <strong>in both directions</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 4 kap. 3 §\">TSFS 2019:74 4 kap. 3 §</a>"],"signs":[]},{"id":"pr-c4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"Which of these may drive past this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C4-1\" alt=\"C4 No motor vehicles with more than two wheels\" width=\"64\" height=\"64\"></div>","opts":["A two-wheeled motorcycle","A passenger car","A light truck","A car with a trailer"],"a":0,"ex":"<strong>C4</strong> bans motor vehicles with <strong>more than two wheels</strong>. Two-wheeled motorcycles and mopeds may pass.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C4"]},{"id":"pr-c27-which","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"Which of these may you overtake under this sign (if it is safe)?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C27-1\" alt=\"C27 No overtaking\" width=\"64\" height=\"64\"></div>","opts":["A two-wheeled motorcycle without a sidecar","A car","A tractor","A bus"],"a":0,"ex":"<strong>C27</strong> forbids overtaking motor vehicles <strong>other than</strong> two-wheeled mopeds and two-wheeled motorcycles without a sidecar. Bicycles, riders and horse-drawn vehicles are not covered either.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C27"]},{"id":"pr-c27-end","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"Where does this ban end?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C27-1\" alt=\"C27 No overtaking\" width=\"64\" height=\"64\"></div>","opts":["At the end sign C28","At the next junction","After 1 kilometre","At the next speed limit sign"],"a":0,"ex":"The no-overtaking ban applies on the road where it is put up <strong>until sign C28</strong> (end of no overtaking) – it does <strong>not</strong> end at a junction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C27"]},{"id":"pr-c27-mc","area":"rules","paths":["motorcycle"],"lesson":"prohibitory-signs","q":"You ride a motorcycle and pass this sign. May you overtake a car?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C27-1\" alt=\"C27 No overtaking\" width=\"64\" height=\"64\"></div>","opts":["No – the ban applies to you too","Yes – motorcycles are exempt","Yes, if the car is slower than 70 km/h","Yes, outside built-up areas"],"a":0,"ex":"The ban applies to <strong>all</strong> drivers: you may not overtake a car. But cars may overtake <strong>you</strong>, because you ride a two-wheeled motorcycle without a sidecar.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C27"]},{"id":"pr-c19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"The sign shows <strong>50 m</strong>. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C19-1\" alt=\"C19 Minimum distance\" width=\"64\" height=\"64\"></div>","opts":["You may not drive closer than 50 m to the motor vehicle in front going the same way","The road ends in 50 metres","Overtaking is forbidden for 50 metres","Parking is allowed 50 metres from here"],"a":0,"ex":"<strong>C19 (minimum distance)</strong> forbids driving closer than the distance shown to the <strong>motor vehicle in front</strong>. It is often used on bridges and in tunnels.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C19"]},{"id":"pr-weight","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"A weight sign (C20) shows <strong>3.5 t</strong>. Which weight counts?","img":"","opts":["The vehicle’s actual gross weight right now, with people and load","The total weight in the registration certificate","The kerb weight without a driver","The weight of the load only"],"a":0,"ex":"The weight signs are about the <strong>gross weight</strong> – the weight the wheels actually put on the road at that moment, people and load included.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:559#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Act (2001:559) — Vägtrafikdefinitionslagen 2 §\">Vägtrafikdefinitionslagen 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":[]},{"id":"pr-c17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"A height limit sign shows <strong>3.0 m</strong>. With a box on the roof your car is 3.2 m high. What do you do?","img":"","opts":["Do not drive in – choose another way","Drive in slowly","Drive in if the box is empty","Drive in on the shoulder"],"a":0,"ex":"The height limit sign (<strong>C17</strong>) gives the maximum height allowed. Remember roof boxes, bikes on the roof and high loads.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":[]},{"id":"pr-stop-or-park","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"Which of these counts as <strong>stopping</strong> (<em>stannande</em>) and not parking?","img":"","opts":["Letting a passenger get out","Waiting in the car with the engine running for a friend to come","Leaving the car for two minutes to buy a newspaper","Sitting in the car to make a phone call"],"a":0,"ex":"Stopping is standing still briefly <strong>to let people get in or out or to load or unload goods</strong>. Anything else – even waiting in the car with the engine running – is <strong>parking</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2001:651#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Ordinance (2001:651) — Vägtrafikdefinitionsförordningen 2 §\">Vägtrafikdefinitionsförordningen 2 §</a>"],"signs":[]},{"id":"pr-c35","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"May you let a passenger out where this sign applies?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C35-1\" alt=\"C35 No parking\" width=\"64\" height=\"64\"></div>","opts":["Yes – stopping is allowed, parking is not","No – neither stopping nor parking","Only at night","Only for taxis"],"a":0,"ex":"<strong>C35 (no parking)</strong> has one red slash: you may <strong>stop</strong> to let someone in or out or to load, but you may <strong>not park</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2001:651#P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Definitions Ordinance (2001:651) — Vägtrafikdefinitionsförordningen 2 §\">Vägtrafikdefinitionsförordningen 2 §</a>"],"signs":["C35"]},{"id":"pr-c35-side","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"On which side of the road does this sign apply?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C35-1\" alt=\"C35 No parking\" width=\"64\" height=\"64\"></div>","opts":["On the side where it stands","On both sides","On the opposite side","In the whole street"],"a":0,"ex":"The stopping and parking signs apply on <strong>the side of the road where they stand</strong>, from the sign to the next junction or another stopping or parking sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C35"]},{"id":"pr-c39","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"May you stop here to let a passenger out?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C39-1\" alt=\"C39 No stopping or parking\" width=\"64\" height=\"64\"></div>","opts":["No","Yes, for at most one minute","Yes, if the engine is running","Yes, if the hazard lights are on"],"a":0,"ex":"<strong>C39 (no stopping or parking)</strong> forbids even a short stop for passengers. Only standing still because of the traffic or to avoid danger is allowed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C39"]},{"id":"pr-c38","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"Today is <strong>14 May</strong>. Where does this sign say you may <strong>not</strong> park?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C38-1\" alt=\"C38 Date parking\" width=\"64\" height=\"64\"></div>","opts":["On the side of the street with even house numbers","On the side with odd house numbers","On both sides","Nowhere – the sign only applies in winter"],"a":0,"ex":"<strong>C38 (date parking)</strong>: on <strong>even</strong> dates you may not park on the side with <strong>even</strong> house numbers; on odd dates not on the side with odd numbers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C38"]},{"id":"pr-c36","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"It is the 7th of the month. May you park where this sign applies?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C36-1\" alt=\"C36 No parking on odd dates\" width=\"64\" height=\"64\"></div>","opts":["No – parking is banned on odd dates","Yes – parking is banned on even dates","Yes, but only for 2 hours","Only at night"],"a":0,"ex":"<strong>C36</strong> bans parking on <strong>odd</strong> dates (1st, 3rd, 5th, 7th …). C37 bans parking on even dates.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C36"]},{"id":"pr-c40-lastplats","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"A special-purpose place (C40) is marked <strong>LASTPLATS</strong>. What is it for?","img":"","opts":["Loading or unloading heavy or bulky goods","Parking for trucks overnight","Short-term parking for everyone","Taxis waiting for customers"],"a":0,"ex":"<em>Lastplats</em> means a place for loading or unloading <strong>heavy or bulky goods</strong>. You may only park or stop there for that purpose – though a brief stop to let people in or out is allowed if it does not hinder the purpose.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P54\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 54 §\">TrF 3 kap. 54 §</a>"],"signs":[]},{"id":"pr-time-panel-none","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"A no-parking sign has <strong>no time panel</strong>. When does it apply?","img":"","opts":["All the time","Weekdays 8–18","Only during the day","Only on weekdays"],"a":0,"ex":"Without a time panel, the ban applies <strong>all the time</strong>. A panel such as 8–18 limits it to those times.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"md-forbids","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"May you drive a car on a path marked with this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D4-1\" alt=\"D4 Cycle track\" width=\"64\" height=\"64\"></div>","opts":["No – only cross it","Yes, at walking pace","Yes, if no cyclists are there","Yes, to park"],"a":0,"ex":"A mandatory sign for a certain kind of traffic also <strong>forbids all other traffic</strong>. <strong>D4</strong> marks a cycle track for cyclists and class II moped riders; other vehicles may only <strong>cross</strong> it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 9 §\">VMF 2 kap. 9 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 6 §\">TrF 3 kap. 6 §</a>"],"signs":["D4"]},{"id":"md-cross-cycle-track","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"You cross a cycle track to reach a property. Who goes first?","img":"","opts":["Cyclists and class II moped riders on the cycle track","You, because you are in a car","Whoever comes from the right","Whoever arrives first"],"a":0,"ex":"When you cross a cycle track, you must <strong>give way</strong> to cyclists and class II moped riders on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P59\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 59 §\">TrF 3 kap. 59 §</a>"],"signs":[]},{"id":"md-d2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign on a traffic island tell you?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D2-1\" alt=\"D2 Pass this side\" width=\"64\" height=\"64\"></div>","opts":["Pass the sign on the side the arrow shows","Turn right at the next junction","The road turns sharply to the right","One-way traffic to the right"],"a":0,"ex":"<strong>D2 (pass this side)</strong> means vehicles may only pass the sign on the side the arrow shows.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D2"]},{"id":"md-island","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"There is an island in the middle of a two-way road and no sign on it. On which side do you pass?","img":"","opts":["On the right","On the left","On either side","You must stop before it"],"a":0,"ex":"Without a D2 sign, you pass an island in the middle of a two-way road on the <strong>right</strong>. On a one-way road, or if the island is right of the centre, either side is allowed unless a sign says otherwise.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P13\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 13 §\">TrF 3 kap. 13 §</a>"],"signs":[]},{"id":"md-roundabout-giveway","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"You drive into a roundabout. Who must give way?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D3-1\" alt=\"D3 Roundabout\" width=\"64\" height=\"64\"></div>","opts":["You – to every vehicle already in the roundabout","The vehicles in the roundabout – to you","Whoever comes from the right","Nobody"],"a":0,"ex":"A driver entering a roundabout must <strong>give way to every vehicle already in it</strong>. D3 is always put up together with a give-way or stop sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P22\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 22 §\">TrF 3 kap. 22 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 5 kap. 8 §\">TSFS 2019:74 5 kap. 8 §</a>"],"signs":["D3"]},{"id":"md-roundabout-direction","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"In which direction do you drive around a roundabout in Sweden?","img":"","opts":["Anticlockwise – keeping the centre on your left","Clockwise","Either way","It depends on the lane"],"a":0,"ex":"In a roundabout you drive <strong>anticlockwise</strong>, around the central island on your left.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P13\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 13 §\">TrF 3 kap. 13 §</a>"],"signs":[]},{"id":"md-bus-lane","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"A bus lane on the right-hand side has this sign and no panel. Who may drive in it?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D10-1\" alt=\"D10 Bus lane\" width=\"64\" height=\"64\"></div>","opts":["Buses in scheduled services, cyclists and class II moped riders","All vehicles outside rush hour","Taxis and motorcycles","Electric cars"],"a":0,"ex":"In a lane for vehicles in scheduled services only those vehicles may be driven – and, if the lane is on the right, <strong>bicycles and class II mopeds</strong>. A panel can let others in, for example taxis.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 2 §\">TrF 8 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D10"]},{"id":"md-bus-lane-cross","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What may you do with a car in a bus lane?","img":"","opts":["Only cross it, for example to turn","Drive in it for up to 100 metres","Stop briefly to let passengers out","Park in it at night"],"a":0,"ex":"Other drivers may only <strong>cross</strong> a bus lane, and you may not stop or park in it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 10 §\">TrF 3 kap. 10 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"md-bus-lane-mc","area":"rules","paths":["motorcycle"],"lesson":"mandatory-signs","q":"May you ride a motorcycle in a bus lane?","img":"","opts":["No – unless a panel allows motorcycles","Yes, always","Yes, in queues","Yes, outside built-up areas"],"a":0,"ex":"A motorcycle is not a vehicle in scheduled services. Unless a <strong>panel</strong> allows motorcycles, you may only cross the bus lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 2 §\">TrF 8 kap. 2 §</a>"],"signs":[]},{"id":"is-e5-speed","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"You pass this sign and see no speed limit sign. What is the speed limit?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E5-1\" alt=\"E5 Built-up area\" width=\"64\" height=\"64\"></div>","opts":["50 km/h","30 km/h","70 km/h","40 km/h"],"a":0,"ex":"<strong>E5</strong> marks the start of a built-up area, where the general limit is <strong>50 km/h</strong> unless signs show something else.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 17 §\">TrF 3 kap. 17 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E5"]},{"id":"is-f10-not-e5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"You pass a <strong>place name sign</strong> (F10) with the name of a village, but no built-up area sign (E5). Does the 50 km/h rule for built-up areas start?","img":"","opts":["No – only the E5 sign starts a built-up area","Yes – all place name signs start it","Yes, if there are houses on both sides","Only at night"],"a":0,"ex":"The place name sign only tells you the <strong>name</strong> of the place. A built-up area is decided in a local traffic regulation and marked with <strong>E5</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 17 §\">VMF 2 kap. 17 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K10P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 10 kap. 1 §\">TrF 10 kap. 1 §</a>"],"signs":[]},{"id":"is-pedestrian-street","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"Which rules apply on a street with this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E7-1\" alt=\"E7 Pedestrian street\" width=\"64\" height=\"64\"></div>","opts":["Walking pace, no parking, give way to pedestrians – and motor vehicles may only cross, except for deliveries and some other needs","30 km/h and parking on the right side only","Only bicycles may be ridden there","Normal traffic rules, but pedestrians have priority at crossings"],"a":0,"ex":"On a <strong>pedestrian street</strong> (E7): vehicles at most <strong>walking pace</strong>, <strong>no parking</strong>, drivers <strong>give way to pedestrians</strong>. Motor vehicles may only cross it, except when needed for deliveries, goods or residents’ transport, hotel guests, or sick or disabled people.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1 §\">TrF 8 kap. 1 §</a>"],"signs":["E7"]},{"id":"is-walking-area","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"May you drive through an area with this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E9-1\" alt=\"E9 Walking-speed area\" width=\"64\" height=\"64\"></div>","opts":["Yes – at walking pace, giving way to pedestrians and without parking","No – only residents may drive there","Yes – at most 30 km/h","Only to deliver goods"],"a":0,"ex":"In a <strong>walking-speed area</strong> (E9) you may drive through, but at most at <strong>walking pace</strong>, you must <strong>give way to pedestrians</strong>, and you may <strong>not park</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1 §\">TrF 8 kap. 1 §</a>"],"signs":["E9"]},{"id":"is-cycle-street","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What is the highest speed on a street with this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E33-CYKELGATA\" alt=\"E33 Cycle street\" width=\"64\" height=\"64\"></div>","opts":["30 km/h","Walking pace","20 km/h","50 km/h"],"a":0,"ex":"On a <strong>cycle street</strong> (E33): at most <strong>30 km/h</strong>, parking only in arranged parking places, drivers entering from another road give way to vehicles on it, and motor vehicle drivers must adapt their speed to the cyclists.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K8P1a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 8 kap. 1a §\">TrF 8 kap. 1a §</a>"],"signs":["E33"]},{"id":"is-leave-area","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"You drive out of a walking-speed area onto an ordinary street. Who gives way?","img":"","opts":["You – to the traffic on the street","The traffic on the street – to you","Whoever comes from the right","Nobody"],"a":0,"ex":"A driver who leaves a pedestrian street, walking-speed area or cycle street must <strong>give way</strong> to the traffic on the road they enter.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>"],"signs":[]},{"id":"is-recommended","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What is this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E11-1\" alt=\"E11 Recommended lower speed\" width=\"64\" height=\"64\"></div>","opts":["A recommended lower speed – but you must always adapt your speed to the conditions","A speed limit that is checked by camera","A minimum speed","The speed limit for heavy vehicles only"],"a":0,"ex":"<strong>E11</strong> is a <strong>recommendation</strong> – a stretch where it is suitable to drive slower than the limit. The law still requires you to adapt your speed to the conditions, so ignoring it can still be breaking the law.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":["E11"]},{"id":"is-merging","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"Two lanes merge into one. What does the law require?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E15-1\" alt=\"E15 Merging lanes (zip merge)\" width=\"64\" height=\"64\"></div>","opts":["Both drivers adapt to each other with mutual consideration","The left lane always has priority","The right lane always has priority","The faster vehicle goes first"],"a":0,"ex":"Where lanes merge, the drivers must adapt with <strong>mutual consideration</strong>. If you see someone wanting to move into your lane, adjust your speed to make it easier for them. Taking turns (the zip principle) is common practice.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P44\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 44 §\">TrF 3 kap. 44 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P43\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 43 §\">TrF 3 kap. 43 §</a>"],"signs":["E15"]},{"id":"is-passing-place","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"May you park at a place with this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E18-1\" alt=\"E18 Passing place\" width=\"64\" height=\"64\"></div>","opts":["No – it is for meeting and letting others pass","Yes, for up to 24 hours","Yes, at night","Yes, if you leave the hazard lights on"],"a":0,"ex":"<strong>E18</strong> marks a <strong>passing place</strong> on a narrow road. Parking there is not allowed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P55\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 55 §\">TrF 3 kap. 55 §</a>"],"signs":["E18"]},{"id":"is-bus-stop","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"A bus stop is shown only with this sign – nothing is marked on the road. Where may you <strong>not</strong> stop or park?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E22-1\" alt=\"E22 Bus stop\" width=\"64\" height=\"64\"></div>","opts":["From 20 metres before to 5 metres after the sign – except briefly for passengers if buses are not hindered","Within 10 metres on both sides","Within 50 metres before the sign","Only right next to the sign"],"a":0,"ex":"If the stop is not marked on the road, you may not stop or park from <strong>20 m before to 5 m after</strong> the sign – except briefly to let people in or out, if it does not hinder the buses.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P54\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 54 §\">TrF 3 kap. 54 §</a>"],"signs":["E22"]},{"id":"is-bus-leaving","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"On a 50 km/h street, a bus at a stop signals that it is pulling out. What must you do?","img":"","opts":["Slow down and stop if needed, so the bus can get out","Overtake the bus quickly","Sound the horn and keep going","Nothing – the bus must wait for a gap"],"a":0,"ex":"Where the limit is <strong>50 km/h or lower</strong>, you must slow down – and stop if needed – to let a bus that signals it is leaving a bus stop get out.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P45\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 45 §\">TrF 3 kap. 45 §</a>"],"signs":[]},{"id":"is-24h","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"On a public street in a built-up area where parking is allowed, how long may a car stay parked in a row on weekdays?","img":"","opts":["At most 24 hours","At most 2 hours","At most 72 hours","As long as you like"],"a":0,"ex":"Even where parking is allowed, a vehicle may not stay parked <strong>more than 24 hours in a row</strong> on weekdays (except the day before a Sunday or public holiday) on municipal streets in built-up areas and on public roads.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P49a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 49a §\">TrF 3 kap. 49a §</a>"],"signs":[]},{"id":"is-camera","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign tell you?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E24-1\" alt=\"E24 Automatic traffic surveillance\" width=\"64\" height=\"64\"></div>","opts":["That a camera may check your speed or other rules ahead","That filming is forbidden","That a speed camera stands exactly at the sign","That a tourist viewpoint is ahead"],"a":0,"ex":"<strong>E24 (automatic traffic surveillance)</strong> tells you a camera may check speed or other rules – or register you for taxes or fees. It normally stands 40–300 m before the camera.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 6 kap. 30 §\">TSFS 2019:74 6 kap. 30 §</a>"],"signs":["E24"]},{"id":"is-motorway-rules","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"Which of these is forbidden on a road with this sign?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E-11\" alt=\"E1 Motorway\" width=\"64\" height=\"64\"></div>","opts":["Reversing","Driving at 100 km/h","Overtaking on the left","Driving a motorcycle"],"a":0,"ex":"On a <strong>motorway</strong> you may not turn around, <strong>reverse</strong>, stop or park (except at signed parking places and rest areas). Only motor vehicles built for and allowed at least 40 km/h may use it.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K9P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 9 kap. 1 §\">TrF 9 kap. 1 §</a>"],"signs":["E1"]},{"id":"ds-green","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"A direction sign has a <strong>green</strong> background. Where does it lead?","img":"","opts":["Along or to a motorway or expressway","To a park","To a temporary diversion","To a private road"],"a":0,"ex":"Green direction signs lead along or to a <strong>motorway or expressway</strong>. Blue ones lead to public roads, white ones to local destinations.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 14 §\">VMF 2 kap. 14 §</a>"],"signs":[]},{"id":"ds-yellow-red","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"A direction sign is <strong>yellow with a red border</strong>. What does it lead to?","img":"","opts":["A private road (<em>enskild väg</em>)","A motorway","A hospital","A temporary diversion"],"a":0,"ex":"Yellow with a red border means the sign leads along or to a <strong>private road</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 14 §\">VMF 2 kap. 14 §</a>"],"signs":[]},{"id":"ds-orange","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"What does an <strong>orange</strong> direction sign show?","img":"","opts":["A temporary diversion","A tourist attraction","A motorway","A road for heavy vehicles"],"a":0,"ex":"Orange signs with black text show a <strong>temporary diversion</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 14 §\">VMF 2 kap. 14 §</a>"],"signs":[]},{"id":"ds-brown","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"What does a <strong>brown</strong> direction sign lead to?","img":"","opts":["A destination of tourist interest","A private road","A temporary diversion","A railway station"],"a":0,"ex":"Brown signs with white text lead to destinations of <strong>tourist interest</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 14 §\">VMF 2 kap. 14 §</a>"],"signs":[]},{"id":"ds-white","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"What does a <strong>white</strong> direction sign with black text lead to?","img":"","opts":["A local destination, institution or facility","A motorway","A private road","A diversion"],"a":0,"ex":"White signs lead to <strong>local destinations</strong> in a town, or to institutions and facilities.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 14 §\">VMF 2 kap. 14 §</a>"],"signs":[]},{"id":"ds-lanes-not-overtaking","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"The lanes are assigned to different destinations with lane direction signs over the road. You drive faster in your lane than the cars in the next lane. Is that overtaking?","img":"","opts":["No","Yes – and it is only allowed on the left","Yes – and it is forbidden","Only if you change lanes"],"a":0,"ex":"Where the carriageway is divided into lanes for different destinations with lane direction signs, passing vehicles in another lane is <strong>not counted as overtaking</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P41\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 41 §\">TrF 3 kap. 41 §</a>"],"signs":[]},{"id":"ds-dashed-number","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"A road number on a direction sign has a <strong>dashed border</strong>. What does that mean?","img":"","opts":["The road leads to the road with that number","The road is temporarily closed","The road is a private road","The road has a low weight limit"],"a":0,"ex":"A <strong>dashed border</strong> around a road number means the road <strong>leads to</strong> the road with that number.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 17 §\">VMF 2 kap. 17 §</a>"],"signs":[]},{"id":"ds-f26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"What does this sign mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"F26-1\" alt=\"F26 Lane closed – traffic in the opposite lane\" width=\"64\" height=\"64\"></div>","opts":["A lane is closed and traffic is led into the lane for the opposite direction","Move over to the other lane in your direction","Two lanes become three","A motorway exit ahead"],"a":0,"ex":"<strong>F26</strong> means a lane is temporarily closed and <strong>no other lane in your direction</strong> can be used, so traffic is led into the opposite lane. F25 means you can move to another lane in your direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P17\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 17 §\">VMF 2 kap. 17 §</a>"],"signs":["F26"]},{"id":"ds-f1-distance","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"direction-signs","q":"Outside built-up areas, how far before a junction does the advance direction sign (F1) normally stand?","img":"","opts":["300–400 metres","50–100 metres","1–2 kilometres","Right at the junction"],"a":0,"ex":"F1 stands <strong>300–400 m</strong> before the junction outside built-up areas and 50–100 m before it in a built-up area – so you can choose direction and lane in time.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202019_74.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations and general advice on road signs and other devices — TSFS 2019:74 8 kap. 5 §\">TSFS 2019:74 8 kap. 5 §</a>"],"signs":[],"noExam":1},{"id":"ap-saturday","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"A no-parking sign has the panel <strong>8–17 (8–14)</strong> and <strong>8–13</strong> in red. Is parking banned on a normal <strong>Saturday at 15:00</strong>?","img":"","opts":["No – on Saturdays the ban ends at 14:00","Yes – until 17:00","Yes – all day","Yes – until 13:00"],"a":0,"ex":"Numbers <strong>in brackets</strong> apply on a weekday before a Sunday or public holiday – usually Saturday – so the ban is 08:00–14:00. At 15:00 you may park.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ap-sunday-no-red","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"A no-parking sign has the panel <strong>8–18 (8–15)</strong> – no red numbers. Is parking banned on a <strong>Sunday at 12:00</strong>?","img":"","opts":["No – without red numbers the ban does not apply on Sundays and holidays","Yes – 08:00–18:00","Yes – 08:00–15:00","Yes – all day"],"a":0,"ex":"<strong>Red numbers</strong> are for Sundays and public holidays. If there are none, the rule does <strong>not</strong> apply on those days.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ap-red-numbers","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"On a time panel, what do the <strong>red</strong> numbers mean?","img":"","opts":["Sundays and public holidays","Saturdays","Night time","The time when parking costs money"],"a":0,"ex":"On a time panel: numbers <strong>without brackets</strong> = normal weekdays; numbers <strong>in brackets</strong> = a weekday before a Sunday or public holiday; <strong>red numbers</strong> = Sundays and public holidays.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ap-midnight","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"A no-parking sign has the panel <strong>20–06</strong> (black, no brackets). Is parking banned on a <strong>Tuesday at 03:00</strong>?","img":"","opts":["Yes – the period after midnight belongs to the following day","No – the ban only applies 20:00–24:00","No – night times are never banned","Only on Saturdays"],"a":0,"ex":"If the time on a panel runs past midnight, the period after midnight applies on the <strong>following day</strong>. Monday 20:00 to Tuesday 06:00 is banned.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ap-arrow-down","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"A no-parking sign has this panel with an arrow pointing down. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T11-3\" alt=\"T11 Extent\" width=\"64\" height=\"64\"></div>","opts":["The ban ends here","The ban starts here","The ban applies below the sign only","Park with the front down the slope"],"a":0,"ex":"On the extent panel (<strong>T11</strong>), an arrow pointing <strong>down</strong> means the rule <strong>ends here</strong>. Arrows in both directions mean the rule applies on both sides of the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T11"]},{"id":"ap-symbol","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"Under a no-parking sign there is a panel with a <strong>truck</strong> symbol. Who may not park?","img":"","opts":["Only trucks","Everyone except trucks","Everyone","Only cars"],"a":0,"ex":"A panel with a vehicle symbol (<strong>T8</strong>) means the sign applies <strong>only</strong> to that vehicle type.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ap-disc","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"You park at <strong>10:10</strong> where a parking disc is required. What time do you set on the disc?","img":"","opts":["10:30","10:00","10:10","11:00"],"a":0,"ex":"The disc is set to the <strong>next half hour</strong> after you parked – 10:30.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P49a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 49a §\">TrF 3 kap. 49a §</a>"],"signs":[]},{"id":"ap-disc-before","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"You park at <strong>07:40</strong>. A 2-hour limit with a parking disc applies from <strong>08:00</strong>, and you will stay until 09:30. What time do you set on the disc?","img":"","opts":["08:00","07:40","08:30","You do not need a disc"],"a":0,"ex":"If you park <strong>before</strong> a time limit starts and stay after it starts, set the disc to the time the limit <strong>begins</strong> – here 08:00.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P49a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 49a §\">TrF 3 kap. 49a §</a>"],"signs":[]},{"id":"ap-charging","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"This panel is under a parking sign. Who may park there?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T24-1\" alt=\"T24 Charging place\" width=\"64\" height=\"64\"></div>","opts":["Only vehicles that can be charged externally for their propulsion","All electric and hybrid cars, including hybrids that cannot be plugged in","Everyone, for at most 2 hours","Only taxis"],"a":0,"ex":"At a <strong>charging place</strong> only vehicles that can be <strong>charged externally</strong> for their propulsion may be parked. Others – including ordinary hybrids that cannot be plugged in – may only stop to let people in or out.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P54\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 54 §\">TrF 3 kap. 54 §</a>"],"signs":["T24"]},{"id":"ap-combined-panel","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"Under a P sign there is <strong>one</strong> panel with a parking-disc symbol, <strong>“2 tim”</strong> and <strong>“8–18 (8–15)”</strong>. You park on a Saturday at 16:00. What applies?","img":"","opts":["No time limit and no disc – the conditions apply only 08:00–15:00 on Saturdays","At most 2 hours with a disc","Parking is forbidden","At most 2 hours without a disc"],"a":0,"ex":"Instructions on the <strong>same panel</strong> apply together. On a Saturday the conditions apply 08:00–15:00, so at 16:00 neither the time limit nor the disc applies.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 2 §\">VMF 2 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"ap-t5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"A panel under a sign shows <strong>3.5 t</strong> with the “total weight” wording (T5). Which vehicles does the sign apply to?","img":"","opts":["Vehicles whose registered total weight is above 3.5 tonnes","Vehicles that weigh more than 3.5 tonnes right now","All vehicles with a trailer","All vehicles lighter than 3.5 tonnes"],"a":0,"ex":"Panel <strong>T5</strong> refers to the <strong>total weight</strong> – the highest weight the vehicle is registered for – not what it weighs at the moment.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":[]},{"id":"rm-warning-line","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A line along the middle of the road has <strong>long dashes and short gaps</strong>. What is it?","img":"","opts":["A warning line – crossing is allowed but unsuitable","A centre line – crossing is fine","A solid line – crossing is forbidden","An edge line"],"a":0,"ex":"The <strong>warning line</strong> (M3, line 3 : gap 1) separates opposite directions where it is unsuitable to cross, and can warn that a solid line is coming.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P4\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 4 §\">VMF 4 kap. 4 §</a>"],"signs":[]},{"id":"rm-centre-line","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A line in the middle of the road has <strong>short dashes and long gaps</strong>. What is it?","img":"","opts":["A centre line","A warning line","A solid line","A cycle lane line"],"a":0,"ex":"Short lines with long gaps (1 : 3 or 1 : 1) are a <strong>centre line</strong> (between opposite directions) or a <strong>lane line</strong> (between lanes in the same direction).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P4\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 4 §\">VMF 4 kap. 4 §</a>"],"signs":[]},{"id":"rm-solid-wheel","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"How much of your vehicle may cross a solid centre line when nothing special applies?","img":"","opts":["Not even one wheel","One wheel","Half the vehicle","The whole vehicle if no one is coming"],"a":0,"ex":"A vehicle may not be driven <strong>with any wheel</strong> on a restricted area or over a solid line – unless one of the exceptions applies, and then only with special care.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P11\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 11 §\">TrF 3 kap. 11 §</a>"],"signs":[]},{"id":"rm-solid-exception","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"In which situation may you cross a solid line, with special care?","img":"","opts":["To get past an obstacle on the road","To overtake a slow car","To overtake a tractor going at 30 km/h","To turn around because you missed your exit"],"a":0,"ex":"Exceptions: to <strong>pass an obstacle on the road</strong>, when a junction is otherwise too narrow for the vehicle, to drive to or from a <strong>property</strong>, or where a <strong>broken line</strong> runs immediately to the right of the solid line in your direction. Overtaking is not an exception.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P11\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 11 §\">TrF 3 kap. 11 §</a>"],"signs":[]},{"id":"rm-combined-broken","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A double line in the middle of the road is <strong>broken on your side and solid on the other side</strong>. May you cross it?","img":"","opts":["Yes, with care – the line nearest you decides","No – the solid line forbids it","Only in daylight","Only to turn left"],"a":0,"ex":"With combined lines, <strong>the line nearest to you decides</strong>. A broken line on your side means you may cross – with care.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 7 §\">VMF 4 kap. 7 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P11\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 11 §\">TrF 3 kap. 11 §</a>"],"signs":[]},{"id":"rm-combined-solid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A double line is <strong>solid on your side and broken on the other side</strong>. May you cross it to overtake?","img":"","opts":["No","Yes, if it is safe","Yes, at most 70 km/h","Yes, for motorcycles"],"a":0,"ex":"The line nearest you decides. A <strong>solid</strong> line on your side means you may <strong>not</strong> cross it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P7\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 7 §\">VMF 4 kap. 7 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P11\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 11 §\">TrF 3 kap. 11 §</a>"],"signs":[]},{"id":"rm-shoulder-solid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A faster car wants to overtake you. The <strong>edge line is solid</strong>. May you move out onto the shoulder for a moment?","img":"","opts":["No – not over a solid edge line","Yes, to make it easier for the faster car","Yes, if you indicate","Yes, outside built-up areas"],"a":0,"ex":"Ordinary vehicles may use the shoulder temporarily to let others pass – but <strong>not</strong> when the carriageway is bordered by a <strong>solid</strong> edge line.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 12 §\">TrF 3 kap. 12 §</a>"],"signs":[]},{"id":"rm-shoulder-broken","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"The edge line is <strong>broken</strong>. A faster car comes up behind you. What may you do?","img":"","opts":["Move onto the shoulder for a moment to let it pass, if the shoulder is suitable","Nothing – the shoulder is only for cyclists","Speed up to the speed limit","Stop on the carriageway"],"a":0,"ex":"If needed to make it easier for other traffic, the shoulder may be used <strong>temporarily</strong> by other vehicles too – when the edge line is not solid.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 12 §\">TrF 3 kap. 12 §</a>"],"signs":[]},{"id":"rm-back-from-shoulder","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"You drive back onto the carriageway from the shoulder. Who gives way?","img":"","opts":["You – to vehicles on the carriageway","Vehicles on the carriageway – to you","Whoever is faster","Nobody"],"a":0,"ex":"A driver who comes onto the carriageway from the shoulder must <strong>give way</strong> to the vehicles there.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 21 §\">TrF 3 kap. 21 §</a>"],"signs":[]},{"id":"rm-yellow-temp","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"At road works there are <strong>yellow</strong> lines as well as the normal white lines. Which do you follow?","img":"","opts":["The yellow lines","The white lines","Whichever is nearer the middle","Neither – follow the car in front"],"a":0,"ex":"Temporary yellow lines at road works apply <strong>instead of</strong> the ordinary white markings.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P3\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 3 §\">VMF 4 kap. 3 §</a>"],"signs":[]},{"id":"rm-yellow-solid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A <strong>solid yellow line</strong> is painted along the kerb. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M21-1\" alt=\"M21 No stopping or parking (yellow line)\" width=\"64\" height=\"64\"></div>","opts":["No stopping or parking","No parking, but stopping is allowed","Parking for disabled people","Bus lane"],"a":0,"ex":"<strong>M21</strong>, a solid yellow line at the edge of the carriageway, means <strong>no stopping or parking</strong>. A broken yellow line (M22) means no parking.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 9 §\">VMF 4 kap. 9 §</a>"],"signs":["M21"]},{"id":"rm-yellow-broken","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"A <strong>broken yellow line</strong> is painted along the kerb. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M22-1\" alt=\"M22 No parking (yellow broken line)\" width=\"64\" height=\"64\"></div>","opts":["No parking – stopping is allowed","No stopping or parking","Parking allowed for 2 hours","Cycle lane"],"a":0,"ex":"<strong>M22</strong>, a broken yellow line, means <strong>no parking</strong>. It can also show the extent of a bus stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 9 §\">VMF 4 kap. 9 §</a>"],"signs":["M22"]},{"id":"rm-arrows-solid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"Your lane is separated from the next by a <strong>solid</strong> lane line and has a left-turn arrow painted in it. What applies?","img":"","opts":["You must turn left","The arrow is only advice","You may go straight on if no one is coming","You may turn right"],"a":0,"ex":"If the lane is bordered by a <strong>solid</strong> lane line, drivers <strong>must follow</strong> the direction(s) the arrow shows. Between broken lane lines the arrows are advice.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 9 §\">VMF 4 kap. 9 §</a>"],"signs":[]},{"id":"rm-stop-solid-3m","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"You want to stop next to a <strong>solid line between lanes</strong>. What is required?","img":"","opts":["At least 3 metres between your vehicle and the line, unless a broken line runs between you and it","At least 1 metre","Your hazard lights must be on","Nothing special"],"a":0,"ex":"You may not stop or park along a solid lane line if there is <strong>less than 3 metres</strong> between your vehicle and the line – unless a broken line runs between them. Otherwise others would have to cross the solid line to pass.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P53\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 53 §\">TrF 3 kap. 53 §</a>"],"signs":[]},{"id":"rm-cycle-box","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"At a junction there is a marked box like this in front of the stop line for cars. What do you do as a driver?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M17A-CYKELBOX\" alt=\"M17a Cycle box\" width=\"64\" height=\"64\"></div>","opts":["Stop at your own stop line and leave the box free","Stop in the box","Use the box when you turn right","Park in the box at night"],"a":0,"ex":"<strong>M17a (cycle box)</strong> shows a suitable place for cyclists and class II moped riders to wait. Drivers stop at their stop line and leave the box free.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 8 §\">VMF 4 kap. 8 §</a>"],"signs":["M17a"]},{"id":"rm-parking-bays","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"Parking spaces are marked on the road. How must you park?","img":"","opts":["With no wheel outside the marked space","With at least two wheels inside","As close to the kerb as possible, ignoring the lines","Diagonally across two spaces"],"a":0,"ex":"Where parking spaces are marked (M24), the vehicle must be parked <strong>inside</strong> the marking – no wheel outside.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P49\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 49 §\">TrF 3 kap. 49 §</a>"],"signs":[]},{"id":"sig-yellow","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"The light changes from green to this when you are far enough away to stop safely. What must you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG4-1\" alt=\"SIG4 Yellow light\" width=\"64\" height=\"64\"></div>","opts":["Stop","Speed up to get through","Drive on carefully","Stop only if a car is coming"],"a":0,"ex":"Yellow means <strong>stop</strong> – you may only continue if you were so close when it changed that you <strong>cannot stop without danger</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 6 §\">VMF 3 kap. 6 §</a>"],"signs":["SIG4"]},{"id":"sig-red-yellow","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does red and yellow together mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG2-1\" alt=\"SIG2 Red and yellow light\" width=\"64\" height=\"64\"></div>","opts":["Green is coming immediately – but you may not start yet","You may start if the junction is empty","The signal is out of order","Stop if you can, otherwise drive on"],"a":0,"ex":"Red + yellow means green is coming <strong>immediately</strong>. Otherwise it means the same as red – you may <strong>not</strong> start yet.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 6 §\">VMF 3 kap. 6 §</a>"],"signs":["SIG2"]},{"id":"sig-order","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"In which order do the lights of an ordinary Swedish traffic light change?","img":"","opts":["Red → red + yellow → green → yellow → red","Red → green → yellow → red","Red → yellow → green → red","Green → red + yellow → red"],"a":0,"ex":"The order is <strong>red → red + yellow → green → yellow → red</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 5 §\">VMF 3 kap. 5 §</a>"],"signs":[]},{"id":"sig-green-arrow","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"The main light shows <strong>red</strong>, and a <strong>green arrow to the left</strong> is lit next to it. What may you do?","img":"","opts":["Turn left – the green arrow applies to its direction","Nothing – red applies to everything","Go straight on","Turn right"],"a":0,"ex":"A <strong>green arrow</strong> means you may drive in the arrow’s direction <strong>even if another light is shown at the same time</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 6 §\">VMF 3 kap. 6 §</a>"],"signs":[]},{"id":"sig-green-turn","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"You have green and turn right. Pedestrians are crossing the road you turn into on their green light. What do you do?","img":"","opts":["Drive slowly and give way to the pedestrians","Drive on – you have green too","Sound the horn so they hurry","Stop in the middle of the junction until all lights change"],"a":0,"ex":"After turning at a junction you must drive slowly and <strong>give way to pedestrians</strong> who are crossing correctly – even when you have green.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P60\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 60 §\">TrF 3 kap. 60 §</a>"],"signs":[]},{"id":"sig-block-junction","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"You have green, but the traffic beyond the junction is standing still. What should you do?","img":"","opts":["Wait – do not drive in if you risk having to stop in the junction","Drive in and wait in the junction","Drive in and use the hazard lights","Turn instead"],"a":0,"ex":"You must not drive into a junction in a way that makes you stop there and block the crossing traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 20 §\">TrF 3 kap. 20 §</a>"],"signs":[]},{"id":"sig-flashing-yellow","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"The traffic light only flashes yellow. What does that mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG5-1\" alt=\"SIG5 Flashing yellow light\" width=\"64\" height=\"64\"></div>","opts":["The signal is not working – take special care and follow the signs and general rules","Stop and wait for green","You have priority","The light will turn green within 10 seconds"],"a":0,"ex":"Flashing yellow is shown when the signal is out of order or temporarily not working. It means <strong>take special care</strong> – the signs and the general rules apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 5 §\">VMF 3 kap. 5 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 6 §\">VMF 3 kap. 6 §</a>"],"signs":["SIG5"]},{"id":"sig-pedestrian-flash","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"The green pedestrian light <strong>flashes</strong>. What should drivers expect?","img":"","opts":["That pedestrians may still be on the crossing after their light turns red","That pedestrians must run","That drivers get green at once","That the crossing closes"],"a":0,"ex":"A flashing green person means red is coming soon. A pedestrian still on the road when it turns red should <strong>continue</strong> to the other side – so expect people on the crossing.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 8 §\">VMF 3 kap. 8 §</a>"],"signs":[]},{"id":"sig-lane-cross","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"This signal is lit over your lane on a motorway. What must you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG12-1\" alt=\"SIG12 Lane signal – red cross\" width=\"64\" height=\"64\"></div>","opts":["Leave the lane – it and the shoulder beside it may not be used","Slow down to 70 km/h","Stop in the lane","Continue – it is only a warning"],"a":0,"ex":"A <strong>red cross</strong> over a lane means the lane – and the shoulder beside it – may <strong>not</strong> be used.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 15 §\">VMF 3 kap. 15 §</a>"],"signs":["SIG12"]},{"id":"sig-lane-yellow","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"This yellow arrow is lit over your lane. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG13-1\" alt=\"SIG13 Lane signal – yellow arrow\" width=\"64\" height=\"64\"></div>","opts":["Change lane in the direction of the arrow","Exit the motorway","The lane ends in 1 km","Overtaking is allowed"],"a":0,"ex":"A <strong>yellow arrow</strong> lane signal means <strong>change lane</strong> in the direction of the arrow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 15 §\">VMF 3 kap. 15 §</a>"],"signs":["SIG13"]},{"id":"sig-two-red","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"Two red lights flash in turn outside a fire station. What do you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG16-1\" alt=\"SIG16 Flashing red lights (bridge, fire station, tunnel …)\" width=\"64\" height=\"64\"></div>","opts":["Stop at the stop line or before the signal","Slow down and drive on carefully","Drive on – it is only for fire engines","Sound the horn"],"a":0,"ex":"Two red lights flashing in turn mean <strong>stop</strong> – at the stop line or before the signal. They are used at fire and ambulance stations, opening bridges, airfields, tunnels and similar places.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P19\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 19 §\">VMF 3 kap. 19 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P20\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 20 §\">VMF 3 kap. 20 §</a>"],"signs":["SIG16"]},{"id":"sig-steady-red","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A single <strong>steady red light</strong> is shown on the road ahead. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG17-1\" alt=\"SIG17 Steady red light (road closed)\" width=\"64\" height=\"64\"></div>","opts":["The road is completely closed","Stop, then drive on carefully","A bus is leaving","The road is partly closed"],"a":0,"ex":"A steady red light means the road is <strong>completely closed</strong>. A flashing yellow light means partly closed (or draws attention to a sign or device).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P21\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 21 §\">VMF 3 kap. 21 §</a>"],"signs":["SIG17"]},{"id":"sig-bus-signal","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"Next to the ordinary traffic light there is a signal with <strong>white symbols</strong> (S, bars). You drive a car in an ordinary lane. Who is that signal for?","img":"","opts":["Buses and trams in scheduled services, and those using the bus lane – not you","All vehicles","Only taxis","Cyclists"],"a":0,"ex":"Signals with white symbols apply to <strong>vehicles in scheduled services and trams</strong>, and to everyone using a bus lane where they stand. In an ordinary lane, follow your own traffic light.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P9\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 9 §\">VMF 3 kap. 9 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 10 §\">VMF 3 kap. 10 §</a>"],"signs":[]},{"id":"sig-cycle-signal","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A traffic light has a white bicycle on blue above the red light. For a cyclist, which signal applies?","img":"","opts":["The cycle signal, before the vehicle signal","The vehicle signal","Whichever shows green","Neither – cyclists follow pedestrian signals"],"a":0,"ex":"For cyclists and class II moped riders, the <strong>cycle signal</strong> applies before the vehicle signal.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 2 §\">VMF 3 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P3\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 3 §\">VMF 3 kap. 3 §</a>"],"signs":[]},{"id":"pol-p1-side","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A police officer stands in the junction with the arms stretched out. You see the officer’s <strong>side</strong>. What do you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P1-1\" alt=\"P1 Police – stop (arm stretched out)\" width=\"64\" height=\"64\"></div>","opts":["Drive on","Stop","Turn right","Reverse"],"a":0,"ex":"<strong>P1</strong>: traffic coming from the <strong>front or behind</strong> the officer must stop. If you see the officer’s <strong>side</strong>, the road along the outstretched arms is free – you may drive.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P1"]},{"id":"pol-p1-front","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A police officer with the arms stretched out faces <strong>towards you</strong>. What do you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P1-1\" alt=\"P1 Police – stop (arm stretched out)\" width=\"64\" height=\"64\"></div>","opts":["Stop","Drive on slowly","Turn left","Flash your lights"],"a":0,"ex":"With the arm sign <strong>P1</strong>, traffic coming from the officer’s <strong>front or back</strong> must stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P1"]},{"id":"pol-raised-hand","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A police officer raises one hand with the palm towards you. What does it mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P2-1\" alt=\"P2 Police – stop (raised hand)\" width=\"64\" height=\"64\"></div>","opts":["Stop","Drive on","Slow down","Pull over for a check"],"a":0,"ex":"<strong>P2</strong>, a raised hand, means <strong>stop</strong> for the road user the palm faces.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P2"]},{"id":"pol-p11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A police car behind you shows <strong>blue and red lights flashing in turn</strong>. What must you do?","img":"","opts":["Pull over to the side and stop","Speed up and let it pass","Follow it","Nothing – it is on its way somewhere else"],"a":0,"ex":"Blue and red lights flashing in turn from a police vehicle behind you (<strong>P11</strong>) mean the vehicle <strong>in front</strong> must <strong>pull over to the side and stop</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":[]},{"id":"pol-p10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"The police car in front of you shows this sign. What must you do?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P10-1\" alt=\"P10 Police vehicle – follow and stop behind it\" width=\"64\" height=\"64\"></div>","opts":["Follow it and stop when it stops","Overtake it","Keep a 100 m distance","Turn off at the next exit"],"a":0,"ex":"<strong>P10</strong> means the vehicle <strong>behind</strong> the police car must <strong>follow it</strong> and stop when it stops.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P10"]},{"id":"pol-check","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"A police officer signals you to stop for a check. What does the law say?","img":"","opts":["The driver of a motor vehicle must stop","You may continue if you are in a hurry","You only stop if you have done something wrong","You may drive on and call the police later"],"a":0,"ex":"The driver of a motor vehicle <strong>must stop</strong> when a police officer – or another person authorised to check traffic – signals to stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 1 §\">TrF 4 kap. 1 §</a>"],"signs":[]},{"id":"pol-guard","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"At road works a guard holds up a sign saying <strong>STOPP VAKT</strong>. What do you do?","img":"","opts":["Stop","Drive on slowly","Overtake on the shoulder","Flash your lights"],"a":0,"ex":"A guard at road works can direct traffic, and you must follow the guard’s signs. <strong>STOPP VAKT</strong> means stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 2 §\">VMF 5 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K2P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 2 kap. 2 §\">TrF 2 kap. 2 §</a>"],"signs":[]},{"id":"mk-x3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"How do you pass this side obstacle marker?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X3-1\" alt=\"X3 Side obstacle marker\" width=\"64\" height=\"64\"></div>","opts":["On the side the yellow fields slope down towards","On the side the yellow fields slope up towards","On either side","You must stop before it"],"a":0,"ex":"<strong>X3</strong>: pass on the side the yellow fields <strong>slope down towards</strong>. With horizontal fields (a temporary version) you may pass on both sides.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X3"]},{"id":"mk-x1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What do these yellow arrows on a blue board tell you?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X1\" alt=\"X1 Marker arrow\" width=\"64\" height=\"64\"></div>","opts":["You must turn sharply in the direction of the arrows","A motorway exit","Overtaking is allowed to the right","The road becomes one-way"],"a":0,"ex":"<strong>X1 (marker arrows)</strong> means you must turn <strong>sharply</strong> in the direction of the arrows – for example at a sharp bend.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X1"]},{"id":"mk-red-background","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"The marker boards X1–X3 sometimes have a <strong>red</strong> background instead of blue. Why?","img":"","opts":["They are used at road works or for another temporary reason","They warn of a railway crossing","They mark a motorway","They are old and faded"],"a":0,"ex":"When X1, X2 or X3 are used at <strong>road works</strong> or for another <strong>temporary</strong> reason, the background is red instead of blue.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":[]},{"id":"st-theory-scored","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"The theory test has 70 questions. How many of them count towards your result?","img":"","opts":["65","70","60","52"],"a":0,"ex":"Five of the 70 questions are <strong>trial questions</strong> that do not count, so the most you can score is <strong>65 points</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>"],"signs":[],"noExam":1},{"id":"st-theory-pass","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"How many points do you need to pass the theory test?","img":"","opts":["At least 52 of 65","At least 45 of 65","At least 60 of 70","All 65"],"a":0,"ex":"The pass mark is <strong>52 points or more</strong> out of the 65 scored questions.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>"],"signs":[],"noExam":1},{"id":"st-theory-time","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"How long do you have for the theory test (without an interpreter)?","img":"","opts":["50 minutes","30 minutes","70 minutes","100 minutes"],"a":0,"ex":"The test time is <strong>50 minutes</strong>. With an interpreter it is 100 minutes.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/teoriprovet-pa-annat-sprak/\" target=\"_blank\" rel=\"noopener\" title=\"The theory test in other languages\">Trafikverket – språk</a>"],"signs":[],"noExam":1},{"id":"st-theory-valid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"You pass the theory test on 1 October 2026. Until when is the pass valid?","img":"","opts":["One year – until 1 October 2027","Four months","Two years","Until your learner’s permit expires"],"a":0,"ex":"A theory test passed on or after <strong>19 August 2026</strong> is valid for <strong>one year</strong> from the day of the test. You must pass the driving test within that time.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202026_47.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Amendment making a passed theory test valid for one year (in force 19 August 2026) — TSFS 2026:47 5 kap. 1 §\">TSFS 2026:47 5 kap. 1 §</a>"],"signs":[],"noExam":1},{"id":"st-theory-id","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"Which of these can you <strong>not</strong> use as ID at the theory test?","img":"","opts":["The digital BankID card on your phone","A Swedish passport","A Swedish national ID card","A Swedish driving licence"],"a":0,"ex":"You must show a valid <strong>physical</strong> ID document. Digital IDs such as Freja eID and the digital BankID card are not accepted.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/fore-provet/\" target=\"_blank\" rel=\"noopener\" title=\"Before the test (photo and ID)\">Trafikverket – före provet</a>"],"signs":[],"noExam":1},{"id":"st-theory-cheat","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"What can happen if you cheat at the theory test?","img":"","opts":["You are reported to the police and banned from tests for one or two years","You only have to retake the test the same day","You lose one point","Nothing, if it is the first time"],"a":0,"ex":"Cheating means a police report for a false declaration, a <strong>ban from tests for one or two years</strong>, the test is cancelled and any other booked test is cancelled.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/\" target=\"_blank\" rel=\"noopener\" title=\"Getting a licence (tips and cheating rules)\">Trafikverket – ta körkort</a>"],"signs":[],"noExam":1},{"id":"st-theory-risk-first","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"theory-test","q":"What must be done and valid before you may take the theory test for a car or motorcycle?","img":"","opts":["Both parts of the risk education","Only part 1 of the risk education","The driving test","A first-aid course"],"a":0,"ex":"Trafikverket checks that <strong>both parts</strong> of the risk education are done and valid when you arrive for the theory test.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P4b\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 4b §\">KKL 3 kap. 4b §</a>"],"signs":[],"noExam":1},{"id":"st-permit-what","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"learner-permit","q":"What is a learner’s permit (<em>körkortstillstånd</em>)?","img":"","opts":["A decision that you meet the medical and personal requirements for a licence","A licence that lets you drive alone for one year","A certificate that you have passed the theory test","A permit for your supervisor to teach you"],"a":0,"ex":"The law defines the learner’s permit as a decision that the applicant meets the <strong>medical and personal requirements</strong> for a licence. You need it to practise and to take the tests – it does not let you drive alone.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K1P1\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 1 kap. 1 §\">KKL 1 kap. 1 §</a>"],"signs":[]},{"id":"st-permit-valid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"learner-permit","q":"How long is a learner’s permit valid?","img":"","opts":["Five years, and it cannot be extended","Two years, and it can be extended","Until you are 25","One year"],"a":0,"ex":"The permit is valid for <strong>five years</strong> and <strong>cannot be extended</strong>. After that you must apply for a new one.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/korkortstillstand/\" target=\"_blank\" rel=\"noopener\" title=\"Learner's permit\">Transportstyrelsen – körkortstillstånd</a>"],"signs":[]},{"id":"st-permit-vision","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"learner-permit","q":"What visual acuity do you need for a car or motorcycle licence?","img":"","opts":["At least 0.5 with both eyes together – glasses or lenses allowed","At least 1.0 in each eye without glasses","At least 0.2 in the better eye","There is no requirement"],"a":0,"ex":"You need a visual acuity of at least <strong>0.5</strong> when you look with both eyes together. Glasses or contact lenses are allowed.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/medicinska-krav/\" target=\"_blank\" rel=\"noopener\" title=\"Medical requirements (including eyesight)\">Transportstyrelsen – medicinska krav</a>"],"signs":[]},{"id":"st-permit-age","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"learner-permit","q":"From what age can you apply for a learner’s permit?","img":"","opts":["There is no minimum age for applying","15","16","18"],"a":0,"ex":"There is <strong>no minimum age</strong> for applying. The age limits apply to <strong>practising</strong> and to <strong>getting the licence</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/korkortstillstand/\" target=\"_blank\" rel=\"noopener\" title=\"Learner's permit\">Transportstyrelsen – körkortstillstånd</a>"],"signs":[],"noExam":1},{"id":"st-permit-group","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"learner-permit","q":"You got a learner’s permit for a car (B). Can you use the same permit for the motorcycle licence (A)?","img":"","opts":["Yes, while it is valid – both are in group 1","No, every category needs its own permit","Only if you apply within six months","Only after you have passed the car test"],"a":0,"ex":"Learner’s permits come in groups. <strong>Group 1</strong> covers AM, A1, A2, A, B and BE (and tractors), so the same valid permit covers both.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/korkortstillstand/\" target=\"_blank\" rel=\"noopener\" title=\"Learner's permit\">Transportstyrelsen – körkortstillstånd</a>"],"signs":[],"noExam":1},{"id":"st-permit-personal","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"learner-permit","q":"What does being “suitable with regard to personal circumstances” require?","img":"","opts":["That you are not unreliable as to sobriety and can be expected to respect the traffic rules","That you own a car","That you have finished school","That you have a job"],"a":0,"ex":"The law requires that the applicant is <strong>not unreliable in matters of sobriety</strong> and can be expected to <strong>respect the traffic rules</strong> and show consideration, judgement and responsibility in traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P2\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 2 §\">KKL 3 kap. 2 §</a>"],"signs":[]},{"id":"st-practice-age-car","area":"rules","paths":["car-manual","car-automatic"],"lesson":"practice-driving","q":"From what age may you practise driving a passenger car (without a trailer)?","img":"","opts":["16","15","17","18"],"a":0,"ex":"You may practise driving a passenger car from <strong>16</strong>. With a light trailer, or in a light truck, the age is <strong>17 years and 6 months</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K4P2\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 4 kap. 2 §\">KKL 4 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/ovningskora/\" target=\"_blank\" rel=\"noopener\" title=\"Practice driving\">Transportstyrelsen – övningsköra</a>"],"signs":[]},{"id":"st-practice-age-trailer","area":"rules","paths":["car-manual","car-automatic"],"lesson":"practice-driving","q":"From what age may you practise driving a car with a light trailer?","img":"","opts":["17 years and 6 months","16 years","18 years","17 years"],"a":0,"ex":"Practice with a <strong>light trailer</strong> – or in a light truck – is allowed from <strong>17 years and 6 months</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K4P2\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 4 kap. 2 §\">KKL 4 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/ovningskora/\" target=\"_blank\" rel=\"noopener\" title=\"Practice driving\">Transportstyrelsen – övningsköra</a>"],"signs":[]},{"id":"st-practice-age-mc","area":"rules","paths":["motorcycle"],"lesson":"practice-driving","q":"You are 21 and have no A2 licence. Can you practise privately on a heavy motorcycle (category A)?","img":"","opts":["No – without A2 you must be 23","Yes, from 18","Yes, from 21","Yes, if your supervisor is over 30"],"a":0,"ex":"Without A2, practice for category A starts at <strong>23</strong>. With A2 for at least 1 year and 6 months it is <strong>19 years and 6 months</strong>, and only at a driving school (with the instructor on the motorcycle or in a sidecar) from <strong>17 years and 6 months</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K4P2\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 4 kap. 2 §\">KKL 4 kap. 2 §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K4P3\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 4 kap. 3 §\">KKL 4 kap. 3 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/valj-behorighet/motorcykel/a-tung-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Category A: heavy motorcycle\">Transportstyrelsen – A</a>"],"signs":[]},{"id":"st-supervisor-req","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"Which requirements must a private supervisor (<em>handledare</em>) meet?","img":"","opts":["At least 24 years old and a licence for the vehicle type for at least 5 of the last 10 years","At least 18 years old and a licence for at least 1 year","At least 21 years old and an instructor’s training","At least 30 years old and no traffic fines ever"],"a":0,"ex":"A supervisor must be at least <strong>24</strong> and have held a licence for the vehicle type for a total of at least <strong>five of the last ten years</strong>. They must also be approved by Transportstyrelsen for each learner.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K4P7\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 4 kap. 7 §\">KKL 4 kap. 7 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/handledare/\" target=\"_blank\" rel=\"noopener\" title=\"Supervisor for private practice\">Transportstyrelsen – handledare</a>"],"signs":[]},{"id":"st-supervisor-driver","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"During private practice, who counts as the driver of the car?","img":"","opts":["The supervisor","The learner","Both equally","The owner of the car"],"a":0,"ex":"The <strong>supervisor counts as the driver</strong> and is responsible for the drive.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/handledare/\" target=\"_blank\" rel=\"noopener\" title=\"Supervisor for private practice\">Transportstyrelsen – handledare</a>"],"signs":[]},{"id":"st-supervisor-max","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"How many learners can one supervisor have approval for at the same time?","img":"","opts":["Five","One","Three","Ten"],"a":0,"ex":"A supervisor can have at most <strong>five learners</strong> at the same time.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/handledare/\" target=\"_blank\" rel=\"noopener\" title=\"Supervisor for private practice\">Transportstyrelsen – handledare</a>"],"signs":[],"noExam":1},{"id":"st-supervisor-valid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"How long is a supervisor approval valid?","img":"","opts":["Five years – but it ends at once if the supervisor’s licence is revoked","One year","Until the learner passes","Ten years"],"a":0,"ex":"The approval is valid for <strong>five years</strong>, and it ends <strong>at once</strong> if the supervisor’s licence is revoked.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K4P8\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 4 kap. 8 §\">KKL 4 kap. 8 §</a>"],"signs":[],"noExam":1},{"id":"st-practice-carry","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"What must the learner carry during private practice?","img":"","opts":["A valid ID document","The theory test result","The car’s registration certificate","Nothing"],"a":0,"ex":"The learner must carry an <strong>ID document</strong>. The supervisor must carry the supervisor certificate (<em>handledarbevis</em>), on paper or digitally.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P15a\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 15a §\">KKL 3 kap. 15a §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/handledare/\" target=\"_blank\" rel=\"noopener\" title=\"Supervisor for private practice\">Transportstyrelsen – handledare</a>"],"signs":[]},{"id":"st-practice-sign","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"Where must the ÖVNINGSKÖR sign be during practice?","img":"","opts":["Clearly visible from behind, without blocking the view","On the front windscreen","Inside the car on the dashboard","It is only needed on motorways"],"a":0,"ex":"The green and white <strong>ÖVNINGSKÖR</strong> sign must be <strong>clearly visible from behind</strong> and must not block the view.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/ovningskora/\" target=\"_blank\" rel=\"noopener\" title=\"Practice driving\">Transportstyrelsen – övningsköra</a>"],"signs":[]},{"id":"st-practice-intro","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"Is an introduction course (<em>introduktionsutbildning</em>) required before private practice in a car today?","img":"","opts":["No – the requirement was removed on 1 August 2026","Yes, for both learner and supervisor","Yes, but only for the learner","Only for motorcycles"],"a":0,"ex":"Since <strong>1 August 2026</strong> the introduction course is no longer required. The supervisor must still be approved, and the learner still needs a valid learner’s permit.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/pressrum/nyhetsarkiv/2026/introduktionsutbildningen-tas-bort--det-har-behover-du-ha-koll-pa/\" target=\"_blank\" rel=\"noopener\" title=\"The introduction course is removed from 1 August 2026\">Transportstyrelsen news 2026</a>"],"signs":[],"noExam":1},{"id":"st-practice-mc-supervisor","area":"rules","paths":["motorcycle"],"lesson":"practice-driving","q":"How may a supervisor follow a motorcycle learner during private practice?","img":"","opts":["As a passenger on the same motorcycle, or on their own motorcycle","In a car right behind the learner","By phone, from home","On a bicycle"],"a":0,"ex":"The supervisor must either ride as a <strong>passenger</strong> on the same motorcycle or ride <strong>their own motorcycle</strong> – not follow in a car – and can only practise with <strong>one learner at a time</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/ovningskora/\" target=\"_blank\" rel=\"noopener\" title=\"Practice driving\">Transportstyrelsen – övningsköra</a>"],"signs":[]},{"id":"st-practice-paid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"practice-driving","q":"You practise privately with a friend who is <strong>not</strong> an approved supervisor. What is this?","img":"","opts":["Unlawful driving","Allowed if the friend has had a licence for 5 years","Allowed outside built-up areas","Allowed if you do not drive faster than 50 km/h"],"a":0,"ex":"Practising with someone who is not an approved supervisor counts as <strong>unlawful driving</strong> (<em>olovlig körning</em>) – and your learner’s permit can be revoked.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P3\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 3 §\">Trafikbrottslagen 3 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/handledarskap-och-ovningskorning/handledare/\" target=\"_blank\" rel=\"noopener\" title=\"Supervisor for private practice\">Transportstyrelsen – handledare</a>"],"signs":[]},{"id":"st-risk-part1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"risk-education","q":"What is part 1 of the risk education (<em>riskettan</em>) about?","img":"","opts":["Alcohol, other drugs, tiredness and other risky behaviour","Skid training on a slippery track","Parking and reversing","First aid"],"a":0,"ex":"Part 1 is about <strong>alcohol, other drugs, tiredness and other risky behaviour</strong>. Part 2 is about speed, safety and driving in difficult conditions.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202012_40.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on risk education for category B — TSFS 2012:40 1 kap. 2 §\">TSFS 2012:40 1 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-bil/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for cars\">Transportstyrelsen – riskutbildning bil</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for motorcycles\">Transportstyrelsen – riskutbildning MC</a>"],"signs":[]},{"id":"st-risk-valid","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"risk-education","q":"How long is the risk education valid?","img":"","opts":["Until you get your licence, but at most five years","One year","For life","Two years from part 2"],"a":0,"ex":"The risk education is valid <strong>until the day you get your licence</strong>, but <strong>at most five years</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-bil/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for cars\">Transportstyrelsen – riskutbildning bil</a>"],"signs":[]},{"id":"st-risk-mc-car","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"risk-education","q":"You did the risk education for a car. Does it count for a motorcycle licence?","img":"","opts":["No – the motorcycle needs its own risk education","Yes, it counts for all categories","Only part 1 counts","Yes, if it is less than one year old"],"a":0,"ex":"The car course <strong>does not count</strong> for a motorcycle, and the motorcycle course does not count for a car.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-bil/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for cars\">Transportstyrelsen – riskutbildning bil</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for motorcycles\">Transportstyrelsen – riskutbildning MC</a>"],"signs":[]},{"id":"st-risk-part2-car","area":"rules","paths":["car-manual","car-automatic"],"lesson":"risk-education","q":"What does part 2 of the risk education for cars include?","img":"","opts":["A skid track (<em>halkbana</em>)","A manoeuvre track for motorcycles","A night drive on the motorway","A visit to a hospital"],"a":0,"ex":"For cars, part 2 includes a <strong>skid track</strong> where you feel how much longer it takes to stop on a slippery surface.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-bil/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for cars\">Transportstyrelsen – riskutbildning bil</a>"],"signs":[]},{"id":"st-risk-part2-mc","area":"rules","paths":["motorcycle"],"lesson":"risk-education","q":"What does part 2 of the motorcycle risk education include?","img":"","opts":["A manoeuvre track (<em>manöverbana</em>)","A skid track in a car","A theory test","Riding on a motorway with an instructor"],"a":0,"ex":"For motorcycles, part 2 includes a <strong>manoeuvre track</strong>. You must wear a helmet and full protective gear.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for motorcycles\">Transportstyrelsen – riskutbildning MC</a>"],"signs":[]},{"id":"st-risk-revoked","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"risk-education","q":"Your licence is revoked and you must take new tests. What about the risk education?","img":"","opts":["You must do it again","Your old one still counts","You only need part 2 again","It is not needed for new tests"],"a":0,"ex":"The risk education stops being valid on the day you get your licence. If you must take new tests after a revocation, you must also do the <strong>risk education again</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/ta-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers about getting a licence\">Transportstyrelsen – frågor och svar</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/nytt-korkort-efter-aterkallelse/\" target=\"_blank\" rel=\"noopener\" title=\"Getting a new licence after revocation (with and without probation)\">Transportstyrelsen – nytt körkort efter återkallelse</a>"],"signs":[]},{"id":"st-probation-length","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"after-the-test","q":"How long is the probation period (<em>prövotid</em>) for a new car or motorcycle licence?","img":"","opts":["Two years from the day of the test","One year from the day of the test","Three years from the day you collect the card","There is no probation"],"a":0,"ex":"A licence issued after a passed test has a probation period of <strong>two years</strong> from the day of the test (one year for AM).","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 18 §\">KKL 3 kap. 18 §</a>"],"signs":[]},{"id":"st-probation-revoked","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"after-the-test","q":"Your licence is revoked for speeding during your probation period. What must you do to get a licence again?","img":"","opts":["Get a new learner’s permit, do the risk education again and pass both tests again","Just wait for the waiting period to end","Only pass a new driving test","Only pay a fee"],"a":0,"ex":"A revocation <strong>during probation</strong> means a new <strong>learner’s permit</strong>, a new <strong>risk education</strong> and <strong>both the theory test and the driving test</strong> again – whatever the waiting period.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/nytt-korkort-efter-aterkallelse/\" target=\"_blank\" rel=\"noopener\" title=\"Getting a new licence after revocation (with and without probation)\">Transportstyrelsen – nytt körkort efter återkallelse</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K5P15\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 5 kap. 15 §\">KKL 5 kap. 15 §</a>"],"signs":[]},{"id":"st-probation-rules","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"after-the-test","q":"Which traffic rules apply to you during the probation period?","img":"","opts":["The same rules as for every other driver","A lower speed limit of 80 km/h","No passengers after 22:00","A zero alcohol limit, while other drivers have 0.5 per mille"],"a":0,"ex":"During probation the traffic rules are <strong>the same</strong> as for everyone else. What differs is the consequence if your licence is <strong>revoked</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 18 §\">KKL 3 kap. 18 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/forlorat-korkort/nytt-korkort-efter-aterkallelse/\" target=\"_blank\" rel=\"noopener\" title=\"Getting a new licence after revocation (with and without probation)\">Transportstyrelsen – nytt körkort efter återkallelse</a>"],"signs":[]},{"id":"st-probation-other-licence","area":"rules","paths":["motorcycle"],"lesson":"after-the-test","q":"You have had a B licence for three years and now pass the test for category A. How long is the probation for the new category?","img":"","opts":["None – only what is left of the older licence’s probation, which has ended","Two years","One year","Until you are 24"],"a":0,"ex":"If you already have a valid licence with a category other than AM, the new category only gets the probation time that is <strong>left</strong> on the older licence – here none.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P18\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 18 §\">KKL 3 kap. 18 §</a>"],"signs":[]},{"id":"st-carry-licence","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"after-the-test","q":"What must you carry when you drive?","img":"","opts":["Your licence – or, within two months of it being issued but not yet handed out, an ID document","Only the car’s registration certificate","Nothing, the police can check the register","Your learner’s permit"],"a":0,"ex":"The driver must carry the <strong>licence</strong>. If it has been issued but not yet handed out, an <strong>ID document</strong> is enough during the first two months.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P15\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 15 §\">KKL 3 kap. 15 §</a>"],"signs":[]},{"id":"st-renew","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"after-the-test","q":"How often must a licence with categories A and B be renewed?","img":"","opts":["Every 10 years","Every 5 years","Every 15 years","Never"],"a":0,"ex":"A licence for AM, A1, A2, A, B and BE must be renewed within <strong>10 years</strong> of being issued or last renewed.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 14 §\">KKL 3 kap. 14 §</a>"],"signs":[]},{"id":"st-collect-card","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"after-the-test","q":"What happens if you never collect your new licence card?","img":"","opts":["It is not valid if it has not been collected within one year","It is posted to you again every month","Nothing – the licence is valid anyway","You must take the driving test again after 6 months"],"a":0,"ex":"A licence that has not been collected within <strong>one year</strong> from the day it was issued is <strong>not valid</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P13\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 13 §\">KKL 3 kap. 13 §</a>"],"signs":[],"noExam":1},{"id":"st-dt-brake-car","area":"rules","paths":["car-manual","car-automatic"],"lesson":"driving-test-car","q":"From what speed is the efficient braking exercise in the car driving test done?","img":"","opts":["At least 50 km/h","At least 30 km/h","At least 70 km/h","At least 90 km/h"],"a":0,"ex":"You stop the car in the shortest possible distance from <strong>at least 50 km/h</strong>. The examiner decides the speed.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/sa-gar-korprovet-till/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: how the driving test works\">Trafikverket – körprov B</a>"],"signs":[],"noExam":1},{"id":"st-dt-own-car","area":"rules","paths":["car-manual","car-automatic"],"lesson":"driving-test-car","q":"Which car may you use for the category B driving test?","img":"","opts":["A car from Trafikverket or a driving school","Your own car","Any car that is insured","Your supervisor’s car"],"a":0,"ex":"You must use a car from <strong>Trafikverket</strong> or from a <strong>driving school</strong> – not your own car.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/sa-gar-korprovet-till/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: how the driving test works\">Trafikverket – körprov B</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/boka-betala-och-avboka-prov/priser/\" target=\"_blank\" rel=\"noopener\" title=\"Prices for tests and photos\">Trafikverket – priser</a>"],"signs":[],"noExam":1},{"id":"st-dt-parts-car","area":"rules","paths":["car-manual","car-automatic"],"lesson":"driving-test-car","q":"Which three parts does the car driving test have?","img":"","opts":["Safety check, special manoeuvres and driving in traffic","Theory questions, parking and motorway driving","Skid track, parking and a written test","Only driving in traffic"],"a":0,"ex":"The driving test has a <strong>safety check</strong>, <strong>special manoeuvres</strong> (for example parking, reversing, hill start and efficient braking) and <strong>driving in traffic</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/sa-gar-korprovet-till/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: how the driving test works\">Trafikverket – körprov B</a>"],"signs":[],"noExam":1},{"id":"st-dt-stall","area":"rules","paths":["car-manual"],"lesson":"driving-test-car","q":"You stall the engine once during the driving test, without causing danger. What happens?","img":"","opts":["It can be fine – it matters if it happens many times","You fail at once","The test is paused and restarted","You must do the efficient braking again"],"a":0,"ex":"Stalling <strong>once</strong> can be fine if it does not cause danger. If it happens many times, it shows you need more practice.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/sa-gar-korprovet-till/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: how the driving test works\">Trafikverket – körprov B</a>"],"signs":[],"noExam":1},{"id":"st-rt-brake-mc","area":"rules","paths":["motorcycle"],"lesson":"riding-test-mc","q":"From which speeds do you brake in the braking part of the motorcycle manoeuvre test?","img":"","opts":["70 km/h and 90 km/h","30 km/h and 50 km/h","50 km/h only","110 km/h"],"a":0,"ex":"The manoeuvre test ends with efficient, controlled braking to a stop from <strong>70 km/h and 90 km/h</strong>, using <strong>both</strong> brakes.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"st-rt-evasive-mc","area":"rules","paths":["motorcycle"],"lesson":"riding-test-mc","q":"At what speed is the evasive manoeuvre in the high-speed part of the motorcycle test done?","img":"","opts":["At least 50 km/h","At least 30 km/h","At least 70 km/h","At walking pace"],"a":0,"ex":"You accelerate to <strong>at least 50 km/h</strong>, make an evasive manoeuvre and ride the serpentine at the same speed.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"st-rt-lowspeed-mc","area":"rules","paths":["motorcycle"],"lesson":"riding-test-mc","q":"In the low-speed part of the motorcycle manoeuvre test, how should you mainly control the speed?","img":"","opts":["With the clutch","Only with the rear brake","Only with the throttle","With the engine off"],"a":0,"ex":"The speed should mainly be controlled <strong>with the clutch</strong>; you may support with the throttle and the brake.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"st-rt-bike-mc","area":"rules","paths":["motorcycle"],"lesson":"riding-test-mc","q":"Which motorcycle meets the requirements for a category A riding test?","img":"","opts":["55 kW, 190 kg kerb weight, 650 cm³ combustion engine, manual gearbox","35 kW, 160 kg, 500 cm³","11 kW, 125 cm³","50 kW, 170 kg, 600 cm³"],"a":0,"ex":"A category A test motorcycle needs at least <strong>50 kW</strong>, a kerb weight <strong>over 175 kg</strong>, and with a combustion engine at least <strong>595 cm³</strong> – and a manual gearbox with a clutch lever.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"st-78-meaning","area":"rules","paths":["car-manual","car-automatic"],"lesson":"code-78","q":"What does code 78 on a driving licence mean?","img":"","opts":["You may only drive vehicles with automatic transmission","You must wear glasses","You may not drive on motorways","You may only drive electric cars"],"a":0,"ex":"Code <strong>78</strong> means the licence is limited to vehicles with <strong>automatic transmission</strong>. You get it if you pass the driving test in a car with an automatic gearbox.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/korkortets-innehall-och-utformning/\" target=\"_blank\" rel=\"noopener\" title=\"What the licence card shows\">Transportstyrelsen – körkortets innehåll</a>"],"signs":[]},{"id":"st-78-electric","area":"rules","paths":["car-manual","car-automatic"],"lesson":"code-78","q":"You pass the driving test in an electric car with no clutch pedal. What does your licence say?","img":"","opts":["Code 78 – automatic only","No code – electric cars count as manual","Code 78 only for electric cars","Code 96"],"a":0,"ex":"A vehicle with an automatic gearbox <strong>without a clutch pedal</strong> counts as automatic – including most electric cars – so the licence gets <strong>code 78</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/ta-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers about getting a licence\">Transportstyrelsen – frågor och svar</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>"],"signs":[]},{"id":"st-78-remove","area":"rules","paths":["car-manual","car-automatic"],"lesson":"code-78","q":"You have code 78 (not set for medical reasons) and want to drive manual cars. What do you need?","img":"","opts":["Pass a new driving test in a manual car – no new theory test or learner’s permit","Take both the theory test and the driving test again","Apply to Transportstyrelsen – no test is needed","Wait two years after your probation"],"a":0,"ex":"You take a <strong>new driving test in a manual car</strong>. No new learner’s permit is needed (unless the condition is medical), and no new risk education or theory test.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P7a\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 7a §\">KKL 3 kap. 7a §</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P4b\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 4b §\">KKL 3 kap. 4b §</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>"],"signs":[]},{"id":"st-78-manual-drive","area":"rules","paths":["car-manual","car-automatic"],"lesson":"code-78","q":"A driver with code 78 drives a manual car. What is this?","img":"","opts":["A crime punished with a fine","Allowed if a passenger has a manual licence","Allowed in an emergency","Allowed during the probation period"],"a":0,"ex":"Driving with intentional or careless disregard of a condition on your licence is punished with a <strong>fine</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1951:649#P3\" target=\"_blank\" rel=\"noopener\" title=\"Act (1951:649) on Penalties for Certain Traffic Offences — Trafikbrottslagen 3 §\">Trafikbrottslagen 3 §</a>"],"signs":[]},{"id":"st-78-supervisor","area":"rules","paths":["car-manual","car-automatic"],"lesson":"code-78","q":"Your supervisor has code 78. Can you practise privately with them in a manual car?","img":"","opts":["No","Yes","Yes, but only outside built-up areas","Yes, if you have done the risk education"],"a":0,"ex":"If you practise in a <strong>manual</strong> car, your supervisor may <strong>not</strong> have code 78 on their own licence.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/ta-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers about getting a licence\">Transportstyrelsen – frågor och svar</a>"],"signs":[],"noExam":1},{"id":"st-b-weight","area":"rules","paths":["car-manual","car-automatic"],"lesson":"journey-car","q":"What is the highest total weight of a car you may drive with a B licence?","img":"","opts":["3,500 kg","3,000 kg","4,250 kg","2,500 kg"],"a":0,"ex":"Category B covers passenger cars and light trucks with a <strong>total weight of at most 3,500 kg</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/fordon-du-far-kora/\" target=\"_blank\" rel=\"noopener\" title=\"Vehicles you may drive with each licence category\">Transportstyrelsen – fordon du får köra</a>"],"signs":[]},{"id":"st-b-trailer-calc","area":"rules","paths":["car-manual","car-automatic"],"lesson":"journey-car","q":"Your car has a total weight of 1,900 kg. Which trailer may you tow with an ordinary B licence?","img":"","opts":["A trailer with a total weight of 1,600 kg","A trailer with a total weight of 1,700 kg","A trailer with a total weight of 2,000 kg","Any trailer, if it is empty"],"a":0,"ex":"A trailer is light if its total weight is at most 750 kg, <strong>or</strong> if car + trailer together are at most <strong>3,500 kg</strong>. 1,900 + 1,600 = 3,500 kg is allowed; 1,900 + 1,700 = 3,600 kg needs B96. What counts is the <strong>total weight</strong> in the registration certificate, not the actual load.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/fordon-du-far-kora/\" target=\"_blank\" rel=\"noopener\" title=\"Vehicles you may drive with each licence category\">Transportstyrelsen – fordon du får köra</a>"],"signs":[]},{"id":"st-b-light-trailer","area":"rules","paths":["car-manual","car-automatic"],"lesson":"journey-car","q":"Which trailer is always a light trailer, whatever car tows it?","img":"","opts":["One with a total weight of at most 750 kg","One with a total weight of at most 1,000 kg","Any trailer without brakes","Any trailer shorter than 3 metres"],"a":0,"ex":"A trailer with a <strong>total weight of at most 750 kg</strong> always counts as light.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/fordon-du-far-kora/\" target=\"_blank\" rel=\"noopener\" title=\"Vehicles you may drive with each licence category\">Transportstyrelsen – fordon du får köra</a>"],"signs":[]},{"id":"st-b-moped","area":"rules","paths":["car-manual","car-automatic"],"lesson":"journey-car","q":"Which of these may you also drive with a B licence?","img":"","opts":["A class I moped","A heavy motorcycle (A)","A bus","A truck of 5,000 kg"],"a":0,"ex":"Every licence category includes <strong>AM</strong> (class I mopeds), and any licence allows class II mopeds.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P7b\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 7b §\">KKL 2 kap. 7b §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/fordon-du-far-kora/\" target=\"_blank\" rel=\"noopener\" title=\"Vehicles you may drive with each licence category\">Transportstyrelsen – fordon du får köra</a>"],"signs":[]},{"id":"st-b-requirements","area":"rules","paths":["car-manual","car-automatic"],"lesson":"journey-car","q":"Which is <strong>not</strong> a requirement for getting a B licence?","img":"","opts":["Having practised with a driving school","Being at least 18","A valid risk education for cars","Living permanently in Sweden or having studied here for at least six months"],"a":0,"ex":"You need a learner’s permit, residence (or six months of studies) in Sweden, age <strong>18</strong>, a valid <strong>risk education</strong> and passed tests. A driving school is <strong>not</strong> required – you can practise privately with an approved supervisor.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/valj-behorighet/personbil-och-latt-lastbil/b-personbil-och-latt-lastbil/\" target=\"_blank\" rel=\"noopener\" title=\"Category B: passenger car and light truck\">Transportstyrelsen – B</a>"],"signs":[],"noExam":1},{"id":"st-a-age","area":"rules","paths":["motorcycle"],"lesson":"journey-mc","q":"When can you get a category A (heavy motorcycle) licence?","img":"","opts":["At 24 – or at 20 if you have held A2 for at least two years","At 18","At 21 – or at 18 with A1","At 25"],"a":0,"ex":"Category A needs you to be <strong>24</strong> (direct access), or <strong>20</strong> if you have held <strong>A2 for at least two years</strong> (step access).","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 1 §\">KKL 3 kap. 1 §</a>"],"signs":[]},{"id":"st-a2-power","area":"rules","paths":["motorcycle"],"lesson":"journey-mc","q":"What is the highest power for a motorcycle in category A2?","img":"","opts":["35 kW","11 kW","50 kW","There is no limit"],"a":0,"ex":"A2 covers motorcycles of at most <strong>35 kW</strong> and 0.2 kW per kg; a restricted motorcycle may not come from one with more than 70 kW.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/valj-behorighet/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licences (A1, A2, A)\">Transportstyrelsen – motorcykel</a>"],"signs":[]},{"id":"st-a1-limits","area":"rules","paths":["motorcycle"],"lesson":"journey-mc","q":"Which motorcycle fits category A1?","img":"","opts":["At most 125 cm³ and 11 kW","At most 250 cm³ and 25 kW","At most 50 cm³","At most 35 kW"],"a":0,"ex":"A1 (light motorcycle) covers motorcycles of at most <strong>125 cm³</strong> and <strong>11 kW</strong>, with at most 0.1 kW per kg.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 2 kap. 5 §\">KKL 2 kap. 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/valj-behorighet/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licences (A1, A2, A)\">Transportstyrelsen – motorcykel</a>"],"signs":[]},{"id":"st-a-step-theory","area":"rules","paths":["motorcycle"],"lesson":"journey-mc","q":"You have held A2 for two years and are 20. What do you need to take for category A?","img":"","opts":["Only a riding test","Both the theory test and the riding test","Only the theory test","A new risk education and both tests"],"a":0,"ex":"With step access from <strong>A2</strong> you only take a <strong>riding test</strong> – no new theory test, and no new risk education.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:488#K3P4\" target=\"_blank\" rel=\"noopener\" title=\"Driving Licence Act (1998:488) — KKL 3 kap. 4 §\">KKL 3 kap. 4 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/valj-behorighet/motorcykel/a-tung-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Category A: heavy motorcycle\">Transportstyrelsen – A</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/ta-korkort/\" target=\"_blank\" rel=\"noopener\" title=\"Questions and answers about getting a licence\">Transportstyrelsen – frågor och svar</a>"],"signs":[],"noExam":1},{"id":"st-a-covers-car","area":"rules","paths":["motorcycle"],"lesson":"journey-mc","q":"Does an A licence let you drive a passenger car?","img":"","opts":["No – that needs category B","Yes, up to 3,500 kg","Yes, automatic cars only","Yes, if the car has three wheels"],"a":0,"ex":"An A licence covers all two- and three-wheeled motorcycles, class I and II mopeds and some tractors and motor implements – but <strong>not cars</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/har-korkort/fordon-du-far-kora/\" target=\"_blank\" rel=\"noopener\" title=\"Vehicles you may drive with each licence category\">Transportstyrelsen – fordon du får köra</a>"],"signs":[]},{"id":"ty-tread-summer","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"What is the minimum tread depth for car tyres in summer conditions?","img":"","opts":["1.6 mm","3 mm","1 mm","4 mm"],"a":0,"ex":"The main tread pattern may not be worn below <strong>1.6 mm</strong> in the middle 75 % of the tread width. Grip on wet roads gets much worse long before that.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 4 §\">TSFS 2009:19 4 §</a>"],"signs":[]},{"id":"ty-tread-winter","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"What is the minimum tread depth on winter tyres from 1 December to 31 March when there are winter road conditions?","img":"","opts":["3 mm","1.6 mm","5 mm","2 mm"],"a":0,"ex":"When winter tyres are required, they must have at least <strong>3 mm</strong> of tread.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 5 §\">TSFS 2009:19 5 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/vinterdack/\" target=\"_blank\" rel=\"noopener\" title=\"Winter tyres\">Transportstyrelsen – vinterdäck</a>"],"signs":[]},{"id":"ty-winter-when","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"When must a car have winter tyres (or equivalent equipment)?","img":"","opts":["From 1 December to 31 March, when there are winter road conditions","From 1 October to 15 April, always","Whenever the temperature is below 0 °C","From 1 November to 31 March, always"],"a":0,"ex":"Cars, light trucks, light buses and trailers they tow must have winter tyres or equivalent equipment <strong>1 December – 31 March</strong> when <strong>winter road conditions</strong> apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P18a\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 18a §\">TrF 4 kap. 18a §</a>"],"signs":[]},{"id":"ty-winter-conditions","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"What counts as <strong>winter road conditions</strong> (<em>vinterväglag</em>)?","img":"","opts":["Snow, ice, slush or frost on any part of the road","Snow covering the whole road","Temperatures below −5 °C","Only ice on bridges"],"a":0,"ex":"Winter road conditions means <strong>snow, ice, slush or frost on any part</strong> of the road.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 3 §\">TSFS 2009:19 3 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/vinterdack/\" target=\"_blank\" rel=\"noopener\" title=\"Winter tyres\">Transportstyrelsen – vinterdäck</a>"],"signs":[]},{"id":"ty-who-decides","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"Who decides whether winter road conditions apply at a certain place?","img":"","opts":["The police","The driver","The municipality","Trafikverket’s weather service"],"a":0,"ex":"Transportstyrelsen says the <strong>police</strong> decide whether winter road conditions apply at a given place.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/vinterdack/\" target=\"_blank\" rel=\"noopener\" title=\"Winter tyres\">Transportstyrelsen – vinterdäck</a>"],"signs":[]},{"id":"ty-ms","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"A car tyre is marked only <strong>M+S</strong>. Does it count as a winter tyre?","img":"","opts":["No – it needs the alpine symbol (3PMSF), the POR marking or studs","Yes – M+S means winter tyre","Yes, if the tread is at least 3 mm","Only on the rear axle"],"a":0,"ex":"A winter tyre for a car must have the <strong>alpine symbol</strong> (mountain with three peaks and a snowflake), be marked <strong>POR</strong>, or be <strong>studded</strong>. M+S alone is not enough.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 3 §\">TSFS 2009:19 3 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/vinterdack/\" target=\"_blank\" rel=\"noopener\" title=\"Winter tyres\">Transportstyrelsen – vinterdäck</a>"],"signs":[]},{"id":"ty-chains","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"What can count as “equivalent equipment” instead of winter tyres?","img":"","opts":["Snow chains","Wider summer tyres","Lower tyre pressure","Sand in the boot"],"a":0,"ex":"The rules allow winter tyres <strong>or equivalent equipment</strong> – for example <strong>snow chains</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 3 §\">TSFS 2009:19 3 §</a>"],"signs":[]},{"id":"ty-studs-period","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"When may you drive with studded tyres?","img":"","opts":["1 October to 15 April – and outside that period only if there are, or may be, winter road conditions","All year","Only 1 December to 31 March","Only when there is ice on the road"],"a":0,"ex":"Studded tyres are allowed <strong>1 October – 15 April</strong>, and outside that period only when there are – or may be – winter road conditions.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 8 §\">TSFS 2009:19 8 §</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/vinterdack/\" target=\"_blank\" rel=\"noopener\" title=\"Winter tyres\">Transportstyrelsen – vinterdäck</a>"],"signs":[]},{"id":"ty-mix","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"You have studded tyres only on the front wheels and non-studded winter tyres at the back. Is that allowed?","img":"","opts":["No – a car may not have studded and non-studded tyres at the same time","Yes","Yes, on front-wheel-drive cars","Yes, if all have 3 mm tread"],"a":0,"ex":"A car may <strong>not</strong> use studded and non-studded tyres at the same time.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 10 §\">TSFS 2009:19 10 §</a>"],"signs":[]},{"id":"ty-trailer-studs","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"Your car has studded tyres and there are winter road conditions. What applies to the trailer you tow?","img":"","opts":["It must also have studded tyres","It may have summer tyres","It needs snow chains","Nothing"],"a":0,"ex":"If the car has studded tyres and there are winter road conditions, a trailer it tows must <strong>also have studded tyres</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 11 §\">TSFS 2009:19 11 §</a>"],"signs":[]},{"id":"ty-best-rear","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"Where should you fit the two tyres with the deepest tread?","img":"","opts":["On the rear axle – also on a front-wheel-drive car","On the front axle","On the driving wheels","It does not matter"],"a":0,"ex":"Transportstyrelsen advises fitting the tyres with the <strong>best grip on the rear axle</strong> – also on front-wheel-drive cars – to reduce the risk of skidding when braking and in bends.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/\" target=\"_blank\" rel=\"noopener\" title=\"Tyres\">Transportstyrelsen – däck</a>"],"signs":[]},{"id":"ty-pressure","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"How should you check the tyre pressure?","img":"","opts":["When the tyres are cold, against the values in the owner’s manual","After a long drive, when the tyres are warm","By looking at the tyres","Only when a warning light comes on"],"a":0,"ex":"Find the right pressure in the <strong>owner’s manual</strong> and check it when the tyres are <strong>cold</strong>. Wrong pressure affects handling, fuel consumption and the life of the tyre.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/\" target=\"_blank\" rel=\"noopener\" title=\"Tyres\">Transportstyrelsen – däck</a>"],"signs":[]},{"id":"ty-pressure-effect","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"What can wrong tyre pressure affect?","img":"","opts":["Handling, fuel consumption and the life of the tyre","Only comfort","Only the tyre’s colour","Nothing, on modern cars"],"a":0,"ex":"Wrong tyre pressure affects the car’s <strong>handling</strong>, its <strong>fuel consumption</strong> and the <strong>life</strong> of the tyre.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/\" target=\"_blank\" rel=\"noopener\" title=\"Tyres\">Transportstyrelsen – däck</a>"],"signs":[]},{"id":"ty-damage","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"A tyre has a cut that shows the inner reinforcement. May you drive on it?","img":"","opts":["No","Yes, if the tread is deep enough","Yes, in summer","Yes, on the rear axle"],"a":0,"ex":"A tyre may not have cracks, holes or other damage that exposes its <strong>inner reinforcement</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/forfattningssamling/ts-foreskrifter-i-nummerordning/2009/details?RuleNumber=2009:19&amp;ruleprefix=TSFS\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the use of tyres on cars and trailers — TSFS 2009:19 6 §\">TSFS 2009:19 6 §</a>"],"signs":[]},{"id":"ty-old-car","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"Which cars are exempt from the winter tyre requirement?","img":"","opts":["Cars that are 30 years old or more","Electric cars","Four-wheel-drive cars","Cars with ABS"],"a":0,"ex":"The requirement does not apply to vehicles that are <strong>30 years old or more</strong> (by model year).","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P18c\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 18c §\">TrF 4 kap. 18c §</a>"],"signs":[],"noExam":1},{"id":"ty-store","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"tyres","q":"How should you store tyres between seasons?","img":"","opts":["Cool, dry and dark","Warm and sunny","Outside in the rain","Next to the heater"],"a":0,"ex":"Transportstyrelsen advises storing tyres <strong>cool, dry and dark</strong>.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/fordon/fordonsregler/dack/\" target=\"_blank\" rel=\"noopener\" title=\"Tyres\">Transportstyrelsen – däck</a>"],"signs":[],"noExam":1},{"id":"br-abs-steer","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"brakes-and-abs","q":"In an emergency in a car with ABS, how do you brake?","img":"","opts":["Press the brake pedal firmly and keep the pressure – ABS should let you keep steering control","Pump the pedal quickly","Brake gently to avoid activating the ABS","Pull the parking brake"],"a":0,"ex":"With ABS, apply the footbrake <strong>firmly</strong> and do not release the pressure. ABS should ensure that <strong>steering control is retained</strong>. A pulsing pedal is normal.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 120\">UK Highway Code rule 120</a>"],"signs":[]},{"id":"br-abs-distance","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"brakes-and-abs","q":"Does ABS always give a shorter stopping distance?","img":"","opts":["No – its main benefit is that you can steer while braking hard","Yes, on all surfaces","Yes, on ice","Yes, if the tyres are new"],"a":0,"ex":"Do <strong>not</strong> assume that a vehicle with ABS will stop in a shorter distance. ABS keeps the wheels from locking so that you <strong>keep steering control</strong>.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 120\">UK Highway Code rule 120</a>"],"signs":[]},{"id":"br-lock","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"brakes-and-abs","q":"Why should you avoid braking so hard that the wheels lock (in a car without ABS)?","img":"","opts":["Locked wheels can lead to loss of control – the car cannot be steered","It wears the brake pads","It is forbidden","It turns off the engine"],"a":0,"ex":"In an emergency, brake immediately, but try not to brake so harshly that you lock the wheels – <strong>locked wheels can lead to loss of control</strong>.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 118\">UK Highway Code rule 118</a>"],"signs":[]},{"id":"br-wet","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"brakes-and-abs","q":"You have just driven through deep water. What should you do?","img":"","opts":["Test the brakes gently at the first safe opportunity – they may be less effective","Brake hard at once to dry them","Nothing – brakes are not affected by water","Pull the parking brake while driving"],"a":0,"ex":"After deep water the brakes may be <strong>less effective</strong>. Test them gently when it is safe; if they are weak, apply light pressure while driving slowly to dry them.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 121\">UK Highway Code rule 121</a>"],"signs":[]},{"id":"br-aeb","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"brakes-and-abs","q":"According to Trafikverket’s research summary, roughly how much did collision warning plus automatic emergency braking reduce rear-end collisions with injuries?","img":"","opts":["By about half","By about 5 %","By about 90 %","Not at all"],"a":0,"ex":"Several studies show that <strong>FCW + AEB</strong> reduced injury rear-end collisions by about <strong>53–56 %</strong> – roughly half. But the systems cannot see everything; you are still the driver.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>"],"signs":[]},{"id":"sk-cause","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"What usually causes a skid?","img":"","opts":["Braking, accelerating or steering too harshly, or driving too fast for the conditions","Driving in too high a gear","Driving with dipped beam","Having the windows open"],"a":0,"ex":"Skidding is usually caused by the driver <strong>braking, accelerating or steering too harshly</strong> or driving <strong>too fast</strong> for the road conditions.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 119\">UK Highway Code rule 119</a>"],"signs":[]},{"id":"sk-recover","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"The rear of your car starts to skid to the <strong>right</strong>. What do you do?","img":"","opts":["Release the brake or ease off the accelerator, and steer to the right","Brake hard and steer to the left","Accelerate hard","Pull the parking brake"],"a":0,"ex":"Remove the cause – release the brake fully or ease off the accelerator – and <strong>steer in the direction of the skid</strong>: if the rear skids to the right, steer right.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 119\">UK Highway Code rule 119</a>"],"signs":[]},{"id":"sk-aquaplane","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"In heavy rain the steering suddenly feels light and unresponsive. What is happening, and what do you do?","img":"","opts":["Water is stopping the tyres from gripping – ease off the accelerator and slow down gradually","The power steering has failed – brake hard","The tyres are too hard – speed up","Nothing – it is normal in rain"],"a":0,"ex":"Unresponsive steering in the wet probably means <strong>water is preventing the tyres from gripping</strong> (aquaplaning). <strong>Ease off the accelerator</strong> and slow down gradually – no hard braking or sharp steering.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 227\">UK Highway Code rule 227</a>"],"signs":[]},{"id":"sk-wet-distance","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"How much longer are stopping distances on a wet road compared with a dry road?","img":"","opts":["At least double","About 10 % longer","The same with ABS","Half as long"],"a":0,"ex":"In wet weather, stopping distances will be <strong>at least double</strong> those on dry roads, because the tyres have less grip.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 227\">UK Highway Code rule 227</a>"],"signs":[]},{"id":"sk-ice-distance","area":"vehicle","paths":["car-manual","car-automatic","motorcycle"],"lesson":"skids-and-traction","q":"On icy roads, how much longer can stopping distances be than on dry roads?","img":"","opts":["Up to ten times longer","About twice as long","About 20 % longer","The same with winter tyres"],"a":0,"ex":"In icy and snowy weather, stopping distances can be <strong>ten times greater</strong> than on dry roads. Keep well back from the road user in front.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 230\">UK Highway Code rule 230</a>"],"signs":[]},{"id":"sk-ice-technique","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"How should you drive on an icy road?","img":"","opts":["At a slow speed in as high a gear as possible, accelerating and braking very gently","In a low gear with high engine speed","At normal speed if you have ABS","With sharp steering movements to keep control"],"a":0,"ex":"On ice, avoid sudden actions. Drive <strong>slowly in as high a gear as possible</strong>, accelerate and brake <strong>very gently</strong>, and brake on the straight <strong>before</strong> bends.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 231\">UK Highway Code rule 231</a>"],"signs":[]},{"id":"sk-ice-noise","area":"vehicle","paths":["car-manual","car-automatic","motorcycle"],"lesson":"skids-and-traction","q":"Which sign can tell you that you are driving on ice?","img":"","opts":["The tyres become almost silent and the steering feels light","The tyres get louder","The engine speed drops","The car pulls to the left"],"a":0,"ex":"Unresponsive steering may indicate ice, and <strong>on ice the tyres make virtually no noise</strong>. Check the grip by braking gently at a safe place.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 231\">UK Highway Code rule 231</a>"],"signs":[]},{"id":"sk-test-grip","area":"vehicle","paths":["car-manual","car-automatic","motorcycle"],"lesson":"skids-and-traction","q":"How can you check the grip when there is snow or ice?","img":"","opts":["Brake gently at a safe place with no traffic behind you","Brake hard in a bend","Accelerate hard from standstill at a junction","Turn the steering wheel sharply at speed"],"a":0,"ex":"Check your grip on snow or ice by <strong>choosing a safe place to brake gently</strong>.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/driving-in-adverse-weather-conditions-226-to-237\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – driving in bad weather — UK Highway Code rule 231\">UK Highway Code rule 231</a>"],"signs":[]},{"id":"sk-esc","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"According to Trafikverket’s research summary, roughly how much did ESC (anti-skid) reduce single-vehicle, head-on and overtaking crashes with injuries?","img":"","opts":["About 31 %","About 3 %","About 90 %","It had no effect"],"a":0,"ex":"ESC reduced such injury crashes by about <strong>31 %</strong> – about 41 % where someone was killed or seriously injured – and the effect was largest on <strong>wet roads (56 %)</strong>.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>"],"signs":[]},{"id":"sk-esc-limits","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"skids-and-traction","q":"Your car has ESC. Which is true?","img":"","opts":["It helps, but if you drive too fast for the grip you can still leave the road","It lets you take bends at any speed","It replaces winter tyres","It makes the braking distance on ice normal"],"a":0,"ex":"ESC can reduce the risk of skidding, but it cannot change physics. The law still requires a speed at which you keep <strong>control</strong> of the vehicle.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"ss-belt","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"According to Trafikverket’s research summary, how much did the seat belt reduce deaths among front-seat car occupants?","img":"","opts":["About 45 %","About 5 %","About 15 %","About 95 %"],"a":0,"ex":"The seat belt reduced deaths among front-seat occupants by about <strong>45 %</strong> in all types of car crashes.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>"],"signs":[]},{"id":"ss-belt-airbag","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"Why should you always wear the seat belt even in a car with airbags?","img":"","opts":["The airbag is made to work together with the belt – together they cut deaths in frontal crashes far more","Airbags only work at low speed","The belt switches the airbag on","It is only a recommendation"],"a":0,"ex":"Belt and driver airbag <strong>together</strong> reduced driver deaths in frontal crashes by about <strong>61 %</strong>, compared with about 29 % for the airbag alone. Using the belt is also the law.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 10 §\">TrF 4 kap. 10 §</a>"],"signs":[]},{"id":"ss-reminder","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"What happens to seat belt use in the front seats of cars with an effective seat belt reminder?","img":"","opts":["It rises to about 99 %","It falls","It stays at about 50 %","It does not change"],"a":0,"ex":"Studies cited by Trafikverket found belt use in the front seats of about <strong>99 %</strong> in cars with an effective seat belt reminder.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>"],"signs":[]},{"id":"ss-airbag-child","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"From about what height is a child safe sitting in front of an active passenger airbag?","img":"","opts":["About 140 cm","About 100 cm","About 120 cm","Never, at any height"],"a":0,"ex":"A child is not safe in front of an active airbag until about <strong>140 cm</strong> tall. Never put a child seat or booster in front of an active airbag.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/sa-skyddar-du-barnen---regler-och-tips/\" target=\"_blank\" rel=\"noopener\" title=\"How to protect children in the car – rules and tips\">Transportstyrelsen – Så skyddar du barnen</a>"],"signs":[]},{"id":"ss-side-airbag","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"Are <strong>side airbags</strong> a danger to a child in a child seat?","img":"","opts":["No","Yes – they must be switched off","Yes, for rear-facing seats","Only in winter"],"a":0,"ex":"Transportstyrelsen says <strong>side airbags</strong> and curtains are <strong>no danger</strong> to children in child seats. The danger is an active <strong>front</strong> passenger airbag.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/trafikregler-och-vagmarken/trafikregler/i-fordonet/sa-skyddar-du-barnen---regler-och-tips/\" target=\"_blank\" rel=\"noopener\" title=\"How to protect children in the car – rules and tips\">Transportstyrelsen – Så skyddar du barnen</a>"],"signs":[]},{"id":"ss-ldw","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"What does a <strong>lane departure warning</strong> (LDW) do?","img":"","opts":["Warns you when the car is about to leave its lane – generally from about 65 km/h","Steers the car back by itself at any speed","Brakes the car automatically in a queue","Shows the speed limit"],"a":0,"ex":"LDW <strong>warns</strong> when the car is about to leave its lane, generally from about <strong>65 km/h</strong>. In Swedish data it reduced injuries in head-on and single-vehicle crashes by about 40 %.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>"],"signs":[]},{"id":"ss-isa","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"What is <strong>ISA</strong> (intelligent speed assistance)?","img":"","opts":["A system that informs you about the speed limit and helps you keep within it – standard in new EU cars from 2024","A system that brakes for pedestrians","A cruise control that ignores speed limits","An anti-skid system"],"a":0,"ex":"ISA informs the driver about the current <strong>speed limit</strong> and supports keeping within it. It is <strong>standard equipment in all new cars in the EU from 2024</strong>.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>"],"signs":[]},{"id":"ss-assist-limits","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"Your car has lane keeping assist and automatic emergency braking. Who is responsible for driving it?","img":"","opts":["You – the systems only work in certain conditions","The car manufacturer","The systems, when switched on","Nobody, above 65 km/h"],"a":0,"ex":"Assistance systems only work in certain conditions – many only above or below certain speeds. <strong>You</strong> are always responsible for driving the car safely.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"ss-ncap","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-systems-car","q":"What did research cited by Trafikverket find about cars with 5 stars in Euro NCAP’s tests?","img":"","opts":["The risk of serious and fatal injury in car-to-car collisions was clearly lower than in 2-star cars","They have no crashes at all","They need no seat belts","They are only safer for pedestrians"],"a":0,"ex":"The risk of serious and fatal injury in collisions between cars was clearly <strong>lower in 5-star cars</strong> than in 2-star cars. Using a safe car is part of Trafikverket’s basic safety advice.","src":["<a class=\"cite\" href=\"https://bransch.trafikverket.se/contentassets/6172806b6959485d895374173243047f/2025_ny/trafiksakerhet/fordonssakerhet.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Safety effects of vehicle safety systems\">Trafikverket – Effektsamband fordonssäkerhet</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-i-bil/\" target=\"_blank\" rel=\"noopener\" title=\"Safety in the car\">Trafikverket – Säkerhet i bil</a>"],"signs":[]},{"id":"ev-hybrid-charging","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"electric-and-hybrid","q":"May an ordinary hybrid car that <strong>cannot be plugged in</strong> park at a charging place?","img":"","opts":["No – only vehicles that can be charged externally","Yes – all hybrids may","Yes, for 2 hours","Yes, at night"],"a":0,"ex":"At a charging place only vehicles that can be <strong>charged externally</strong> for their propulsion may park or stop. Others may only stop to let people in or out.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P54\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 54 §\">TrF 3 kap. 54 §</a>"],"signs":[]},{"id":"ev-quiet","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"electric-and-hybrid","q":"What should you keep in mind when you drive an electric car slowly in a car park?","img":"","opts":["It is much quieter than a petrol car at low speed – pedestrians may not hear you","It is louder than a petrol car","It cannot reverse","It has no brakes at low speed"],"a":0,"ex":"Electric cars are <strong>quieter</strong> than conventional cars at <strong>low speeds</strong>, where engine noise dominates. Pedestrians – especially children and people with impaired sight – may not hear you.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/miljo/buller/\" target=\"_blank\" rel=\"noopener\" title=\"Noise\">Transportstyrelsen – Buller</a>"],"signs":[]},{"id":"ev-weight","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"electric-and-hybrid","q":"Under the EU’s new licence directive, what will a B licence holder with two years’ experience be allowed to drive from 26 November 2027?","img":"","opts":["Cars running fully or partly on alternative fuels up to 4,250 kg (not motorhomes)","Any truck up to 7,500 kg","Buses with 16 passengers","Heavy motorcycles"],"a":0,"ex":"From <strong>26 November 2027</strong>, after two years with B, cars running fully or partly on <strong>alternative fuels</strong> (for example electricity) up to <strong>4,250 kg</strong> – not motorhomes. Until then, 3,500 kg applies.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/om-oss/dina-rattigheter-lagar-och-regler/lagar-och-regler/regler-for-vag/kommande-korkortsregler/\" target=\"_blank\" rel=\"noopener\" title=\"Upcoming driving licence rules (EU's fourth driving licence directive)\">Transportstyrelsen – kommande regler</a>"],"signs":[],"noExam":1},{"id":"mg-coasting","area":"vehicle","paths":["car-manual"],"lesson":"manual-gearbox","q":"Why should you not drive downhill with the gear in neutral or the clutch pressed down (coasting)?","img":"","opts":["There is no engine braking, the speed rises quickly and you lose control","It damages the gearbox immediately","It is forbidden on all roads","It uses more electricity"],"a":0,"ex":"Coasting <strong>removes engine braking</strong>, makes the speed downhill increase quickly, makes you use the footbrake more (which can reduce its effect), affects steering in bends, and makes it harder to select the right gear when needed.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 122\">UK Highway Code rule 122</a>"],"signs":[]},{"id":"mg-licence","area":"vehicle","paths":["car-manual"],"lesson":"manual-gearbox","q":"You pass the driving test in a manual car. Which cars may you drive?","img":"","opts":["Both manual and automatic cars","Only manual cars","Only cars with five gears","Automatic cars only after one year"],"a":0,"ex":"A licence from a test in a manual car lets you drive <strong>both</strong> manual and automatic cars. A test in an automatic car gives code 78.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/korkortsprov/personbil-och-latt-lastbil/kunskapsprov-b/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: the theory test\">Trafikverket – teoriprov B</a>"],"signs":[]},{"id":"cc-lane-change","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"car-controls","q":"What should you do before changing lanes?","img":"","opts":["Use the mirrors and, if necessary, take a quick glance over your shoulder into the blind spot","Signal and move over at once","Only look in the inside mirror","Sound the horn"],"a":0,"ex":"First use your <strong>mirrors</strong> and, if necessary, take a <strong>quick sideways glance</strong> (the blind spot), so you do not force anyone to change course or speed. Then signal, and move over when it is clear.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 133\">UK Highway Code rule 133</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P43\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 43 §\">TrF 3 kap. 43 §</a>"],"signs":[]},{"id":"cc-adjust","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"car-controls","q":"What must you adjust when you get into the car at the driving test?","img":"","opts":["Seat, head restraint, steering wheel, mirrors and seat belt","Only the mirrors","The radio and the climate control","Nothing – the examiner does it"],"a":0,"ex":"Trafikverket says you adjust the <strong>seat, head restraint, steering wheel, mirrors and seat belt</strong> when you get in.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/sa-gar-korprovet-till/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: how the driving test works\">Trafikverket – körprov B</a>"],"signs":[],"noExam":1},{"id":"sc-items","area":"vehicle","paths":["car-manual","car-automatic"],"lesson":"safety-check-car","q":"Which of these can the examiner ask you to check in the safety check of the car driving test?","img":"","opts":["Fluids such as coolant, engine oil and washer fluid","The car’s registration number","The radio","The fuel price"],"a":0,"ex":"The safety check can include lights, indicators, reflectors and horn, wipers and washers, steering, brakes, tyres and rims, <strong>fluids</strong> and warning systems. If you find a fault, suggest what to do.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/personbil-och-latt-lastbil/sa-gar-korprovet-till/\" target=\"_blank\" rel=\"noopener\" title=\"Car licence: how the driving test works\">Trafikverket – körprov B</a>"],"signs":[],"noExam":1},{"id":"mcv-helmet-ece","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"Which helmet may you use on a motorcycle?","img":"","opts":["One that is E-marked and type-approved under ECE Regulation 22, series 05 or later","Any helmet that covers the head","A bicycle helmet, if you ride slowly","Any helmet bought in the EU"],"a":0,"ex":"The helmet must be <strong>E-marked</strong> and type-approved under <strong>UN ECE Regulation 22, amendment series 05 or later</strong> (22.05 or 22.06).","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202017_94.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on protective helmets — TSFS 2017:94 3 §\">TSFS 2017:94 3 §</a>"],"signs":[]},{"id":"mcv-helmet-stickers","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"You want to paint your helmet and drill holes for a camera mount. Is that a problem?","img":"","opts":["Yes – a helmet may not be used if something has been done that can reduce its protection","No – helmets are very strong","Only paint is a problem","Only if the helmet is new"],"a":0,"ex":"A helmet may not be used if something has been done to it that can reduce its protection – Transportstyrelsen gives <strong>stickers, protruding objects, holes in the shell and paint</strong> as examples.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202017_94.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on protective helmets — TSFS 2017:94 6 §\">TSFS 2017:94 6 §</a>"],"signs":[]},{"id":"mcv-helmet-fastened","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"How must the helmet be worn?","img":"","opts":["Securely fastened so it sits firmly on the head","With the strap loose for comfort","Pushed back so you see more","Only fastened outside built-up areas"],"a":0,"ex":"The helmet must be <strong>securely fastened</strong> so that it sits firmly on the head.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202017_94.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on protective helmets — TSFS 2017:94 5 §\">TSFS 2017:94 5 §</a>"],"signs":[]},{"id":"mcv-visor","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"Why should you replace a badly scratched visor?","img":"","opts":["Scratches limit your view, especially in bright sunshine and in darkness","It is only a cosmetic problem","It is required every year","It makes the helmet heavier"],"a":0,"ex":"Scratched or poorly fitting eye protection can <strong>limit your view</strong>, particularly in <strong>bright sunshine and in darkness</strong>. Check your visor before each ride.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 84\">UK Highway Code rule 84</a>"],"signs":[]},{"id":"mcv-be-seen","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"You wear a bright helmet, fluorescent clothing and ride with the headlight on. Can you be sure drivers have seen you?","img":"","opts":["No – they may still not see you, or misjudge your distance or speed, especially at junctions","Yes, always","Yes, in daylight","Yes, if you also sound the horn"],"a":0,"ex":"Bright and fluorescent gear and dipped headlights make you more conspicuous, but other drivers <strong>may still not have seen you</strong> or judged your distance or speed correctly – especially at <strong>junctions</strong>.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 86\">UK Highway Code rule 86</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 3 kap. 2 §\">TSFS 2011:19 3 kap. 2 §</a>"],"signs":[]},{"id":"mcv-dark","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"What helps other road users see you on a motorcycle in the dark?","img":"","opts":["Reflective clothing or strips","Black clothing","A tinted visor","Riding close behind cars"],"a":0,"ex":"<strong>Reflective</strong> clothing or strips reflect light from other vehicles’ headlamps, so you are seen from further away.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 87\">UK Highway Code rule 87</a>"],"signs":[]},{"id":"mcv-gear","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"Which gear may help protect you in a motorcycle crash?","img":"","opts":["Strong boots, gloves and protective clothing","Trainers and a T-shirt","Shorts in summer","Sunglasses instead of a visor"],"a":0,"ex":"Strong <strong>boots, gloves</strong> and suitable <strong>protective clothing</strong> may help protect you in a collision. Trafikverket lists helmet and other protective equipment among the key safety measures for riders.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 84\">UK Highway Code rule 84</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcv-abs-rule","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"Which new motorcycles must have ABS under EU rules?","img":"","opts":["Motorcycles over 125 cc","All motorcycles, including 50 cc","Only motorcycles over 1,000 cc","None – ABS is optional"],"a":0,"ex":"New motorcycles <strong>over 125 cc</strong> must have ABS. For smaller ones the manufacturer may choose between ABS and a combined brake system.","src":["<a class=\"cite\" href=\"https://oeil.europarl.europa.eu/oeil/en/document-summary?id=1257404\" target=\"_blank\" rel=\"noopener\" title=\"EU type-approval rules for motorcycles and mopeds\">EU Regulation 168/2013 (summary)</a>"],"signs":[]},{"id":"mcv-abs-measure","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"Which vehicle technology does Trafikverket name among the most important safety measures for motorcycles?","img":"","opts":["ABS – also on light motorcycles – and cornering ABS","Loud exhausts","Larger fuel tanks","Wider handlebars"],"a":0,"ex":"Trafikverket lists <strong>ABS (also for light motorcycles)</strong>, <strong>cornering ABS</strong>, speed-warning systems and better crash safety among the measures for motorcycles.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcv-both-brakes","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"How must you brake in the braking part of the motorcycle riding test?","img":"","opts":["Efficiently and controlled, with both the front and the rear brake","Only with the rear brake","Only with the front brake","With engine braking only"],"a":0,"ex":"The test ends with efficient, controlled braking to a stop from <strong>70 km/h and 90 km/h</strong>, using <strong>both</strong> the front and the rear brake.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[]},{"id":"mcv-lock","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"Why should you avoid locking the wheels when you brake hard?","img":"","opts":["Locked wheels can lead to loss of control","It damages the chain","It is forbidden","It turns the lights off"],"a":0,"ex":"In an emergency, brake at once – but avoid braking so harshly that you <strong>lock the wheels</strong>, because locked wheels can lead to loss of control. On a motorcycle, a locked front wheel can quickly make you fall.","src":["<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/general-rules-techniques-and-advice-for-all-drivers-and-riders-103-to-158\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – general driving techniques — UK Highway Code rule 118\">UK Highway Code rule 118</a>"],"signs":[]},{"id":"mcv-auto-lights","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"What do EU rules require for the headlights of new models of motorcycles?","img":"","opts":["That they switch on automatically","That they are yellow","That they can be switched off in daylight","Nothing"],"a":0,"ex":"New models of motorcycles and mopeds must have <strong>lights that switch on automatically</strong>, to increase visibility.","src":["<a class=\"cite\" href=\"https://oeil.europarl.europa.eu/oeil/en/document-summary?id=1257404\" target=\"_blank\" rel=\"noopener\" title=\"EU type-approval rules for motorcycles and mopeds\">EU Regulation 168/2013 (summary)</a>"],"signs":[]},{"id":"mcv-kill","area":"vehicle","paths":["motorcycle"],"lesson":"mc-safety-check","q":"Which of these can be part of the safety check at the motorcycle riding test?","img":"","opts":["The chain, the stand and the kill switch","The fuel price","The colour of the motorcycle","The insurance papers only"],"a":0,"ex":"The check can include lights, brakes, tyres, the <strong>power transmission (chain, belt or shaft)</strong>, the <strong>stand</strong>, mirrors, bearings, suspension, engine oil and the <strong>kill switch</strong>.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"mcv-test-bike","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"What kind of gearbox must the motorcycle have at an ordinary category A riding test?","img":"","opts":["A manual gearbox with a clutch lever","An automatic gearbox","Either – it does not matter","An electric motor only"],"a":0,"ex":"The motorcycle must have a <strong>manual gearbox and a clutch lever</strong> – unless the test is for an automatic-only licence.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"mcv-pillion","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"How should a passenger sit on a motorcycle?","img":"","opts":["Astride a proper seat, facing forward, with both feet on the footrests","Side-saddle, if the trip is short","On the tank in front of the rider","Standing on the footrests"],"a":0,"ex":"A passenger may only be carried if the motorcycle is built for it – at most one, and the rider must be 18. The passenger sits <strong>astride a proper seat</strong>, <strong>facing forward</strong>, with <strong>both feet on the footrests</strong>.","src":["<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K4P6b\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 4 kap. 6b §\">TrF 4 kap. 6b §</a>","<a class=\"cite\" href=\"https://www.gov.uk/guidance/the-highway-code/rules-for-motorcyclists-83-to-88\" target=\"_blank\" rel=\"noopener\" title=\"The Highway Code (UK) – advice for motorcyclists — UK Highway Code rule 85\">UK Highway Code rule 85</a>"],"signs":[]},{"id":"mcv-crawl","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"How do you best control a motorcycle at walking pace, for example in a tight turn?","img":"","opts":["Control the speed mainly with the clutch, supported by throttle and brake","Only with the front brake","With the engine switched off","With the throttle fully open"],"a":0,"ex":"At very low speed, control the speed mainly with the <strong>clutch</strong>, supported by the throttle and brake – exactly what the low-speed part of the manoeuvre test checks. The curriculum calls it good balance when crawling.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>","<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 2 kap. 2 §\">TSFS 2011:19 2 kap. 2 §</a>"],"signs":[]},{"id":"mcv-risk-gear","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"Which protective gear must you wear in the practical part of the motorcycle risk education?","img":"","opts":["Helmet, protective clothing of leather or other strong material, eye protection, strong boots, gloves and a back protector","Only a helmet","A helmet and a reflective vest","Whatever you like, if it is summer"],"a":0,"ex":"Transportstyrelsen requires a <strong>helmet</strong> and protective equipment – <strong>clothes of leather or other strong material, goggles or similar, strong boots, gloves and a back protector</strong> – all free from damage.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/sv/vagtrafik/korkort/ta-korkort/riskutbildning/riskutbildning-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Risk education for motorcycles\">Transportstyrelsen – riskutbildning MC</a>"],"signs":[]},{"id":"mcv-evasive","area":"vehicle","paths":["motorcycle"],"lesson":"mc-cornering","q":"What does the evasive manoeuvre in the motorcycle test show?","img":"","opts":["That you use the right riding and steering technique when you cannot stop before an obstacle","That you can ride fast on a motorway","That you can park between two cars","That you can ride with no hands"],"a":0,"ex":"The examiner assesses that you can use the <strong>right riding and steering technique</strong> in an emergency where you <strong>cannot stop before an obstacle</strong> – done at about 50 km/h.","src":["<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[],"noExam":1},{"id":"mcv-ppe-curriculum","area":"vehicle","paths":["motorcycle"],"lesson":"mc-protective-gear","q":"What does the motorcycle curriculum say about personal protective equipment?","img":"","opts":["You must explain why it matters and use it","It is optional and not part of the training","Only the helmet is mentioned","Only for racing"],"a":0,"ex":"The curriculum requires you to explain <strong>the importance of personal protective equipment</strong> – and to use it. Trafikverket lists the helmet and other protective equipment among the key safety measures.","src":["<a class=\"cite\" href=\"https://www.transportstyrelsen.se/TSFS/TSFS%202011_19.pdf\" target=\"_blank\" rel=\"noopener\" title=\"Transport Agency regulations on the course plan for categories A1 and A — TSFS 2011:19 2 kap. 2 §\">TSFS 2011:19 2 kap. 2 §</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/resa-och-trafik/trafiksakerhet/sakerhet-pa-vag/sakerhet-pa-motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle safety\">Trafikverket – Säkerhet på motorcykel</a>"],"signs":[]},{"id":"mcv-countersteer-start","area":"vehicle","paths":["motorcycle"],"lesson":"mc-cornering","q":"You ride at 60 km/h and want to turn right. How do you make the motorcycle lean into the turn?","img":"","opts":["Press the right handgrip forward","Press the left handgrip forward","Pull the front brake lever","Take both feet off the footrests"],"a":0,"ex":"Above walking pace a motorcycle must <strong>lean</strong> to turn. Gentle forward pressure on the handgrip <strong>in the direction of the turn</strong> starts the lean – to turn right, press the right handgrip. This is called <strong>counter-steering</strong>.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Turning\">SGI Motorcycle Handbook Turning</a>"],"signs":[]},{"id":"mcv-countersteer-wheel","area":"vehicle","paths":["motorcycle"],"lesson":"mc-cornering","q":"You press the right handgrip forward at speed. What does the front wheel do for an instant?","img":"","opts":["It turns slightly to the left, so the motorcycle starts to lean right","It turns sharply to the right","It locks","It lifts off the road"],"a":0,"ex":"The front wheel moves <strong>away</strong> from the turn for a moment, which makes the motorcycle start to <strong>lean</strong> in the direction of the turn. Then the wheel re-centres and the motorcycle turns.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Turning\">SGI Motorcycle Handbook Turning</a>"],"signs":[]},{"id":"mcv-lean-sharper","area":"vehicle","paths":["motorcycle"],"lesson":"mc-cornering","q":"What is true about leaning when you turn a motorcycle?","img":"","opts":["The sharper the turn, the more the motorcycle must lean","The faster you go, the less it needs to lean in the same bend","A motorcycle turns without leaning above 50 km/h","Leaning is only needed at walking pace"],"a":0,"ex":"A motorcycle must lean in order to turn, and <strong>the sharper the turn, the more it must lean</strong>. That is why braking and choosing the speed are done <strong>before</strong> the bend.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Turning\">SGI Motorcycle Handbook Turning</a>","<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Emergency steering\">SGI Motorcycle Handbook Emergency steering</a>"],"signs":[]},{"id":"mcv-front-share","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"About how much of a motorcycle’s braking power does the front brake give?","img":"","opts":["About three-quarters","About a quarter","About half","Almost nothing – the rear brake does the work"],"a":0,"ex":"The front brake gives about <strong>three-quarters</strong> of the braking power, so you must use <strong>both</strong> brakes to stop quickly.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Braking\">SGI Motorcycle Handbook Braking</a>"],"signs":[]},{"id":"mcv-rear-lock","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"In a hard stop on a motorcycle without ABS, the rear wheel locks while you are going straight. What should you do?","img":"","opts":["Keep the rear brake on until you have come to a complete stop","Release the rear brake at once and accelerate","Turn the handlebars sharply","Pull in the front brake harder until that wheel locks too"],"a":0,"ex":"If the rear wheel does lock, do <strong>not</strong> release the brake until you have come to a <strong>complete stop</strong>. Best of all, squeeze both brakes progressively so the wheels do not lock.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Quick stops\">SGI Motorcycle Handbook Quick stops</a>"],"signs":[]},{"id":"mcv-quick-stop-clutch","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"What do you do with the clutch in an emergency stop on a motorcycle?","img":"","opts":["Pull in the clutch, so the engine does not stall","Release the clutch fully and keep the gear in","Nothing – the clutch is never used when braking","Change up a gear first"],"a":0,"ex":"Apply both brakes with a progressive squeeze and <strong>pull in the clutch</strong>.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Quick stops\">SGI Motorcycle Handbook Quick stops</a>"],"signs":[]},{"id":"mcv-brake-before-bend","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"When should you do your braking for a bend on a motorcycle?","img":"","opts":["Before the bend, while the motorcycle is upright","In the middle of the bend, while you lean","At the exit of the bend","It does not matter"],"a":0,"ex":"Make sure all your braking is done <strong>before</strong> the turn. Braking hard while leaning uses grip you need for cornering, and makes the motorcycle stand up and run wide.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Braking\">SGI Motorcycle Handbook Braking</a>","<a class=\"cite\" href=\"https://lagen.nu/1998:1276#K3P14\" target=\"_blank\" rel=\"noopener\" title=\"Road Traffic Ordinance (1998:1276) — TrF 3 kap. 14 §\">TrF 3 kap. 14 §</a>"],"signs":[]},{"id":"mcv-slippery-brakes","area":"vehicle","paths":["motorcycle"],"lesson":"mc-road-surface","q":"Which brake is more effective on a slippery surface?","img":"","opts":["The front brake – it is still more effective than the rear, even on slippery surfaces","The rear brake – the front must never be used on slippery roads","Neither works on a slippery road","Only engine braking works"],"a":0,"ex":"Use <strong>both</strong> brakes, gently and smoothly. The <strong>front</strong> brake is still more effective than the rear brake, even on slippery surfaces.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Slippery surfaces\">SGI Motorcycle Handbook Slippery surfaces</a>"],"signs":[]},{"id":"mcv-clutch-hand","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"How do you work the clutch on an ordinary motorcycle?","img":"","opts":["With the lever in front of the left handgrip, using the left hand","With a pedal under the right foot","With the lever on the right handgrip","With the left foot"],"a":0,"ex":"The <strong>clutch lever</strong> is in front of the <strong>left</strong> handgrip. Squeezing it disconnects the engine from the rear wheel – you must do that whenever you change gear.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Know your motorcycle controls\">SGI Motorcycle Handbook Know your motorcycle controls</a>"],"signs":[]},{"id":"mcv-rear-brake-foot","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"On most motorcycles, how do you work the rear brake?","img":"","opts":["With the right foot, on the pedal in front of the right footrest","With the left hand","With the left foot, on the gear lever","With the right hand only"],"a":0,"ex":"On most motorcycles the <strong>right foot</strong> works the <strong>rear</strong> brake, and the <strong>right hand</strong> works the <strong>front</strong> brake. They should be used together.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Know your motorcycle controls\">SGI Motorcycle Handbook Know your motorcycle controls</a>"],"signs":[]},{"id":"mcv-gear-foot","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"On most motorcycles, how do you change gear?","img":"","opts":["Pull in the clutch, then lift or press the gear lever with your left foot","Turn the throttle backwards","Press a button on the right handgrip, without the clutch","Press the rear brake pedal"],"a":0,"ex":"The gear lever is on the <strong>left</strong> side, just ahead of the footrest. Squeeze the clutch lever with the left hand, then lift or press the gear lever with your <strong>left toe</strong>.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Know your motorcycle controls\">SGI Motorcycle Handbook Know your motorcycle controls</a>"],"signs":[]},{"id":"mcv-kill-use","area":"vehicle","paths":["motorcycle"],"lesson":"mc-controls","q":"What is the red kill switch (engine stop switch) on the right handlebar for?","img":"","opts":["To stop the engine quickly in an emergency","To switch on the main beam","To turn off the ABS","To warm up the engine"],"a":0,"ex":"The kill switch stops the engine <strong>quickly</strong> – for example after a fall. The engine will not start when it is in the OFF position, and it is part of the safety check at the riding test.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Know your motorcycle controls\">SGI Motorcycle Handbook Know your motorcycle controls</a>","<a class=\"cite\" href=\"https://www.trafikverket.se/korkort/ta-korkort/motorcykel/\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle licence: theory test and riding test\">Trafikverket – motorcykel</a>"],"signs":[]},{"id":"mcv-knees","area":"vehicle","paths":["motorcycle"],"lesson":"mc-cornering","q":"Why should you hold your knees against the tank when you ride?","img":"","opts":["It helps you keep your balance as the motorcycle turns","It makes the engine run cooler","It is required by law","It switches off the indicators"],"a":0,"ex":"Holding your knees firmly against the tank helps you keep your <strong>balance</strong> as the motorcycle turns – and keeps your arms free to steer.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Body position\">SGI Motorcycle Handbook Body position</a>"],"signs":[]},{"id":"mcv-abs-small","area":"vehicle","paths":["motorcycle"],"lesson":"mc-braking","q":"What do EU rules say about the brakes of new motorcycles of at most 125 cc?","img":"","opts":["The manufacturer may choose between ABS and a combined brake system","They must not have ABS","They must have drum brakes","EU rules say nothing about brakes"],"a":0,"ex":"New motorcycles <strong>over 125 cc</strong> must have <strong>ABS</strong>. For motorcycles <strong>under 125 cc</strong>, the manufacturer may choose between <strong>ABS</strong> and a <strong>combined brake system</strong>.","src":["<a class=\"cite\" href=\"https://oeil.europarl.europa.eu/oeil/en/document-summary?id=1257404\" target=\"_blank\" rel=\"noopener\" title=\"EU type-approval rules for motorcycles and mopeds\">EU Regulation 168/2013 (summary)</a>"],"signs":[]},{"id":"mcv-grating","area":"vehicle","paths":["motorcycle"],"lesson":"mc-road-surface","q":"You ride over a metal bridge grating and the motorcycle starts to wander back and forth. What do you do?","img":"","opts":["Stay on course, hold the controls firmly and ride straight across","Brake hard at once","Steer quickly from side to side to correct it","Stop on the grating and walk the motorcycle"],"a":0,"ex":"On a badly rutted surface or a metal grating the motorcycle tends to <strong>wander</strong>. It feels uneasy but is generally not dangerous: <strong>stay on course</strong>, grip the controls firmly and ride straight across.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Grooves and gratings\">SGI Motorcycle Handbook Grooves and gratings</a>"],"signs":[]},{"id":"mcv-rails-angle","area":"vehicle","paths":["motorcycle"],"lesson":"mc-road-surface","q":"How should you cross railway or tram tracks on a motorcycle?","img":"","opts":["Slow down and cross at an angle of 45–90 degrees","Ride along the rail until it ends","Cross at a very small angle, almost parallel to the rails","Brake hard on the rails"],"a":0,"ex":"Check for trains, slow down and cross at an angle between <strong>45 and 90 degrees</strong>, so the wheels cannot get caught in the tracks. If a rail runs along your path, move away and cross it at a clear angle – do not try to edge across it.","src":["<a class=\"cite\" href=\"https://sgi.sk.ca/motorcycle/-/knowledge_base/motorcycle-handbook/turning\" target=\"_blank\" rel=\"noopener\" title=\"Motorcycle Driver's Handbook (Saskatchewan, Canada) – riding technique — SGI Motorcycle Handbook Railway tracks\">SGI Motorcycle Handbook Railway tracks</a>"],"signs":[]},{"id":"sign-A1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A1-1\" alt=\"A1 Dangerous bend\" width=\"64\" height=\"64\"></div>","opts":["Level crossing with barriers","Dangerous bend","Roundabout ahead","Level crossing without barriers"],"a":1,"ex":"A1 is <strong>Dangerous bend</strong> (Swedish: <i lang=\"sv\">Varning för farlig kurva</i>). Warns of a dangerous bend and shows which way the bend turns.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A1"],"gen":"sign"},{"id":"sign-A2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A2-1\" alt=\"A2 Several dangerous bends\" width=\"64\" height=\"64\"></div>","opts":["Crossroads (right-hand rule)","Several dangerous bends","Steep descent","Cyclists and moped riders"],"a":1,"ex":"A2 is <strong>Several dangerous bends</strong> (Swedish: <i lang=\"sv\">Varning för flera farliga kurvor</i>). Warns of several dangerous bends and shows which way the first one turns.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A2"],"gen":"sign"},{"id":"sign-A3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A3-1\" alt=\"A3 Steep descent\" width=\"64\" height=\"64\"></div>","opts":["Animals","Steep descent","Falling rocks","Several dangerous bends"],"a":1,"ex":"A3 is <strong>Steep descent</strong> (Swedish: <i lang=\"sv\">Varning för nedförslutning</i>). Warns of a steep downhill slope. The number gives the gradient in per cent and is set to match the actual slope at the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A3"],"gen":"sign"},{"id":"sign-A4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A4-1\" alt=\"A4 Steep ascent\" width=\"64\" height=\"64\"></div>","opts":["Horse riders","Steep ascent","Pedestrian crossing ahead","Crossroads (right-hand rule)"],"a":1,"ex":"A4 is <strong>Steep ascent</strong> (Swedish: <i lang=\"sv\">Varning för stigning</i>). Warns of a steep uphill slope. The number gives the gradient in per cent and is set to match the actual slope at the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A4"],"gen":"sign"},{"id":"sign-A5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A5-1\" alt=\"A5 Road narrows\" width=\"64\" height=\"64\"></div>","opts":["Level crossing with barriers","Road narrows","St Andrew's cross (level crossing)","Children"],"a":1,"ex":"A5 is <strong>Road narrows</strong> (Swedish: <i lang=\"sv\">Varning för avsmalnande väg</i>). Warns that the road or lane gets narrower. The symbol is drawn to match the actual narrowing at the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A5"],"gen":"sign"},{"id":"sign-A6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A6-1\" alt=\"A6 Opening bridge\" width=\"64\" height=\"64\"></div>","opts":["Tramway crossing without barriers","Opening bridge","Low-flying aircraft","Level crossing with barriers"],"a":1,"ex":"A6 is <strong>Opening bridge</strong> (Swedish: <i lang=\"sv\">Varning för bro</i>). Warns of a bridge that can be opened (for example to let boats pass).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A6"],"gen":"sign"},{"id":"sign-A7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A7-1\" alt=\"A7 Quay or river bank\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing ahead","Road works","Quay or river bank","Side wind"],"a":2,"ex":"A7 is <strong>Quay or river bank</strong> (Swedish: <i lang=\"sv\">Varning för kaj</i>). Warns of a place where the road ends at water.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A7"],"gen":"sign"},{"id":"sign-A8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A8-1\" alt=\"A8 Uneven road\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Uneven road","Steep descent","Soft verge or high road edge"],"a":1,"ex":"A8 is <strong>Uneven road</strong> (Swedish: <i lang=\"sv\">Varning för ojämn väg</i>). Warns of bumps or damage in the road surface that make it wise to drive more slowly than you otherwise would.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A8"],"gen":"sign"},{"id":"sign-A9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A9-1\" alt=\"A9 Speed bump or dip\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Loose stones","Speed bump or dip","Slow-moving vehicles"],"a":2,"ex":"A9 is <strong>Speed bump or dip</strong> (Swedish: <i lang=\"sv\">Varning för farthinder</i>). Warns of a raised hump or a dip that has been built on purpose to make traffic slow down.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A9"],"gen":"sign"},{"id":"sign-A10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A10-1\" alt=\"A10 Slippery road\" width=\"64\" height=\"64\"></div>","opts":["Traffic signals ahead","Slippery road","Animals","Level crossing with barriers"],"a":1,"ex":"A10 is <strong>Slippery road</strong> (Swedish: <i lang=\"sv\">Varning för slirig väg</i>). Warns that the road may be slippery. It is used to warn of slippery snow or ice only if there are special reasons.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A10"],"gen":"sign"},{"id":"sign-A11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A11-1\" alt=\"A11 Loose stones\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Loose stones","Quay or river bank","Queues likely"],"a":1,"ex":"A11 is <strong>Loose stones</strong> (Swedish: <i lang=\"sv\">Varning för stenskott</i>). Warns of the risk of stones being thrown up by tyres. It is not used on gravel roads and similar roads, where this is common.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A11"],"gen":"sign"},{"id":"sign-A12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A12-1\" alt=\"A12 Falling rocks\" width=\"64\" height=\"64\"></div>","opts":["Soft verge or high road edge","Falling rocks","Animals","Several dangerous bends"],"a":1,"ex":"A12 is <strong>Falling rocks</strong> (Swedish: <i lang=\"sv\">Varning för stenras</i>). Warns of the risk of rock falls, and that stones from a rock fall may lie on the road. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A12"],"gen":"sign"},{"id":"sign-A13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A13-1\" alt=\"A13 Pedestrian crossing ahead\" width=\"64\" height=\"64\"></div>","opts":["Children","Pedestrian crossing ahead","Queues likely","Several dangerous bends"],"a":1,"ex":"A13 is <strong>Pedestrian crossing ahead</strong> (Swedish: <i lang=\"sv\">Varning för övergångsställe</i>). Warns of a pedestrian crossing ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A13"],"gen":"sign"},{"id":"sign-A14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A14\" alt=\"A14 Pedestrians\" width=\"64\" height=\"64\"></div>","opts":["Queues likely","Pedestrians","Opening bridge","Children"],"a":1,"ex":"A14 is <strong>Pedestrians</strong> (Swedish: <i lang=\"sv\">Varning för gående</i>). Warns of a stretch of road where pedestrians often cross or walk on or beside the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A14"],"gen":"sign"},{"id":"sign-A15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A15-1\" alt=\"A15 Children\" width=\"64\" height=\"64\"></div>","opts":["Level crossing without barriers","Children","Falling rocks","Queues likely"],"a":1,"ex":"A15 is <strong>Children</strong> (Swedish: <i lang=\"sv\">Varning för barn</i>). Warns of a stretch of road where children often cross or spend time on or beside the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A15"],"gen":"sign"},{"id":"sign-A16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A16-1\" alt=\"A16 Cyclists and moped riders\" width=\"64\" height=\"64\"></div>","opts":["Steep descent","Falling rocks","Cyclists and moped riders","St Andrew's cross (level crossing)"],"a":2,"ex":"A16 is <strong>Cyclists and moped riders</strong> (Swedish: <i lang=\"sv\">Varning för cyklande och mopedförare</i>). Warns of a stretch of road where cyclists or moped riders often cross the road or ride out onto it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A16"],"gen":"sign"},{"id":"sign-A17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A17-1\" alt=\"A17 Skiers\" width=\"64\" height=\"64\"></div>","opts":["Two-way traffic","Skiers","Steep ascent","Soft verge or high road edge"],"a":1,"ex":"A17 is <strong>Skiers</strong> (Swedish: <i lang=\"sv\">Varning för skidåkare</i>). Warns of a place where skiers often cross or spend time on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A17"],"gen":"sign"},{"id":"sign-A18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A18-1\" alt=\"A18 Horse riders\" width=\"64\" height=\"64\"></div>","opts":["Queues likely","Horse riders","Several dangerous bends","Opening bridge"],"a":1,"ex":"A18 is <strong>Horse riders</strong> (Swedish: <i lang=\"sv\">Varning för ridande</i>). Warns of a stretch of road where people on horseback often cross or spend time on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A18"],"gen":"sign"},{"id":"sign-A19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"wildlife","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A19-1\" alt=\"A19 Animals\" width=\"64\" height=\"64\"></div>","opts":["Several dangerous bends","Animals","Low-flying aircraft","Horse-drawn vehicles"],"a":1,"ex":"A19 is <strong>Animals</strong> (Swedish: <i lang=\"sv\">Varning för djur</i>). Warns of a place or stretch of road where there is a special risk of animals on or beside the road. The basic sign shows an elk (moose); other symbols show other animals.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A19"],"gen":"sign"},{"id":"sign-A20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A20-1\" alt=\"A20 Road works\" width=\"64\" height=\"64\"></div>","opts":["Opening bridge","Steep ascent","Road works","Level crossing with barriers"],"a":2,"ex":"A20 is <strong>Road works</strong> (Swedish: <i lang=\"sv\">Varning för vägarbete</i>). Warns of a stretch of road where road works or similar work is going on.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A20"],"gen":"sign"},{"id":"sign-A21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A21-1\" alt=\"A21 End of road works\" width=\"64\" height=\"64\"></div>","opts":["Horse riders","End of road works","Other danger","Several dangerous bends"],"a":1,"ex":"A21 is <strong>End of road works</strong> (Swedish: <i lang=\"sv\">Slut på sträcka med vägarbete</i>). Marks the end of a stretch of road works that was marked with sign A20. It is left out if it is clear anyway where the stretch ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A21"],"gen":"sign"},{"id":"sign-A22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A22-1\" alt=\"A22 Traffic signals ahead\" width=\"64\" height=\"64\"></div>","opts":["St Andrew's cross (level crossing)","Traffic signals ahead","Slow-moving vehicles","Horse riders"],"a":1,"ex":"A22 is <strong>Traffic signals ahead</strong> (Swedish: <i lang=\"sv\">Varning för flerfärgssignal</i>). Warns of a place where traffic is controlled by traffic lights with three lamps (red, yellow, green). Inside built-up areas it is only put up if there are special reasons.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A22"],"gen":"sign"},{"id":"sign-A23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A23-1\" alt=\"A23 Low-flying aircraft\" width=\"64\" height=\"64\"></div>","opts":["Crossroads (right-hand rule)","Opening bridge","Low-flying aircraft","Traffic signals ahead"],"a":2,"ex":"A23 is <strong>Low-flying aircraft</strong> (Swedish: <i lang=\"sv\">Varning för lågt flygande flygplan</i>). Warns of low-flying aircraft, for example near the end of a runway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A23"],"gen":"sign"},{"id":"sign-A24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A24-1\" alt=\"A24 Side wind\" width=\"64\" height=\"64\"></div>","opts":["Slippery road","Two-way traffic","Side wind","Roundabout ahead"],"a":2,"ex":"A24 is <strong>Side wind</strong> (Swedish: <i lang=\"sv\">Varning för sidvind</i>). Warns of a stretch of road where strong side winds are common. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A24"],"gen":"sign"},{"id":"sign-A25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A25-1\" alt=\"A25 Two-way traffic\" width=\"64\" height=\"64\"></div>","opts":["Crossroads (right-hand rule)","Two-way traffic","Soft verge or high road edge","Opening bridge"],"a":1,"ex":"A25 is <strong>Two-way traffic</strong> (Swedish: <i lang=\"sv\">Varning för mötande trafik</i>). Warns that a carriageway with one-way traffic becomes a carriageway with traffic in both directions.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A25"],"gen":"sign"},{"id":"sign-A26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A26-1\" alt=\"A26 Tunnel\" width=\"64\" height=\"64\"></div>","opts":["Low-flying aircraft","Tunnel","Tramway crossing without barriers","Skiers"],"a":1,"ex":"A26 is <strong>Tunnel</strong> (Swedish: <i lang=\"sv\">Varning för tunnel</i>). Warns of a tunnel ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A26"],"gen":"sign"},{"id":"sign-A27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A27-1\" alt=\"A27 Soft verge or high road edge\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing ahead","Pedestrians","Soft verge or high road edge","Low-flying aircraft"],"a":2,"ex":"A27 is <strong>Soft verge or high road edge</strong> (Swedish: <i lang=\"sv\">Varning för svag vägkant eller hög körbanekant</i>). Warns of a weak road edge, or of a high step down from the edge of the carriageway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A27"],"gen":"sign"},{"id":"sign-A28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A28-1\" alt=\"A28 Crossroads (right-hand rule)\" width=\"64\" height=\"64\"></div>","opts":["Steep ascent","Crossroads (right-hand rule)","Horse-drawn vehicles","Level crossing without barriers"],"a":1,"ex":"A28 is <strong>Crossroads (right-hand rule)</strong> (Swedish: <i lang=\"sv\">Varning för vägkorsning</i>). Warns of a junction where the right-hand rule applies, that is, you must give way to vehicles coming from your right (Road Traffic Ordinance, chapter 3, section 18).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A28"],"gen":"sign"},{"id":"sign-A29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A29-1\" alt=\"A29 Junction where side roads must give way\" width=\"64\" height=\"64\"></div>","opts":["Horse riders","Junction where side roads must give way","St Andrew's cross (level crossing)","Pedestrians"],"a":1,"ex":"A29 is <strong>Junction where side roads must give way</strong> (Swedish: <i lang=\"sv\">Varning för vägkorsning där trafikanter på anslutande väg har väjningsplikt eller stopplikt</i>). Warns of a junction where drivers on the side roads have to give way or stop. You are on the road with priority. The symbol shows the shape of the junction; the wide line is your road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A29"],"gen":"sign"},{"id":"sign-A30","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A30-1\" alt=\"A30 Roundabout ahead\" width=\"64\" height=\"64\"></div>","opts":["Low-flying aircraft","Tunnel","Roundabout ahead","Loose stones"],"a":2,"ex":"A30 is <strong>Roundabout ahead</strong> (Swedish: <i lang=\"sv\">Varning för cirkulationsplats</i>). Warns of a roundabout ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A30"],"gen":"sign"},{"id":"sign-A31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A31\" alt=\"A31 Slow-moving vehicles\" width=\"64\" height=\"64\"></div>","opts":["Road works","Slow-moving vehicles","Loose stones","Skiers"],"a":1,"ex":"A31 is <strong>Slow-moving vehicles</strong> (Swedish: <i lang=\"sv\">Varning för långsamtgående fordon</i>). Warns of a place where slow vehicles often cross the road or drive out onto it, for example tractors.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A31"],"gen":"sign"},{"id":"sign-A32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A32-1\" alt=\"A32 Horse-drawn vehicles\" width=\"64\" height=\"64\"></div>","opts":["Pedestrians","Horse-drawn vehicles","Children","Soft verge or high road edge"],"a":1,"ex":"A32 is <strong>Horse-drawn vehicles</strong> (Swedish: <i lang=\"sv\">Varning för fordon med förspänt dragdjur</i>). Warns of a stretch of road where vehicles pulled by animals often cross or travel on the road. Other symbols can be used.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A32"],"gen":"sign"},{"id":"sign-A33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A33-1\" alt=\"A33 Snowmobiles\" width=\"64\" height=\"64\"></div>","opts":["Level crossing without barriers","Tunnel","Snowmobiles","Several dangerous bends"],"a":2,"ex":"A33 is <strong>Snowmobiles</strong> (Swedish: <i lang=\"sv\">Varning för terrängskotertrafik</i>). Warns of a place where snowmobiles and other off-road scooters often cross the road or drive out onto it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A33"],"gen":"sign"},{"id":"sign-A34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A34-1\" alt=\"A34 Queues likely\" width=\"64\" height=\"64\"></div>","opts":["Pedestrians","Snowmobiles","Queues likely","Steep descent"],"a":2,"ex":"A34 is <strong>Queues likely</strong> (Swedish: <i lang=\"sv\">Varning för kö</i>). Warns of a stretch of road where there is a risk of queues building up.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A34"],"gen":"sign"},{"id":"sign-A35","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A35-1\" alt=\"A35 Level crossing with barriers\" width=\"64\" height=\"64\"></div>","opts":["Queues likely","Level crossing without barriers","Level crossing with barriers","Traffic signals ahead"],"a":2,"ex":"A35 is <strong>Level crossing with barriers</strong> (Swedish: <i lang=\"sv\">Varning för järnvägskorsning med bommar</i>). Warns of a crossing with a railway or tramway where there are barriers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A35"],"gen":"sign"},{"id":"sign-A36","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A36-1\" alt=\"A36 Level crossing without barriers\" width=\"64\" height=\"64\"></div>","opts":["Accident","Level crossing without barriers","Other danger","Two-way traffic"],"a":1,"ex":"A36 is <strong>Level crossing without barriers</strong> (Swedish: <i lang=\"sv\">Varning för järnvägskorsning utan bommar</i>). Warns of a railway crossing that has no barriers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A36"],"gen":"sign"},{"id":"sign-A37","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A37-1\" alt=\"A37 Tramway crossing without barriers\" width=\"64\" height=\"64\"></div>","opts":["Loose stones","Traffic signals ahead","Tramway crossing without barriers","Opening bridge"],"a":2,"ex":"A37 is <strong>Tramway crossing without barriers</strong> (Swedish: <i lang=\"sv\">Varning för korsning med spårväg utan bommar</i>). Warns of a crossing with a tramway that has no barriers.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A37"],"gen":"sign"},{"id":"sign-A39","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A39-1\" alt=\"A39 St Andrew's cross (level crossing)\" width=\"64\" height=\"64\"></div>","opts":["Loose stones","St Andrew's cross (level crossing)","Slippery road","End of road works"],"a":1,"ex":"A39 is <strong>St Andrew's cross (level crossing)</strong> (Swedish: <i lang=\"sv\">Kryssmärke</i>). Marks a crossing with a railway or tramway with one or more tracks. It is placed immediately before a level crossing. It may be left out on a private road with little traffic, where that can be done without danger. It can also be used at other crossings with a railway or tramway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A39"],"gen":"sign"},{"id":"sign-A40","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A40-1\" alt=\"A40 Other danger\" width=\"64\" height=\"64\"></div>","opts":["Side wind","Other danger","Animals","Loose stones"],"a":1,"ex":"A40 is <strong>Other danger</strong> (Swedish: <i lang=\"sv\">Varning för annan fara</i>). Warns of a danger that no other warning sign covers. An additional panel below it says what the danger is.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A40"],"gen":"sign"},{"id":"sign-A41","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"warning-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"A41\" alt=\"A41 Accident\" width=\"64\" height=\"64\"></div>","opts":["Several dangerous bends","Accident","Slow-moving vehicles","Opening bridge"],"a":1,"ex":"A41 is <strong>Accident</strong> (Swedish: <i lang=\"sv\">Varning för olycka</i>). Warns that there has been a traffic accident on the road ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P5\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 5 §\">VMF 2 kap. 5 §</a>"],"signs":["A41"],"gen":"sign"},{"id":"sign-B1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B1-1\" alt=\"B1 Give way\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing","Give way","End of main road","Main road"],"a":1,"ex":"B1 is <strong>Give way</strong> (Swedish: <i lang=\"sv\">Väjningsplikt</i>). You must give way to vehicles on the road or route you are about to cross or enter. Chapter 3, section 5 of the Road Traffic Ordinance applies – show clearly in good time that you will give way by slowing down or stopping, and go on only when it causes no danger or obstruction. With additional panel T2 (distance) it warns in advance of a give-way point; with T3 it warns in advance of a stop sign. Panel T13 means that all roads into the junction have to give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B1"],"gen":"sign"},{"id":"sign-B2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B2-1\" alt=\"B2 Stop\" width=\"64\" height=\"64\"></div>","opts":["End of main road","Stop","Pedestrian crossing","Cycle crossing"],"a":1,"ex":"B2 is <strong>Stop</strong> (Swedish: <i lang=\"sv\">Stopplikt</i>). You must stop before you drive into the crossing road, route or track area. Chapter 3, section 19 of the Road Traffic Ordinance applies – stop at the stop line, or if there is none, immediately before you enter the crossing road. Panel T14 means that all roads into the junction must stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B2"],"gen":"sign"},{"id":"sign-B3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B3-1\" alt=\"B3 Pedestrian crossing\" width=\"64\" height=\"64\"></div>","opts":["Main road","Pedestrian crossing","Cycle crossing","Oncoming traffic must give way"],"a":1,"ex":"B3 is <strong>Pedestrian crossing</strong> (Swedish: <i lang=\"sv\">Övergångsställe</i>). Marks a pedestrian crossing. The two versions mean exactly the same and can be used alone or together. At an unguarded crossing (one without traffic lights or police), drivers must give way to pedestrians who are on the crossing or about to step onto it, and pedestrians must take account of the distance and speed of approaching vehicles.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B3"],"gen":"sign"},{"id":"sign-B4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B4-1\" alt=\"B4 Main road\" width=\"64\" height=\"64\"></div>","opts":["Oncoming traffic must give way","End of main road","Main road","Pedestrian crossing"],"a":2,"ex":"B4 is <strong>Main road</strong> (Swedish: <i lang=\"sv\">Huvudled</i>). Marks the start of a main road (priority road). Traffic coming onto it from side roads must give way. The sign is repeated after each junction, unless it is clear anyway that the main road continues. Exits from places such as car parks, petrol stations and private property do not count as junctions here.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B4"],"gen":"sign"},{"id":"sign-B5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B5-1\" alt=\"B5 End of main road\" width=\"64\" height=\"64\"></div>","opts":["Main road","End of main road","Give way to oncoming traffic","Stop"],"a":1,"ex":"B5 is <strong>End of main road</strong> (Swedish: <i lang=\"sv\">Huvudled upphör</i>). Marks the end of a main road (priority road). After this sign you no longer have priority over side roads because of the main road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B5"],"gen":"sign"},{"id":"sign-B6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B6-1\" alt=\"B6 Give way to oncoming traffic\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian crossing","Cycle crossing","Give way to oncoming traffic","Stop"],"a":2,"ex":"B6 is <strong>Give way to oncoming traffic</strong> (Swedish: <i lang=\"sv\">Väjningsplikt mot mötande trafik</i>). You may not drive into the stretch ahead (often a narrow section) if doing so would hinder vehicles coming towards you. Let them pass first.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B6"],"gen":"sign"},{"id":"sign-B7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B7-1\" alt=\"B7 Oncoming traffic must give way\" width=\"64\" height=\"64\"></div>","opts":["Main road","Oncoming traffic must give way","Stop","Give way to oncoming traffic"],"a":1,"ex":"B7 is <strong>Oncoming traffic must give way</strong> (Swedish: <i lang=\"sv\">Mötande trafik har väjningsplikt</i>). You have priority over oncoming traffic on the narrow stretch ahead. Drivers coming towards you must give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B7"],"gen":"sign"},{"id":"sign-B8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"B8-1\" alt=\"B8 Cycle crossing\" width=\"64\" height=\"64\"></div>","opts":["Stop","End of main road","Cycle crossing","Give way to oncoming traffic"],"a":2,"ex":"B8 is <strong>Cycle crossing</strong> (Swedish: <i lang=\"sv\">Cykelöverfart</i>). Marks a cycle crossing (cykelöverfart). Drivers must give way to cyclists and riders of class II mopeds who are on the crossing or about to ride onto it. Cyclists must take account of the distance and speed of approaching vehicles.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 6 §\">VMF 2 kap. 6 §</a>"],"signs":["B8"],"gen":"sign"},{"id":"sign-C1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C1-1\" alt=\"C1 No entry\" width=\"64\" height=\"64\"></div>","opts":["No off-road vehicles","No entry","Stop for the reason given","No horse-drawn vehicles"],"a":1,"ex":"C1 is <strong>No entry</strong> (Swedish: <i lang=\"sv\">Förbud mot infart med fordon</i>). Driving any vehicle into the road from this direction is prohibited. It is used, for example, at the far end of a one-way street.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C1"],"gen":"sign"},{"id":"sign-C2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C2-1\" alt=\"C2 No vehicles\" width=\"64\" height=\"64\"></div>","opts":["No pedestrians","No motorcycles or class I mopeds","No vehicles","No motor vehicles (except class II mopeds)"],"a":2,"ex":"C2 is <strong>No vehicles</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med fordon</i>). Traffic with all vehicles is prohibited, in both directions.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C2"],"gen":"sign"},{"id":"sign-C3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C3-1\" alt=\"C3 No motor vehicles (except class II mopeds)\" width=\"64\" height=\"64\"></div>","opts":["No motorcycles or class I mopeds","No motor vehicles with more than two wheels","No motor vehicles (except class II mopeds)","No vehicles"],"a":2,"ex":"C3 is <strong>No motor vehicles (except class II mopeds)</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med annat motordrivet fordon än moped klass II</i>). Traffic with motor vehicles other than class II mopeds is prohibited. If class II mopeds are also prohibited, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C3"],"gen":"sign"},{"id":"sign-C4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C4-1\" alt=\"C4 No motor vehicles with more than two wheels\" width=\"64\" height=\"64\"></div>","opts":["End of temporary speed limit","End of no overtaking","No motor vehicles with more than two wheels","Special rules for stopping and parking"],"a":2,"ex":"C4 is <strong>No motor vehicles with more than two wheels</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med motordrivet fordon med fler än två hjul</i>). Traffic with motor vehicles that have more than two wheels is prohibited – for example cars. Two-wheeled motorcycles and mopeds may still use the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C4"],"gen":"sign"},{"id":"sign-C5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C5-1\" alt=\"C5 No motorcycles or class I mopeds\" width=\"64\" height=\"64\"></div>","opts":["End of no overtaking","No motorcycles or class I mopeds","No motor vehicles with more than two wheels","No vehicles"],"a":1,"ex":"C5 is <strong>No motorcycles or class I mopeds</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med motorcykel och moped klass I</i>). Traffic with motorcycles and class I mopeds is prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C5"],"gen":"sign"},{"id":"sign-C6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C6-1\" alt=\"C6 No motor vehicles with a trailer\" width=\"64\" height=\"64\"></div>","opts":["No stopping or parking","Date parking","No motor vehicles with a trailer","No pedestrians"],"a":2,"ex":"C6 is <strong>No motor vehicles with a trailer</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med motordrivet fordon med tillkopplad släpvagn</i>). Traffic with motor vehicles towing a trailer is prohibited. The ban does not cover semi-trailers or light single-axle trailers of the kind called släpkärra unless a panel says so. If the ban only covers combinations whose trailer weighs more than a certain total weight, panel T5 shows that weight.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C6"],"gen":"sign"},{"id":"sign-C7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C7-1\" alt=\"C7 No heavy trucks\" width=\"64\" height=\"64\"></div>","opts":["No horse-drawn vehicles","No heavy trucks","End of turning place","No vehicles"],"a":1,"ex":"C7 is <strong>No heavy trucks</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med tung lastbil</i>). Traffic with heavy trucks (total weight over 3,500 kg) is prohibited. If the ban also covers light trucks, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C7"],"gen":"sign"},{"id":"sign-C8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C8-1\" alt=\"C8 No tractors or class II motor implements\" width=\"64\" height=\"64\"></div>","opts":["Width limit","No tractors or class II motor implements","No motor vehicles (except class II mopeds)","No horse riding"],"a":1,"ex":"C8 is <strong>No tractors or class II motor implements</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med traktor och motorredskap klass II</i>). Traffic with tractors (class a) and class II motor implements (machines built for at most 30 km/h) is prohibited. If the ban also covers class b tractors or class I motor implements, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C8"],"gen":"sign"},{"id":"sign-C9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C9-1\" alt=\"C9 No vehicles carrying dangerous goods\" width=\"64\" height=\"64\"></div>","opts":["No vehicles","No vehicles carrying dangerous goods","Bearing capacity class","No off-road vehicles"],"a":1,"ex":"C9 is <strong>No vehicles carrying dangerous goods</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med fordon lastat med farligt gods</i>). Traffic with vehicles carrying a load that must be marked with orange plates under the rules on transport of dangerous goods is prohibited. With panel T23 the sign shows the category of a road tunnel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C9"],"gen":"sign"},{"id":"sign-C10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C10-1\" alt=\"C10 No cycles or class II mopeds\" width=\"64\" height=\"64\"></div>","opts":["No heavy trucks","Special-purpose place","No cycles or class II mopeds","Minimum distance"],"a":2,"ex":"C10 is <strong>No cycles or class II mopeds</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med cykel och moped klass II</i>). Traffic with bicycles and class II mopeds is prohibited. If class I mopeds are also banned, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C10"],"gen":"sign"},{"id":"sign-C11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C11-1\" alt=\"C11 No class II mopeds\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with more than two wheels","No class II mopeds","End of turning place","Weight limit for a vehicle or combination"],"a":1,"ex":"C11 is <strong>No class II mopeds</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med moped klass II</i>). Traffic with class II mopeds is prohibited. If class I mopeds are also banned, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C11"],"gen":"sign"},{"id":"sign-C12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C12-1\" alt=\"C12 No horse-drawn vehicles\" width=\"64\" height=\"64\"></div>","opts":["No vehicles","No horse-drawn vehicles","No parking on even dates","Minimum distance"],"a":1,"ex":"C12 is <strong>No horse-drawn vehicles</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med fordon förspänt med dragdjur</i>). Traffic with vehicles pulled by animals is prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C12"],"gen":"sign"},{"id":"sign-C13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C13-1\" alt=\"C13 No off-road vehicles\" width=\"64\" height=\"64\"></div>","opts":["No motorcycles or class I mopeds","No parking","No off-road vehicles","No vehicles"],"a":2,"ex":"C13 is <strong>No off-road vehicles</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med terrängmotorfordon och terrängsläp</i>). Traffic with off-road motor vehicles (such as snowmobiles) and off-road trailers is prohibited. If the ban does not cover terrain vehicles over 450 kg (terrängvagn), a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C13"],"gen":"sign"},{"id":"sign-C14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C14-1\" alt=\"C14 No horse riding\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles (except class II mopeds)","No horse riding","Special rules for stopping and parking","No class II mopeds"],"a":1,"ex":"C14 is <strong>No horse riding</strong> (Swedish: <i lang=\"sv\">Förbud mot ridning</i>). Riding is prohibited. If leading a horse is also prohibited, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C14"],"gen":"sign"},{"id":"sign-C15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C15-1\" alt=\"C15 No pedestrians\" width=\"64\" height=\"64\"></div>","opts":["End of turning place","No pedestrians","No motor vehicles with more than two wheels","No motor vehicles with studded tyres"],"a":1,"ex":"C15 is <strong>No pedestrians</strong> (Swedish: <i lang=\"sv\">Förbud mot gångtrafik</i>). Pedestrian traffic is prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C15"],"gen":"sign"},{"id":"sign-C16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C16-1\" alt=\"C16 Width limit\" width=\"64\" height=\"64\"></div>","opts":["No horse-drawn vehicles","Width limit","No pedestrians","No U-turns"],"a":1,"ex":"C16 is <strong>Width limit</strong> (Swedish: <i lang=\"sv\">Begränsad fordonsbredd</i>). Vehicles wider than the width shown on the sign are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C16"],"gen":"sign"},{"id":"sign-C17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C17-1\" alt=\"C17 Height limit\" width=\"64\" height=\"64\"></div>","opts":["Bearing capacity class","Triple axle load limit","Height limit","Weight limit for a vehicle or combination"],"a":2,"ex":"C17 is <strong>Height limit</strong> (Swedish: <i lang=\"sv\">Begränsad fordonshöjd</i>). Vehicles higher than the height shown on the sign are prohibited. It is used where the free height is less than 4.5 metres.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C17"],"gen":"sign"},{"id":"sign-C18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C18-1\" alt=\"C18 Length limit\" width=\"64\" height=\"64\"></div>","opts":["No heavy trucks","Length limit","Minimum distance","Triple axle load limit"],"a":1,"ex":"C18 is <strong>Length limit</strong> (Swedish: <i lang=\"sv\">Begränsad fordonslängd</i>). Vehicles or vehicle combinations longer than the length shown on the sign are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C18"],"gen":"sign"},{"id":"sign-C19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C19-1\" alt=\"C19 Minimum distance\" width=\"64\" height=\"64\"></div>","opts":["End of turning place","Minimum distance","Date parking","No horse riding"],"a":1,"ex":"C19 is <strong>Minimum distance</strong> (Swedish: <i lang=\"sv\">Minsta avstånd</i>). It is prohibited to keep a shorter distance than the one shown to the motor vehicle in front of you going in the same direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C19"],"gen":"sign"},{"id":"sign-C20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C20-1\" alt=\"C20 Weight limit for a vehicle\" width=\"64\" height=\"64\"></div>","opts":["No class II mopeds","No cycles or class II mopeds","Weight limit for a vehicle","No motor vehicles with more than two wheels"],"a":2,"ex":"C20 is <strong>Weight limit for a vehicle</strong> (Swedish: <i lang=\"sv\">Begränsad bruttovikt på fordon</i>). Vehicles whose gross weight (the actual weight at that moment, load included) is higher than the weight shown are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C20"],"gen":"sign"},{"id":"sign-C21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C21-1\" alt=\"C21 Weight limit for a vehicle or combination\" width=\"64\" height=\"64\"></div>","opts":["End of no overtaking by heavy trucks","Weight limit for a vehicle or combination","No vehicles","Minimum distance"],"a":1,"ex":"C21 is <strong>Weight limit for a vehicle or combination</strong> (Swedish: <i lang=\"sv\">Begränsad bruttovikt på fordon och fordonståg</i>). Vehicles and vehicle combinations whose gross weight (actual weight, load included) is higher than the weight shown are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C21"],"gen":"sign"},{"id":"sign-C23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C23-1\" alt=\"C23 Axle load limit\" width=\"64\" height=\"64\"></div>","opts":["Bearing capacity class","Axle load limit","No overtaking","Speed limit"],"a":1,"ex":"C23 is <strong>Axle load limit</strong> (Swedish: <i lang=\"sv\">Begränsat axeltryck</i>). The highest axle load allowed (the weight the wheels on one axle put on the road) is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C23"],"gen":"sign"},{"id":"sign-C24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C24-1\" alt=\"C24 Bogie load limit\" width=\"64\" height=\"64\"></div>","opts":["No U-turns","Date parking","Bogie load limit","No off-road vehicles"],"a":2,"ex":"C24 is <strong>Bogie load limit</strong> (Swedish: <i lang=\"sv\">Begränsat boggitryck</i>). The highest bogie load allowed (the weight that two axles less than 2 metres apart put on the road) is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C24"],"gen":"sign"},{"id":"sign-C25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C25-1\" alt=\"C25 No turning\" width=\"64\" height=\"64\"></div>","opts":["No cycles or class II mopeds","No motor vehicles with more than two wheels","No turning","End of turning place"],"a":2,"ex":"C25 is <strong>No turning</strong> (Swedish: <i lang=\"sv\">Förbud mot sväng i korsning</i>). Turning in the direction shown is prohibited at the junction (or similar place) where the sign stands or that it is placed before. It can cover several junctions; the length of the stretch is then shown on a panel. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C25"],"gen":"sign"},{"id":"sign-C26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C26-1\" alt=\"C26 No U-turns\" width=\"64\" height=\"64\"></div>","opts":["Stop for the reason given","No U-turns","Speed limit","No vehicles"],"a":1,"ex":"C26 is <strong>No U-turns</strong> (Swedish: <i lang=\"sv\">Förbud mot U-sväng</i>). U-turns are prohibited at the junction (or similar place) where the sign stands or that it is placed before. It can cover several junctions; the length of the stretch is then shown on a panel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C26"],"gen":"sign"},{"id":"sign-C27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C27-1\" alt=\"C27 No overtaking\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","No overtaking","No overtaking by heavy trucks","End of no overtaking"],"a":1,"ex":"C27 is <strong>No overtaking</strong> (Swedish: <i lang=\"sv\">Förbud mot omkörning</i>). It is prohibited to overtake motor vehicles other than two-wheeled mopeds and two-wheeled motorcycles without a sidecar. The ban applies on the road where the sign is placed, until sign C28 (end of no overtaking).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C27"],"gen":"sign"},{"id":"sign-C28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C28-1\" alt=\"C28 End of no overtaking\" width=\"64\" height=\"64\"></div>","opts":["Special-purpose place","End of no overtaking","No parking","No off-road vehicles"],"a":1,"ex":"C28 is <strong>End of no overtaking</strong> (Swedish: <i lang=\"sv\">Slut på förbud mot omkörning</i>). Marks the end of the overtaking ban that started with sign C27.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C28"],"gen":"sign"},{"id":"sign-C29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C29-1\" alt=\"C29 No overtaking by heavy trucks\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with more than two wheels","No overtaking by heavy trucks","Special rules for stopping and parking","No motor vehicles (except class II mopeds)"],"a":1,"ex":"C29 is <strong>No overtaking by heavy trucks</strong> (Swedish: <i lang=\"sv\">Förbud mot omkörning med tung lastbil</i>). Drivers of heavy trucks may not overtake motor vehicles other than two-wheeled mopeds and two-wheeled motorcycles without a sidecar. The ban applies until sign C30.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C29"],"gen":"sign"},{"id":"sign-C30","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C30-1\" alt=\"C30 End of no overtaking by heavy trucks\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","End of no overtaking by heavy trucks","No motorcycles or class I mopeds","No vehicles"],"a":1,"ex":"C30 is <strong>End of no overtaking by heavy trucks</strong> (Swedish: <i lang=\"sv\">Slut på förbud mot omkörning med tung lastbil</i>). Marks the end of the overtaking ban for heavy trucks that started with sign C29.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C30"],"gen":"sign"},{"id":"sign-C31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C31-3\" alt=\"C31 Speed limit\" width=\"64\" height=\"64\"></div>","opts":["Axle load limit","Special rules for stopping and parking","Speed limit","No horse riding"],"a":2,"ex":"C31 is <strong>Speed limit</strong> (Swedish: <i lang=\"sv\">Hastighetsbegränsning</i>). You may not drive faster than the speed shown, in km/h. The limit applies until another speed limit sign, sign C32 (end of temporary speed limit), sign E7 (pedestrian street) or sign E9 (walking-speed area). The sign does not have to be repeated after a junction if the crossing road has the same limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C31"],"gen":"sign"},{"id":"sign-C32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C32-3\" alt=\"C32 End of temporary speed limit\" width=\"64\" height=\"64\"></div>","opts":["Weight limit for a vehicle or combination","End of temporary speed limit","Bearing capacity class","No vehicles"],"a":1,"ex":"C32 is <strong>End of temporary speed limit</strong> (Swedish: <i lang=\"sv\">Tillfällig hastighetsbegränsning upphör</i>). Marks the end of a temporary speed limit that was shown with sign C31. After it, the speed limit that applied before the temporary limit applies again.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C32"],"gen":"sign"},{"id":"sign-C33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C33-1\" alt=\"C33 Stop at customs\" width=\"64\" height=\"64\"></div>","opts":["No heavy trucks","No motor vehicles with more than two wheels","Stop at customs","No motor vehicles with studded tyres"],"a":2,"ex":"C33 is <strong>Stop at customs</strong> (Swedish: <i lang=\"sv\">Stopp vid tull</i>). You must stop for customs formalities, at the stop line or, if there is none, at the sign. The text below the bar is given in a suitable language.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C33"],"gen":"sign"},{"id":"sign-C34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C34\" alt=\"C34 Stop for the reason given\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with studded tyres","Stop for the reason given","Bearing capacity class","Special-purpose place"],"a":1,"ex":"C34 is <strong>Stop for the reason given</strong> (Swedish: <i lang=\"sv\">Stopp för angivet ändamål</i>). You must stop for the reason written below the bar – at the stop line or, if there is none, at the sign. If the sign stands before a traffic signal (STOPP SIGNAL), vehicles that are to pass the signal must stop when it shows red.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C34"],"gen":"sign"},{"id":"sign-C35","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C35-1\" alt=\"C35 No parking\" width=\"64\" height=\"64\"></div>","opts":["No overtaking","End of no overtaking by heavy trucks","No parking","No stopping or parking"],"a":2,"ex":"C35 is <strong>No parking</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera fordon</i>). Parking is prohibited on the side of the road where the sign stands. The ban starts at the sign and applies as shown on a panel, or until another stopping or parking rule is signed, until the next junction, or until a matching sign with panel T11 (arrow pointing down). If another rule applies on a shorter stretch, the ban applies again after it without a new sign. The sign does not give you the right to stop where stopping is prohibited by the Road Traffic Ordinance.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C35"],"gen":"sign"},{"id":"sign-C36","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C36-1\" alt=\"C36 No parking on odd dates\" width=\"64\" height=\"64\"></div>","opts":["No U-turns","No parking on odd dates","Turning place","Bogie load limit"],"a":1,"ex":"C36 is <strong>No parking on odd dates</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera fordon på dag med udda datum</i>). Parking is prohibited on days with an odd date (1st, 3rd, 5th …). Otherwise the same rules as for sign C35 apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C36"],"gen":"sign"},{"id":"sign-C37","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C37-1\" alt=\"C37 No parking on even dates\" width=\"64\" height=\"64\"></div>","opts":["Weight limit for a vehicle","No motor vehicles with more than two wheels","No parking on even dates","No cycles or class II mopeds"],"a":2,"ex":"C37 is <strong>No parking on even dates</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera fordon på dag med jämnt datum</i>). Parking is prohibited on days with an even date (2nd, 4th, 6th …). Otherwise the same rules as for sign C35 apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C37"],"gen":"sign"},{"id":"sign-C38","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C38-1\" alt=\"C38 Date parking\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","Date parking","No heavy trucks","No U-turns"],"a":1,"ex":"C38 is <strong>Date parking</strong> (Swedish: <i lang=\"sv\">Datumparkering</i>). Parking is prohibited on days with an even date on the side of the road with even house numbers, and on days with an odd date on the side with odd house numbers. Otherwise the same rules as for sign C35 apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C38"],"gen":"sign"},{"id":"sign-C39","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C39-1\" alt=\"C39 No stopping or parking\" width=\"64\" height=\"64\"></div>","opts":["No parking","No stopping or parking","No heavy trucks","No vehicles"],"a":1,"ex":"C39 is <strong>No stopping or parking</strong> (Swedish: <i lang=\"sv\">Förbud mot att stanna och parkera fordon</i>). Both stopping and parking are prohibited. The same rules as for sign C35 apply to where the ban starts and ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C39"],"gen":"sign"},{"id":"sign-C40","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C40-1\" alt=\"C40 Special-purpose place\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with a trailer","Special-purpose place","No horse riding","No vehicles"],"a":1,"ex":"C40 is <strong>Special-purpose place</strong> (Swedish: <i lang=\"sv\">Ändamålsplats</i>). A place reserved for a stated purpose. Vehicles may not park or stop there except for that purpose, but may stop briefly to let people get in or out if this does not hinder the purpose. If the purpose is given as lastplats, it means loading or unloading of heavy or bulky goods.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C40"],"gen":"sign"},{"id":"sign-C42","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C42-1\" alt=\"C42 Turning place\" width=\"64\" height=\"64\"></div>","opts":["Bogie load limit","Turning place","No horse-drawn vehicles","No motor vehicles with more than two wheels"],"a":1,"ex":"C42 is <strong>Turning place</strong> (Swedish: <i lang=\"sv\">Vändplats</i>). Marks a place meant for turning vehicles around, where parking is prohibited. If the no-stopping symbol (C39) is shown in the sign instead, both stopping and parking are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C42"],"gen":"sign"},{"id":"sign-C44","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C44\" alt=\"C44 No motor vehicles with studded tyres\" width=\"64\" height=\"64\"></div>","opts":["No parking","End of temporary speed limit","No motor vehicles with studded tyres","No motor vehicles (except class II mopeds)"],"a":2,"ex":"C44 is <strong>No motor vehicles with studded tyres</strong> (Swedish: <i lang=\"sv\">Förbud mot trafik med annat motordrivet fordon med dubbdäck än moped klass II</i>). Traffic with motor vehicles that have studded tyres is prohibited, except class II mopeds. If class II mopeds are also banned, a panel says so.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C44"],"gen":"sign"},{"id":"sign-C46","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"prohibitory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"C46\" alt=\"C46 Triple axle load limit\" width=\"64\" height=\"64\"></div>","opts":["No motor vehicles with more than two wheels","Triple axle load limit","No overtaking","No cycles or class II mopeds"],"a":1,"ex":"C46 is <strong>Triple axle load limit</strong> (Swedish: <i lang=\"sv\">Begränsat trippelaxeltryck</i>). The highest triple axle load allowed (the weight that three axles close together put on the road) is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P8\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 8 §\">VMF 2 kap. 8 §</a>"],"signs":["C46"],"gen":"sign"},{"id":"sign-D1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D1-1\" alt=\"D1 Mandatory direction\" width=\"64\" height=\"64\"></div>","opts":["Footpath","Mandatory direction","Mandatory direction for vehicles with dangerous goods","Cycle track"],"a":1,"ex":"D1 is <strong>Mandatory direction</strong> (Swedish: <i lang=\"sv\">Påbjuden körriktning</i>). Vehicles may only be driven in the direction of the arrow, or, where there are two arrows, in the direction of either arrow. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D1"],"gen":"sign"},{"id":"sign-D2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D2-1\" alt=\"D2 Pass this side\" width=\"64\" height=\"64\"></div>","opts":["Bus lane","Pass this side","Cycle track","Footpath"],"a":1,"ex":"D2 is <strong>Pass this side</strong> (Swedish: <i lang=\"sv\">Påbjuden körbana</i>). Vehicles may only pass the sign on the side the arrow points to, or where there are two arrows, on either side. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D2"],"gen":"sign"},{"id":"sign-D3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D3-1\" alt=\"D3 Roundabout\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Bus lane","Roundabout","Separated paths for pedestrians and cyclists"],"a":2,"ex":"D3 is <strong>Roundabout</strong> (Swedish: <i lang=\"sv\">Cirkulationsplats</i>). Marks a roundabout (cirkulationsplats). Drive anticlockwise around the centre, and give way to every vehicle already in the roundabout when you enter.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D3"],"gen":"sign"},{"id":"sign-D4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D4-1\" alt=\"D4 Cycle track\" width=\"64\" height=\"64\"></div>","opts":["Footpath","Cycle track","Pass this side","Roundabout"],"a":1,"ex":"D4 is <strong>Cycle track</strong> (Swedish: <i lang=\"sv\">Påbjuden cykelbana</i>). Marks a track for cyclists (and class II mopeds unless a panel says otherwise). Other traffic is not allowed on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D4"],"gen":"sign"},{"id":"sign-D5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D5-1\" alt=\"D5 Footpath\" width=\"64\" height=\"64\"></div>","opts":["End of compulsory path, lane or route","Footpath","Cycle track","Separated paths for pedestrians and cyclists"],"a":1,"ex":"D5 is <strong>Footpath</strong> (Swedish: <i lang=\"sv\">Påbjuden gångbana</i>). Marks a path for pedestrians only.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D5"],"gen":"sign"},{"id":"sign-D6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D6-1\" alt=\"D6 Shared path for pedestrians and cyclists\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Shared path for pedestrians and cyclists","Footpath","Cycle track"],"a":1,"ex":"D6 is <strong>Shared path for pedestrians and cyclists</strong> (Swedish: <i lang=\"sv\">Påbjuden gång- och cykelbana</i>). Marks a path shared by pedestrians and cyclists (and class II mopeds unless a panel says otherwise).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D6"],"gen":"sign"},{"id":"sign-D7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D7-1\" alt=\"D7 Separated paths for pedestrians and cyclists\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Cycle track","Separated paths for pedestrians and cyclists","Bridle path"],"a":2,"ex":"D7 is <strong>Separated paths for pedestrians and cyclists</strong> (Swedish: <i lang=\"sv\">Påbjudna gång- och cykelbanor</i>). Marks paths that are divided by a road marking, kerb or similar into one part for pedestrians and one for cyclists. The position of the symbols on the sign shows which side is for whom. Class II mopeds may use the cycle part unless a panel says otherwise.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D7"],"gen":"sign"},{"id":"sign-D8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D8-1\" alt=\"D8 Bridle path\" width=\"64\" height=\"64\"></div>","opts":["Mandatory direction for vehicles with dangerous goods","Bridle path","Shared path for pedestrians and cyclists","End of compulsory path, lane or route"],"a":1,"ex":"D8 is <strong>Bridle path</strong> (Swedish: <i lang=\"sv\">Påbjuden ridväg</i>). Marks a path for horse riding. Walking is also allowed on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D8"],"gen":"sign"},{"id":"sign-D9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D9-1\" alt=\"D9 Route for off-road vehicles\" width=\"64\" height=\"64\"></div>","opts":["Pass this side","Route for off-road vehicles","Cycle track","End of compulsory path, lane or route"],"a":1,"ex":"D9 is <strong>Route for off-road vehicles</strong> (Swedish: <i lang=\"sv\">Påbjuden led för terrängmotorfordon och terrängsläp</i>). Marks a route for off-road motor vehicles (such as snowmobiles) and off-road trailers. Walking is also allowed on it.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D9"],"gen":"sign"},{"id":"sign-D10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D10-1\" alt=\"D10 Bus lane\" width=\"64\" height=\"64\"></div>","opts":["Shared path for pedestrians and cyclists","Mandatory direction for vehicles with dangerous goods","Bus lane","Route for off-road vehicles"],"a":2,"ex":"D10 is <strong>Bus lane</strong> (Swedish: <i lang=\"sv\">Påbjudet körfält eller körbana för fordon i linjetrafik med flera</i>). Marks a lane or carriageway for vehicles in scheduled services (buses) and the others allowed by the Road Traffic Ordinance – bicycles and class II mopeds may use it if it is on the right-hand side. A panel can allow other vehicles, such as taxis.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D10"],"gen":"sign"},{"id":"sign-D11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"mandatory-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"D11-1\" alt=\"D11 End of compulsory path, lane or route\" width=\"64\" height=\"64\"></div>","opts":["Cycle track","End of compulsory path, lane or route","Roundabout","Pass this side"],"a":1,"ex":"D11 is <strong>End of compulsory path, lane or route</strong> (Swedish: <i lang=\"sv\">Slut på påbjuden bana, körfält, väg eller led</i>). Marks the end of a path, lane, road or route marked with one of the signs D4–D10. It is left out if it is clear anyway that the rule has ended. The symbol in it is the same as on the sign that started the stretch.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P10\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 10 §\">VMF 2 kap. 10 §</a>"],"signs":["D11"],"gen":"sign"},{"id":"sign-E1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E-11\" alt=\"E1 Motorway\" width=\"64\" height=\"64\"></div>","opts":["End of expressway","Motorway","Emergency exit","Automatic traffic surveillance"],"a":1,"ex":"E1 is <strong>Motorway</strong> (Swedish: <i lang=\"sv\">Motorväg</i>). Marks the start of a motorway (motorväg), where the special motorway rules apply. Used as an advance notice, a panel gives the distance to where the motorway begins. The sign can also appear inside a direction sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E1"],"gen":"sign"},{"id":"sign-E2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E2-1\" alt=\"E2 End of motorway\" width=\"64\" height=\"64\"></div>","opts":["Zone sign","Environmental zone","End of motorway","Pedestrian street"],"a":2,"ex":"E2 is <strong>End of motorway</strong> (Swedish: <i lang=\"sv\">Motorväg upphör</i>). Marks the end of a motorway. Used as an advance notice, a panel gives the distance. It is not used where a motorway turns into an expressway (motortrafikled).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E2"],"gen":"sign"},{"id":"sign-E3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E3-1\" alt=\"E3 Expressway\" width=\"64\" height=\"64\"></div>","opts":["Taxi rank","Expressway","One-way traffic","End of motorway"],"a":1,"ex":"E3 is <strong>Expressway</strong> (Swedish: <i lang=\"sv\">Motortrafikled</i>). Marks the start of an expressway (motortrafikled) – a road for fast motor traffic with no level junctions, where most motorway rules apply. Used as an advance notice, a panel gives the distance. The sign can also appear inside a direction sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E3"],"gen":"sign"},{"id":"sign-E4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E4-1\" alt=\"E4 End of expressway\" width=\"64\" height=\"64\"></div>","opts":["Built-up area","End of expressway","End of motorway","Recommended lower speed"],"a":1,"ex":"E4 is <strong>End of expressway</strong> (Swedish: <i lang=\"sv\">Motortrafikled upphör</i>). Marks the end of an expressway. Used as an advance notice, a panel gives the distance. It is not used where an expressway turns into a motorway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E4"],"gen":"sign"},{"id":"sign-E5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E5-1\" alt=\"E5 Built-up area\" width=\"64\" height=\"64\"></div>","opts":["Recommended lower speed","End of pedestrian street","Built-up area","End of environmental zone"],"a":2,"ex":"E5 is <strong>Built-up area</strong> (Swedish: <i lang=\"sv\">Tättbebyggt område</i>). Marks the start of a built-up area (tättbebyggt område). The name of the place may be shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E5"],"gen":"sign"},{"id":"sign-E6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E6-1\" alt=\"E6 End of built-up area\" width=\"64\" height=\"64\"></div>","opts":["Zone sign","Expressway","End of built-up area","End of recommended lower speed"],"a":2,"ex":"E6 is <strong>End of built-up area</strong> (Swedish: <i lang=\"sv\">Tättbebyggt område upphör</i>). Marks the end of a built-up area. The name of the place may be shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E6"],"gen":"sign"},{"id":"sign-E7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E7-1\" alt=\"E7 Pedestrian street\" width=\"64\" height=\"64\"></div>","opts":["End of recommended lower speed","Pedestrian street","Zone sign","Passing place"],"a":1,"ex":"E7 is <strong>Pedestrian street</strong> (Swedish: <i lang=\"sv\">Gågata</i>). Marks a pedestrian street (gågata). Vehicles may drive at walking speed only, may not park, and must give way to pedestrians. Motor vehicles may only cross it, except for deliveries to shops, transport of goods or residents to and from addresses, transport of hotel guests, and transport of sick or disabled people. A panel can prohibit even that traffic.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E7"],"gen":"sign"},{"id":"sign-E8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E8-1\" alt=\"E8 End of pedestrian street\" width=\"64\" height=\"64\"></div>","opts":["Recommended maximum speed","End of pedestrian street","Environmental zone","Recommended lower speed"],"a":1,"ex":"E8 is <strong>End of pedestrian street</strong> (Swedish: <i lang=\"sv\">Gågata upphör</i>). Marks the end of a pedestrian street. It is left out if it is clear anyway where the street ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E8"],"gen":"sign"},{"id":"sign-E9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E9-1\" alt=\"E9 Walking-speed area\" width=\"64\" height=\"64\"></div>","opts":["Merging lanes (zip merge)","Walking-speed area","Taxi rank","End of motorway"],"a":1,"ex":"E9 is <strong>Walking-speed area</strong> (Swedish: <i lang=\"sv\">Gångfartsområde</i>). Marks a walking-speed area (gångfartsområde). Vehicles may drive at walking speed only, may not park, and must give way to pedestrians.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E9"],"gen":"sign"},{"id":"sign-E10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E10-1\" alt=\"E10 End of walking-speed area\" width=\"64\" height=\"64\"></div>","opts":["Emergency lay-by","End of walking-speed area","Escape route","End of motorway"],"a":1,"ex":"E10 is <strong>End of walking-speed area</strong> (Swedish: <i lang=\"sv\">Gångfartsområde upphör</i>). Marks the end of a walking-speed area. It is left out if it is clear anyway where the area ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E10"],"gen":"sign"},{"id":"sign-E11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E11-1\" alt=\"E11 Recommended lower speed\" width=\"64\" height=\"64\"></div>","opts":["End of expressway","Recommended lower speed","Emergency lay-by","Recommended maximum speed"],"a":1,"ex":"E11 is <strong>Recommended lower speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad lägre hastighet</i>). Marks a stretch or an area where special measures have been taken, or where conditions make it suitable to drive slower than the speed limit. The recommended speed is shown on the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E11"],"gen":"sign"},{"id":"sign-E12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E12-1\" alt=\"E12 End of recommended lower speed\" width=\"64\" height=\"64\"></div>","opts":["Parking","End of recommended lower speed","End of environmental zone","End of motorway"],"a":1,"ex":"E12 is <strong>End of recommended lower speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad lägre hastighet upphör</i>). Marks the end of a stretch with a recommended lower speed. It is left out if it is clear anyway where the stretch ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E12"],"gen":"sign"},{"id":"sign-E13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E13-1\" alt=\"E13 Recommended maximum speed\" width=\"64\" height=\"64\"></div>","opts":["Environmental zone","End of expressway","Recommended maximum speed","End of recommended lower speed"],"a":2,"ex":"E13 is <strong>Recommended maximum speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad högsta hastighet</i>). Used only as a variable (electronic) sign. It shows that conditions are temporarily such that it is not suitable to drive faster than the speed shown, for example because of queues, an accident or bad weather. The speed shown is always lower than the speed limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E13"],"gen":"sign"},{"id":"sign-E14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E14-1\" alt=\"E14 End of recommended maximum speed\" width=\"64\" height=\"64\"></div>","opts":["Automatic traffic surveillance","End of recommended maximum speed","End of built-up area","Environmental zone"],"a":1,"ex":"E14 is <strong>End of recommended maximum speed</strong> (Swedish: <i lang=\"sv\">Rekommenderad högsta hastighet upphör</i>). Shows that the temporary conditions behind a recommended maximum speed (E13) have ended. It is left out if that is clear anyway.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E14"],"gen":"sign"},{"id":"sign-E15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E15-1\" alt=\"E15 Merging lanes (zip merge)\" width=\"64\" height=\"64\"></div>","opts":["End of walking-speed area","Merging lanes (zip merge)","Zone sign","One-way traffic"],"a":1,"ex":"E15 is <strong>Merging lanes (zip merge)</strong> (Swedish: <i lang=\"sv\">Sammanvävning</i>). Informs that two lanes or two carriageways run together and that drivers must adapt to each other (chapter 3, section 44 of the Road Traffic Ordinance). It is also used in advance, with the distance on a panel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E15"],"gen":"sign"},{"id":"sign-E16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E16-1\" alt=\"E16 One-way traffic\" width=\"64\" height=\"64\"></div>","opts":["Special rules for parking","One-way traffic","End of built-up area","Escape route"],"a":1,"ex":"E16 is <strong>One-way traffic</strong> (Swedish: <i lang=\"sv\">Enkelriktad trafik</i>). Shows that vehicle traffic on the road goes one way only, in the direction of the arrow. An upward arrow means traffic goes one way straight ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E16"],"gen":"sign"},{"id":"sign-E17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E17-1\" alt=\"E17 Dead end\" width=\"64\" height=\"64\"></div>","opts":["End of environmental zone","Dead end","Recommended lower speed","End of built-up area"],"a":1,"ex":"E17 is <strong>Dead end</strong> (Swedish: <i lang=\"sv\">Återvändsväg E17</i>). Shows that you cannot drive through. The symbol is drawn to match the place and can be part of a direction sign. If cyclists and class II moped riders can get through, the bicycle symbol (S8) is added to the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E17"],"gen":"sign"},{"id":"sign-E18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"meeting-and-overtaking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E18-1\" alt=\"E18 Passing place\" width=\"64\" height=\"64\"></div>","opts":["Escape route","End of environmental zone","Passing place","End of built-up area"],"a":2,"ex":"E18 is <strong>Passing place</strong> (Swedish: <i lang=\"sv\">Mötesplats</i>). Marks a passing place (mötesplats) on a narrow road, where vehicles can meet or let others overtake.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E18"],"gen":"sign"},{"id":"sign-E19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E19-1\" alt=\"E19 Parking\" width=\"64\" height=\"64\"></div>","opts":["Special rules for parking","Parking","Toll road or charge","Bus stop"],"a":1,"ex":"E19 is <strong>Parking</strong> (Swedish: <i lang=\"sv\">Parkering</i>). Parking is allowed in a car park, or on a stretch on the side of the road where the sign stands. By a road, the permission starts at the sign and applies as a panel says, until another stopping or parking rule is signed, or else to the next junction. In a car park it covers the whole car park. It does not allow parking where the Road Traffic Ordinance forbids stopping or parking, and it does not allow parking longer than 24 hours in a row on weekdays on public streets and roads.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E19"],"gen":"sign"},{"id":"sign-E20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E20-1\" alt=\"E20 Zone sign\" width=\"64\" height=\"64\"></div>","opts":["Recommended lower speed","End of expressway","Zone sign","End of motorway"],"a":2,"ex":"E20 is <strong>Zone sign</strong> (Swedish: <i lang=\"sv\">Områdesmärke</i>). Marks the start of an area (zone) where the prohibition or permission shown inside the sign applies. It stands at every entrance to the area and applies until sign E21 (end of zone) or until it is otherwise clear that it no longer applies. Exceptions inside the area are shown with other signs and panels, and the zone rule applies again after them without a new sign. Times can be shown in the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E20"],"gen":"sign"},{"id":"sign-E22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E22-1\" alt=\"E22 Bus stop\" width=\"64\" height=\"64\"></div>","opts":["End of walking-speed area","Bus stop","End of motorway","End of cycle street"],"a":1,"ex":"E22 is <strong>Bus stop</strong> (Swedish: <i lang=\"sv\">Busshållplats</i>). Marks a stop for buses in scheduled service and school transport, unless the stop is clearly shown in another way. Bus lines, operators and times may be shown on or by the sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E22"],"gen":"sign"},{"id":"sign-E23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E23-1\" alt=\"E23 Taxi rank\" width=\"64\" height=\"64\"></div>","opts":["End of expressway","Taxi rank","End of recommended maximum speed","End of walking-speed area"],"a":1,"ex":"E23 is <strong>Taxi rank</strong> (Swedish: <i lang=\"sv\">Taxi</i>). Marks the far end (in the direction of travel) of a special place where taxis wait.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E23"],"gen":"sign"},{"id":"sign-E24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"speed-limits","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E24-1\" alt=\"E24 Automatic traffic surveillance\" width=\"64\" height=\"64\"></div>","opts":["Special rules for parking","Automatic traffic surveillance","Taxi rank","End of expressway"],"a":1,"ex":"E24 is <strong>Automatic traffic surveillance</strong> (Swedish: <i lang=\"sv\">Automatisk trafikövervakning</i>). Shows that automatic monitoring with a camera or similar may take place at the spot or along the stretch – to check traffic rules (for example speed), or for taxes or fees. Personal data may be recorded. For a longer stretch, the length is shown on panel T1, and the sign is repeated at suitable distances.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E24"],"gen":"sign"},{"id":"sign-E25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E25-1\" alt=\"E25 Toll road or charge\" width=\"64\" height=\"64\"></div>","opts":["End of built-up area","End of expressway","Toll road or charge","Parking"],"a":2,"ex":"E25 is <strong>Toll road or charge</strong> (Swedish: <i lang=\"sv\">Betalväg</i>). Shows that a fee or special tax must be paid to drive on a certain road or within a certain area, for example congestion tax or a bridge toll.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E25"],"gen":"sign"},{"id":"sign-E26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E26-1\" alt=\"E26 Tunnel\" width=\"64\" height=\"64\"></div>","opts":["Emergency exit","Tunnel","End of environmental zone","Merging lanes (zip merge)"],"a":1,"ex":"E26 is <strong>Tunnel</strong> (Swedish: <i lang=\"sv\">Tunnel</i>). Marks a tunnel. The length of the tunnel is shown, and its name may be shown. The sign is repeated after every kilometre, then showing the remaining length.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E26"],"gen":"sign"},{"id":"sign-E27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E27-1\" alt=\"E27 Emergency lay-by\" width=\"64\" height=\"64\"></div>","opts":["End of motorway","Escape route","Emergency lay-by","End of built-up area"],"a":2,"ex":"E27 is <strong>Emergency lay-by</strong> (Swedish: <i lang=\"sv\">Nöduppställningsplats</i>). Marks a place to stop a vehicle after a breakdown, engine failure or similar. A symbol for an emergency telephone or a fire extinguisher may be added. With a panel showing distance, it gives advance notice.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E27"],"gen":"sign"},{"id":"sign-E28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E28-1\" alt=\"E28 Emergency exit\" width=\"64\" height=\"64\"></div>","opts":["Tunnel","Emergency exit","End of built-up area","End of environmental zone"],"a":1,"ex":"E28 is <strong>Emergency exit</strong> (Swedish: <i lang=\"sv\">Nödutgång</i>). Marks an emergency exit for people on foot, for example in a tunnel.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E28"],"gen":"sign"},{"id":"sign-E29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"information-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E29-1\" alt=\"E29 Escape route\" width=\"64\" height=\"64\"></div>","opts":["Built-up area","Escape route","End of expressway","End of motorway"],"a":1,"ex":"E29 is <strong>Escape route</strong> (Swedish: <i lang=\"sv\">Utrymningsväg</i>). Shows the direction and distance to an emergency exit or similar for people on foot. The signs are placed at most 25 metres apart.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E29"],"gen":"sign"},{"id":"sign-E31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E31-1\" alt=\"E31 Environmental zone\" width=\"64\" height=\"64\"></div>","opts":["End of recommended maximum speed","Environmental zone","Emergency lay-by","Emergency exit"],"a":1,"ex":"E31 is <strong>Environmental zone</strong> (Swedish: <i lang=\"sv\">Miljözon</i>). Marks the start of an environmental zone (miljözon), where only vehicles meeting certain emission standards may be driven (Road Traffic Ordinance, chapter 4, sections 22–24 a). Class 1 covers heavy trucks and buses, class 2 covers cars, light trucks and light buses, and class 3 has the strictest rules for both groups. The zone applies until sign E6 (end of built-up area), E32 (end of zone) or another zone sign.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E31"],"gen":"sign"},{"id":"sign-E32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"environment-and-vehicles","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E32-1\" alt=\"E32 End of environmental zone\" width=\"64\" height=\"64\"></div>","opts":["Bus stop","Merging lanes (zip merge)","End of environmental zone","End of motorway"],"a":2,"ex":"E32 is <strong>End of environmental zone</strong> (Swedish: <i lang=\"sv\">Slut på miljözon</i>). Marks the end of an environmental zone.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E32"],"gen":"sign"},{"id":"sign-E33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E33-CYKELGATA\" alt=\"E33 Cycle street\" width=\"64\" height=\"64\"></div>","opts":["Expressway","Cycle street","Passing place","Parking"],"a":1,"ex":"E33 is <strong>Cycle street</strong> (Swedish: <i lang=\"sv\">Cykelgata</i>). Marks a cycle street (cykelgata). Vehicles may not drive faster than 30 km/h, may only park in specially arranged parking spaces, and drivers of motor vehicles must adapt their speed to the cyclists. A driver who comes onto a cycle street from another road must give way to vehicles on the cycle street.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E33"],"gen":"sign"},{"id":"sign-E34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"special-areas","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"E34-CYKELGATA-UPPHOR\" alt=\"E34 End of cycle street\" width=\"64\" height=\"64\"></div>","opts":["Recommended maximum speed","End of cycle street","End of expressway","Taxi rank"],"a":1,"ex":"E34 is <strong>End of cycle street</strong> (Swedish: <i lang=\"sv\">Cykelgata upphör</i>). Marks the end of a cycle street.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P12\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 12 §\">VMF 2 kap. 12 §</a>"],"signs":["E34"],"gen":"sign"},{"id":"sign-M1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M1-1\" alt=\"M1 Centre line or lane line\" width=\"64\" height=\"64\"></div>","opts":["Warning line","Yellow zigzag line","Centre line or lane line","Parking space marking"],"a":2,"ex":"M1 is <strong>Centre line or lane line</strong> (Swedish: <i lang=\"sv\">Mittlinje eller körfältslinje</i>). A broken line. As a centre line it marks the border between lanes for traffic in opposite directions; as a lane line it marks the border between lanes in the same direction. The dashes and gaps have the length ratio 1:3 or 1:1. A centre line can also mark the middle of a cycle track (ratio 1:1).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M1"],"gen":"sign"},{"id":"sign-M2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M2-1\" alt=\"M2 Edge line\" width=\"64\" height=\"64\"></div>","opts":["Purpose place marking","Bicycle symbol","Edge line","Reversible lane line"],"a":2,"ex":"M2 is <strong>Edge line</strong> (Swedish: <i lang=\"sv\">Kantlinje</i>). A broken line marking the outer edge of the carriageway. Ratio 1:2 between dash and gap.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M2"],"gen":"sign"},{"id":"sign-M3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M3-1\" alt=\"M3 Warning line\" width=\"64\" height=\"64\"></div>","opts":["Bicycle symbol","Warning line","Centre line combined with a warning line","Cycle lane line"],"a":1,"ex":"M3 is <strong>Warning line</strong> (Swedish: <i lang=\"sv\">Varningslinje</i>). A broken line with long dashes and short gaps (ratio 3:1) between lanes for opposite directions. It tells you that crossing it is unsuitable because of traffic conditions, for example poor sight ahead. It can also warn of a solid line coming up.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M3"],"gen":"sign"},{"id":"sign-M4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M4-1\" alt=\"M4 Guide line\" width=\"64\" height=\"64\"></div>","opts":["Reversible lane line","Guide line","Cycle lane line","Stop line"],"a":1,"ex":"M4 is <strong>Guide line</strong> (Swedish: <i lang=\"sv\">Ledlinje</i>). A broken line (ratio 1:1) showing a suitable path through complicated junctions, or elsewhere where guidance is needed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M4"],"gen":"sign"},{"id":"sign-M5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M5-1\" alt=\"M5 Cycle lane line\" width=\"64\" height=\"64\"></div>","opts":["Solid line","Guide line","Cycle lane line","Bicycle symbol"],"a":2,"ex":"M5 is <strong>Cycle lane line</strong> (Swedish: <i lang=\"sv\">Cykelfältslinje</i>). A broken line (ratio 1:1) marking the border between a cycle lane and another lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M5"],"gen":"sign"},{"id":"sign-M6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M6-1\" alt=\"M6 Bus lane line\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Bus lane line","Warning line","No parking (yellow broken line)"],"a":1,"ex":"M6 is <strong>Bus lane line</strong> (Swedish: <i lang=\"sv\">Linje för fordon i linjetrafik med flera</i>). A broken line (ratio 1:1) marking the border between a lane for buses in scheduled service (and others allowed) and another lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M6"],"gen":"sign"},{"id":"sign-M7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M7-1\" alt=\"M7 Reversible lane line\" width=\"64\" height=\"64\"></div>","opts":["Edge line","Reversible lane line","Solid line","Cycle box"],"a":1,"ex":"M7 is <strong>Reversible lane line</strong> (Swedish: <i lang=\"sv\">Reversibelt körfält</i>). A double broken line (ratio 1:1) marking a lane that is used by traffic in one direction at some times and the other direction at other times.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M7"],"gen":"sign"},{"id":"sign-M8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M8-1\" alt=\"M8 Solid line\" width=\"64\" height=\"64\"></div>","opts":["Stop line","Solid line","Give-way or stop ahead","Warning line combined with a solid line"],"a":1,"ex":"M8 is <strong>Solid line</strong> (Swedish: <i lang=\"sv\">Heldragen linje</i>). A solid line replaces a broken line where it is not allowed, for safety reasons, to cross over to oncoming lanes, change lanes or drive out onto the shoulder. You may not drive with any wheel over a solid line (with a few exceptions, for example to pass an obstacle or to reach a property, with special care). A solid centre line can be single or double; a solid lane line and a solid edge line are single.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M8"],"gen":"sign"},{"id":"sign-M9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M9-1\" alt=\"M9 Restricted area (hatched area)\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Restricted area (hatched area)","Warning line combined with a solid line","Purpose place marking"],"a":1,"ex":"M9 is <strong>Restricted area (hatched area)</strong> (Swedish: <i lang=\"sv\">Spärrområde</i>). An area marked with angled or diagonal stripes and bordered by a solid line. Vehicles may not drive on it (Road Traffic Ordinance chapter 3, section 11). Part or all of the area can be painted white.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M9"],"gen":"sign"},{"id":"sign-M10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M10-1\" alt=\"M10 Centre or lane line combined with a solid line\" width=\"64\" height=\"64\"></div>","opts":["Cycle box","Warning line combined with a solid line","Centre or lane line combined with a solid line","Pedestrian symbol"],"a":2,"ex":"M10 is <strong>Centre or lane line combined with a solid line</strong> (Swedish: <i lang=\"sv\">Mittlinje eller körfältslinje och heldragen linje</i>). Used where vehicles on the side of the solid line may not change lanes or cross, while vehicles on the side of the broken line may.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M10"],"gen":"sign"},{"id":"sign-M11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M11-1\" alt=\"M11 Warning line combined with a solid line\" width=\"64\" height=\"64\"></div>","opts":["Cycle box","Warning line combined with a solid line","Pedestrian and cycle arrow","Lane arrows"],"a":1,"ex":"M11 is <strong>Warning line combined with a solid line</strong> (Swedish: <i lang=\"sv\">Varningslinje och heldragen linje</i>). Used where vehicles on the side of the solid line may not change lanes or cross, while vehicles on the warning-line side may (if it is safe).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M11"],"gen":"sign"},{"id":"sign-M12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M12-1\" alt=\"M12 Centre line combined with a warning line\" width=\"64\" height=\"64\"></div>","opts":["Give-way or stop ahead","Centre line combined with a warning line","Give-way line","Edge line"],"a":1,"ex":"M12 is <strong>Centre line combined with a warning line</strong> (Swedish: <i lang=\"sv\">Mittlinje och varningslinje</i>). Used where crossing the warning line is unsuitable because of the traffic conditions, while crossing from the centre-line side is less of a problem.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M12"],"gen":"sign"},{"id":"sign-M13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M13-1\" alt=\"M13 Stop line\" width=\"64\" height=\"64\"></div>","opts":["Warning line","Lane arrows","Stop line","Cycle passage or cycle crossing marking"],"a":2,"ex":"M13 is <strong>Stop line</strong> (Swedish: <i lang=\"sv\">Stopplinje</i>). Marks where a vehicle must stop because of a sign, a traffic signal or a level-crossing light signal (Y1).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M13"],"gen":"sign"},{"id":"sign-M14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M14-1\" alt=\"M14 Give-way line\" width=\"64\" height=\"64\"></div>","opts":["Speed limit marking","Guide line","Give-way line","BUSS marking"],"a":2,"ex":"M14 is <strong>Give-way line</strong> (Swedish: <i lang=\"sv\">Väjningslinje</i>). A row of triangles across the road (“shark’s teeth”) that marks the line vehicles should not pass when giving way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M14"],"gen":"sign"},{"id":"sign-M15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M15-1\" alt=\"M15 Pedestrian crossing marking\" width=\"64\" height=\"64\"></div>","opts":["Speed limit marking","Pedestrian crossing marking","Change lanes","Give-way or stop ahead"],"a":1,"ex":"M15 is <strong>Pedestrian crossing marking</strong> (Swedish: <i lang=\"sv\">Övergångsställe</i>). Stripes across the road marking a pedestrian crossing. It is used where sign B3 is placed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M15"],"gen":"sign"},{"id":"sign-M16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"pedestrians-and-cyclists","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M16-1\" alt=\"M16 Cycle passage or cycle crossing marking\" width=\"64\" height=\"64\"></div>","opts":["Give-way or stop ahead","Cycle passage or cycle crossing marking","Bus lane line","Edge line"],"a":1,"ex":"M16 is <strong>Cycle passage or cycle crossing marking</strong> (Swedish: <i lang=\"sv\">Cykelpassage eller cykelöverfart</i>). Marks a cycle passage or a cycle crossing (where sign B8 stands). At a cycle crossing it is combined with a give-way line (M14). A pedestrian crossing marking may form one of its edges.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M16"],"gen":"sign"},{"id":"sign-M17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M17-1\" alt=\"M17 Speed bump marking\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Speed bump marking","Cycle box","Purpose place marking"],"a":1,"ex":"M17 is <strong>Speed bump marking</strong> (Swedish: <i lang=\"sv\">Farthinder</i>). Marks a speed bump, dip or similar.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M17"],"gen":"sign"},{"id":"sign-M17a","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M17A-CYKELBOX\" alt=\"M17a Cycle box\" width=\"64\" height=\"64\"></div>","opts":["Bicycle symbol","Guide line","Cycle box","Edge line"],"a":2,"ex":"M17a is <strong>Cycle box</strong> (Swedish: <i lang=\"sv\">Cykelbox</i>). Marks a suitable waiting position for cyclists and class II moped riders, for example in front of cars at traffic lights. It is adapted to the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M17a"],"gen":"sign"},{"id":"sign-M18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M18-1\" alt=\"M18 Give-way or stop ahead\" width=\"64\" height=\"64\"></div>","opts":["Parking space marking","Give-way or stop ahead","BUSS marking","Road number marking"],"a":1,"ex":"M18 is <strong>Give-way or stop ahead</strong> (Swedish: <i lang=\"sv\">Förberedande upplysning om väjningsplikt eller stopplikt</i>). A triangle painted on the road warning that you will have to give way or stop further ahead.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M18"],"gen":"sign"},{"id":"sign-M19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M19-1\" alt=\"M19 Lane arrows\" width=\"64\" height=\"64\"></div>","opts":["Bus lane line","Lane arrows","Cycle box","Restricted area (hatched area)"],"a":1,"ex":"M19 is <strong>Lane arrows</strong> (Swedish: <i lang=\"sv\">Körfältspilar</i>). Show the suitable lane for the next junction. If the lane is bordered by solid lane lines, drivers must follow the direction or directions of the arrows (except when entering or leaving a reserved lane near the junction). Double arrows in the same direction show the lane for the next junction and the one after. The arrows also mean you may not drive in the opposite direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M19"],"gen":"sign"},{"id":"sign-M20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"turning-and-lanes","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M20-1\" alt=\"M20 Change lanes\" width=\"64\" height=\"64\"></div>","opts":["Pedestrian symbol","Change lanes","Speed limit marking","Edge line"],"a":1,"ex":"M20 is <strong>Change lanes</strong> (Swedish: <i lang=\"sv\">Körfältsbyte</i>). An arrow showing that you must change lane as soon as possible, because your lane ends.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M20"],"gen":"sign"},{"id":"sign-M21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M21-1\" alt=\"M21 No stopping or parking (yellow line)\" width=\"64\" height=\"64\"></div>","opts":["Yellow zigzag line","Speed limit marking","No stopping or parking (yellow line)","Warning line combined with a solid line"],"a":2,"ex":"M21 is <strong>No stopping or parking (yellow line)</strong> (Swedish: <i lang=\"sv\">Förbud mot att stanna och parkera</i>). A solid yellow line at the edge of the carriageway showing that stopping and parking are prohibited.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M21"],"gen":"sign"},{"id":"sign-M22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M22-1\" alt=\"M22 No parking (yellow broken line)\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking marking","No parking (yellow broken line)","Cycle box","Bicycle symbol"],"a":1,"ex":"M22 is <strong>No parking (yellow broken line)</strong> (Swedish: <i lang=\"sv\">Förbud mot att parkera</i>). A broken yellow line at the edge of the carriageway showing that parking is prohibited. It is also used to show the extent of a bus stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M22"],"gen":"sign"},{"id":"sign-M23","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M23-1\" alt=\"M23 Yellow zigzag line\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking marking","Warning line","Yellow zigzag line","Change lanes"],"a":2,"ex":"M23 is <strong>Yellow zigzag line</strong> (Swedish: <i lang=\"sv\">Förbud mot att stanna och parkera eller att parkera</i>). A yellow zigzag that reinforces markings M21 (no stopping or parking) and M22 (no parking).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M23"],"gen":"sign"},{"id":"sign-M24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M24-1\" alt=\"M24 Parking space marking\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Parking space marking","No parking (yellow broken line)","Bus lane line"],"a":1,"ex":"M24 is <strong>Parking space marking</strong> (Swedish: <i lang=\"sv\">Uppställningsplats</i>). Marks the border of a space where vehicles may be placed. It can be a broken line.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M24"],"gen":"sign"},{"id":"sign-M25","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M25-1\" alt=\"M25 Pedestrian and cycle arrow\" width=\"64\" height=\"64\"></div>","opts":["BUSS marking","Guide line","Pedestrian and cycle arrow","Warning line"],"a":2,"ex":"M25 is <strong>Pedestrian and cycle arrow</strong> (Swedish: <i lang=\"sv\">Gång- och cykelpil</i>). Shows a suitable route for pedestrians or for cyclists and class II moped riders.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M25"],"gen":"sign"},{"id":"sign-M26","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M26-1\" alt=\"M26 Bicycle symbol\" width=\"64\" height=\"64\"></div>","opts":["Reversible lane line","Bicycle symbol","Disabled parking marking","Give-way line"],"a":1,"ex":"M26 is <strong>Bicycle symbol</strong> (Swedish: <i lang=\"sv\">Cykel</i>). Shows a track or a suitable route for cyclists and class II moped riders.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M26"],"gen":"sign"},{"id":"sign-M27","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M27-1\" alt=\"M27 Pedestrian symbol\" width=\"64\" height=\"64\"></div>","opts":["Cycle passage or cycle crossing marking","Pedestrian symbol","No parking (yellow broken line)","Parking space marking"],"a":1,"ex":"M27 is <strong>Pedestrian symbol</strong> (Swedish: <i lang=\"sv\">Gående</i>). Shows a path or suitable route for pedestrians.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M27"],"gen":"sign"},{"id":"sign-M28","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M28-1\" alt=\"M28 BUSS marking\" width=\"64\" height=\"64\"></div>","opts":["Speed bump marking","Speed limit marking","BUSS marking","Pedestrian crossing marking"],"a":2,"ex":"M28 is <strong>BUSS marking</strong> (Swedish: <i lang=\"sv\">Buss</i>). Shows that the lane is meant for buses in scheduled service and others allowed there.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M28"],"gen":"sign"},{"id":"sign-M29","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M29-1\" alt=\"M29 Speed limit marking\" width=\"64\" height=\"64\"></div>","opts":["Guide line","Parking space marking","Speed limit marking","Pedestrian and cycle arrow"],"a":2,"ex":"M29 is <strong>Speed limit marking</strong> (Swedish: <i lang=\"sv\">Hastighet</i>). Painted on the road to remind you of the speed limit.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M29"],"gen":"sign"},{"id":"sign-M30","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M30\" alt=\"M30 Road number marking\" width=\"64\" height=\"64\"></div>","opts":["No parking (yellow broken line)","Road number marking","Bus lane line","Pedestrian crossing marking"],"a":1,"ex":"M30 is <strong>Road number marking</strong> (Swedish: <i lang=\"sv\">Vägnummer</i>). Shows the road number painted on the road.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M30"],"gen":"sign"},{"id":"sign-M31","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M31-1\" alt=\"M31 Purpose place marking\" width=\"64\" height=\"64\"></div>","opts":["Bicycle symbol","Purpose place marking","Stop line","Information marking"],"a":1,"ex":"M31 is <strong>Purpose place marking</strong> (Swedish: <i lang=\"sv\">Ändamålsplats</i>). Shows that a parking space is meant for a certain purpose, for example LASTPLATS (loading place). The text matches the purpose.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M31"],"gen":"sign"},{"id":"sign-M32","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M32-1\" alt=\"M32 STOPP marking\" width=\"64\" height=\"64\"></div>","opts":["Edge line","Warning line combined with a solid line","STOPP marking","Give-way line"],"a":2,"ex":"M32 is <strong>STOPP marking</strong> (Swedish: <i lang=\"sv\">Stopp</i>). The word STOPP painted on the road. Used together with sign B2 to reinforce the duty to stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M32"],"gen":"sign"},{"id":"sign-M33","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M33-1\" alt=\"M33 Disabled parking marking\" width=\"64\" height=\"64\"></div>","opts":["Parking space marking","Disabled parking marking","Guide line","Reversible lane line"],"a":1,"ex":"M33 is <strong>Disabled parking marking</strong> (Swedish: <i lang=\"sv\">Rörelsehindrad</i>). Shows a parking space only for people with reduced mobility (with a disabled parking permit).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M33"],"gen":"sign"},{"id":"sign-M34","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"road-markings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"M34-1\" alt=\"M34 Information marking\" width=\"64\" height=\"64\"></div>","opts":["Cycle box","Information marking","Guide line","Warning line combined with a solid line"],"a":1,"ex":"M34 is <strong>Information marking</strong> (Swedish: <i lang=\"sv\">Information</i>). Text painted on the road that gives information, a warning or guidance that matters to road users, for example SKOLA (school).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K4P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 4 kap. 1 §\">VMF 4 kap. 1 §</a>"],"signs":["M34"],"gen":"sign"},{"id":"sign-P1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P1-1\" alt=\"P1 Police – stop (arm stretched out)\" width=\"64\" height=\"64\"></div>","opts":["Police vehicle – slow down (traffic behind)","Police – stop (arm stretched out)","Control point","Police – stop (lamp)"],"a":1,"ex":"P1 is <strong>Police – stop (arm stretched out)</strong> (Swedish: <i lang=\"sv\">Stopp</i>). Stop for road users coming from in front of or behind the police officer. It is used in junctions and applies as long as the officer faces the same way. For road users coming from the side, it means the way is clear and they may drive. It can be combined with P2 and given with a stop paddle.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P1"],"gen":"sign"},{"id":"sign-P2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P2-1\" alt=\"P2 Police – stop (raised hand)\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Police vehicle – pull over and stop in front","Police – stop (raised hand)","Police vehicle – slow down (traffic behind)"],"a":2,"ex":"P2 is <strong>Police – stop (raised hand)</strong> (Swedish: <i lang=\"sv\">Stopp</i>). Stop for the road user that the palm of the hand is facing. It can be given with a stop paddle.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P2"],"gen":"sign"},{"id":"sign-P3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P3-1\" alt=\"P3 Police – stop (lamp)\" width=\"64\" height=\"64\"></div>","opts":["Control point ahead","Police – stop (lamp)","Control point","Police vehicle – follow and stop behind it"],"a":1,"ex":"P3 is <strong>Police – stop (lamp)</strong> (Swedish: <i lang=\"sv\">Stopp</i>). Stop for the road user that the lamp is facing. Used in darkness and when visibility is poor; the lamp is held where it is easiest to see.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P3"],"gen":"sign"},{"id":"sign-P4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P4-1\" alt=\"P4 Police – drive on\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Police – drive on","Police – slow down","Police – stop (raised hand)"],"a":1,"ex":"P4 is <strong>Police – drive on</strong> (Swedish: <i lang=\"sv\">Kör fram</i>). Road users in the direction of the officer’s waving movement may continue.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P4"],"gen":"sign"},{"id":"sign-P5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P5-1\" alt=\"P5 Police – slow down\" width=\"64\" height=\"64\"></div>","opts":["Police – drive on","Police – stop (lamp)","Police – slow down","Police – stop (raised hand)"],"a":2,"ex":"P5 is <strong>Police – slow down</strong> (Swedish: <i lang=\"sv\">Minska hastigheten</i>). The road user the officer is facing must reduce speed. In darkness or poor visibility it can be made clearer with a lamp or reflector showing white or yellow light.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P5"],"gen":"sign"},{"id":"sign-P6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P6-1\" alt=\"P6 Control point\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (raised hand)","Police vehicle – slow down (traffic behind)","Control point","Control point ahead"],"a":2,"ex":"P6 is <strong>Control point</strong> (Swedish: <i lang=\"sv\">Kontroll</i>). Drivers must drive into the control point to be checked. If a symbol for a vehicle type is shown, only drivers of those vehicles must drive in.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P6"],"gen":"sign"},{"id":"sign-P7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P7-1\" alt=\"P7 Control point ahead\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Control point ahead","Control point","Police – stop (raised hand)"],"a":1,"ex":"P7 is <strong>Control point ahead</strong> (Swedish: <i lang=\"sv\">Förberedande upplysning om kontroll</i>). Advance notice of a control point.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P7"],"gen":"sign"},{"id":"sign-P8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P8-1\" alt=\"P8 Police vehicle – slow down (traffic behind)\" width=\"64\" height=\"64\"></div>","opts":["Police vehicle – follow and stop behind it","Police – drive on","Police vehicle – slow down (traffic behind)","Police – stop (raised hand)"],"a":2,"ex":"P8 is <strong>Police vehicle – slow down (traffic behind)</strong> (Swedish: <i lang=\"sv\">Minska hastigheten</i>). Road users behind the police vehicle must reduce speed. In darkness it can be made clearer with white or yellow light or a reflector.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P8"],"gen":"sign"},{"id":"sign-P9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P9-1\" alt=\"P9 Police vehicle – slow down (oncoming traffic)\" width=\"64\" height=\"64\"></div>","opts":["Police vehicle – pull over and stop in front","Police vehicle – slow down (oncoming traffic)","Police – stop (lamp)","Control point ahead"],"a":1,"ex":"P9 is <strong>Police vehicle – slow down (oncoming traffic)</strong> (Swedish: <i lang=\"sv\">Minska hastigheten</i>). Road users meeting the police vehicle must reduce speed. In darkness it can be made clearer with white or yellow light or a reflector.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P9"],"gen":"sign"},{"id":"sign-P10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P10-1\" alt=\"P10 Police vehicle – follow and stop behind it\" width=\"64\" height=\"64\"></div>","opts":["Police – stop (lamp)","Police – drive on","Police vehicle – follow and stop behind it","Police – stop (raised hand)"],"a":2,"ex":"P10 is <strong>Police vehicle – follow and stop behind it</strong> (Swedish: <i lang=\"sv\">Följ efter och stanna bakom polisfordonet när detta stannar</i>). The driver of the vehicle behind the police vehicle must follow it and stop when it stops. It can be given with a stop paddle.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P10"],"gen":"sign"},{"id":"sign-P11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"P11-1\" alt=\"P11 Police vehicle – pull over and stop in front\" width=\"64\" height=\"64\"></div>","opts":["Police – slow down","Police vehicle – slow down (oncoming traffic)","Police vehicle – pull over and stop in front","Police – stop (raised hand)"],"a":2,"ex":"P11 is <strong>Police vehicle – pull over and stop in front</strong> (Swedish: <i lang=\"sv\">Kör in till vägkanten och stanna framför polisfordonet</i>). The driver of the vehicle in front of the police vehicle must pull over to the side of the road and stop. The signal is given with blue and red lights flashing alternately.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K7P2\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 7 kap. 2 §\">VMF 7 kap. 2 §</a>"],"signs":["P11"],"gen":"sign"},{"id":"sign-T1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T1-1\" alt=\"T1 Length of stretch\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","Length of stretch","Fee","How the roads continue in the junction"],"a":1,"ex":"T1 is <strong>Length of stretch</strong> (Swedish: <i lang=\"sv\">Vägsträckas längd</i>). Shows where a stretch begins and ends, measured from the sign. For example “200–800 m” means the sign above applies from 200 metres ahead to 800 metres ahead; “0–1.2 km” means it applies from here for 1.2 kilometres.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T1"],"gen":"sign"},{"id":"sign-T2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T2-1\" alt=\"T2 Distance\" width=\"64\" height=\"64\"></div>","opts":["All-way give way","Total weight","Distance","Distance to stop sign"],"a":2,"ex":"T2 is <strong>Distance</strong> (Swedish: <i lang=\"sv\">Avstånd</i>). Shows the distance to what the sign above refers to – for example to a danger, a ban or a give-way point.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T2"],"gen":"sign"},{"id":"sign-T3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T3-1\" alt=\"T3 Distance to stop sign\" width=\"64\" height=\"64\"></div>","opts":["Distance","Extent","Distance to stop sign","Text panel"],"a":2,"ex":"T3 is <strong>Distance to stop sign</strong> (Swedish: <i lang=\"sv\">Avstånd till stopplikt</i>). Used only under sign B1 (give way). It warns that there is a stop sign (stopplikt) at the distance shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T3"],"gen":"sign"},{"id":"sign-T4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T4-1\" alt=\"T4 Free width\" width=\"64\" height=\"64\"></div>","opts":["Parking ticket","All-way give way","Free width","Disabled parking permit"],"a":2,"ex":"T4 is <strong>Free width</strong> (Swedish: <i lang=\"sv\">Fri bredd</i>). Shows the free width of the road, for example where the road narrows.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T4"],"gen":"sign"},{"id":"sign-T5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T5\" alt=\"T5 Total weight\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","Total weight","Distance","Tunnel category"],"a":1,"ex":"T5 is <strong>Total weight</strong> (Swedish: <i lang=\"sv\">Totalvikt</i>). The sign above applies only to vehicles with a total weight (the highest weight the vehicle is registered for) above the value shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T5"],"gen":"sign"},{"id":"sign-T6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T6-1\" alt=\"T6 Times\" width=\"64\" height=\"64\"></div>","opts":["Extent","Times","Free width","Time limit for parking"],"a":1,"ex":"T6 is <strong>Times</strong> (Swedish: <i lang=\"sv\">Tidsangivelse</i>). Shows when the sign above applies. Black or white numbers without brackets mean weekdays except the day before a Sunday or public holiday. Numbers in brackets mean the day before a Sunday or public holiday (usually Saturday). Red numbers mean Sundays and public holidays. If a period runs past midnight, the part after midnight belongs to the next day. If a particular date or weekday is given, the rule applies that day whatever kind of day it is.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T6"],"gen":"sign"},{"id":"sign-T7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T7\" alt=\"T7 Disabled parking permit\" width=\"64\" height=\"64\"></div>","opts":["Free width","Disabled parking permit","Extent","All-way stop"],"a":1,"ex":"T7 is <strong>Disabled parking permit</strong> (Swedish: <i lang=\"sv\">Rörelsehindrade</i>). Used only under sign E19 (parking). The parking applies to people who may park with a parking permit for people with disabilities. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T7"],"gen":"sign"},{"id":"sign-T8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T8-1\" alt=\"T8 Vehicle type or road user panel\" width=\"64\" height=\"64\"></div>","opts":["Free width","Times","Vehicle type or road user panel","All-way stop"],"a":2,"ex":"T8 is <strong>Vehicle type or road user panel</strong> (Swedish: <i lang=\"sv\">Symboltavla</i>). The sign above applies only to the vehicle type or road user group shown by the symbol. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T8"],"gen":"sign"},{"id":"sign-T9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T9-1\" alt=\"T9 People with impaired sight\" width=\"64\" height=\"64\"></div>","opts":["Times","People with impaired sight","Disabled parking permit","Free width"],"a":1,"ex":"T9 is <strong>People with impaired sight</strong> (Swedish: <i lang=\"sv\">Nedsatt syn</i>). Shows that people with impaired sight are often found here.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T9"],"gen":"sign"},{"id":"sign-T10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T10\" alt=\"T10 People with impaired hearing\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","People with impaired hearing","Free width","All-way stop"],"a":1,"ex":"T10 is <strong>People with impaired hearing</strong> (Swedish: <i lang=\"sv\">Nedsatt hörsel</i>). Shows that people with impaired hearing are often found here. This panel is always yellow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T10"],"gen":"sign"},{"id":"sign-T11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T11-1\" alt=\"T11 Extent\" width=\"64\" height=\"64\"></div>","opts":["Free width","Extent","Times","Total weight"],"a":1,"ex":"T11 is <strong>Extent</strong> (Swedish: <i lang=\"sv\">Utsträckning</i>). A panel with arrows pointing both ways (horizontal or vertical) means the rule applies on both sides of the sign. An arrow pointing down means the rule ends here. An arrow to the right or left shows that the rule applies in that direction. Under a parking sign (E19) it has black arrows on white without a border.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T11"],"gen":"sign"},{"id":"sign-T12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T12-1\" alt=\"T12 Direction\" width=\"64\" height=\"64\"></div>","opts":["Distance","Direction","People with impaired hearing","Times"],"a":1,"ex":"T12 is <strong>Direction</strong> (Swedish: <i lang=\"sv\">Riktning</i>). Shows the direction to what the sign above refers to.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T12"],"gen":"sign"},{"id":"sign-T13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T13-1\" alt=\"T13 All-way give way\" width=\"64\" height=\"64\"></div>","opts":["How the roads continue in the junction","All-way give way","How to park","Text panel"],"a":1,"ex":"T13 is <strong>All-way give way</strong> (Swedish: <i lang=\"sv\">Flervägsväjning</i>). Shows that drivers on every road into the junction have to give way.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T13"],"gen":"sign"},{"id":"sign-T14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T14-1\" alt=\"T14 All-way stop\" width=\"64\" height=\"64\"></div>","opts":["Free width","All-way stop","How the roads continue in the junction","All-way give way"],"a":1,"ex":"T14 is <strong>All-way stop</strong> (Swedish: <i lang=\"sv\">Flervägsstopp</i>). Shows that drivers on every road into the junction must stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T14"],"gen":"sign"},{"id":"sign-T15","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"priority-signs","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T15-1\" alt=\"T15 How the roads continue in the junction\" width=\"64\" height=\"64\"></div>","opts":["Times","Fee","How the roads continue in the junction","Direction"],"a":2,"ex":"T15 is <strong>How the roads continue in the junction</strong> (Swedish: <i lang=\"sv\">Vägars fortsättning i korsning</i>). Shows a junction where drivers on the road drawn with a narrow line must give way to vehicles on the road drawn with a wide line. The symbol is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T15"],"gen":"sign"},{"id":"sign-T16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T16\" alt=\"T16 Fee\" width=\"64\" height=\"64\"></div>","opts":["Free width","Fee","All-way give way","Distance"],"a":1,"ex":"T16 is <strong>Fee</strong> (Swedish: <i lang=\"sv\">Avgift</i>). Parking costs money according to the price list on the parking meter, ticket machine or similar, and any other conditions written there must be followed. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T16"],"gen":"sign"},{"id":"sign-T17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T17-1\" alt=\"T17 Parking disc\" width=\"64\" height=\"64\"></div>","opts":["How to park","Parking disc","All-way stop","Charging place"],"a":1,"ex":"T17 is <strong>Parking disc</strong> (Swedish: <i lang=\"sv\">Parkeringsskiva</i>). You must show the time you started parking with a parking disc (P-skiva) or similar. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T17"],"gen":"sign"},{"id":"sign-T18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T18\" alt=\"T18 Time limit for parking\" width=\"64\" height=\"64\"></div>","opts":["Times","Time limit for parking","Parking disc","Distance"],"a":1,"ex":"T18 is <strong>Time limit for parking</strong> (Swedish: <i lang=\"sv\">Tillåten tid för parkering</i>). Shows the longest time you may park. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T18"],"gen":"sign"},{"id":"sign-T19","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T19\" alt=\"T19 Residents\" width=\"64\" height=\"64\"></div>","opts":["Text panel","Disabled parking permit","Residents","Parking disc"],"a":2,"ex":"T19 is <strong>Residents</strong> (Swedish: <i lang=\"sv\">Boende</i>). Residents of an area who have a special permit may park under special conditions. An area code may be added. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T19"],"gen":"sign"},{"id":"sign-T20","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T20\" alt=\"T20 Parking ticket\" width=\"64\" height=\"64\"></div>","opts":["Parking disc","Parking ticket","Distance to stop sign","Text panel"],"a":1,"ex":"T20 is <strong>Parking ticket</strong> (Swedish: <i lang=\"sv\">Parkeringsbiljett</i>). Parking is free of charge, but you must use a parking ticket. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T20"],"gen":"sign"},{"id":"sign-T21","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T21-1\" alt=\"T21 How to park\" width=\"64\" height=\"64\"></div>","opts":["Disabled parking permit","Free width","How to park","Parking ticket"],"a":2,"ex":"T21 is <strong>How to park</strong> (Swedish: <i lang=\"sv\">Uppställning av fordon</i>). Shows how vehicles must be placed in a car park – for example at right angles, in a line, or at an angle. The panel is drawn to match the place.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T21"],"gen":"sign"},{"id":"sign-T22","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"additional-panels","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T22-1\" alt=\"T22 Text panel\" width=\"64\" height=\"64\"></div>","opts":["Free width","Text panel","Distance","Disabled parking permit"],"a":1,"ex":"T22 is <strong>Text panel</strong> (Swedish: <i lang=\"sv\">Text</i>). Gives an extra instruction in words that no other panel, or combination of panels, can give. Times on panel T6 work as usual.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T22"],"gen":"sign"},{"id":"sign-T24","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"stopping-and-parking","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"T24-1\" alt=\"T24 Charging place\" width=\"64\" height=\"64\"></div>","opts":["Distance to stop sign","Charging place","Distance","All-way stop"],"a":1,"ex":"T24 is <strong>Charging place</strong> (Swedish: <i lang=\"sv\">Laddplats</i>). Used under sign E19 (parking). It marks a place for charging electric vehicles, where only vehicles that can be charged from an external source may park.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K2P30\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 2 kap. 30 §\">VMF 2 kap. 30 §</a>"],"signs":["T24"],"gen":"sign"},{"id":"sign-SIG1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG1-1\" alt=\"SIG1 Red light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Red light","Lane signal – yellow arrow","Green light"],"a":1,"ex":"SIG1 is <strong>Red light</strong> (Swedish: <i lang=\"sv\">Röd</i>). Stop. Vehicles may not pass the stop line, or the signal if there is no stop line. A red arrow outline in the lamp means the red light only applies to the direction of the arrow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG1"],"gen":"sign"},{"id":"sign-SIG2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG2-1\" alt=\"SIG2 Red and yellow light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – green arrow","Public transport signal with a horizontal bar","Red and yellow light","Flashing yellow light"],"a":2,"ex":"SIG2 is <strong>Red and yellow light</strong> (Swedish: <i lang=\"sv\">Röd + gul</i>). The light is about to turn green. Otherwise it means the same as red – you may not drive yet.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG2"],"gen":"sign"},{"id":"sign-SIG3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG3-1\" alt=\"SIG3 Green light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Green light","Yellow light","Public transport signal with a horizontal bar"],"a":1,"ex":"SIG3 is <strong>Green light</strong> (Swedish: <i lang=\"sv\">Grön</i>). Vehicles may go ahead. A green arrow means the signal applies to the direction of the arrow, and you may drive in that direction even if another light is showing at the same time.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG3"],"gen":"sign"},{"id":"sign-SIG4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG4-1\" alt=\"SIG4 Yellow light\" width=\"64\" height=\"64\"></div>","opts":["Green light","Yellow light","Flashing yellow light","Public transport signal with a vertical bar or arrow"],"a":1,"ex":"SIG4 is <strong>Yellow light</strong> (Swedish: <i lang=\"sv\">Gul</i>). Stop. Vehicles may not pass the stop line (or the signal) unless they were so close when the light changed from green to yellow that they cannot stop safely.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG4"],"gen":"sign"},{"id":"sign-SIG5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG5-1\" alt=\"SIG5 Flashing yellow light\" width=\"64\" height=\"64\"></div>","opts":["Red and yellow light","Steady red light (road closed)","Flashing yellow light","Green pedestrian light"],"a":2,"ex":"SIG5 is <strong>Flashing yellow light</strong> (Swedish: <i lang=\"sv\">Blinkande gul</i>). Take special care when passing. It is shown only when the signals are out of order or temporarily not working for a short time; the normal priority rules and signs then apply.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG5"],"gen":"sign"},{"id":"sign-SIG6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG6-1\" alt=\"SIG6 Red pedestrian light\" width=\"64\" height=\"64\"></div>","opts":["Public transport signal with a horizontal bar","Yellow light","Red pedestrian light","Public transport signal &quot;S&quot;"],"a":2,"ex":"SIG6 is <strong>Red pedestrian light</strong> (Swedish: <i lang=\"sv\">Röd akustisk signal med långsam pulsfrekvens</i>). A standing figure, often with a slow ticking sound. Pedestrians may not step onto the carriageway, cycle track or crossing. Someone already on the road when it turns red should continue to the other side, or stop on a refuge if there is one.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG6"],"gen":"sign"},{"id":"sign-SIG7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG7-1\" alt=\"SIG7 Green pedestrian light\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Green pedestrian light","Steady red light (road closed)","Red and yellow light"],"a":1,"ex":"SIG7 is <strong>Green pedestrian light</strong> (Swedish: <i lang=\"sv\">Grön akustisk signal med snabb pulsfrekvens</i>). A walking figure, often with a fast ticking sound. Pedestrians may cross. A flashing green figure (with a fast sound with breaks) means it will soon turn red.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG7"],"gen":"sign"},{"id":"sign-SIG8","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG8-1\" alt=\"SIG8 Public transport signal &quot;S&quot;\" width=\"64\" height=\"64\"></div>","opts":["Red and yellow light","Public transport signal &quot;S&quot;","Red pedestrian light","Flashing red lights (bridge, fire station, tunnel …)"],"a":1,"ex":"SIG8 is <strong>Public transport signal &quot;S&quot;</strong> (Swedish: <i lang=\"sv\">S</i>). Stop. A white S in a signal for buses and trams. It applies to vehicles in scheduled service and trams – and to everyone using a bus lane where the signal stands by that lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG8"],"gen":"sign"},{"id":"sign-SIG9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG9-1\" alt=\"SIG9 Public transport signal &quot;S&quot; with a horizontal bar\" width=\"64\" height=\"64\"></div>","opts":["Lane signal – red cross","Yellow light","Public transport signal &quot;S&quot; with a horizontal bar","Red pedestrian light"],"a":2,"ex":"SIG9 is <strong>Public transport signal &quot;S&quot; with a horizontal bar</strong> (Swedish: <i lang=\"sv\">S+vågrätt streck</i>). The signal is about to show the vertical bar (go). Otherwise it means the same as S – stop.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG9"],"gen":"sign"},{"id":"sign-SIG10","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG10-1\" alt=\"SIG10 Public transport signal with a vertical bar or arrow\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Public transport signal with a vertical bar or arrow","Flashing red lights (bridge, fire station, tunnel …)","Public transport signal &quot;S&quot; with a horizontal bar"],"a":1,"ex":"SIG10 is <strong>Public transport signal with a vertical bar or arrow</strong> (Swedish: <i lang=\"sv\">Lodrätt streck eller pil</i>). Go. Buses and trams may continue. An arrow means it applies to that direction.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG10"],"gen":"sign"},{"id":"sign-SIG11","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG11-1\" alt=\"SIG11 Public transport signal with a horizontal bar\" width=\"64\" height=\"64\"></div>","opts":["Flashing yellow light (take special care)","Public transport signal with a horizontal bar","Green pedestrian light","Red and yellow light"],"a":1,"ex":"SIG11 is <strong>Public transport signal with a horizontal bar</strong> (Swedish: <i lang=\"sv\">Vågrätt streck</i>). Stop, unless the vehicle was so close when the signal changed from a vertical to a horizontal bar that it cannot stop safely. A flashing horizontal bar means take special care.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG11"],"gen":"sign"},{"id":"sign-SIG12","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG12-1\" alt=\"SIG12 Lane signal – red cross\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Lane signal – red cross","Steady red light (road closed)","Red pedestrian light"],"a":1,"ex":"SIG12 is <strong>Lane signal – red cross</strong> (Swedish: <i lang=\"sv\">Rött kryss</i>). A red cross above a lane means the lane, and the shoulder next to it, may not be used.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG12"],"gen":"sign"},{"id":"sign-SIG13","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG13-1\" alt=\"SIG13 Lane signal – yellow arrow\" width=\"64\" height=\"64\"></div>","opts":["Green pedestrian light","Public transport signal with a vertical bar or arrow","Lane signal – yellow arrow","Red and yellow light"],"a":2,"ex":"SIG13 is <strong>Lane signal – yellow arrow</strong> (Swedish: <i lang=\"sv\">Gul pil eller pilar</i>). A yellow diagonal arrow (or arrows) above a lane means you must change to another lane in the direction shown.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG13"],"gen":"sign"},{"id":"sign-SIG14","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG14-1\" alt=\"SIG14 Lane signal – green arrow\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Red pedestrian light","Lane signal – green arrow","Flashing red lights (bridge, fire station, tunnel …)"],"a":2,"ex":"SIG14 is <strong>Lane signal – green arrow</strong> (Swedish: <i lang=\"sv\">Grön pil</i>). A green arrow pointing down above a lane means the lane may be used. A road sign may be shown instead of the green arrow.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG14"],"gen":"sign"},{"id":"sign-SIG16","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG16-1\" alt=\"SIG16 Flashing red lights (bridge, fire station, tunnel …)\" width=\"64\" height=\"64\"></div>","opts":["Public transport signal with a vertical bar or arrow","Flashing red lights (bridge, fire station, tunnel …)","Yellow light","Green light"],"a":1,"ex":"SIG16 is <strong>Flashing red lights (bridge, fire station, tunnel …)</strong> (Swedish: <i lang=\"sv\">Rött blinkande ljus</i>). Two red lights flashing alternately mean stop. You may not pass the stop line, or the signal. They are used where a road is temporarily closed, for example at an opening bridge, a fire or ambulance station, an airfield, road works or a tunnel. A ringing sound may be added.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG16"],"gen":"sign"},{"id":"sign-SIG17","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG17-1\" alt=\"SIG17 Steady red light (road closed)\" width=\"64\" height=\"64\"></div>","opts":["Public transport signal with a horizontal bar","Steady red light (road closed)","Yellow light","Lane signal – red cross"],"a":1,"ex":"SIG17 is <strong>Steady red light (road closed)</strong> (Swedish: <i lang=\"sv\">Rött fast ljus</i>). A steady red light means the road is completely closed.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG17"],"gen":"sign"},{"id":"sign-SIG18","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"SIG18-1\" alt=\"SIG18 Flashing yellow light (take special care)\" width=\"64\" height=\"64\"></div>","opts":["Yellow light","Flashing red lights (bridge, fire station, tunnel …)","Flashing yellow light (take special care)","Red and yellow light"],"a":2,"ex":"SIG18 is <strong>Flashing yellow light (take special care)</strong> (Swedish: <i lang=\"sv\">Gult blinkande ljus för påkallande av särskild försiktighet</i>). Used where a road is partly closed, or to make a sign or other device easier to notice. It can also be combined with a sound to warn pedestrians of a crossing tram or bus.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K3P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 3 kap. 1 §\">VMF 3 kap. 1 §</a>"],"signs":["SIG18"],"gen":"sign"},{"id":"sign-X1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X1\" alt=\"X1 Marker arrow\" width=\"64\" height=\"64\"></div>","opts":["Exit marker","Yellow light arrow(s)","Marker arrow","Side obstacle marker"],"a":2,"ex":"X1 is <strong>Marker arrow</strong> (Swedish: <i lang=\"sv\">Markeringspil</i>). Yellow arrow(s) showing that drivers must turn sharply in the direction of the arrow(s), for example because of a bend. The number of arrows matches the place. At road works or other temporary places it has a red background.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X1"],"gen":"sign"},{"id":"sign-X2","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X2-1\" alt=\"X2 Obstacle marker board\" width=\"64\" height=\"64\"></div>","opts":["Side obstacle marker","Special warning device","Obstacle marker board","Road barrier"],"a":2,"ex":"X2 is <strong>Obstacle marker board</strong> (Swedish: <i lang=\"sv\">Markeringsskärm för hinder</i>). Shows that the road is narrowed by an obstacle. It can also show that a road is completely or partly closed. The number of yellow fields matches the obstacle. At road works or other temporary places it has a red background.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X2"],"gen":"sign"},{"id":"sign-X3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X3-1\" alt=\"X3 Side obstacle marker\" width=\"64\" height=\"64\"></div>","opts":["Obstacle marker board","Yellow light arrow(s)","Side obstacle marker","Exit marker"],"a":2,"ex":"X3 is <strong>Side obstacle marker</strong> (Swedish: <i lang=\"sv\">Markeringsskärm för sidohinder, farthinder med mera</i>). Marks the edge of a road or carriageway, or separates the directions of traffic at complicated places. Vehicles must pass on the side the yellow stripes slope down towards. At road works or other temporary places it has a red background; the yellow fields may then be horizontal, and you may pass on either side.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X3"],"gen":"sign"},{"id":"sign-X4","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"motorways","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X4-1\" alt=\"X4 Exit marker\" width=\"64\" height=\"64\"></div>","opts":["Road barrier","Exit marker","Post marker","Side obstacle marker"],"a":1,"ex":"X4 is <strong>Exit marker</strong> (Swedish: <i lang=\"sv\">Avfartsskärm</i>). Marks the split between a main carriageway and an exit that has a deceleration lane.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X4"],"gen":"sign"},{"id":"sign-X5","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X5-1\" alt=\"X5 Yellow light arrow(s)\" width=\"64\" height=\"64\"></div>","opts":["Yellow light arrow(s)","Exit marker","Post marker","Road barrier"],"a":0,"ex":"X5 is <strong>Yellow light arrow(s)</strong> (Swedish: <i lang=\"sv\">Gul ljuspil eller ljuspilar</i>). Road users must pass on the side shown by the arrow or arrows, which may be flashing.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X5"],"gen":"sign"},{"id":"sign-X6","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"accidents-first-aid","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X6-1\" alt=\"X6 Special warning device\" width=\"64\" height=\"64\"></div>","opts":["Side obstacle marker","Special warning device","Temporary closure","Obstacle marker board"],"a":1,"ex":"X6 is <strong>Special warning device</strong> (Swedish: <i lang=\"sv\">Särskild varningsanordning</i>). A triangle with a text showing that the road is restricted by a temporary obstacle or similar. The text matches the reason.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X6"],"gen":"sign"},{"id":"sign-X7","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"signals-and-police","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X7-1\" alt=\"X7 Road barrier\" width=\"64\" height=\"64\"></div>","opts":["Side obstacle marker","Road barrier","Yellow light arrow(s)","Exit marker"],"a":1,"ex":"X7 is <strong>Road barrier</strong> (Swedish: <i lang=\"sv\">Vägbom</i>). Shows that a road is completely or partly closed to traffic. It may carry more devices to make it easier to see.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X7"],"gen":"sign"},{"id":"sign-X9","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"right-of-way","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"X9-1\" alt=\"X9 Roundabout centre marker\" width=\"64\" height=\"64\"></div>","opts":["Exit marker","Roundabout centre marker","Post marker","Obstacle marker board"],"a":1,"ex":"X9 is <strong>Roundabout centre marker</strong> (Swedish: <i lang=\"sv\">Cirkulationstrafik</i>). Marks the centre of a roundabout, around which vehicles must drive.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K5P1\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 5 kap. 1 §\">VMF 5 kap. 1 §</a>"],"signs":["X9"],"gen":"sign"},{"id":"sign-Y1","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"Y1\" alt=\"Y1 Level crossing light signal\" width=\"64\" height=\"64\"></div>","opts":["Level crossing barrier","Level crossing bell","Level crossing light signal","Level crossing marker board"],"a":2,"ex":"Y1 is <strong>Level crossing light signal</strong> (Swedish: <i lang=\"sv\">Rött blinkande ljus</i>). Two red lights flashing alternately mean stop. Road users may not pass the stop line, or the signal if there is no stop line. Below the red lights there may be a round white light that flashes to make the crossing easier to notice.","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K6P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 6 kap. 6 §\">VMF 6 kap. 6 §</a>"],"signs":["Y1"],"gen":"sign"},{"id":"sign-Y3","area":"rules","paths":["car-manual","car-automatic","motorcycle"],"lesson":"railway-crossings","q":"What does this sign, marking or signal mean?","img":"<div class=\"q-sign\"><img class=\"sign-img large\" data-sign=\"Y3-1\" alt=\"Y3 Level crossing barrier\" width=\"64\" height=\"64\"></div>","opts":["Level crossing light signal","Level crossing barrier","Level crossing marker board","Level crossing bell"],"a":1,"ex":"Y3 is <strong>Level crossing barrier</strong> (Swedish: <i lang=\"sv\">Bom</i>). A full or half barrier. It has at least one lamp showing flashing red light towards approaching traffic from when it starts to lower until it is fully raised. The back of the barrier may have the text “Kör genom bommen” (drive through the barrier).","src":["<a class=\"cite\" href=\"https://lagen.nu/2007:90#K6P6\" target=\"_blank\" rel=\"noopener\" title=\"Road Signs Ordinance (2007:90) — VMF 6 kap. 6 §\">VMF 6 kap. 6 §</a>"],"signs":["Y3"],"gen":"sign"}];
